run(function()
	local TriggerBot
	local CPS
	local ProjectileMode
	local ProjectileFireRate
	local ProjectileWaitDelay
	local ProjectileFirstPerson
	local rayParams = cloneRaycast()
	local lastProjectileShot = 0
	local wasHoldingProjectile = false
	local VirtualInputManager = game:GetService("VirtualInputManager")
	local tick = tick
	local task_wait = task.wait
	local pcall = pcall
	local lastClickTime = 0
	local clickCooldown = 0.015
	
	local function leftClick()
		local now = tick()
		if now - lastClickTime < clickCooldown then
			return false
		end
		
		local success = pcall(function()
			VirtualInputManager:SendMouseButtonEvent(0, 0, 0, true, game, 0)
			task_wait(0.02)
			VirtualInputManager:SendMouseButtonEvent(0, 0, 0, false, game, 0)
		end)
		
		if success then
			lastClickTime = now
		end
		return success
	end
	
	local lastProjectileCheck = 0
	local cachedProjectileResult = false
	local lastHotbarSlot = -1
	local cachedSwordRange = nil
	local lastSwordTool = nil
	
	TriggerBot = vape.Categories.Combat:CreateModule({
		Name = 'AutoAttack',
		Function = function(callback)
			if callback then
				local frameCounter = 0
				local lastToolType = nil
				
				repeat
					frameCounter = frameCounter + 1
					local doAttack = false
					local holdingProjectile = isHoldingProjectile()
					
					if not bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN) and entitylib.isAlive then
						if ProjectileMode.Enabled and holdingProjectile then
							if ProjectileFirstPerson.Enabled and not isFirstPerson() then
								wasHoldingProjectile = false
							else
								if holdingProjectile and not wasHoldingProjectile then
									task_wait(ProjectileWaitDelay.Value)
									leftClick()
									lastProjectileShot = tick()
									wasHoldingProjectile = true
								elseif holdingProjectile then
									local currentTime = tick()
									if (currentTime - lastProjectileShot) >= ProjectileFireRate.Value then
										leftClick()
										lastProjectileShot = currentTime
									end
								else
									wasHoldingProjectile = false
								end
							end
						elseif store.hand.toolType == 'sword' and bedwars.DaoController.chargingMaid == nil then
							local currentTool = store.hand.tool
							if currentTool ~= lastSwordTool then
								lastSwordTool = currentTool
								local itemMeta = bedwars.ItemMeta[currentTool.Name]
								cachedSwordRange = itemMeta and itemMeta.sword and itemMeta.sword.attackRange or 14.4
							end
							
							local attackRange = cachedSwordRange or 14.4
							
							if frameCounter % 2 == 0 then
								rayParams.FilterDescendantsInstances = {lplr.Character}
								
								local unit = lplr:GetMouse().UnitRay
								local localPos = entitylib.character.RootPart.Position
								local rayRange = attackRange
								local ray = bedwars.QueryUtil:raycast(unit.Origin, unit.Direction * 200, rayParams)
								
								if ray and (localPos - ray.Instance.Position).Magnitude <= rayRange then
									local entityList = entitylib.List
									for i = 1, #entityList do
										local ent = entityList[i]
										doAttack = ent.Targetable and ray.Instance:IsDescendantOf(ent.Character) and (localPos - ent.RootPart.Position).Magnitude <= rayRange
										if doAttack then
											break
										end
									end
								end
							end
							
							if not doAttack then
								doAttack = bedwars.SwordController:getTargetInRegion(attackRange or 3.8 * 3, 0)
							end
							
							if doAttack then
								bedwars.SwordController:swingSwordAtMouse()
							end
						else
							wasHoldingProjectile = false
						end
					end
					
					if doAttack and not holdingProjectile then
						task_wait(1 / CPS.GetRandomValue())
					else
						task_wait(holdingProjectile and 0.033 or 0.05)
					end
				until not TriggerBot.Enabled
			else
				cachedSwordRange = nil
				lastSwordTool = nil
				lastHotbarSlot = -1
				wasHoldingProjectile = false
			end
		end,
		Tooltip = 'Automatically swings when hovering over a entity'
	})
	
	CPS = TriggerBot:CreateTwoSlider({
		Name = 'CPS',
		Min = 1,
		Max = 9,
		DefaultMin = 7,
		DefaultMax = 7
	})
	
	ProjectileMode = TriggerBot:CreateToggle({
		Name = 'Projectile Mode',
		Tooltip = 'Auto-shoots crossbow/bow when holding projectile weapon'
	})
	
	ProjectileFireRate = TriggerBot:CreateSlider({
		Name = 'Projectile Fire Rate',
		Min = 0.1,
		Max = 3,
		Default = 1.2,
		Decimal = 10,
		Suffix = function(val)
			return val == 1 and 'second' or 'seconds'
		end,
		Tooltip = 'How fast to auto-fire (1.2 = every 1.2 seconds)',
		Visible = function()
			return ProjectileMode.Enabled
		end
	})
	
	ProjectileWaitDelay = TriggerBot:CreateSlider({
		Name = 'Projectile Wait Delay',
		Min = 0,
		Max = 1,
		Default = 0,
		Decimal = 100,
		Suffix = 's',
		Tooltip = 'Delay before shooting (helps prevent ghosting)',
		Visible = function()
			return ProjectileMode.Enabled
		end
	})
	
	ProjectileFirstPerson = TriggerBot:CreateToggle({
		Name = 'Projectile First Person Only',
		Default = false,
		Tooltip = 'Only works in first person mode',
		Visible = function()
			return ProjectileMode.Enabled
		end
	})
end)

run(function()
	local Velocity
	local Horizontal
	local Vertical
	local Chance
	local TargetCheck
	local rand, old = Random.new()
	
	Velocity = vape.Categories.Combat:CreateModule({
		Name = 'Velocity',
		Function = function(callback)
			if callback then
				old = bedwars.KnockbackUtil.applyKnockback
				bedwars.KnockbackUtil.applyKnockback = function(root, mass, dir, knockback, ...)
					if rand:NextNumber(0, 100) > Chance.Value then return end
					local check = (not TargetCheck.Enabled) or entitylib.EntityPosition({
						Range = 50,
						Part = 'RootPart',
						Players = true
					})
	
					if check then
						knockback = knockback or {}
						if Horizontal.Value == 0 and Vertical.Value == 0 then return end
						knockback.horizontal = (knockback.horizontal or 1) * (Horizontal.Value / 100)
						knockback.vertical = (knockback.vertical or 1) * (Vertical.Value / 100)
					end
					
					return old(root, mass, dir, knockback, ...)
				end
			else
				bedwars.KnockbackUtil.applyKnockback = old
			end
		end,
		Tooltip = 'Reduces knockback taken'
	})
	Horizontal = Velocity:CreateSlider({
		Name = 'Horizontal',
		Min = 0,
		Max = 100,
		Default = 0,
		Suffix = '%'
	})
	Vertical = Velocity:CreateSlider({
		Name = 'Vertical',
		Min = 0,
		Max = 100,
		Default = 0,
		Suffix = '%'
	})
	Chance = Velocity:CreateSlider({
		Name = 'Chance',
		Min = 0,
		Max = 100,
		Default = 100,
		Suffix = '%'
	})
	TargetCheck = Velocity:CreateToggle({Name = 'Only when targeting'})
end)

--[[
	Blatant Modules
]]

run(function()
    local PlayerAttachModule
    local ModeDropdown
    local RangeSlider
    local HeightOffsetSlider
    local GroundTouchToggle
    local StrafeDistSlider
    local StrafeSpeedSlider
    local StrafeAngleSlider
    local PredictionSlider

    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true

    local function isValidTarget(ent, myRoot)
        if not ent or not ent.Targetable or not ent.RootPart or not ent.Humanoid then 
            return false 
        end
        if ent.Humanoid.Health <= 0 or ent.Humanoid:GetState() == Enum.HumanoidStateType.Dead then 
            return false 
        end
        if ent.Player then
            if entitylib.isFriend and entitylib.isFriend(ent.Player) then
                return false
            end
            local myPlayer = game:GetService("Players").LocalPlayer
            if myPlayer and myPlayer.Team and ent.Player.Team and myPlayer.Team == ent.Player.Team then
                return false
            end
        end
        return true
    end

    PlayerAttachModule = vape.Categories.Blatant:CreateModule({
        Name = 'PlayerAttach',
        Function = function(callback)
            if callback then
                local strafeTime = 0
                local strafeDirection = 1
                local cycleTimer = 0
                local tpTick, tpToggle, oldy = tick(), true, nil
                
                PlayerAttachModule:Clean(runService.PreSimulation:Connect(function(dt)
                    if not entitylib.isAlive or not entitylib.character.RootPart then return end
                    
                    local myRoot = entitylib.character.RootPart
                    local closestTarget = nil
                    local closestDist = RangeSlider.Value

                    for _, ent in ipairs(entitylib.List) do
                        if isValidTarget(ent, myRoot) then
                            local dist = (ent.RootPart.Position - myRoot.Position).Magnitude
                            if dist <= closestDist then
                                closestDist = dist
                                closestTarget = ent
                            end
                        end
                    end

                    if closestTarget and closestTarget.RootPart then
                        local targetRoot = closestTarget.RootPart
                        local mode = ModeDropdown.Value

                        if mode == 'OverHead' then
                            local currentHeight = HeightOffsetSlider.Value

                            -- Ground Touch / TP Down Logic adapted from Fly module
                            if GroundTouchToggle.Enabled then
                                cycleTimer = cycleTimer + dt
                                if cycleTimer >= 1.6 then
                                    cycleTimer = 0
                                end
                                
                                local isTouchingGround = cycleTimer <= 0.23
                                if isTouchingGround then
                                    currentHeight = 0
                                end
                            end

                            local targetHead = closestTarget.Character and closestTarget.Character:FindFirstChild("Head")
                            local targetVelocity = targetRoot.AssemblyLinearVelocity or targetRoot.Velocity or Vector3.zero
                            local predictionOffset = targetVelocity * (PredictionSlider.Value / 10)
                            
                            local basePos = (targetHead and targetHead.Position or targetRoot.Position) + predictionOffset
                            local targetPos = basePos + Vector3.new(0, currentHeight, 0)

                            -- Raycast safety filter to prevent wall/floor phase flags
                            rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
                            rayCheck.CollisionGroup = myRoot.CollisionGroup

                            if GroundTouchToggle.Enabled and (cycleTimer <= 0.23) then
                                local ray = workspace:Raycast(myRoot.Position, Vector3.new(0, -50, 0), rayCheck)
                                if ray then
                                    targetPos = Vector3.new(targetPos.X, ray.Position.Y + (entitylib.character.HipHeight or 3), targetPos.Z)
                                end
                            end

                            -- Smooth physics-safe interpolation matching network ownership & velocity
                            local currentPos = myRoot.Position
                            local clampedPos = currentPos:Lerp(targetPos, math.clamp(dt * 22, 0.1, 0.9))
                            
                            myRoot.CFrame = CFrame.lookAlong(clampedPos, targetRoot.CFrame.LookVector)
                            myRoot.AssemblyLinearVelocity = targetVelocity

                        elseif mode == 'Strafe' then
                            local maxAngle = StrafeAngleSlider.Value
                            local orbitRadius = StrafeDistSlider.Value
                            local strafeSpeed = StrafeSpeedSlider.Value
                            
                            if maxAngle > 0 then
                                local enemyLook = targetRoot.CFrame.LookVector
                                local toMyRoot = (myRoot.Position - targetRoot.Position).Unit
                                local dotProduct = enemyLook:Dot(toMyRoot)
                                
                                if dotProduct > 0.2 then
                                    strafeDirection = -strafeDirection
                                end

                                strafeTime = strafeTime + (dt * (strafeSpeed / 2) * strafeDirection)
                                
                                local halfArc = math.rad(maxAngle / 2)
                                local currentRadian = math.sin(strafeTime) * halfArc
                                
                                local offsetX = math.cos(currentRadian) * orbitRadius
                                local offsetZ = math.sin(currentRadian) * orbitRadius
                                
                                local targetPos = targetRoot.Position + Vector3.new(offsetX, 0, offsetZ)
                                
                                rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
                                rayCheck.CollisionGroup = myRoot.CollisionGroup

                                local raycastResult = workspace:Raycast(targetRoot.Position, targetPos - targetRoot.Position, rayCheck)
                                if raycastResult then
                                    strafeDirection = strafeDirection * -1
                                    strafeTime = strafeTime + (dt * (strafeSpeed / 2) * strafeDirection * 2)
                                    
                                    currentRadian = math.sin(strafeTime) * halfArc
                                    offsetX = math.cos(currentRadian) * orbitRadius
                                    offsetZ = math.sin(currentRadian) * orbitRadius
                                    targetPos = targetRoot.Position + Vector3.new(offsetX, 0, offsetZ)
                                    
                                    local safetyCheck = workspace:Raycast(targetRoot.Position, targetPos - targetRoot.Position, rayCheck)
                                    if safetyCheck then
                                    targetPos = safetyCheck.Position - (targetPos - targetRoot.Position).Unit * 2
                                    end
                                end
                                
                                local currentPos = myRoot.Position
                                local desiredPos = Vector3.new(targetPos.X, targetRoot.Position.Y, targetPos.Z)
                                local clampedPos = currentPos:Lerp(desiredPos, math.clamp(dt * strafeSpeed * 3.5, 0.1, 0.9))
                                
                                myRoot.CFrame = CFrame.lookAlong(clampedPos, targetRoot.Position - clampedPos)
                                
                                local targetVel = targetRoot.AssemblyLinearVelocity or targetRoot.Velocity or Vector3.zero
                                local currentVel = myRoot.AssemblyLinearVelocity or myRoot.Velocity
                                myRoot.AssemblyLinearVelocity = currentVel:Lerp(targetVel, math.clamp(dt * 12, 0.1, 1))
                            end
                        end
                    end
                end))
            end
        end,
        Tooltip = 'Anti-cheat safe PlayerAttach featuring PreSimulation physics and raycast ground matching'
    })

    RangeSlider = PlayerAttachModule:CreateSlider({
        Name = 'Detection Range',
        Min = 5,
        Max = 60,
        Default = 30,
        Suffix = function(val) return val == 1 and 'stud' or 'studs' end
    })

    HeightOffsetSlider = PlayerAttachModule:CreateSlider({
        Name = 'OverHead Height',
        Min = 1,
        Max = 12,
        Default = 4,
        Suffix = function(val) return val == 1 and 'stud' or 'studs' end
    })

    GroundTouchToggle = PlayerAttachModule:CreateToggle({
        Name = 'Ground Touch',
        Default = false,
        Tooltip = 'Drops down safely to touch the ground for 0.23s every 1.6s using raycast anti-cheat bypass'
    })

    StrafeDistSlider = PlayerAttachModule:CreateSlider({
        Name = 'Strafe Distance',
        Min = 5,
        Max = 30,
        Default = 12,
        Suffix = function(val) return val == 1 and 'stud' or 'studs' end
    })

    StrafeSpeedSlider = PlayerAttachModule:CreateSlider({
        Name = 'Strafe Speed',
        Min = 1,
        Max = 10,
        Default = 5,
        Tooltip = 'Speed of the auto strafe movement'
    })

    StrafeAngleSlider = PlayerAttachModule:CreateSlider({
        Name = 'Strafe Angle',
        Min = 30,
        Max = 360,
        Default = 180,
        Suffix = function(val) return '°' end,
        Tooltip = 'Maximum arc swing angle for auto strafing'
    })

    PredictionSlider = PlayerAttachModule:CreateSlider({
        Name = 'Velocity Lead',
        Min = 0,
        Max = 10,
        Default = 2,
        Tooltip = 'Scales target velocity lead in OverHead mode.'
    })

    ModeDropdown = PlayerAttachModule:CreateDropdown({
        Name = 'Mode',
        List = {'OverHead', 'Strafe'},
        Default = 'OverHead',
        Function = function(val)
            HeightOffsetSlider.Object.Visible = (val == 'OverHead')
            GroundTouchToggle.Object.Visible = (val == 'OverHead')
            PredictionSlider.Object.Visible = (val == 'OverHead')
            StrafeDistSlider.Object.Visible = (val == 'Strafe')
            StrafeSpeedSlider.Object.Visible = (val == 'Strafe')
            StrafeAngleSlider.Object.Visible = (val == 'Strafe')
        end,
        Tooltip = 'OverHead: Floats above target with optional ground touch | Strafe: Auto-moves around target'
    })

    HeightOffsetSlider.Object.Visible = (ModeDropdown.Value == 'OverHead')
    GroundTouchToggle.Object.Visible = (ModeDropdown.Value == 'OverHead')
    PredictionSlider.Object.Visible = (ModeDropdown.Value == 'OverHead')
    StrafeDistSlider.Object.Visible = (ModeDropdown.Value == 'Strafe')
    StrafeSpeedSlider.Object.Visible = (ModeDropdown.Value == 'Strafe')
    StrafeAngleSlider.Object.Visible = (ModeDropdown.Value == 'Strafe')
end)

run(function()
    local AutoReset
    local OwlCheckReset
    local PearlCheckReset
    local CannonCheckReset -- Toggle option for Cannon Check
    local cachedLowestPointReset
    local pearlLastInHandTick = 0  
    local cannonLastInHandTick = 0  

    AutoReset = vape.Categories.Utility:CreateModule({
        Name = 'AutoVoidReset',
        Function = function(callback)
            if callback then
                repeat task.wait() until store.matchState ~= 0 or (not AutoReset.Enabled)
                if not AutoReset.Enabled then return end

                cachedLowestPointReset = math.huge
                for _, v in pairs(store.blocks) do
                    local point = (v.Position.Y - (v.Size.Y / 2)) - 50
                    if point < cachedLowestPointReset then
                        cachedLowestPointReset = point
                    end
                end
                if cachedLowestPointReset == math.huge then
                    cachedLowestPointReset = -100
                end

                repeat
                    if entitylib.isAlive then
                        local root = entitylib.character.RootPart
                        if not root then task.wait(0.1) continue end

                        local handItem = store.inventory and store.inventory.inventory and store.inventory.inventory.hand
                        
                        -- Update hand holding timers
                        if handItem then
                            if handItem.itemType == 'telepearl' then
                                pearlLastInHandTick = tick()
                            elseif handItem.itemType == 'cannon' then
                                cannonLastInHandTick = tick()
                            end
                        end

                        -- Main void check conditions
                        if root.Position.Y < cachedLowestPointReset 
                            and (lplr.Character:GetAttribute('InflatedBalloons') or 0) <= 0 
                            and not getItem('balloon') then

                            local owlBlock = OwlCheckReset.Enabled and root:FindFirstChild('OwlLiftForce')
                            if not owlBlock then
                                local pearlBlock = PearlCheckReset.Enabled and (tick() - pearlLastInHandTick) < 4
                                if not pearlBlock then
                                    -- Cannon Check: Checks if CannonCheckReset is enabled, if cannon was held recently (< 4s), or if a cannon is anywhere in inventory
                                    local cannonBlock = CannonCheckReset.Enabled and ((tick() - cannonLastInHandTick) < 4 or getItem('cannon'))
                                    if not cannonBlock then
                                        local hum = lplr.Character and lplr.Character:FindFirstChildOfClass('Humanoid')
                                        if hum then hum.Health = -1 end
                                    end
                                end
                            end
                        end
                    end
                    task.wait(0.1)
                until not AutoReset.Enabled
            end
        end,
        Tooltip = 'Resets your character when you fall into the void'
    })

    -- UI Options/Toggles
    OwlCheckReset = AutoReset:CreateToggle({
        Name = 'Owl Check',
        Function = function() end,
        Tooltip = 'Prevents auto reset while actively using an owl'
    })

    PearlCheckReset = AutoReset:CreateToggle({
        Name = 'Pearl Check',
        Function = function() end,
        Tooltip = 'Prevents auto reset if you recently held a pearl'
    })

    CannonCheckReset = AutoReset:CreateToggle({
        Name = 'Cannon Check',
        Function = function() end,
        Tooltip = 'Prevents auto reset if you have a cannon or recently held one'
    })
end)

local AntiFallDirection
run(function()
    local AntiFall
    local Mode
    local Material
    local Color
	local rayCheck = cloneRaycast()
    rayCheck.RespectCanCollide = true

    local math_huge = math.huge
    local tick = tick
    local task_wait = task.wait
    local vector3new = Vector3.new
    local vector3zero = Vector3.zero
    
    local cachedLowGround = math_huge
    local lastGroundScan = 0
    local groundScanInterval = 2 
    
    local function getLowGround()
        local now = tick()
        if now - lastGroundScan < groundScanInterval and cachedLowGround ~= math_huge then
            return cachedLowGround
        end
        
        lastGroundScan = now
        local mag = math_huge
        local blockStore = bedwars.BlockController:getStore()
        local allPositions = blockStore:getAllBlockPositions()
        
        for i = 1, #allPositions do
            local pos = allPositions[i] * 3
            if pos.Y < mag and not getPlacedBlock(pos + vector3new(0, 3, 0)) then
                mag = pos.Y
            end
        end
        
        cachedLowGround = mag
        return mag
    end

    AntiFall = vape.Categories.Blatant:CreateModule({
        Name = 'AntiFall',
        Function = function(callback)
            if callback then
                repeat task_wait() until store.matchState ~= 0 or (not AntiFall.Enabled)
                if not AntiFall.Enabled then return end

                local pos, debounce = getLowGround(), tick()
                if pos ~= math_huge then
                    AntiFallPart = Instance.new('Part')
                    AntiFallPart.Size = vector3new(10000, 1, 10000)
                    AntiFallPart.Transparency = 1 - Color.Opacity
                    AntiFallPart.Material = Enum.Material[Material.Value]
                    AntiFallPart.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
                    AntiFallPart.Position = vector3new(0, pos - 2, 0)
                    AntiFallPart.CanCollide = Mode.Value == 'Collide'
                    AntiFallPart.Anchored = true
                    AntiFallPart.CanQuery = false
                    AntiFallPart.Parent = workspace
                    AntiFall:Clean(AntiFallPart)
                    
                    AntiFall:Clean(AntiFallPart.Touched:Connect(function(touched)
                        if touched.Parent == lplr.Character and entitylib.isAlive and debounce < tick() then
                            debounce = tick() + 0.1
                            
                            if Mode.Value == 'Normal' then
                                local top = getNearGround()
                                if top then
                                    local lastTeleport = lplr:GetAttribute('LastTeleported')
                                    local connection
                                    local frameCounter = 0
                                    
                                    local vapeModules = vape.Modules
                                    local flyEnabled = vapeModules.Fly
                                    local infFlyEnabled = vapeModules.InfiniteFly
                                    local longJumpEnabled = vapeModules.LongJump
                                    
                                    local yMask = vector3new(1, 0, 1)
                                    local yOnly = vector3new(0, 1, 0)
                                    
                                    connection = runService.PreSimulation:Connect(function()
                                        frameCounter = frameCounter + 1
                                        
                                        if frameCounter % 5 == 0 then
                                            if flyEnabled.Enabled or infFlyEnabled.Enabled or longJumpEnabled.Enabled then
                                                connection:Disconnect()
                                                AntiFallDirection = nil
                                                return
                                            end
                                        end

                                        if entitylib.isAlive and lplr:GetAttribute('LastTeleported') == lastTeleport then
                                            local root = entitylib.character.RootPart
                                            local rootPos = root.Position
                                            local delta = (top - rootPos) * yMask
                                            
                                            AntiFallDirection = delta.Unit == delta.Unit and delta.Unit or vector3zero
                                            root.Velocity *= yMask
                                            
                                            if frameCounter % 3 == 0 then
                                                rayCheck.FilterDescendantsInstances = {gameCamera, lplr.Character}
                                                rayCheck.CollisionGroup = root.CollisionGroup

                                                local ray = workspace:Raycast(rootPos, AntiFallDirection, rayCheck)
                                                if ray then
                                                    for i = 1, 5 do
                                                        local dpos = roundPos(ray.Position + ray.Normal * 1.5) + vector3new(0, 3, 0)
                                                        if not getPlacedBlock(dpos) then
                                                            top = vector3new(top.X, pos.Y, top.Z)
                                                            break
                                                        end
                                                    end
                                                end
                                            end

                                            local yDiff = top.Y - rootPos.Y
                                            root.CFrame += vector3new(0, yDiff, 0)
                                            
                                            if not frictionTable.Speed then
                                                local speed = getSpeed()
                                                local newVelocity = (AntiFallDirection * speed) + vector3new(0, root.AssemblyLinearVelocity.Y, 0)
                                                root.AssemblyLinearVelocity = newVelocity
                                            end

                                            if delta.Magnitude < 1 then
                                                connection:Disconnect()
                                                AntiFallDirection = nil
                                            end
                                        else
                                            connection:Disconnect()
                                            AntiFallDirection = nil
                                        end
                                    end)
                                    AntiFall:Clean(connection)
                                end
                            elseif Mode.Value == 'Velocity' then
                                local rootVel = entitylib.character.RootPart.Velocity
                                entitylib.character.RootPart.Velocity = vector3new(rootVel.X, 100, rootVel.Z)
                            end
                        end
                    end))
                end
            else
                AntiFallDirection = nil
                cachedLowGround = math_huge
                lastGroundScan = 0
            end
        end,
        Tooltip = 'Help\'s you with your Parkinson\'s\nPrevents you from falling into the void.'
    })
    
    Mode = AntiFall:CreateDropdown({
        Name = 'Move Mode',
        List = {'Normal', 'Collide', 'Velocity'},
        Function = function(val)
            if AntiFallPart then
                AntiFallPart.CanCollide = val == 'Collide'
            end
        end,
        Tooltip = 'Normal - Smoothly moves you towards the nearest safe point\nVelocity - Launches you upward after touching\nCollide - Allows you to walk on the part'
    })
    
    local materials = {'ForceField'}
    for _, v in Enum.Material:GetEnumItems() do
        if v.Name ~= 'ForceField' then
            table.insert(materials, v.Name)
        end
    end
    
    Material = AntiFall:CreateDropdown({
        Name = 'Material',
        List = materials,
        Function = function(val)
            if AntiFallPart then
                AntiFallPart.Material = Enum.Material[val]
            end
        end
    })
    
    Color = AntiFall:CreateColorSlider({
        Name = 'Color',
        DefaultOpacity = 0.5,
        Function = function(h, s, v, o)
            if AntiFallPart then
                AntiFallPart.Color = Color3.fromHSV(h, s, v)
                AntiFallPart.Transparency = 1 - o
            end
        end
    })
end)

run(function()
    local _sharedHitBlock = nil
    local _hitBlockPatchers = {}

    getgenv().registerHitBlockPatch = function(key, fn)
        _hitBlockPatchers[key] = fn
        if not _sharedHitBlock and bedwars.BlockBreaker then
            _sharedHitBlock = bedwars.BlockBreaker.hitBlock
        end
        if not bedwars.BlockBreaker then return end
        bedwars.BlockBreaker.hitBlock = function(self, maid, raycastparams, ...)
            for _, patcher in _hitBlockPatchers do
                local result = patcher(self, maid, raycastparams, ...)
                if result ~= nil then return result end
            end
            if _sharedHitBlock then return _sharedHitBlock(self, maid, raycastparams, ...) end
        end
    end

    getgenv().unregisterHitBlockPatch = function(key)
        _hitBlockPatchers[key] = nil
        if not next(_hitBlockPatchers) then
            if bedwars.BlockBreaker then
                bedwars.BlockBreaker.hitBlock = _sharedHitBlock
            end
            _sharedHitBlock = nil
        end
    end

    local FastBreak
    local Time
    local BedCheck
    local Blacklist
    local blocks
    local string_lower = string.lower
    local string_find = string.find
    local task_wait = task.wait
    local currentBlock = nil
    local oldHitBlock = nil
    local lastHotbarSlot = nil
    local bedCache = {}
    local blacklistCache = {}
    local lastCacheClean = 0
    local cacheCleanInterval = 5 
    
    local function isBed(block)
        if not block then return false end
        local cached = bedCache[block]
        if cached ~= nil then return cached end
        
        local result = false
        pcall(function()
            if collectionService:HasTag(block, 'bed') or (block.Parent and collectionService:HasTag(block.Parent, 'bed')) then
                result = true
            elseif string_find(string_lower(block.Name), 'bed', 1, true) then
                result = true
            end
        end)
        
        if result then bedCache[block] = true end
        return result
    end
    
    local cachedBlacklistLower = {}
    local function updateBlacklistCache()
        if not blocks or not blocks.ListEnabled then return end
        
        cachedBlacklistLower = {}
        for _, v in pairs(blocks.ListEnabled) do
            table.insert(cachedBlacklistLower, string_lower(v))
        end
    end
    
    local function isBlacklisted(block)
        if not block or #cachedBlacklistLower == 0 then return false end
        local cached = blacklistCache[block]
        if cached ~= nil then return cached end
        
        local name = string_lower(block.Name)
        local result = false
        for i = 1, #cachedBlacklistLower do
            if string_find(name, cachedBlacklistLower[i], 1, true) then
                result = true
                break
            end
        end
        
        blacklistCache[block] = result
        return result
    end
    
    local function shouldSkip(block)
        if not block then return false end
        if BedCheck and BedCheck.Enabled and isBed(block) then return true end
        if Blacklist and Blacklist.Enabled and isBlacklisted(block) then return true end
        return false
    end
    
    local lastBreakUpdate = 0
    local breakUpdateCooldown = 0.05
    local pendingUpdate = false
    
    local function updateBreakSpeed()
        if not FastBreak or not FastBreak.Enabled then return end
        local now = tick()
        if now - lastBreakUpdate < breakUpdateCooldown then
            pendingUpdate = true
            return
        end
        lastBreakUpdate = now
        pendingUpdate = false
        
        pcall(function()
            local cooldown = (shouldSkip(currentBlock)) and 0.3 or Time.Value
            bedwars.BlockBreakController.blockBreaker:setCooldown(cooldown)
        end)
    end
    
    FastBreak = vape.Categories.Blatant:CreateModule({
        Name = 'FastBreak',
        Function = function(callback)
            if callback then
                lastHotbarSlot = nil

				registerHitBlockPatch('FastBreak', function(self, maid, raycastparams, ...)
					local block = nil
					pcall(function()
						local blockInfo = self.clientManager:getBlockSelector():getMouseInfo(1, {ray = raycastparams})
						if blockInfo and blockInfo.target and blockInfo.target.blockInstance then
							block = blockInfo.target.blockInstance
						end
					end)
					
					local currentSlot = store.inventory and store.inventory.hotbarSlot
					local slotChanged = currentSlot ~= lastHotbarSlot
					if slotChanged then
						lastHotbarSlot = currentSlot
					end

					if block ~= currentBlock or slotChanged then
						currentBlock = block
						updateBreakSpeed()
					end
					end)
                
                updateBlacklistCache()
                
                task.spawn(function()
                    while FastBreak.Enabled do
                        if tick() - lastCacheClean > cacheCleanInterval then
                            lastCacheClean = tick()
                            bedCache = {}
                            blacklistCache = {}
                        end
                        if pendingUpdate then updateBreakSpeed() end
                        task_wait(0.05) 
                    end
                end)
			else
				pcall(function() bedwars.BlockBreakController.blockBreaker:setCooldown(0.3) end)
				unregisterHitBlockPatch('FastBreak')
				currentBlock = nil
				lastHotbarSlot = nil
				bedCache, blacklistCache, cachedBlacklistLower = {}, {}, {}
			end
        end,
        Tooltip = 'mine faster'
    })
    
    Time = FastBreak:CreateSlider({
        Name = 'Break speed',
        Min = 0, Max = 0.3, Default = 0.25, Decimal = 100, Suffix = 'seconds',
        Function = function() updateBreakSpeed() end
    })
    
    BedCheck = FastBreak:CreateToggle({
        Name = 'Bed Check',
        Default = false,
        Tooltip = 'mining is normal when breaking beds',
        Function = function() bedCache = {}; updateBreakSpeed() end
    })
    
    Blacklist = FastBreak:CreateToggle({
        Name = 'Blacklist Blocks',
        Default = false,
        Tooltip = 'mining is normal for blacklisted blocks',
        Function = function(v)
            if blocks then blocks.Object.Visible = v end
            blacklistCache = {}
            if v then updateBlacklistCache() end
            updateBreakSpeed()
        end
    })
    
    blocks = FastBreak:CreateTextList({
        Name = 'Blacklisted Blocks',
        Placeholder = 'bed',
        Visible = false,
        Function = function()
            updateBlacklistCache()
            blacklistCache = {}
            updateBreakSpeed()
        end
    })
end)

run(function()
    local Value
    local VerticalValue
    local WallCheck
    local PopBalloons
    local TP
    local lastonground = false
    local MobileButtons
    local FlyAnywayProgressBar = {Enabled = false}
    local FlyAnywayProgressBarFrame
    local BarColor
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    local up, down, old = 0, 0
    local mobileControls = {}
    local groundtime = nil
    local onground = false
    local flyCooldownActive = false
    local lastGroundTouchTime = 0
    local MAX_FLY_TIME = 2.5
    local tick = tick
    local task_wait = task.wait
    local math_max = math.max
    local math_floor = math.floor
    local string_format = string.format
    local vector3new = Vector3.new
    local vector3zero = Vector3.zero
    local udim2new = UDim2.new
    local cframeLookAlong = CFrame.lookAlong
    local cachedBalloonCount = 0
    local lastBalloonCheck = 0
    local balloonCheckInterval = 0.2 
    local cachedMatchState = 0
    local lastMatchStateCheck = 0
    local lastGroundTime = tick()
    local airTime = 0
    
    local function createMobileButton(name, position, icon)
        local button = Instance.new("TextButton")
        button.Name = name
        button.Size = udim2new(0, 60, 0, 60)
        button.Position = position
        button.BackgroundTransparency = 0.2
        button.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        button.BorderSizePixel = 0
        button.Text = icon
        button.TextScaled = true
        button.TextColor3 = Color3.fromRGB(255, 255, 255)
        button.Font = Enum.Font.SourceSansBold
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 8)
        corner.Parent = button
        return button
    end

    local function cleanupMobileControls()
        for _, control in pairs(mobileControls) do
            if control then
                control:Destroy()
            end
        end
        mobileControls = {}
    end

    local progressBarFrameCounter = 0
    local MAX_FRAME_COUNTER = 600
    local function updateProgressBar()
        if not FlyAnywayProgressBarFrame then return end

        if (TP and TP.Enabled) or not entitylib.isAlive then
            FlyAnywayProgressBarFrame.Visible = false
            return
        end
        
        local now = tick()
        if now - lastBalloonCheck > balloonCheckInterval then
            lastBalloonCheck = now
            cachedBalloonCount = lplr.Character:GetAttribute('InflatedBalloons') or 0
            cachedMatchState = store.matchState
        end
        
        local flyAllowed = cachedBalloonCount > 0 or cachedMatchState == 2
        
        if flyAllowed then
            FlyAnywayProgressBarFrame.Frame.Size = udim2new(1, 0, 0, 20)
            FlyAnywayProgressBarFrame.TextLabel.Text = "∞"
            FlyAnywayProgressBarFrame.Visible = FlyAnywayProgressBar.Enabled
            return
        end
        
        progressBarFrameCounter = (progressBarFrameCounter + 1) % MAX_FRAME_COUNTER
        if progressBarFrameCounter % 3 == 0 then
            local hipHeight = entitylib.character.Humanoid.HipHeight
            local checkPos = entitylib.character.HumanoidRootPart.Position + vector3new(0, (hipHeight * -2) - 1, 0)
            local newray = getPlacedBlock(checkPos)
            onground = newray ~= nil
        end
        
        if onground then
            groundtime = nil
            flyCooldownActive = false
            lastGroundTouchTime = now
            
            FlyAnywayProgressBarFrame.Frame.Size = udim2new(1, 0, 0, 20)
            FlyAnywayProgressBarFrame.TextLabel.Text = string_format("%.1fs", MAX_FLY_TIME)
            FlyAnywayProgressBarFrame.Visible = FlyAnywayProgressBar.Enabled and Fly.Enabled
            
            local tween = FlyAnywayProgressBarFrame.Frame:FindFirstChild("Tween")
            if tween then
                tween:Destroy()
            end
        else
            if not groundtime then
                groundtime = now + MAX_FLY_TIME
                flyCooldownActive = false
            end
            
            local timeLeft = math_max(0, groundtime - now)
            local progress = timeLeft / MAX_FLY_TIME
            
            FlyAnywayProgressBarFrame.Frame.Size = udim2new(progress, 0, 0, 20)
            FlyAnywayProgressBarFrame.TextLabel.Text = string_format("%.1fs", timeLeft)
            FlyAnywayProgressBarFrame.Visible = FlyAnywayProgressBar.Enabled and Fly.Enabled
            
            if timeLeft <= 0 and not flyCooldownActive then
                flyCooldownActive = true
            end
        end
        
        lastonground = onground
    end

    Fly = vape.Categories.Blatant:CreateModule({
        Name = 'Fly',
        Function = function(callback)
            frictionTable.Fly = callback or nil
            updateVelocity()
            if callback then
                up, down, old = 0, 0, bedwars.BalloonController.deflateBalloon
                bedwars.BalloonController.deflateBalloon = function() end
                local tpTick, tpToggle, oldy = tick(), true

                if lplr.Character and (lplr.Character:GetAttribute('InflatedBalloons') or 0) == 0 and getItem('balloon') then
                    bedwars.BalloonController:inflateBalloon()
                end

                Fly:Clean(vapeEvents.AttributeChanged.Event:Connect(function(changed)
                    if changed == 'InflatedBalloons' then
                        local char = lplr.Character
                        if not char then return end
                        cachedBalloonCount = char:GetAttribute('InflatedBalloons') or 0
                        if cachedBalloonCount == 0 and getItem('balloon') then
                            bedwars.BalloonController:inflateBalloon()
                        end
                    end
                end))

                local renderFrameCounter = 0
                Fly:Clean(runService.RenderStepped:Connect(function(delta)
                    if FlyAnywayProgressBar.Enabled and Fly.Enabled then
                        renderFrameCounter = renderFrameCounter + 1
                        if renderFrameCounter % 2 == 0 then
                            updateProgressBar()
                        end
                    end
                end))

                local preSimFrameCounter = 0
                local lastWallRaycast = 0
                local wallRaycastInterval = 0.05
                
                Fly:Clean(runService.PreSimulation:Connect(function(dt)
                    if entitylib.isAlive and isnetworkowner(entitylib.character.RootPart) then
                        preSimFrameCounter = preSimFrameCounter + 1
                        local now = tick()
                        
                        if preSimFrameCounter % 12 == 0 then
                            cachedBalloonCount = lplr.Character and lplr.Character:GetAttribute('InflatedBalloons') or 0
                            cachedMatchState = store.matchState
                        end

                        local humanoid = entitylib.character.Humanoid
                        if humanoid.FloorMaterial ~= Enum.Material.Air then
                            lastGroundTime = now
                        end
                        airTime = now - lastGroundTime
                        
                        local flyAllowed = cachedBalloonCount > 0 or cachedMatchState == 2
                        
                        local oscillation = (now % 0.4 < 0.2) and -1 or 1
                        local mass = (1.95 + (flyAllowed and 6 or 0) * oscillation) + ((up + down) * VerticalValue.Value)
                        
                        local root = entitylib.character.RootPart
                        local moveDirection = entitylib.character.Humanoid.MoveDirection
                        local velo = getSpeed()
                        local destination = (moveDirection * math_max(Value.Value - velo, 0) * dt)
                        
                        if WallCheck.Enabled and (now - lastWallRaycast) > wallRaycastInterval then
                            lastWallRaycast = now
                            local filterList = {lplr.Character, gameCamera}
                            if AntiVoidPart then table.insert(filterList, AntiVoidPart) end
                            rayCheck.FilterDescendantsInstances = filterList
                            rayCheck.CollisionGroup = root.CollisionGroup

                            if destination.Magnitude > 0.001 then
                                local ray = workspace:Raycast(root.Position, destination, rayCheck)
                                if ray then
                                    destination = ((ray.Position + ray.Normal) - root.Position)
                                end
                            end
                        end

                        if not flyAllowed then
                            if tpToggle then
                                if airTime > 2 then  
                                    if not oldy then
                                        rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiVoidPart}
                                        rayCheck.CollisionGroup = root.CollisionGroup
                                        local ray = workspace:Raycast(root.Position, vector3new(0, -1000, 0), rayCheck)
                                        if ray and TP.Enabled then
                                            tpToggle = false
                                            oldy = root.Position.Y
                                            tpTick = now + 0.11
                                            root.CFrame = cframeLookAlong(vector3new(root.Position.X, ray.Position.Y + entitylib.character.HipHeight, root.Position.Z), root.CFrame.LookVector)
                                        end
                                    end
                                end
                            else
                                if oldy then
                                    if tpTick < now then
                                        local newpos = vector3new(root.Position.X, oldy, root.Position.Z)
                                        root.CFrame = cframeLookAlong(newpos, root.CFrame.LookVector)
                                        tpToggle = true
                                        oldy = nil
                                    else
                                        mass = 0
                                    end
                                end
                            end
                        end

                        root.CFrame += destination
                        root.AssemblyLinearVelocity = (moveDirection * velo) + vector3new(0, mass, 0)
                    end
                end))

                local isMobile = inputService.TouchEnabled and not inputService.KeyboardEnabled and not inputService.MouseEnabled
                local MobileEnabled = MobileButtons.Enabled or isMobile
                if MobileEnabled then
                    local gui = Instance.new("ScreenGui")
                    gui.Name = "FlyControls"
                    gui.ResetOnSpawn = false
                    gui.Parent = lplr.PlayerGui

                    local upButton = createMobileButton("UpButton", udim2new(0.9, -70, 0.7, -140), "↑")
                    local downButton = createMobileButton("DownButton", udim2new(0.9, -70, 0.7, -70), "↓")

                    mobileControls.UpButton = upButton
                    mobileControls.DownButton = downButton
                    mobileControls.ScreenGui = gui

                    upButton.Parent = gui
                    downButton.Parent = gui

                    Fly:Clean(upButton.MouseButton1Down:Connect(function()
                        up = 1
                    end))
                    Fly:Clean(upButton.MouseButton1Up:Connect(function()
                        up = 0
                    end))
                    Fly:Clean(downButton.MouseButton1Down:Connect(function()
                        down = -1
                    end))
                    Fly:Clean(downButton.MouseButton1Up:Connect(function()
                        down = 0
                    end))
                end

                Fly:Clean(inputService.InputBegan:Connect(function(input)
                    if not inputService:GetFocusedTextBox() then
                        if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA then
                            up = 1
                        elseif input.KeyCode == Enum.KeyCode.LeftShift or input.KeyCode == Enum.KeyCode.ButtonL2 then
                            down = -1
                        end
                    end
                end))
                Fly:Clean(inputService.InputEnded:Connect(function(input)
                    if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA then
                        up = 0
                    elseif input.KeyCode == Enum.KeyCode.LeftShift or input.KeyCode == Enum.KeyCode.ButtonL2 then
                        down = 0
                    end
                end))
                if inputService.TouchEnabled then
                    pcall(function()
                        local jumpButton = lplr.PlayerGui.TouchGui.TouchControlFrame.JumpButton
                        Fly:Clean(jumpButton:GetPropertyChangedSignal('ImageRectOffset'):Connect(function()
                            if not mobileControls.UpButton then
                                up = jumpButton.ImageRectOffset.X == 146 and 1 or 0
                            end
                        end))
                    end)
                end
            else
                if FlyAnywayProgressBarFrame then
                    FlyAnywayProgressBarFrame.Visible = false
                end
                lastonground = nil
                groundtime = nil
                flyCooldownActive = false
                bedwars.BalloonController.deflateBalloon = old
                if PopBalloons.Enabled and entitylib.isAlive and (lplr.Character:GetAttribute('InflatedBalloons') or 0) > 0 then
                    for _ = 1, 3 do
                        bedwars.BalloonController:deflateBalloon()
                    end
                end
                cleanupMobileControls()
                cachedBalloonCount = 0
                lastBalloonCheck = 0
                cachedMatchState = 0
            end
        end,
        ExtraText = function()
            return 'Heatseeker'
        end,
        Tooltip = 'Makes you go ZOOM'
    })
    Value = Fly:CreateSlider({
        Name = 'Speed',
        Min = 1,
        Max = 23,
        Default = 23,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    VerticalValue = Fly:CreateSlider({
        Name = 'Vertical Speed',
        Min = 1,
        Max = 150,
        Default = 50,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    WallCheck = Fly:CreateToggle({
        Name = 'Wall Check',
        Default = true
    })
    PopBalloons = Fly:CreateToggle({
        Name = 'Pop Balloons',
        Default = true
    })
    FlyAnywayProgressBar = Fly:CreateToggle({
        Name = "Progress Bar",
        Function = function(callback)
            if BarColor and BarColor.Object then
                BarColor.Object.Visible = callback
            end
            if callback then
                FlyAnywayProgressBarFrame = Instance.new("Frame")
                FlyAnywayProgressBarFrame.AnchorPoint = Vector2.new(0.5, 0)
                FlyAnywayProgressBarFrame.Position = udim2new(0.5, 0, 1, -200)
                FlyAnywayProgressBarFrame.Size = udim2new(0.2, 0, 0, 20)
                FlyAnywayProgressBarFrame.BackgroundTransparency = 0.5
                FlyAnywayProgressBarFrame.BorderSizePixel = 0
                FlyAnywayProgressBarFrame.BackgroundColor3 = Color3.new(0, 0, 0)
                FlyAnywayProgressBarFrame.Visible = false
                FlyAnywayProgressBarFrame.Parent = vape.gui
                
                local FlyAnywayProgressBarFrame2 = Instance.new("Frame")
                FlyAnywayProgressBarFrame2.Name = "Frame"
                FlyAnywayProgressBarFrame2.AnchorPoint = Vector2.new(0, 0)
                FlyAnywayProgressBarFrame2.Position = udim2new(0, 0, 0, 0)
                FlyAnywayProgressBarFrame2.Size = udim2new(1, 0, 0, 20)
                FlyAnywayProgressBarFrame2.BackgroundTransparency = 0
                FlyAnywayProgressBarFrame2.BorderSizePixel = 0
                FlyAnywayProgressBarFrame2.BackgroundColor3 = BarColor and Color3.fromHSV(BarColor.H, BarColor.S, BarColor.V) or Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value)
                FlyAnywayProgressBarFrame2.Visible = true
                FlyAnywayProgressBarFrame2.Parent = FlyAnywayProgressBarFrame
                
                local FlyAnywayProgressBartext = Instance.new("TextLabel")
                FlyAnywayProgressBartext.Name = "TextLabel"
                FlyAnywayProgressBartext.Text = "2.5s"
                FlyAnywayProgressBartext.Font = Enum.Font.Gotham
                FlyAnywayProgressBartext.TextStrokeTransparency = 0
                FlyAnywayProgressBartext.TextColor3 = Color3.new(0.9, 0.9, 0.9)
                FlyAnywayProgressBartext.TextSize = 20
                FlyAnywayProgressBartext.Size = udim2new(1, 0, 1, 0)
                FlyAnywayProgressBartext.BackgroundTransparency = 1
                FlyAnywayProgressBartext.Position = udim2new(0, 0, 0, 0)
                FlyAnywayProgressBartext.Parent = FlyAnywayProgressBarFrame
            else
                if FlyAnywayProgressBarFrame then 
                    FlyAnywayProgressBarFrame:Destroy() 
                    FlyAnywayProgressBarFrame = nil 
                end
            end
        end,
        Tooltip = "show amount of time for fly",
        Default = true
    })
    BarColor = Fly:CreateColorSlider({
        Name = 'Bar Color',
        Darker = true,
        Visible = false,
        Function = function(h, s, v, o)
            if FlyAnywayProgressBarFrame then
                FlyAnywayProgressBarFrame:FindFirstChild('Frame').BackgroundColor3 = Color3.fromHSV(h, s, v)
                FlyAnywayProgressBarFrame:FindFirstChild('Frame').BackgroundTransparency = 1 - o
            end
        end
    })

    TP = Fly:CreateToggle({
        Name = 'TP Down',
        Default = true,
        Function = function(callback)
            if callback and FlyAnywayProgressBarFrame then
                FlyAnywayProgressBarFrame.Visible = false
            end
        end
    })
    MobileButtons = Fly:CreateToggle({
        Name = "Mobile Buttons",
        Visible = false,
        Tooltip = 'puts up n down buttons on ur screen gng',
        Function = function() 
            if Fly.Enabled then
                Fly:Toggle()
                Fly:Toggle()
            end
        end
    })

    task.defer(function()
        if BarColor and BarColor.Object then
            BarColor.Object.Visible = FlyAnywayProgressBar.Enabled
        end
        if MobileButtons and MobileButtons.Object then
            MobileButtons.Object.Visible = inputService.TouchEnabled
        end
    end)
end)

