run(function()
	local DamageBoost
	local stack
	
	DamageBoost = vape.Categories.Blatant:CreateModule({
		Name = 'DamageBoost',
		Function = function(callback)
			if callback then
				DamageBoost:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
					if entitylib.isAlive and tick() > (stack or 0) and damageTable.entityInstance == lplr.Character and not vape.Modules.LongJump.Enabled then
						local horizontal = (damageTable.knockbackMultiplier and damageTable.knockbackMultiplier.horizontal or 0)
						knockbackSpeed = bedwars.KnockbackUtil.calculateKnockbackVelocity(Vector3.one, 1, {
							vertical = 0,
							horizontal = horizontal,
						}).Magnitude * (0.9 + (store.ping and store.ping.total or 0))
						stack = tick() + (knockbackSpeed / 45)
						knockbackBoost = tick() + (horizontal / 3.5)
					end
				end))
			end
		end,
		Tooltip = 'makes you go slightly faster when damaged'
	})
end)

run(function()
    local PreventSlow
    local SpeedMultiplier
    local old

    -- Helper to determine if an item/modifier is a projectile
    local function isProjectileItem(tab)
        if store and store.hand and store.hand.tool then
            local toolName = store.hand.tool.Name
            local meta = bedwars and bedwars.ItemMeta and bedwars.ItemMeta[toolName]
            if meta and (meta.projectileSource or meta.projectileType or toolName:find('bow') or toolName:find('projectile') or toolName:find('snowball') or toolName:find('fireball')) then
                return true
            end
        end
        if tab then
            local name = tostring(tab.name or tab.id or ''):lower()
            if name:find('bow') or name:find('projectile') or name:find('charge') or name:find('use_item') then
                return true
            end
        end
        return false
    end

    PreventSlow = vape.Categories.Blatant:CreateModule({
        Name = 'PreventSlow',
        Function = function(callback)
            local modifier = bedwars.SprintController:getMovementStatusModifier()
            if callback then
                old = modifier.addModifier
                modifier.addModifier = function(self, tab)
                    -- Only bypass speed slowdowns when holding/using projectile items
                    if tab and tab.moveSpeedMultiplier and isProjectileItem(tab) then
                        tab.moveSpeedMultiplier = math.max(tab.moveSpeedMultiplier, SpeedMultiplier.Value)
                    end
                    return old(self, tab)
                end

                for i in modifier.modifiers do
                    if isProjectileItem(i) and (i.moveSpeedMultiplier or 1) < SpeedMultiplier.Value then
                        modifier:removeModifier(i)
                    end
                end
            else
                if old then
                    modifier.addModifier = old
                    old = nil
                end
            end
        end,
        Tooltip = 'Prevents slowing down strictly when using projectile items.'
    })

    SpeedMultiplier = PreventSlow:CreateSlider({
        Name = 'Speed Multiplier',
        Min = 0.1,
        Max = 1,
        Default = 1,
        Decimal = 100,
        Tooltip = 'Minimum movement speed multiplier allowed when using projectiles'
    })
end)

run(function()
	local NoFall
	local Chance
	local voidParams = RaycastParams.new()
	voidParams.FilterType = Enum.RaycastFilterType.Exclude
	voidParams.IgnoreWater = true
	local lastVoidCheck = 0
	local cachedVoid = false

	local function nearVoid(position)
		if not entitylib.isAlive then return false end
		local now = tick()
		if (now - lastVoidCheck) < 0.15 then
			return cachedVoid
		end
		lastVoidCheck = now
		voidParams.FilterDescendantsInstances = {entitylib.character.Character, gameCamera}
		local result = workspace:Raycast(position, Vector3.new(0, -8, 0), voidParams)
		cachedVoid = result == nil and position.Y < 0
		return cachedVoid
	end

	NoFall = vape.Categories.Blatant:CreateModule({
		Name = 'NoFall',
		Function = function(callback)
			if callback then
				NoFall:Clean(runService.Heartbeat:Connect(function(dt)
					if entitylib.isAlive and bedwars.Knit.Controllers.MatchController:getMatchState() == 1 then
						local root = entitylib.character.RootPart
						local v = root.Velocity

						if root.Velocity.Y < -35 then
							if nearVoid(root.Position) or math.random(1, 100) <= Chance.Value then
								root.Velocity = Vector3.new(0,2.5,0)
								entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Landed)
								runService.PreRender:Wait()
								root.Velocity = v
							end
						end
					end
				end))

				NoFall:Clean(entitylib.Events.LocalAdded:Connect(function(char)
					local animator = char.Humanoid:WaitForChild('Animator', 1)
					if animator and NoFall.Enabled then
						task.wait(.5)
						NoFall:Toggle()
						NoFall:Toggle()
					end
				end))
			end
		end,
		Tooltip = 'Take no fall damage.'
	})

	Chance = NoFall:CreateSlider({
		Name = 'Chance',
		Min = 1,
		Max = 100,
		Default = 100,
		Suffix = '%'
	})
end)

run(function()
	local FastPickup
	local FastPickupDelay
	local PickupRemote = replicatedStorage:WaitForChild('rbxts_include'):WaitForChild('node_modules'):WaitForChild('@rbxts'):WaitForChild('net'):WaitForChild('out'):WaitForChild('_NetManaged'):WaitForChild('PickupItemDrop')

	FastPickup = vape.Categories.Blatant:CreateModule({
		Name = 'FastPickup',
		Tooltip = 'change how fast you pikc items up',
		Function = function(callback)
			if callback then
				FastPickup:Clean(task.spawn(function()
					while FastPickup.Enabled do
						if entitylib.isAlive then
							for _, drop in pairs(workspace:WaitForChild('ItemDropsCache'):GetChildren()) do
								task.spawn(function()
									task.wait(FastPickupDelay.Value)
									pcall(function()
										PickupRemote:InvokeServer({ itemDrop = drop })
									end)
								end)
							end
						end
						task.wait(0.05)
					end
				end))
			end
		end,
	})

	FastPickupDelay = FastPickup:CreateSlider({
		Name = 'Delay',
		Min = 0,
		Max = 0.5,
		Default = 0,
		Decimal = 100,
		Suffix = 's',
	})
end)

run(function()
    local BCR
    local Value
    local CpsConstants = nil
    
    BCR = vape.Categories.World:CreateModule({
        Name = "FastPlace",
        Function = function(callback)
            
            if callback then
                task.wait(1)
                
                pcall(function()
                    CpsConstants = require(replicatedStorage.TS['shared-constants']).CpsConstants
                end)
                
                if not CpsConstants then
                    pcall(function()
                        CpsConstants = bedwars.CpsConstants
                    end)
                end
                
                if CpsConstants then
                    local newCPS = Value.Value == 0 and 1000 or Value.Value
                    CpsConstants.BLOCK_PLACE_CPS = newCPS
                    
                    if isMobile then
                        for _, v in {'2', '5'} do
                            pcall(function()
                                BCR:Clean(lplr.PlayerGui.MobileUI[v].MouseButton1Down:Connect(function()
                                    if CpsConstants then
                                        local currentValue = Value.Value == 0 and 1000 or Value.Value
                                        CpsConstants.BLOCK_PLACE_CPS = currentValue
                                    end
                                end))
                            end)
                        end
                    end
                    
                    task.spawn(function()
                        while BCR.Enabled do
                            local currentValue = Value.Value == 0 and 1000 or Value.Value
                            if CpsConstants.BLOCK_PLACE_CPS ~= currentValue then
                                CpsConstants.BLOCK_PLACE_CPS = currentValue
                            end
                            task.wait(0.3)
                        end
                    end)
                end
                
            else
                if CpsConstants then
                    CpsConstants.BLOCK_PLACE_CPS = 12
                end
            end
        end,
        Tooltip = 'place blocks faster'
    })
    
    Value = BCR:CreateSlider({
        Name = "CPS Limit",
        Suffix = "CPS",
        Default = 12,
        Min = 12,
        Max = 20,
        Function = function()
            if BCR.Enabled and CpsConstants then
                local newCPS = Value.Value == 0 and 1000 or Value.Value
                CpsConstants.BLOCK_PLACE_CPS = newCPS
            end
        end,
    })
end)

run(function()
	local TargetPart
	local Targets
	local Sort
	local TargetPlayerMode
	local FOV
	local AutoCharge
	local PredictionMultiplier
	local Aim = {}
	local OtherProjectiles
	local rayCheck = RaycastParams.new()
	rayCheck.FilterType = Enum.RaycastFilterType.Include
	rayCheck.FilterDescendantsInstances = {workspace:FindFirstChild('Map')}
	local old

	-- Inject custom sort methods
	if not sortmethods['Closest'] then
		sortmethods['Closest'] = function(a, b)
			if not entitylib.isAlive then return false end
			local origin = entitylib.character.RootPart.Position
			local distA = a.RootPart and (origin - a.RootPart.Position).Magnitude or math.huge
			local distB = b.RootPart and (origin - b.RootPart.Position).Magnitude or math.huge
			return distA < distB
		end
	end

	if not sortmethods['Lowest Health'] then
		sortmethods['Lowest Health'] = function(a, b)
			local hpA = a.Humanoid and a.Humanoid.Health or math.huge
			local hpB = b.Humanoid and b.Humanoid.Health or math.huge
			return hpA < hpB
		end
	end

	if not sortmethods['Highest Health'] then
		sortmethods['Highest Health'] = function(a, b)
			local hpA = a.Humanoid and a.Humanoid.Health or 0
			local hpB = b.Humanoid and b.Humanoid.Health or 0
			return hpA > hpB
		end
	end

	local ProjectileAimbot = vape.Categories.Blatant:CreateModule({
		Name = 'ProjectileAimbot',
		Function = function(callback)
			if callback then
				old = bedwars.ProjectileController.calculateImportantLaunchValues
				bedwars.ProjectileController.calculateImportantLaunchValues = function(...)
					local self, projmeta, worldmeta, origin, shootpos = ...

					local baseMode = Sort.Value
					local playerFilter = TargetPlayerMode and TargetPlayerMode.Value or 'None'

					local plr = entitylib.EntityMouse({
						Part = 'RootPart',
						Range = FOV.Value,
						Players = Targets.Players.Enabled,
						NPCs = Targets.NPCs.Enabled,
						Wallcheck = Targets.Walls.Enabled,
						Origin = entitylib.isAlive and (shootpos or entitylib.character.RootPart.Position) or Vector3.zero,
						Sort = sortmethods[baseMode]
					})

					-- If Target Player mode is set to a custom filter (Closest, Lowest Health, Highest Health)
					if plr and playerFilter ~= 'None' and sortmethods[playerFilter] then
						local customSortFn = sortmethods[playerFilter]
						local allTargets = entitylib.GetAllTargets and entitylib.GetAllTargets({
							Part = 'RootPart',
							Range = FOV.Value,
							Players = Targets.Players.Enabled,
							NPCs = Targets.NPCs.Enabled,
							Wallcheck = Targets.Walls.Enabled,
							Origin = entitylib.isAlive and (shootpos or entitylib.character.RootPart.Position) or Vector3.zero,
						})

						if allTargets and #allTargets > 0 then
							table.sort(allTargets, function(a, b)
								local okA = a and a.RootPart and a.Humanoid and a.Humanoid.Health > 0
								local okB = b and b.RootPart and b.Humanoid and b.Humanoid.Health > 0
								if not okA then return false end
								if not okB then return true end
								return customSortFn(a, b)
							end)
							plr = allTargets[1] or plr
						end
					end

					if plr then
						local pos = shootpos or self:getLaunchPosition(origin)
						if not pos then
							return old(...)
						end

						if (not OtherProjectiles.Enabled) and not projmeta.projectile:find('arrow') then
							return old(...)
						end

						if table.find(Blacklist.ListEnabled or {}, ((projmeta.projectile == 'glue_trap' or projmeta.projectile == 'glue_projectile') and 'gloop' or projmeta.projectile)) then
							return old(...)
						end

						local meta = projmeta:getProjectileMeta()
						local lifetime = (worldmeta and meta.predictionLifetimeSec or meta.lifetimeSec or 3)
						local gravity = (meta.gravitationalAcceleration or 196.2) * projmeta.gravityMultiplier
						local projSpeed = (meta.launchVelocity or 100)
						local offsetpos = pos + (projmeta.projectile == 'owl_projectile' and Vector3.zero or projmeta.fromPositionOffset)
						local balloons = plr.Character:GetAttribute('InflatedBalloons')
						local playerGravity = workspace.Gravity

						if balloons and balloons > 0 then
							playerGravity = (workspace.Gravity * (1 - ((balloons >= 4 and 1.2 or balloons >= 3 and 1 or 0.975))))
						end

						if plr.Character.PrimaryPart:FindFirstChild('rbxassetid://8200754399') then
							playerGravity = 6
						end

						if plr.Player and plr.Player:GetAttribute('IsOwlTarget') then
							for _, owl in pairs(collectionService:GetTagged('Owl')) do
								if owl:GetAttribute('Target') == plr.Player.UserId and owl:GetAttribute('Status') == 2 then
									playerGravity = 0
								end
							end
						end

						local newlook = CFrame.new(offsetpos, plr[TargetPart.Value].Position) * CFrame.new(projmeta.projectile == 'owl_projectile' and Vector3.zero or Vector3.new(bedwars.BowConstantsTable.RelX, bedwars.BowConstantsTable.RelY, bedwars.BowConstantsTable.RelZ))
						local targetVelocity = projmeta.projectile == 'telepearl' and Vector3.zero or (plr[TargetPart.Value].Velocity * PredictionMultiplier.Value)

						local calc = prediction.SolveTrajectory(newlook.p, projSpeed, gravity, plr[TargetPart.Value].Position, targetVelocity, playerGravity, plr.HipHeight, plr.Jumping and 42.6 or nil, rayCheck, plr.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(plr.RootPart.Velocity.Y) > 0.01, plr.RootPart.Position, plr.RootPart, nil, true)
						if calc then
							targetinfo.Targets[plr] = tick() + 1
							return {
								initialVelocity = (CFrame.new(newlook.Position, calc).LookVector * projSpeed) * ((AutoCharge.Enabled or not Aim.Enabled) and 1 or projmeta.velocityMultiplier),
								positionFrom = offsetpos,
								deltaT = lifetime,
								gravitationalAcceleration = gravity,
								drawDurationSeconds = AutoCharge.Enabled and 5 or projmeta.drawDurationSeconds
							}
						end
					end

					return old(...)
				end
			else
				bedwars.ProjectileController.calculateImportantLaunchValues = old
			end
		end,
		Tooltip = 'Silently aims at the nearest target near ur cursor / angle'
	})

	Targets = ProjectileAimbot:CreateTargets({
		Players = true,
		Walls = true
	})

	-- 1. Target mode (Cursor, Angle)
	Sort = ProjectileAimbot:CreateDropdown({
		Name = 'Target mode',
		List = {'Cursor', 'Angle'},
		Default = 'Cursor'
	})

	-- 2. Target Player mode (None, Closest, Lowest Health, Highest Health)
	TargetPlayerMode = ProjectileAimbot:CreateDropdown({
		Name = 'Target Player mode',
		List = {'None', 'Closest', 'Lowest Health', 'Highest Health'},
		Default = 'None',
		Tooltip = 'Filters target player selection'
	})

	TargetPart = ProjectileAimbot:CreateDropdown({
		Name = 'Part',
		List = {'RootPart', 'Head'}
	})

	PredictionMultiplier = ProjectileAimbot:CreateSlider({
		Name = 'Prediction',
		Min = 0,
		Max = 2,
		Default = 1,
		Tooltip = 'change the prediction on the projectileaimbot'
	})

	FOV = ProjectileAimbot:CreateSlider({
		Name = 'FOV Range',
		Min = 1,
		Max = 1000,
		Default = 120
	})

	AutoCharge = ProjectileAimbot:CreateToggle({
		Name = 'Auto Charge',
		Function = function(callback)
			if Aim.Object then
				Aim.Object.Visible = callback
			end
		end,
		Default = true,
		Tooltip = 'Fully charges your bow, Allowing your projectile to deal more damage'
	})

	Aim = ProjectileAimbot:CreateToggle({
		Name = 'Aim change',
		Default = true,
		Darker = true,
		Tooltip = 'Changes your trajectory to match charge percentage.'
	})

	OtherProjectiles = ProjectileAimbot:CreateToggle({
		Name = 'Other Projectiles',
		Default = true
	})

	Blacklist = ProjectileAimbot:CreateTextList({
		Name = 'Blacklist',
		Default = {'telepearl'}
	})
end)

local Attacking
run(function()
	local SilentAura
	local Targets
	local Sort
	local ExtraRange
	local MaxTargets
	local AngleSlider
	local Swing
	local Limit
	local LegitAura
	local AttackCheck
	local kitChecks
	local AirHit
	local AirHitsChance
	local FastHits
	local LegitSwitch
	local Arrows
	local ArrowCharge
	local AttackRemote
	local lastAttackTime = 0
	local lastTargetTime = 0
	local AnimDelay = tick()
	local FROZEN_THRESHOLD = 10
	local HIT_PERIOD = 0.2974
	local SERVER_FLOOR = 0.298
	local kaPeriod = HIT_PERIOD
	local kaNextFire = 0
	local kaSync = 0
	local kaSyncSrv = 0
	local kaLastSrv = 0
	local kaLastSend = 0
	local projectileRemote = {InvokeServer = function() end}

	local function getEffectiveRange()
		local extra = (ExtraRange and ExtraRange.Value or 0) * 3
		return 22 + extra
	end

	task.spawn(function()
		task.wait()
		local _remotes = getgenv().remotes or remotes
		if _remotes and _remotes.FireProjectile and bedwars.Client then
			pcall(function() projectileRemote = bedwars.Client:Get(_remotes.FireProjectile).instance end)
		end
		if _remotes and _remotes.AttackEntity and bedwars.Client then
			pcall(function() AttackRemote = bedwars.Client:Get(_remotes.AttackEntity).instance end)
		end
	end)

	local function getKnitControllers()
		return (bedwars.KnitClient and bedwars.KnitClient.Controllers) or (bedwars.Knit and bedwars.Knit.Controllers)
	end

	local function FireAttackRemote(weapon, entityInstance, selfPos, targetPos)
		if not AttackRemote then return false end

		local delta = (targetPos - selfPos).Magnitude
		if delta < 0.01 then return false end

		local currentMaxRange = getEffectiveRange()
		local dir = CFrame.lookAt(selfPos, targetPos).LookVector
		local pos = selfPos + dir * math.max(delta - currentMaxRange, 0)

		AttackRemote:FireServer({
			weapon = weapon,
			chargedAttack = {chargeRatio = 0},
			entityInstance = entityInstance,
			validate = {
				raycast = {
					cameraPosition = {value = pos},
					cursorDirection = {value = dir}
				},
				targetPosition = {value = targetPos},
				selfPosition = {value = pos}
			}
		})
		return true
	end

	local function isOnTinker()
		local ok, mounted = pcall(function()
			local controllers = getKnitControllers()
			return controllers and controllers.TinkerKitController and controllers.TinkerKitController.mounted
		end)
		return ok and mounted == true
	end

	local _lastTinkerSwing = 0
	local function playTinkerSwing()
		local now = workspace:GetServerTimeNow()
		if now - _lastTinkerSwing < 0.35 then return end
		_lastTinkerSwing = now
		pcall(function()
			local controllers = getKnitControllers()
			local controller = controllers and controllers.TinkerKitController
			if not controller then return end
			local model = controller.userMap[lplr]
			if not model then return end
			local mac = controllers.MountAnimationController
			if not mac then return end
			local animId = bedwars.AnimationType and bedwars.AnimationType.TINKER_ATTACK
			mac:playAnimationInMount(model, animId, 1.85)
		end)
	end

	local _adCacheSword = nil
	local _adCacheMeta = nil
	local _adCacheTime = 0

	local function isMeleeWeapon(toolName)
		if not toolName then return false end
		local lower = toolName:lower()
		if lower:find('frosty_hammer') or lower:find('tinker') or lower:find('chainsaw') or lower:find('sword') or lower:find('blade') or lower:find('scythe') or lower:find('dagger') or lower:find('hammer') or lower:find('axe') then
			return true
		end
		local meta = bedwars.ItemMeta and bedwars.ItemMeta[toolName]
		return meta and (meta.sword ~= nil or meta.tinkerChainsaw ~= nil or meta.tinkerMech ~= nil)
	end

	local function computeAttackData()
		if not entitylib.isAlive then return false end

		local casting = lplr:GetAttribute('IsCasting')
		if casting ~= nil and casting ~= false and casting ~= 0 and casting ~= '' then
			if casting == true then return false end
			if type(casting) == 'number' and casting > workspace:GetServerTimeNow() then return false end
		end

		if bedwars.SwordController and bedwars.SwordController.disableSwingState then return false end

		local stunned = lplr.Character and lplr.Character:GetAttribute('StunnedUntilTime')
		if stunned and stunned > workspace:GetServerTimeNow() then return false end

		if AttackCheck and AttackCheck.Enabled then
			if kitChecks then
				for _, check in pairs(kitChecks) do
					local ok, res = pcall(check)
					if ok and res then return false end
				end
			end
		end

		if tick() - (store.silasAbilityTime or 0) < 2.2 then return false end
		if tick() - (store.terraStompTime or 0) < 0.7 then return false end
		if tick() - (store.terraKickTime or 0) < 0.5 then return false end

		local sword = store.hand
		if not sword or not sword.tool or not isMeleeWeapon(sword.tool.Name) then
			sword = (Limit and Limit.Enabled) and nil or store.tools.sword
		end
		if not sword or not sword.tool then return false end

		local meta = bedwars.ItemMeta[sword.tool.Name]
		if not meta then return false end

		if Limit and Limit.Enabled then
			if not isMeleeWeapon(sword.tool.Name) or (bedwars.DaoController and bedwars.DaoController.chargingMaid) then
				return false
			end
		end

		if LegitAura and LegitAura.Enabled then
			local lastSwing = bedwars.SwordController and bedwars.SwordController.lastSwing
			if not lastSwing or (tick() - lastSwing) > 0.25 then return false end
		end

		return sword, meta
	end

	local function getAttackData()
		local now = os.clock()
		if now - _adCacheTime < 0.02 and _adCacheSword then
			return _adCacheSword, _adCacheMeta
		end
		_adCacheTime = now
		local sword, meta = computeAttackData()
		_adCacheSword = sword
		_adCacheMeta = meta
		return sword, meta
	end

	local function resetSwordCooldown()
		if bedwars.SwordController then
			bedwars.SwordController.lastAttack = 0
			bedwars.SwordController.lastSwing = 0
			if bedwars.SwordController.lastChargedAttackTimeMap then
				for weaponName in pairs(bedwars.SwordController.lastChargedAttackTimeMap) do
					bedwars.SwordController.lastChargedAttackTimeMap[weaponName] = 0
				end
			end
		end
	end

	local function getWeaponAttackSpeed(sword, meta)
		if not sword or not sword.tool then return HIT_PERIOD end
		local toolName = sword.tool.Name:lower()

		if toolName:find('frosty_hammer') then
			local speedLvl = lplr:GetAttribute('speed') or sword.tool:GetAttribute('speed') or 0
			if speedLvl == 3 then
				return 0.25
			elseif speedLvl == 2 then
				return 0.28
			elseif speedLvl == 1 then
				return 0.32
			else
				return 0.35
			end
		end

		if meta and meta.sword and meta.sword.attackSpeed then
			return meta.sword.attackSpeed
		end

		return HIT_PERIOD
	end

	local function triggerFirstPersonSwing(meta)
		pcall(function()
			local tool = store.hand and store.hand.tool
			local toolName = tool and tool.Name:lower() or ""

			local syncEvents = bedwars.ClientSyncEvents or (bedwars.Client and bedwars.Client:GetNamespace('Default'))
			if syncEvents and syncEvents:Get('SwordSwing') then
				syncEvents:Get('SwordSwing'):Fire({ player = lplr })
			end

			if bedwars.SwordController and meta then
				bedwars.SwordController:playSwordEffect(meta, true)
			end

			if bedwars.ViewmodelController and bedwars.ViewmodelController.playAnimation then
				if toolName:find('chainsaw') or toolName:find('tinker') or toolName:find('wood') then
					bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.SWORD_SWING or bedwars.AnimationType.FP_USE_ITEM or 15)
				elseif bedwars.AnimationType and bedwars.AnimationType.SWORD_SWING then
					bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.SWORD_SWING)
				end
			end
		end)
	end

	-- FAST HITS & PROJECTILES
	local function getAmmo(check)
		for _, item in store.inventory.inventory.items do
			if check.ammoItemTypes and table.find(check.ammoItemTypes, item.itemType) then
				return item.itemType
			end
		end
	end

	local _projectilesCache = {}
	local _projectilesCacheTime = 0
	local function getProjectiles()
		if not Arrows or not Arrows.Enabled then return {} end
		local now = tick()
		if now - _projectilesCacheTime < 0.5 and #_projectilesCache > 0 then
			return _projectilesCache
		end
		_projectilesCacheTime = now
		table.clear(_projectilesCache)
		for _, item in store.inventory.inventory.items do
			local meta = bedwars.ItemMeta[item.itemType]
			if not meta then continue end
			local proj = meta.projectileSource
			if not proj or not proj.projectileType then continue end
			local ammo = getAmmo(proj)
			if not ammo then continue end
			local projType = proj.projectileType(ammo)
			local pmeta = projType and bedwars.ProjectileMeta[projType]
			if pmeta and pmeta.arrow and pmeta.launchVelocity then
				table.insert(_projectilesCache, {item, ammo, projType, proj})
			end
		end
		return _projectilesCache
	end

	local function canShoot(proj)
		return tick() > (ProjectileDelay[proj[1].itemType] or 0)
	end

	local sharedFastHitsRayParams = RaycastParams.new()
	sharedFastHitsRayParams.FilterType = Enum.RaycastFilterType.Exclude

	local fhBusy = false

	local function fhInAngle(v)
		if not AngleSlider or AngleSlider.Value >= 360 then return true end
		if not v or not v.RootPart then return false end
		local root = entitylib.character and entitylib.character.RootPart
		if not root then return false end
		local look = root.CFrame.LookVector
		local flatLook = look * Vector3.new(1, 0, 1)
		if flatLook.Magnitude < 0.001 then return true end
		local flat = (v.RootPart.Position - root.Position) * Vector3.new(1, 0, 1)
		if flat.Magnitude <= 1 then return true end
		return math.acos(math.clamp(flatLook.Unit:Dot(flat.Unit), -1, 1)) <= math.rad(AngleSlider.Value) / 2
	end

	local function fhEquipAwait(tool)
		if not tool or not tool.Parent then return false end
		return switchItem(tool, 0.05) and true or false
	end

	local fhRestoreToken = 0
	local function fhRestoreSword()
		local sw = store.tools.sword
		if not sw or not sw.tool or not sw.tool.Parent then return end
		local check = lplr.Character and lplr.Character:FindFirstChild('HandInvItem')
		if not check then return end
		fhRestoreToken = fhRestoreToken + 1
		local token = fhRestoreToken
		check.Value = sw.tool
		task.spawn(function()
			pcall(function() bedwars.Client:Get(remotes.EquipItem):CallServerAsync({hand = sw.tool}) end)
			for _ = 1, 3 do
				task.wait(0.06)
				if token ~= fhRestoreToken then return end
				if not sw.tool.Parent then return end
				if not SilentAura or not SilentAura.Enabled then return end
				if check.Value ~= sw.tool or (store.hand and store.hand.tool ~= sw.tool) then
					check.Value = sw.tool
					pcall(function() bedwars.Client:Get(remotes.EquipItem):CallServerAsync({hand = sw.tool}) end)
				else
					return
				end
			end
		end)
	end

	local _fhVelHistory = {}
	local _fhPing = 0.1
	local _fhPingClock = 0
	local _fhIdChars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

	local function fhGenId()
		local out = table.create(8)
		for i = 1, 8 do
			local n = math.random(1, #_fhIdChars)
			out[i] = _fhIdChars:sub(n, n)
		end
		return table.concat(out)
	end

	local function getFHPing()
		if tick() - _fhPingClock < 1 then return _fhPing end
		_fhPingClock = tick()
		local ok, val = pcall(function()
			return game:GetService('Stats').Network.ServerStatsItem['Data Ping']:GetValue() / 1000
		end)
		_fhPing = (ok and val) and math.clamp(val, 0.02, 1) or 0.1
		return _fhPing
	end

	local function smoothedVelocity(ent, targetPart)
		local rawVel = targetPart.AssemblyLinearVelocity or targetPart.Velocity or Vector3.zero
		local key = tostring(ent)
		if not _fhVelHistory[key] then
			_fhVelHistory[key] = rawVel
		else
			_fhVelHistory[key] = _fhVelHistory[key]:Lerp(rawVel, 0.35)
		end
		return _fhVelHistory[key], rawVel
	end

	local function targetGravity(ent)
		local playerGravity = workspace.Gravity
		local balloons = ent.Character and ent.Character:GetAttribute('InflatedBalloons')
		if balloons and balloons > 0 then
			playerGravity = workspace.Gravity * (1 - (balloons >= 4 and 1.2 or balloons >= 3 and 1 or 0.975))
		end
		return playerGravity
	end

	local function shootProjectile(item, ammo, projectile, itemMeta, selfPos, ent, ignoreSwitch)
		local meta = bedwars.ProjectileMeta[projectile]
		if not meta then return false end

		local switched = false
		if not ignoreSwitch then
			fhBusy = true
			store._fhBusySince = workspace:GetServerTimeNow()
			if not fhEquipAwait(item.tool) then
				fhRestoreSword()
				fhBusy = false
				return false
			end
			switched = true
			local root = entitylib.character and entitylib.character.RootPart
			if not root then
				fhRestoreSword()
				fhBusy = false
				return false
			end
			selfPos = root.Position
		end

		local gravity = tonumber(meta.gravitationalAcceleration) or 196.2
		if gravity < 1 then gravity = 0 end
		local targetPart = ent.RootPart
		local playerGravity = targetGravity(ent)

		local maxCharge = tonumber(itemMeta.maxStrengthChargeSec) or 0
		local chargePct = (ArrowCharge and ArrowCharge.Value or 100) / 100
		local drawTime = maxCharge * chargePct
		local minScalar = tonumber(itemMeta.minStrengthScalar) or 1
		local chargeRatio = maxCharge > 0 and math.clamp(drawTime / maxCharge, 0, 1) or 1
		local projSpeed = meta.launchVelocity * (minScalar + (1 - minScalar) * chargeRatio)

		local ping = getFHPing()
		local smoothVel, rawVel = smoothedVelocity(ent, targetPart)
		smoothVel = Vector3.new(smoothVel.X, rawVel.Y, smoothVel.Z)
		local hip = ent.HipHeight or 2
		local aimPart = targetPart
		local aimOffset = hip * 0.15

		local leadPos = aimPart.Position + Vector3.new(0, aimOffset, 0)
		local netLead = math.clamp(ping, 0.02, 0.12)
		local vy = smoothVel.Y
		local dropY = vy * netLead
		if vy < -12 or vy > 12 then
			dropY = dropY - 0.5 * playerGravity * netLead * netLead
		end
		leadPos = leadPos + Vector3.new(smoothVel.X * netLead, dropY, smoothVel.Z * netLead)

		sharedFastHitsRayParams.FilterDescendantsInstances = {lplr.Character, gameCamera, ent.Character}

		local originPos = selfPos + Vector3.new(0, 1.5, 0)
		local calc, flightTime = prediction.SolveTrajectory(
			originPos, projSpeed, gravity, leadPos, smoothVel,
			playerGravity, ent.HipHeight or 2,
			ent.Jumping and 42.6 or nil, sharedFastHitsRayParams
		)

		local lifetime = tonumber(meta.predictionLifetimeSec) or tonumber(meta.lifetimeSec) or 3
		if not calc or (flightTime and flightTime > lifetime) then
			if switched then
				fhRestoreSword()
				fhBusy = false
			end
			return false
		end

		local shootPos = originPos
		local dir = CFrame.lookAt(shootPos, calc).LookVector
		local id = fhGenId()
		local shotMeta = {shotId = fhGenId(), drawDurationSec = drawTime, drawDurationSeconds = drawTime}

		targetinfo.Targets[ent] = tick() + 1
		ProjectileDelay[item.itemType] = tick() + (tonumber(itemMeta.fireDelaySec) or 0.5) + drawTime

		bedwars.ProjectileController:createLocalProjectile(
			meta, ammo, projectile, shootPos, id, dir * projSpeed, shotMeta
		)

		task.spawn(function()
			projectileRemote:InvokeServer(
				item.tool, ammo, projectile, shootPos, selfPos,
				dir * projSpeed, id, shotMeta,
				workspace:GetServerTimeNow() - ping
			)
		end)

		if switched then
			fhRestoreSword()
			fhBusy = false
		end
		return true
	end

	local function doFastHitsNEW(ent)
		if not ent or not ent.RootPart or not entitylib.isAlive then return end
		if not (Arrows and Arrows.Enabled) then return end
		local selfPos = entitylib.character.RootPart.Position

		local projectiles = getProjectiles()
		if projectiles and #projectiles > 0 then
			for _i = 1, #projectiles do
				fhUsageIndex = (fhUsageIndex or 0) % #projectiles + 1
				local p = projectiles[fhUsageIndex]
				if canShoot(p) then
					local item, ammo, projectile, itemMeta = unpack(p)
					if shootProjectile(item, ammo, projectile, itemMeta, selfPos, ent, false) then return end
					break
				end
			end
		end
	end

	local function doFastHitsLegitSwitch(ent)
		if not ent or not ent.RootPart or not entitylib.isAlive then return end
		local selfPos = entitylib.character.RootPart.Position

		local projectiles = getProjectiles()
		if not projectiles or #projectiles == 0 then return end

		local readyProj
		for _, proj in projectiles do
			if canShoot(proj) then
				readyProj = proj
				break
			end
		end
		if not readyProj then return end

		local item, ammo, projectile, itemMeta = unpack(readyProj)
		local bowSlot, swordSlot
		local originalSlot = store.inventory.hotbarSlot
		local hotbar = store.inventory.hotbar
		for i = 1, #hotbar do
			local hv = hotbar[i]
			if hv and hv.item and hv.item.itemType then
				if hv.item.itemType == item.itemType and not bowSlot then
					bowSlot = i - 1
				end
				if isMeleeWeapon(hv.item.itemType) and not swordSlot then
					swordSlot = i - 1
				end
			end
		end
		if not bowSlot then return end

		fhBusy = true
		store._fhBusySince = workspace:GetServerTimeNow()
		if hotbarSwitch(bowSlot) then task.wait(0.075) end
		shootProjectile(item, ammo, projectile, itemMeta, selfPos, ent, true)
		task.wait(0.075)
		hotbarSwitch(swordSlot or originalSlot)
		fhBusy = false
	end

	local function doFastHits()
		if not FastHits or not FastHits.Enabled then return end
		if not SilentAura or not SilentAura.Enabled then return end
		if not entitylib.isAlive then return end

		local sinceHit = workspace:GetServerTimeNow() - kaLastSrv
		if sinceHit < 0.02 or sinceHit > (kaPeriod * 0.45) then return end

		local selfRoot = entitylib.character and entitylib.character.RootPart
		if not selfRoot then return end

		local ent = store.KillauraTarget
		if not ent or not ent.RootPart then return end
		if not fhInAngle(ent) then return end
		if (ent.RootPart.Position - selfRoot.Position).Magnitude > getEffectiveRange() then return end

		if LegitSwitch and LegitSwitch.Enabled then
			doFastHitsLegitSwitch(ent)
		else
			doFastHitsNEW(ent)
		end
	end

	local function startAutoShootLoop()
		if autoShootLoop then return end
		if not ProjectileDelay then ProjectileDelay = {} end
		fhUsageIndex = 1
		table.clear(ProjectileDelay)

		autoShootLoop = task.spawn(function()
			while SilentAura and SilentAura.Enabled and FastHits and FastHits.Enabled do
				pcall(doFastHits)
				task.wait(0.075)
			end
			fhBusy = false
			autoShootLoop = nil
		end)
	end

	local function stopAutoShootLoop()
		if autoShootLoop then
			pcall(task.cancel, autoShootLoop)
			autoShootLoop = nil
		end
		if ProjectileDelay then table.clear(ProjectileDelay) end
		table.clear(_fhVelHistory)
		fhUsageIndex = 1
		fhBusy = false
	end

	local silentauraFireLoop
	local _graceTarget = nil
	local _graceUntil = 0
	local _fastAcqTime = 0
	local _fastAcqRes = {}

	local function withinAngle(v)
		if not AngleSlider or AngleSlider.Value >= 360 then return true end
		if not v or not v.RootPart then return false end
		local root = entitylib.character and entitylib.character.RootPart
		if not root then return true end
		local flatLV = root.CFrame.LookVector * Vector3.new(1, 0, 1)
		local facing = flatLV.Magnitude > 0.001 and flatLV.Unit or root.CFrame.RightVector
		local flat = (v.RootPart.Position - root.Position) * Vector3.new(1, 0, 1)
		if flat.Magnitude <= 1 then return true end
		return math.acos(math.clamp(facing:Dot(flat.Unit), -1, 1)) <= math.rad(AngleSlider.Value) / 2
	end

	local function inReach(v)
		local root = entitylib.character and entitylib.character.RootPart
		if not root or not v or not v.RootPart then return false end
		return (v.RootPart.Position - root.Position).Magnitude <= getEffectiveRange()
	end

	local function aliveTarget(v)
		if not v or not v.RootPart then return false end
		local char = v.Character
		if not char or not char.Parent then return false end
		if v.Health ~= nil and v.Health <= 0 then return false end
		return true
	end

	local function resolveTargets()
		local limitCount = MaxTargets and MaxTargets.Value or 1
		local list = entitylib.AllPosition({
			Range = getEffectiveRange(),
			Wallcheck = Targets.Walls.Enabled or nil,
			Part = 'RootPart',
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Limit = limitCount * 2,
			Sort = sortmethods[Sort.Value] or sortmethods['Distance']
		})
		local targets = {}
		for _, ent in list do
			if withinAngle(ent) and aliveTarget(ent) then
				table.insert(targets, ent)
				if #targets >= limitCount then break end
			end
		end
		return targets
	end

	local function attemptFire()
		if fhBusy and (workspace:GetServerTimeNow() - (store._fhBusySince or 0)) < 0.15 then return false end
		local targetList = resolveTargets()
		if #targetList == 0 then return false end

		local sword, meta = getAttackData()
		if not sword or not meta then return false end

		local weaponInst = sword.tool
		pcall(function()
			local inv = replicatedStorage:FindFirstChild('Inventories')
			local mine = inv and inv:FindFirstChild(lplr.Name)
			local w = mine and mine:FindFirstChild(sword.tool.Name)
			if w then weaponInst = w end
		end)

		local char = lplr.Character
		if not char or not char.PrimaryPart then return false end
		local selfPos = entitylib.character.RootPart.Position
		local maxDistLimit = getEffectiveRange()
		local firedAny = false

		for _, v in ipairs(targetList) do
			local tchar = v.Character
			if tchar and tchar.PrimaryPart then
				local targetPos = tchar.PrimaryPart.Position
				local dist = (targetPos - selfPos).Magnitude
				if dist <= maxDistLimit then
					local canHit = true
					if AirHit and AirHit.Enabled and AirHitsChance and AirHitsChance.Value < 100 then
						local hum = tchar:FindFirstChildOfClass('Humanoid')
						if hum then
							local inAir = hum.FloorMaterial == Enum.Material.Air
							if not inAir then
								local st = hum:GetState()
								inAir = st == Enum.HumanoidStateType.Jumping or st == Enum.HumanoidStateType.Freefall
							end
							if not inAir then
								local root = tchar.PrimaryPart
								local vy = root and root.AssemblyLinearVelocity.Y or 0
								inAir = math.abs(vy) > 3
							end
							if inAir and math.random(1, 100) > AirHitsChance.Value then
								canHit = false
							end
						end
					end

					if canHit and FireAttackRemote(weaponInst, tchar, selfPos, targetPos) then
						firedAny = true
						store.attackReach = (dist * 100) // 1 / 100
						store.attackReachUpdate = tick() + 1
					end
				end
			end
		end

		if not firedAny then return false end

		local srvNow = workspace:GetServerTimeNow()
		lastAttackTime = tick()

		kaLastSend = srvNow
		if kaLastSrv > 0 then
			kaLastSrv = kaLastSrv + kaPeriod
			if kaLastSrv < srvNow then kaLastSrv = srvNow end
		else
			kaLastSrv = srvNow
		end
		kaNextFire = 0

		if bedwars.SwordController then
			bedwars.SwordController.lastAttack = srvNow
		end
		return true
	end

	local function startSilentAuraFireLoop()
		if silentauraFireLoop then return end

		kaPeriod = HIT_PERIOD
		kaNextFire = 0
		kaLastSrv = 0
		kaLastSend = 0

		silentauraFireLoop = task.spawn(function()
			local frameDelta = 1 / 60
			local lastFrame = os.clock()
			while SilentAura and SilentAura.Enabled do
				runService.Heartbeat:Wait()
				local nowc = os.clock()
				local dt = nowc - lastFrame
				lastFrame = nowc
				if dt > 0 and dt < 0.25 then
					frameDelta = frameDelta + (dt - frameDelta) * 0.2
				end

				local sword, meta = getAttackData()
				if sword and meta then
					local dynamicSpd = getWeaponAttackSpeed(sword, meta)
					kaPeriod = (type(dynamicSpd) == 'number' and dynamicSpd >= 0.1) and (dynamicSpd * 0.976) or HIT_PERIOD
				else
					kaPeriod = HIT_PERIOD
				end

				local target = kaPeriod - math.min(frameDelta * 0.5, kaPeriod * 0.06)
				if (workspace:GetServerTimeNow() - kaLastSrv) >= target then
					pcall(attemptFire)
				end
			end
		end)
	end

	local function stopSilentAuraFireLoop()
		if silentauraFireLoop then
			pcall(task.cancel, silentauraFireLoop)
			silentauraFireLoop = nil
		end
		_graceTarget = nil
		_graceUntil = 0
		_fastAcqTime = 0
		table.clear(_fastAcqRes)
		kaNextFire = 0
		kaSync = 0
		kaSyncSrv = 0
	end

	SilentAura = vape.Categories.Combat:CreateModule({
		Name = 'SilentAura',
		Function = function(callback)
			if callback then
				lastAttackTime = 0
				lastTargetTime = 0
				resetSwordCooldown()

				if inputService.TouchEnabled and not preserveSwordIcon then
					pcall(function()
						lplr.PlayerGui.MobileUI['2'].Visible = Limit and Limit.Enabled
					end)
				end

				if FastHits and FastHits.Enabled then
					startAutoShootLoop()
				end

				startSilentAuraFireLoop()

				repeat
					if AttackCheck and AttackCheck.Enabled then
						local triggered = false
						local stunTime = lplr.Character and lplr.Character:GetAttribute('StunnedUntilTime')
						if stunTime and stunTime > workspace:GetServerTimeNow() then triggered = true end
						if not triggered and kitChecks then
							for _, check in pairs(kitChecks) do
								local ok, res = pcall(check)
								if ok and res then triggered = true break end
							end
						end
						if triggered then
							Attacking = false
							getgenv().Attacking = false
							store.KillauraTarget = nil
							_graceUntil = 0
							task.wait(0.3)
							continue
						end
					end

					local sword, meta = getAttackData()
					if not sword then
						if Attacking then
							Attacking = false
							getgenv().Attacking = false
							store.KillauraTarget = nil
						end
						task.wait(0.05)
						continue
					end

					if vapeTargetInfo and vapeTargetInfo.Targets then
						vapeTargetInfo.Targets.SilentAura = nil
					end

					if sword then
						local selfpos = entitylib.character.RootPart.Position
						local flatLV = entitylib.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
						local localfacing = flatLV.Magnitude > 0.001 and flatLV.Unit or entitylib.character.RootPart.CFrame.RightVector
						local maxAngle = math.rad(AngleSlider.Value) / 2

						local maxCount = MaxTargets and MaxTargets.Value or 1
						local attackPlrs = entitylib.AllPosition({
							Range = getEffectiveRange(),
							Wallcheck = Targets.Walls.Enabled or nil,
							Part = 'RootPart',
							Players = Targets.Players.Enabled,
							NPCs = Targets.NPCs.Enabled,
							Limit = maxCount * 2,
							Sort = sortmethods[Sort.Value] or sortmethods['Distance']
						})

						local function passesAngle(v)
							if AngleSlider.Value >= 360 then return true end
							local flat = (v.RootPart.Position - selfpos) * Vector3.new(1, 0, 1)
							if flat.Magnitude <= 1.0 then return true end
							return math.acos(math.clamp(localfacing:Dot(flat.Unit), -1, 1)) <= maxAngle
						end

						local validTargets = {}
						for _, v in attackPlrs do
							if passesAngle(v) then
								table.insert(validTargets, v)
								if #validTargets >= maxCount then break end
							end
						end

						if #validTargets > 0 then
							lastTargetTime = tick()
							if not Attacking then
								Attacking = true
								getgenv().Attacking = true
							end
							local chosen = validTargets[1]
							store.KillauraTarget = chosen
							for _, v in ipairs(validTargets) do
								targetinfo.Targets[v] = tick() + 1
							end

							if vapeTargetInfo and vapeTargetInfo.Targets then
								vapeTargetInfo.Targets.SilentAura = {
									Humanoid = {Health = chosen.Health, MaxHealth = chosen.MaxHealth},
									Player = chosen.Player
								}
							end

							if AnimDelay <= tick() then
								local allowSwingAnim = not (Swing and Swing.Enabled)
									and not (LegitAura and LegitAura.Enabled)
								if allowSwingAnim then
									AnimDelay = tick() + kaPeriod
									if isOnTinker() then
										playTinkerSwing()
									end
									triggerFirstPersonSwing(meta)
									if vape.ThreadFix and setthreadidentity then
										pcall(setthreadidentity, 8)
									end
								end
							end
						else
							if Attacking then
								Attacking = false
								getgenv().Attacking = false
								store.KillauraTarget = nil
							end
						end
					end

					task.wait()
				until not SilentAura.Enabled
			else
				stopAutoShootLoop()
				stopSilentAuraFireLoop()
				store.KillauraTarget = nil
				if inputService.TouchEnabled then
					pcall(function() lplr.PlayerGui.MobileUI['2'].Visible = true end)
				end
				Attacking = false
				getgenv().Attacking = false
				if vapeTargetInfo and vapeTargetInfo.Targets then
					vapeTargetInfo.Targets.SilentAura = nil
				end
			end
		end,
	})

	pcall(function()
		local PSI = SilentAura:CreateToggle({
			Name = 'Preserve Sword Icon',
			Function = function(callback)
				preserveSwordIcon = callback
			end,
			Default = true
		})
		PSI.Object.Visible = inputService.TouchEnabled
	end)

	Targets = SilentAura:CreateTargets({
		Players = true,
		NPCs = true
	})

	ExtraRange = SilentAura:CreateSlider({
		Name = 'Extra Range',
		Min = 0,
		Max = 6,
		Default = 0,
		Tooltip = 'Adds extra range (each integer = +3 studs)'
	})

	MaxTargets = SilentAura:CreateSlider({
		Name = 'Max Targets',
		Min = 1,
		Max = 5,
		Default = 1,
		Tooltip = 'Maximum number of targets to attack simultaneously'
	})

	AngleSlider = SilentAura:CreateSlider({
		Name = 'Max angle',
		Min = 1,
		Max = 360,
		Default = 360
	})

	Sort = SilentAura:CreateDropdown({
		Name = 'Target Mode',
		List = {'Cursor', 'Angle'}
	})

	Limit = SilentAura:CreateToggle({
		Name = 'Limit to items',
		Function = function(callback)
			if inputService.TouchEnabled and SilentAura.Enabled then
				pcall(function() lplr.PlayerGui.MobileUI['2'].Visible = callback end)
			end
		end,
		Tooltip = 'checks if you got sword held out'
	})

	LegitAura = SilentAura:CreateToggle({
		Name = 'Swing only',
		Tooltip = 'only swings when yu swing manually'
	})

	AirHit = SilentAura:CreateToggle({
		Name = 'Air Hits',
		Default = true,
		Tooltip = 'hit people in the air',
		Function = function(callback)
			if AirHitsChance then
				AirHitsChance.Object.Visible = callback
			end
		end
	})

	AirHitsChance = SilentAura:CreateSlider({
		Name = 'Air Hits Chance',
		Min = 0,
		Max = 100,
		Default = 100,
		Suffix = '%',
		Decimal = 5,
		Darker = true,
		Visible = false
	})

	kitChecks = {
		['Sigrid'] = function() return entitylib.isAlive and lplr.Character and lplr.Character:FindFirstChild('elk') ~= nil end,
	}

	AttackCheck = SilentAura:CreateToggle({
		Name = 'Attack Check',
		Tooltip = 'checks if attacking ina legit way',
		Default = false
	})

	FastHits = SilentAura:CreateToggle({
		Name = 'Fast Hits',
		Default = false,
		Tooltip = 'use projectiles mid pvp',
		Function = function(call)
			if ArrowCharge then ArrowCharge.Object.Visible = call end
			if LegitSwitch then LegitSwitch.Object.Visible = call end
			if Arrows then Arrows.Object.Visible = call end
			if call then
				if SilentAura and SilentAura.Enabled then
					startAutoShootLoop()
				end
			else
				stopAutoShootLoop()
			end
		end
	})

	ArrowCharge = SilentAura:CreateSlider({
		Name = 'FastHits Delay',
		Suffix = '%',
		Min = 0,
		Max = 100,
		Default = 0.25,
		Darker = true,
		Visible = false,
	})

	LegitSwitch = SilentAura:CreateToggle({
		Name = 'Legit Switch',
		Default = false,
		Darker = true,
		Visible = false,
		Tooltip = 'switches to projectiles to lok legit'
	})

	Arrows = SilentAura:CreateToggle({
		Name = 'Arrows',
		Default = true,
		Darker = true,
		Visible = false,
		Tooltip = 'use projectile items that uses arrows'
	})

	task.defer(function()
		if AirHit and AirHit.Enabled and AirHitsChance and AirHitsChance.Object then
			AirHitsChance.Object.Visible = true
		end
		if FastHits and FastHits.Enabled then
			if ArrowCharge then ArrowCharge.Object.Visible = true end
			if LegitSwitch then LegitSwitch.Object.Visible = true end
			if Arrows then Arrows.Object.Visible = true end
		end
	end)
end)

local Attacking
run(function()
	local HitRegisterFixer
	local lastAttackTime = 0
	local lastTargetTime = 0
	local HIT_PERIOD = 0.2974
	local kaPeriod = HIT_PERIOD
	local kaNextFire = 0
	local kaLastSrv = 0
	local kaLastSend = 0
	local fhBusy = false
	local AttackRemote

	task.spawn(function()
		task.wait()
		local _remotes = getgenv().remotes or remotes
		if _remotes and _remotes.AttackEntity and bedwars.Client then
			pcall(function()
				AttackRemote = bedwars.Client:Get(_remotes.AttackEntity).instance
			end)
		end
	end)

	local function getTargetRange()
		return 14.399
	end

	local function FireAttackRemote(weapon, entityInstance, selfPos, targetPos)
		if not AttackRemote then return false end

		local delta = (targetPos - selfPos).Magnitude
		if delta < 0.01 then return false end

		local maxR = getTargetRange()
		local dir = CFrame.lookAt(selfPos, targetPos).LookVector
		local pos = selfPos + dir * math.max(delta - maxR, 0)

		AttackRemote:FireServer({
			weapon = weapon,
			chargedAttack = {chargeRatio = 0},
			entityInstance = entityInstance,
			validate = {
				raycast = {
					cameraPosition = {value = pos},
					cursorDirection = {value = dir}
				},
				targetPosition = {value = targetPos},
				selfPosition = {value = pos}
			}
		})
		return true
	end

	local function computeAttackData()
		if not entitylib.isAlive then return false end

		local casting = lplr:GetAttribute('IsCasting')
		if casting ~= nil and casting ~= false and casting ~= 0 and casting ~= '' then
			if casting == true then return false end
			if type(casting) == 'number' and casting > workspace:GetServerTimeNow() then return false end
		end

		if bedwars.SwordController and bedwars.SwordController.disableSwingState then return false end

		local stunned = lplr.Character and lplr.Character:GetAttribute('StunnedUntilTime')
		if stunned and stunned > workspace:GetServerTimeNow() then return false end

		local sword = store.hand
		if not store.hand or not store.hand.tool then
			sword = store.tools.sword
		end
		if not sword or not sword.tool then return false end

		local meta = bedwars.ItemMeta[sword.tool.Name]
		if not meta then return false end

		return sword, meta
	end

	local function getAttackData()
		local sword, meta = computeAttackData()
		return sword, meta
	end

	-- Dynamically calculates weapon attack speed (supporting Adetunde frost hammers & axes)
	local function getWeaponAttackSpeed(sword, meta)
		if not sword or not sword.tool then return HIT_PERIOD end
		local toolName = sword.tool.Name:lower()

		-- Adetunde Frosty Hammer dynamic upgrade tiers
		if toolName:find('frosty_hammer') or toolName:find('frost') then
			local speedLvl = lplr:GetAttribute('speed') or sword.tool:GetAttribute('speed') or 0
			if speedLvl == 3 then
				return 0.25
			elseif speedLvl == 2 then
				return 0.28
			elseif speedLvl == 1 then
				return 0.32
			else
				return 0.35
			end
		end

		-- Check top-level or itemMeta sword attack speed
		if meta then
			if meta.sword and type(meta.sword.attackSpeed) == 'number' and meta.sword.attackSpeed > 0 then
				return meta.sword.attackSpeed
			end
			if type(meta.attackSpeed) == 'number' and meta.attackSpeed > 0 then
				return meta.attackSpeed
			end
		end

		-- Adetunde character attribute fallback
		local char = lplr.Character
		if char then
			local adetundeSpeed = char:GetAttribute('AdetundeAttackSpeed') or char:GetAttribute('AttackSpeedMultiplier')
			if type(adetundeSpeed) == 'number' and adetundeSpeed > 0 then
				return HIT_PERIOD / adetundeSpeed
			end
		end

		return HIT_PERIOD
	end

	local function resetSwordCooldown()
		if bedwars.SwordController then
			bedwars.SwordController.lastAttack = 0
			bedwars.SwordController.lastSwing = 0
			if bedwars.SwordController.lastChargedAttackTimeMap then
				for weaponName in pairs(bedwars.SwordController.lastChargedAttackTimeMap) do
					bedwars.SwordController.lastChargedAttackTimeMap[weaponName] = 0
				end
			end
		end
	end

	local hitregFireLoop
	local _graceTarget = nil
	local _graceUntil = 0
	local _fastAcqTime = 0
	local _fastAcqRes = nil

	local function withinAngle(v)
		if not v or not v.RootPart then return false end
		local root = entitylib.character and entitylib.character.RootPart
		if not root then return true end
		local flatLV = root.CFrame.LookVector * Vector3.new(1, 0, 1)
		local facing = flatLV.Magnitude > 0.001 and flatLV.Unit or root.CFrame.RightVector
		local flat = (v.RootPart.Position - root.Position) * Vector3.new(1, 0, 1)
		if flat.Magnitude <= 1 then return true end
		return math.acos(math.clamp(facing:Dot(flat.Unit), -1, 1)) <= math.rad(90) / 2
	end

	local function inReach(v)
		local root = entitylib.character and entitylib.character.RootPart
		if not root or not v or not v.RootPart then return false end
		return (v.RootPart.Position - root.Position).Magnitude <= getTargetRange()
	end

	local function aliveTarget(v)
		if not v or not v.RootPart then return false end
		local char = v.Character
		if not char or not char.Parent then return false end
		if v.Health ~= nil and v.Health <= 0 then return false end
		return true
	end

	local function resolveTarget()
		local v = store.KillauraTarget
		if aliveTarget(v) and withinAngle(v) and inReach(v) then
			_graceTarget = v
			_graceUntil = tick() + 0.4
			return v
		end
		if _graceTarget and tick() < _graceUntil then
			local g = _graceTarget
			if aliveTarget(g) and inReach(g) then
				return g
			end
		end
		local now = tick()
		if (now - _fastAcqTime) < 0.03 and _fastAcqRes then
			if not (aliveTarget(_fastAcqRes) and withinAngle(_fastAcqRes) and inReach(_fastAcqRes)) then return nil end
			return _fastAcqRes
		end
		_fastAcqTime = now
		_fastAcqRes = nil
		local list = entitylib.AllPosition({
			Range = getTargetRange(),
			Wallcheck = true,
			Part = 'RootPart',
			Players = true,
			NPCs = true,
			Limit = 5,
			Sort = sortmethods['Distance']
		})
		for _, ent in ipairs(list) do
			if withinAngle(ent) then
				_fastAcqRes = ent
				break
			end
		end
		return _fastAcqRes
	end

	local function attemptFire()
		if fhBusy and (workspace:GetServerTimeNow() - (store._fhBusySince or 0)) < 0.15 then return false end

		local lastSwing = bedwars.SwordController and bedwars.SwordController.lastSwing
		if not lastSwing or (tick() - lastSwing) > 0.2 then return false end

		local v = resolveTarget()
		if not v then return false end

		local sword, meta = getAttackData()
		if not sword or not meta then return false end

		-- Update kaPeriod dynamically using actual Adetunde / weapon speed
		local dynamicSpd = getWeaponAttackSpeed(sword, meta)
		kaPeriod = (type(dynamicSpd) == 'number' and dynamicSpd >= 0.1) and (dynamicSpd * 0.976) or HIT_PERIOD

		local weaponInst = sword.tool
		pcall(function()
			local inv = replicatedStorage:FindFirstChild('Inventories')
			local mine = inv and inv:FindFirstChild(lplr.Name)
			local w = mine and mine:FindFirstChild(sword.tool.Name)
			if w then weaponInst = w end
		end)
		local char = lplr.Character
		if not char or not char.PrimaryPart then return false end
		local tchar = v.Character
		if not tchar or not tchar.PrimaryPart then return false end
		local selfPos = entitylib.character.RootPart.Position
		local targetPos = tchar.PrimaryPart.Position
		local dist = (targetPos - selfPos).Magnitude
		if dist > getTargetRange() then return false end

		if not FireAttackRemote(weaponInst, tchar, selfPos, targetPos) then
			return false
		end

		local srvNow = workspace:GetServerTimeNow()

		lastAttackTime = tick()
		store.attackReach = (dist * 100) // 1 / 100
		store.attackReachUpdate = tick() + 1

		kaLastSend = srvNow
		if kaLastSrv > 0 then
			kaLastSrv = kaLastSrv + kaPeriod
			if kaLastSrv < srvNow then
				kaLastSrv = srvNow
			end
		else
			kaLastSrv = srvNow
		end
		kaNextFire = 0

		if bedwars.SwordController then
			bedwars.SwordController.lastAttack = srvNow
		end
		return true
	end

	local function starthitregFireLoop()
		if hitregFireLoop then return end

		kaPeriod = HIT_PERIOD
		kaNextFire = 0
		kaLastSrv = 0
		kaLastSend = 0

		hitregFireLoop = task.spawn(function()
			local frameDelta = 1 / 60
			local lastFrame = os.clock()
			while HitRegisterFixer and HitRegisterFixer.Enabled do
				runService.Heartbeat:Wait()
				local nowc = os.clock()
				local dt = nowc - lastFrame
				lastFrame = nowc
				if dt > 0 and dt < 0.25 then
					frameDelta = frameDelta + (dt - frameDelta) * 0.2
				end

				-- Re-calculate dynamic weapon attack speed continuously
				local sword, meta = getAttackData()
				if sword and meta then
					local dynamicSpd = getWeaponAttackSpeed(sword, meta)
					kaPeriod = (type(dynamicSpd) == 'number' and dynamicSpd >= 0.1) and (dynamicSpd * 0.976) or HIT_PERIOD
				else
					kaPeriod = HIT_PERIOD
				end

				local target = kaPeriod - math.min(frameDelta * 0.5, kaPeriod * 0.06)
				if (workspace:GetServerTimeNow() - kaLastSrv) >= target then
					pcall(attemptFire)
				end
			end
		end)
	end

	local function stophitregFireLoop()
		if hitregFireLoop then
			pcall(task.cancel, hitregFireLoop)
			hitregFireLoop = nil
		end
		_graceTarget = nil
		_graceUntil = 0
		_fastAcqTime = 0
		_fastAcqRes = nil
		kaNextFire = 0
	end

	local attacked = {}
	HitRegisterFixer = vape.Categories.Combat:CreateModule({
		Name = 'HitRegisterFixer',
		Function = function(callback)
			if callback then
				lastAttackTime = 0
				lastTargetTime = 0
				resetSwordCooldown()

				starthitregFireLoop()

				local _gatherCache = nil
				local _gatherCacheTime = 0
				local function gatherTargets()
					if _gatherCache and (tick() - _gatherCacheTime) < 0.05 then
						return _gatherCache[1], _gatherCache[2]
					end

					local sort = sortmethods['Distance']

					local function buildList(range)
						return entitylib.AllPosition({Range = range, Wallcheck = true, Part = 'RootPart', Players = true, NPCs = true, Limit = 1, Sort = sort})
					end

					local rMax = getTargetRange()
					local attackPlrs = buildList(rMax)
					local swingPlrs = buildList(rMax)
					_gatherCache = {swingPlrs, attackPlrs}
					_gatherCacheTime = tick()
					return swingPlrs, attackPlrs
				end

				local _cachedSwordType = nil

				repeat
					table.clear(attacked)
					local sword, meta = getAttackData()
					if not sword then
						if Attacking then
							Attacking = false
							getgenv().Attacking = false
							store.KillauraTarget = nil
						end
						task.wait(0.05)
						continue
					end

					if vapeTargetInfo and vapeTargetInfo.Targets then
						vapeTargetInfo.Targets.HitRegisterFixer = nil
					end

					if sword then
						local swordName = sword.tool.Name
						if swordName ~= _cachedSwordType and not fhBusy then
							_cachedSwordType = swordName
							resetSwordCooldown()
						end

						local selfpos = entitylib.character.RootPart.Position
						local flatLV = entitylib.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
						local localfacing = flatLV.Magnitude > 0.001 and flatLV.Unit or entitylib.character.RootPart.CFrame.RightVector
						local maxAngle = math.rad(90) / 2
						local swingPlrs, attackPlrs = gatherTargets()

						local function passesAngle(v)
							local flat = (v.RootPart.Position - selfpos) * Vector3.new(1, 0, 1)
							if flat.Magnitude <= 1.0 then return true end
							return math.acos(math.clamp(localfacing:Dot(flat.Unit), -1, 1)) <= maxAngle
						end

						local hasValidAttackTargets = false
						local chosen = nil

						for _, v in ipairs(attackPlrs) do
							if passesAngle(v) then
								hasValidAttackTargets = true
								chosen = v
								break
							end
						end

						if hasValidAttackTargets then
							lastTargetTime = tick()
						end

						if not hasValidAttackTargets and Attacking then
							Attacking = false
							getgenv().Attacking = false
							store.KillauraTarget = nil
						end

						if hasValidAttackTargets then
							if not fhBusy and store.hand and store.hand.tool ~= sword.tool and (tick() - (store._kaSwitch or 0)) > 0.25 then
								store._kaSwitch = tick()
								switchItem(sword.tool, 0)
							end

							if chosen then
								if not Attacking then
									Attacking = true
									getgenv().Attacking = true
								end
								store.KillauraTarget = chosen
								targetinfo.Targets[chosen] = tick() + 1

								if vapeTargetInfo and vapeTargetInfo.Targets then
									vapeTargetInfo.Targets.HitRegisterFixer = {
										Humanoid = {Health = chosen.Health, MaxHealth = chosen.MaxHealth},
										Player = chosen.Player
									}
								end
							end
						end
					end

					task.wait()
				until not HitRegisterFixer.Enabled
			else
				stophitregFireLoop()
				table.clear(attacked)
				store.KillauraTarget = nil
				Attacking = false
				getgenv().Attacking = false
				if vapeTargetInfo and vapeTargetInfo.Targets then
					vapeTargetInfo.Targets.HitRegisterFixer = nil
				end
			end
		end,
	})
end)

local Attacking
run(function()
	local Killaura
	local Targets
	local Sort
	local SwingRange
	local AttackRange
	local AngleSlider
	local Swing
	local Animation
	local AnimationMode
	local AnimationSpeed
	local AnimationTween
	local Limit
	local LegitAura
	local AttackCheck
	local kitChecks
	local SwingTime
	local SwingTimeSlider
	local AirHit
	local AirHitsChance
	local FastHits
	local LegitSwitch
	local Arrows
	local Gloops
	local GloopCooldown
	local Fireballs
	local FireballCooldown
	local ArrowCharge
	local UseKits
	local AttackRemote
	local lastAttackTime = 0
	local lastTargetTime = 0
	local anims, AnimDelay, AnimTween, armC0 = vape.Libraries.auraanims, tick()
	local FROZEN_THRESHOLD = 10
	local HIT_PERIOD = 0.2974
	local SERVER_FLOOR = 0.298
	local SERVER_REACH = 14.399
	local kaPeriod = HIT_PERIOD
	local kaNextFire = 0
	local kaSync = 0
	local kaSyncSrv = 0
	local kaLastSrv = 0
	local kaLastSend = 0
	local glueRemote = {InvokeServer = function() end}
	local projectileRemote = {InvokeServer = function() end}
	local gloopTracker = {}
	local fireballTracker = {}

	task.spawn(function()
		glueRemote = replicatedStorage:WaitForChild('rbxts_include'):WaitForChild('node_modules'):WaitForChild('@rbxts'):WaitForChild('net'):WaitForChild('out'):WaitForChild('_NetManaged'):WaitForChild('ProjectileFire')
	end)

	task.spawn(function()
		task.wait()
		local _remotes = getgenv().remotes or remotes
		projectileRemote = bedwars.Client:Get(_remotes.FireProjectile).instance
		pcall(function()
			AttackRemote = bedwars.Client:Get(_remotes.AttackEntity).instance
		end)
	end)

	local function getKnitControllers()
		return (bedwars.KnitClient and bedwars.KnitClient.Controllers) or (bedwars.Knit and bedwars.Knit.Controllers)
	end

	-- ONLY supported Use Kits are registered here
	local supportedKits = {
		['card'] = 'Fortuna',
		['fortuna'] = 'Fortuna',
		['dragon_slayer'] = 'Kaliyah',
		['kaliyah'] = 'Kaliyah',
		['ice_queen'] = 'Freiya',
		['freiya'] = 'Freiya',
		['void_hunter'] = 'Skoll',
		['skoll'] = 'Skoll',
		['regent'] = 'Void Regent',
		['void_regent'] = 'Void Regent',
		['hannah'] = 'Hannah',
		['spirit_assassin'] = 'Evelynn',
		['evelynn'] = 'Evelynn',
		['evelyn'] = 'Evelynn',
		['midnight'] = 'Nyx',
		['nyx'] = 'Nyx'
	}

	local function getSupportedKitDisplayName(rawKit)
		if not rawKit or rawKit == 'none' or rawKit == '' then return nil end
		local lower = tostring(rawKit):lower()
		for key, display in pairs(supportedKits) do
			if lower:find(key) then
				return display
			end
		end
		return nil
	end

	local function notifyKit(kitDisplayName)
		local title = 'Killaura'
		local msg = 'Set use kit to : ' .. tostring(kitDisplayName)
		if warningNotification then
			warningNotification(title, msg, 3)
		elseif vape and vape.CreateNotification then
			vape:CreateNotification(title, msg, 3)
		end
	end

	local function FireAttackRemote(weapon, entityInstance, selfPos, targetPos)
		if not AttackRemote then return false end

		local delta = (targetPos - selfPos).Magnitude
		if delta < 0.01 then return false end

		local dir = CFrame.lookAt(selfPos, targetPos).LookVector
		local pos = selfPos + dir * math.max(delta - 14.399, 0)

		AttackRemote:FireServer({
			weapon = weapon,
			chargedAttack = {chargeRatio = 0},
			entityInstance = entityInstance,
			validate = {
				raycast = {
					cameraPosition = {value = pos},
					cursorDirection = {value = dir}
				},
				targetPosition = {value = targetPos},
				selfPosition = {value = pos}
			}
		})
		return true
	end

	local function isOnTinker()
		local ok, mounted = pcall(function()
			local controllers = getKnitControllers()
			return controllers and controllers.TinkerKitController and controllers.TinkerKitController.mounted
		end)
		return ok and mounted == true
	end

	local _lastTinkerSwing = 0
	local function playTinkerSwing()
		local now = workspace:GetServerTimeNow()
		if now - _lastTinkerSwing < 0.35 then return end
		_lastTinkerSwing = now
		pcall(function()
			local controllers = getKnitControllers()
			local controller = controllers and controllers.TinkerKitController
			if not controller then return end
			local model = controller.userMap[lplr]
			if not model then return end
			local mac = controllers.MountAnimationController
			if not mac then return end
			local animId = bedwars.AnimationType and bedwars.AnimationType.TINKER_ATTACK
			mac:playAnimationInMount(model, animId, 1.85)
		end)
	end

	local _adCacheSword = nil
	local _adCacheMeta = nil
	local _adCacheTime = 0

	local function isMeleeWeapon(toolName)
		if not toolName then return false end
		local lower = toolName:lower()
		if lower:find('frosty_hammer') or lower:find('tinker') or lower:find('chainsaw') or lower:find('sword') or lower:find('blade') or lower:find('scythe') or lower:find('dagger') or lower:find('hammer') or lower:find('axe') then
			return true
		end
		local meta = bedwars.ItemMeta and bedwars.ItemMeta[toolName]
		return meta and (meta.sword ~= nil or meta.tinkerChainsaw ~= nil or meta.tinkerMech ~= nil)
	end

	local function computeAttackData()
		if not entitylib.isAlive then return false end

		local casting = lplr:GetAttribute('IsCasting')
		if casting ~= nil and casting ~= false and casting ~= 0 and casting ~= '' then
			if casting == true then return false end
			if type(casting) == 'number' and casting > workspace:GetServerTimeNow() then return false end
		end

		if bedwars.SwordController and bedwars.SwordController.disableSwingState then return false end

		local stunned = lplr.Character and lplr.Character:GetAttribute('StunnedUntilTime')
		if stunned and stunned > workspace:GetServerTimeNow() then return false end

		if AttackCheck and AttackCheck.Enabled then
			if kitChecks then
				for _, check in pairs(kitChecks) do
					local ok, res = pcall(check)
					if ok and res then return false end
				end
			end
		end

		if tick() - (store.silasAbilityTime or 0) < 2.2 then return false end
		if tick() - (store.terraStompTime or 0) < 0.7 then return false end
		if tick() - (store.terraKickTime or 0) < 0.5 then return false end

		local sword = store.hand
		if not sword or not sword.tool or not isMeleeWeapon(sword.tool.Name) then
			sword = (Limit and Limit.Enabled) and nil or store.tools.sword
		end
		if not sword or not sword.tool then return false end

		local meta = bedwars.ItemMeta[sword.tool.Name]
		if not meta then return false end

		if Limit and Limit.Enabled then
			if not isMeleeWeapon(sword.tool.Name) or (bedwars.DaoController and bedwars.DaoController.chargingMaid) then
				return false
			end
		end

		if LegitAura and LegitAura.Enabled then
			local lastSwing = bedwars.SwordController and bedwars.SwordController.lastSwing
			if not lastSwing or (tick() - lastSwing) > 0.25 then return false end
		end

		return sword, meta
	end

	local function getAttackData()
		local now = os.clock()
		if now - _adCacheTime < 0.02 and _adCacheSword then
			return _adCacheSword, _adCacheMeta
		end
		_adCacheTime = now
		local sword, meta = computeAttackData()
		_adCacheSword = sword
		_adCacheMeta = meta
		return sword, meta
	end

	local function resetSwordCooldown()
		if bedwars.SwordController then
			bedwars.SwordController.lastAttack = 0
			bedwars.SwordController.lastSwing = 0
			if bedwars.SwordController.lastChargedAttackTimeMap then
				for weaponName in pairs(bedwars.SwordController.lastChargedAttackTimeMap) do
					bedwars.SwordController.lastChargedAttackTimeMap[weaponName] = 0
				end
			end
		end
	end

	local function getWeaponAttackSpeed(sword, meta)
		if not sword or not sword.tool then return HIT_PERIOD end
		local toolName = sword.tool.Name:lower()

		if toolName:find('frosty_hammer') then
			local speedLvl = lplr:GetAttribute('speed') or sword.tool:GetAttribute('speed') or 0
			if speedLvl == 3 then
				return 0.25
			elseif speedLvl == 2 then
				return 0.28
			elseif speedLvl == 1 then
				return 0.32
			else
				return 0.35
			end
		end

		if meta and meta.sword and meta.sword.attackSpeed then
			return meta.sword.attackSpeed
		end

		return HIT_PERIOD
	end

	-- Play First-Person & Viewmodel Swing Animation (Supports All Hephaestus Chainsaw Tiers & Standard Swords)
	local function triggerFirstPersonSwing(meta)
		pcall(function()
			local tool = store.hand and store.hand.tool
			local toolName = tool and tool.Name:lower() or ""

			-- 1. Fire ClientSyncEvent SwordSwing
			local syncEvents = bedwars.ClientSyncEvents or (bedwars.Client and bedwars.Client:GetNamespace('Default'))
			if syncEvents and syncEvents:Get('SwordSwing') then
				syncEvents:Get('SwordSwing'):Fire({
					player = lplr
				})
			end

			-- 2. Play Sword Effect if meta is available
			if bedwars.SwordController and meta then
				bedwars.SwordController:playSwordEffect(meta, true)
			end

			-- 3. Force Viewmodel & Arm Swing for Wood/Base Chainsaw & All Tiers
			if bedwars.ViewmodelController and bedwars.ViewmodelController.playAnimation then
				if toolName:find('chainsaw') or toolName:find('tinker') or toolName:find('wood') then
					bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.SWORD_SWING or bedwars.AnimationType.FP_USE_ITEM or 15)
				elseif bedwars.AnimationType and bedwars.AnimationType.SWORD_SWING then
					bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.SWORD_SWING)
				end
			end
		end)
	end

	-- REAL-TIME USE KITS ENGINE
	local lastNotifiedKit = nil
	local skollMarked = false
	local skollMarkedTarget = nil
	local skollMarkedTime = 0
	local regentBusy = false
	local useKitLoop = nil
	local lastFortunaTime = 0
	local lastHannahTime = 0
	local lastEvelynnTime = 0
	local lastNyxTime = 0

	task.spawn(function()
		local ClientSyncEvents = bedwars.ClientSyncEvents or (bedwars.Client and bedwars.Client:GetNamespace('Default'))
		if ClientSyncEvents then
			pcall(function()
				ClientSyncEvents:Get('VoidHunter_TargetMarked'):Connect(function(data)
					skollMarked = true
					skollMarkedTime = tick()
					if data and data.target then
						skollMarkedTarget = data.target
					end
				end)
				ClientSyncEvents:Get('VoidHunter_TargetMarkedRemoved'):Connect(function()
					skollMarked = false
					skollMarkedTarget = nil
				end)
			end)
		end
	end)

	local function getCurrentKit()
		return store.equippedKit or lplr:GetAttribute('BedwarsKit') or 'none'
	end

	local function findVoidAxeSlot()
		for slot, entry in store.inventory.hotbar or {} do
			local item = entry and entry.item
			local tool = item and item.tool
			if (item and item.itemType == 'void_axe') or (tool and tool.Name == 'void_axe') then
				return slot - 1
			end
		end
		return nil
	end

	local function isInCombatWithTarget(target, maxDist)
		if not target or not target.RootPart or not entitylib.isAlive then return false end
		local myRoot = entitylib.character and entitylib.character.RootPart
		if not myRoot then return false end
		local dist = (target.RootPart.Position - myRoot.Position).Magnitude
		if dist > (maxDist or AttackRange.Value) then return false end

		if Attacking then return true end
		if LegitAura and LegitAura.Enabled then
			local lastSwing = bedwars.SwordController and bedwars.SwordController.lastSwing
			if lastSwing and (tick() - lastSwing) <= 0.35 then
				return true
			end
		end
		return (tick() - lastAttackTime) < 1.0 or (tick() - lastTargetTime) < 0.4
	end

	local function executeKitAbilities()
		if not UseKits or not UseKits.Enabled or not entitylib.isAlive then return end
		local rawKit = getCurrentKit()
		local supportedName = getSupportedKitDisplayName(rawKit)
		if not supportedName then return end

		local kit = tostring(rawKit):lower()
		local myRoot = entitylib.character and entitylib.character.RootPart
		if not myRoot then return end
		local myPos = myRoot.Position
		local target = store.KillauraTarget
		local controllers = getKnitControllers()

		-- 1. Fortuna (Card Throw)
		if kit:find('card') or kit:find('fortuna') then
			if target and target.Character and isInCombatWithTarget(target, 60) then
				if tick() - lastFortunaTime > 0.4 then
					lastFortunaTime = tick()
					if controllers and controllers.FortunaController then
						controllers.FortunaController.target = target.Character
					end
					pcall(function()
						if bedwars.AbilityController and bedwars.AbilityController:canUseAbility('CARD_THROW') then
							bedwars.AbilityController:useAbility('CARD_THROW')
						end
						local rem = replicatedStorage:FindFirstChild('events-@easy-games/game-core:shared/game-core-networking@getEvents.Events')
						if rem and rem:FindFirstChild('useAbility') then
							rem.useAbility:FireServer('CARD_THROW')
						end
						local _remotes = getgenv().remotes or remotes
						if _remotes and _remotes.AttemptCardThrow then
							bedwars.Client:Get(_remotes.AttemptCardThrow).instance:FireServer({ targetEntityInstance = target.Character })
						end
					end)
				end
			end

		-- 2. Kaliyah (dragon_slayer)
		elseif kit:find('dragon_slayer') or kit:find('kaliyah') then
			if bedwars.AbilityController and bedwars.AbilityController:canUseAbility('dragon_slayer_punch', {disableBlockedAbilityAlert = true}) then
				local requiredStacks = 3
				if bedwars.DragonSlayerController and bedwars.DragonSlayerController.dragonEmblems then
					for emblemTarget, v in pairs(bedwars.DragonSlayerController.dragonEmblems) do
						if v.stackCount >= requiredStacks and emblemTarget.PrimaryPart and (emblemTarget.PrimaryPart.Position - myPos).Magnitude <= 18 then
							bedwars.AbilityController:useAbility('dragon_slayer_punch')
							break
						end
					end
				end
			end

		-- 3. Freiya (ice_queen)
		elseif kit:find('ice_queen') or kit:find('freiya') then
			if bedwars.AbilityController and bedwars.AbilityController:canUseAbility('ice_queen', {disableBlockedAbilityAlert = true}) then
				for _, v in pairs(entitylib.List) do
					if v.Targetable and v.Character and (v.Character:GetAttribute('IceQueenStacks') or 0) >= 3 and v.RootPart and (v.RootPart.Position - myPos).Magnitude <= 40 then
						bedwars.AbilityController:useAbility('ice_queen')
						break
					end
				end
			end

		-- 4. Skoll (void_hunter)
		elseif kit:find('void_hunter') or kit:find('skoll') then
			if not skollMarked then
				if target and target.RootPart and isInCombatWithTarget(target, 22) then
					local targetPos = target.RootPart.Position
					local dir = (targetPos - myPos).Unit
					pcall(function()
						if bedwars.AbilityController then
							bedwars.AbilityController:useAbility('void_hunter_mark')
						elseif controllers and controllers.SelectItemController then
							controllers.SelectItemController:useMarkAbility(dir)
						end
					end)
				end
			else
				local shouldDetonate = false
				if skollMarkedTarget and skollMarkedTarget.Parent and skollMarkedTarget:FindFirstChild('HumanoidRootPart') then
					local tPos = skollMarkedTarget.HumanoidRootPart.Position
					if (tPos - myPos).Magnitude >= 35 then
						shouldDetonate = true
					end
				elseif (tick() - skollMarkedTime) > 5 then
					shouldDetonate = true
				end

				if shouldDetonate and bedwars.AbilityController then
					pcall(function() bedwars.AbilityController:useAbility('void_hunter_detonate') end)
				end
			end

		-- 5. Void Regent (void_axe)
		elseif kit:find('void_regent') or kit:find('regent') then
			if not regentBusy and bedwars.VoidAxeController and bedwars.AbilityController and bedwars.AbilityController:canUseAbility('void_axe_jump', {disableBlockedAbilityAlert = true}) then
				if target and target.RootPart and isInCombatWithTarget(target, 16) then
					local axeSlot = findVoidAxeSlot()
					if axeSlot ~= nil then
						regentBusy = true
						local oldSlot = store.inventory.hotbarSlot
						bedwars.Store:dispatch({type = 'InventorySelectHotbarSlot', slot = axeSlot})
						task.wait(0.02)
						if entitylib.isAlive then
							bedwars.VoidAxeController:useVoidAxe()
						end
						task.delay(0.2, function()
							if oldSlot ~= nil and entitylib.isAlive then
								bedwars.Store:dispatch({type = 'InventorySelectHotbarSlot', slot = oldSlot})
							end
							regentBusy = false
						end)
					end
				end
			end

		-- 6. Hannah (Blood For Blood Execution)
		elseif kit:find('hannah') then
			if target and target.Character and (tick() - lastHannahTime) > 0.2 then
				if (target.RootPart.Position - myPos).Magnitude <= 16 then
					local icon = target.Character:FindFirstChild('Hannah Execution Icon')
					local hasTag = collectionService:HasTag(target.Character, 'HannahExecuteInteraction')
					if icon or hasTag then
						lastHannahTime = tick()
						pcall(function()
							local _remotes = getgenv().remotes or remotes
							if _remotes and _remotes.HannahPromptTrigger then
								bedwars.Client:Get(_remotes.HannahPromptTrigger):CallServer({
									user = lplr,
									victimEntity = target.Character
								})
							end
						end)
					end
				end
			end

		-- 7. Evelynn (Spirit Assassin / Orb Auto-Consume via SpiritAssassinController)
		elseif kit:find('spirit_assassin') or kit:find('evelynn') or kit:find('evelyn') then
			if (tick() - lastEvelynnTime) > 0.15 then
				pcall(function()
					local evelynnController = bedwars.SpiritAssassinController or (controllers and controllers.SpiritAssassinController)
					for _, obj in ipairs(collectionService:GetTagged('EvelynnSoul')) do
						local part = obj:IsA('Model') and obj.PrimaryPart or (obj:IsA('BasePart') and obj)
						if part and (part.Position - myPos).Magnitude <= 40 then
							lastEvelynnTime = tick()
							if evelynnController and evelynnController.useSpirit then
								evelynnController:useSpirit(lplr, obj)
							else
								local _remotes = getgenv().remotes or remotes
								if _remotes and _remotes.SpiritAssassinUseSpirit then
									bedwars.Client:Get(_remotes.SpiritAssassinUseSpirit):CallServer({ spiritInstance = obj })
								end
							end
							break
						end
					end
				end)
			end

		-- 8. Nyx (Midnight Ability)
		elseif kit:find('midnight') or kit:find('nyx') then
			if target and isInCombatWithTarget(target, 20) and (tick() - lastNyxTime) > 0.5 then
				lastNyxTime = tick()
				pcall(function()
					if bedwars.AbilityController then
						if bedwars.AbilityController:canUseAbility('midnight', {disableBlockedAbilityAlert = true}) then
							bedwars.AbilityController:useAbility('midnight')
						elseif bedwars.AbilityController:canUseAbility('nyx_ability', {disableBlockedAbilityAlert = true}) then
							bedwars.AbilityController:useAbility('nyx_ability')
						else
							local rem = replicatedStorage:FindFirstChild('events-@easy-games/game-core:shared/game-core-networking@getEvents.Events')
							if rem and rem:FindFirstChild('useAbility') then
								rem.useAbility:FireServer('midnight')
							end
						end
					end
				end)
			end
		end
	end

	local function startUseKitsLoop()
		if useKitLoop then return end
		local activeKit = getCurrentKit()
		local supportedName = getSupportedKitDisplayName(activeKit)
		if supportedName then
			lastNotifiedKit = supportedName
			notifyKit(supportedName)
		else
			lastNotifiedKit = nil
		end

		useKitLoop = task.spawn(function()
			while UseKits and UseKits.Enabled do
				local currentKit = getCurrentKit()
				local currentSupported = getSupportedKitDisplayName(currentKit)
				if currentSupported and currentSupported ~= lastNotifiedKit then
					lastNotifiedKit = currentSupported
					notifyKit(currentSupported)
				elseif not currentSupported then
					lastNotifiedKit = nil
				end
				pcall(executeKitAbilities)
				task.wait(0.08)
			end
			useKitLoop = nil
		end)
	end

	local function stopUseKitsLoop()
		if useKitLoop then
			pcall(task.cancel, useKitLoop)
			useKitLoop = nil
		end
		lastNotifiedKit = nil
	end

	-- FAST HITS & PROJECTILES
	local function getAmmo(check)
		for _, item in store.inventory.inventory.items do
			if check.ammoItemTypes and table.find(check.ammoItemTypes, item.itemType) then
				return item.itemType
			end
		end
	end

	local _projectilesCache = {}
	local _projectilesCacheTime = 0
	local function getProjectiles()
		if not Arrows or not Arrows.Enabled then return {} end
		local now = tick()
		if now - _projectilesCacheTime < 0.5 and #_projectilesCache > 0 then
			return _projectilesCache
		end
		_projectilesCacheTime = now
		table.clear(_projectilesCache)
		for _, item in store.inventory.inventory.items do
			local meta = bedwars.ItemMeta[item.itemType]
			if not meta then continue end
			local proj = meta.projectileSource
			if not proj or not proj.projectileType then continue end
			local ammo = getAmmo(proj)
			if not ammo then continue end
			local projType = proj.projectileType(ammo)
			local pmeta = projType and bedwars.ProjectileMeta[projType]
			if pmeta and pmeta.arrow and pmeta.launchVelocity then
				table.insert(_projectilesCache, {item, ammo, projType, proj})
			end
		end
		return _projectilesCache
	end

	local function canShoot(proj)
		return tick() > (ProjectileDelay[proj[1].itemType] or 0)
	end

	local sharedFastHitsRayParams = RaycastParams.new()
	sharedFastHitsRayParams.FilterType = Enum.RaycastFilterType.Exclude

	local fhBusy = false

	local function fhInAngle(v)
		if not AngleSlider or AngleSlider.Value >= 360 then return true end
		if not v or not v.RootPart then return false end
		local root = entitylib.character and entitylib.character.RootPart
		if not root then return false end
		local look = root.CFrame.LookVector
		local flatLook = look * Vector3.new(1, 0, 1)
		if flatLook.Magnitude < 0.001 then return true end
		local flat = (v.RootPart.Position - root.Position) * Vector3.new(1, 0, 1)
		if flat.Magnitude <= 1 then return true end
		return math.acos(math.clamp(flatLook.Unit:Dot(flat.Unit), -1, 1)) <= math.rad(AngleSlider.Value) / 2
	end

	local function fhEquipAwait(tool)
		if not tool or not tool.Parent then return false end
		return switchItem(tool, 0.05) and true or false
	end

	local fhRestoreToken = 0
	local function fhRestoreSword()
		local sw = store.tools.sword
		if not sw or not sw.tool or not sw.tool.Parent then return end
		local check = lplr.Character and lplr.Character:FindFirstChild('HandInvItem')
		if not check then return end
		fhRestoreToken = fhRestoreToken + 1
		local token = fhRestoreToken
		check.Value = sw.tool
		task.spawn(function()
			pcall(function() bedwars.Client:Get(remotes.EquipItem):CallServerAsync({hand = sw.tool}) end)
			for _ = 1, 3 do
				task.wait(0.06)
				if token ~= fhRestoreToken then return end
				if not sw.tool.Parent then return end
				if not Killaura or not Killaura.Enabled then return end
				if check.Value ~= sw.tool or (store.hand and store.hand.tool ~= sw.tool) then
					check.Value = sw.tool
					pcall(function() bedwars.Client:Get(remotes.EquipItem):CallServerAsync({hand = sw.tool}) end)
				else
					return
				end
			end
		end)
	end

	local _fhVelHistory = {}
	local _fhPing = 0.1
	local _fhPingClock = 0
	local _fhIdChars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

	local function fhGenId()
		local out = table.create(8)
		for i = 1, 8 do
			local n = math.random(1, #_fhIdChars)
			out[i] = _fhIdChars:sub(n, n)
		end
		return table.concat(out)
	end

	local function getFHPing()
		if tick() - _fhPingClock < 1 then return _fhPing end
		_fhPingClock = tick()
		local ok, val = pcall(function()
			return game:GetService('Stats').Network.ServerStatsItem['Data Ping']:GetValue() / 1000
		end)
		_fhPing = (ok and val) and math.clamp(val, 0.02, 1) or 0.1
		return _fhPing
	end

	local function smoothedVelocity(ent, targetPart)
		local rawVel = targetPart.AssemblyLinearVelocity or targetPart.Velocity or Vector3.zero
		local key = tostring(ent)
		if not _fhVelHistory[key] then
			_fhVelHistory[key] = rawVel
		else
			_fhVelHistory[key] = _fhVelHistory[key]:Lerp(rawVel, 0.35)
		end
		return _fhVelHistory[key], rawVel
	end

	local function targetGravity(ent)
		local playerGravity = workspace.Gravity
		local balloons = ent.Character and ent.Character:GetAttribute('InflatedBalloons')
		if balloons and balloons > 0 then
			playerGravity = workspace.Gravity * (1 - (balloons >= 4 and 1.2 or balloons >= 3 and 1 or 0.975))
		end
		if ent.Character and ent.Character.PrimaryPart and ent.Character.PrimaryPart:FindFirstChild('rbxassetid://8200754399') then
			playerGravity = 6
		end
		if ent.Player and ent.Player:GetAttribute('IsOwlTarget') then
			local _owls = collectionService:GetTagged('Owl')
			if #_owls > 0 then
				local _uid = ent.Player.UserId
				for _, owl in ipairs(_owls) do
					if owl:GetAttribute('Target') == _uid and owl:GetAttribute('Status') == 2 then
						playerGravity = 0
						break
					end
				end
			end
		end
		return playerGravity
	end

	local function shootProjectile(item, ammo, projectile, itemMeta, selfPos, ent, ignoreSwitch)
		local meta = bedwars.ProjectileMeta[projectile]
		if not meta then return false end

		local switched = false
		if not ignoreSwitch then
			fhBusy = true
			store._fhBusySince = workspace:GetServerTimeNow()
			if not fhEquipAwait(item.tool) then
				fhRestoreSword()
				fhBusy = false
				return false
			end
			switched = true
			local root = entitylib.character and entitylib.character.RootPart
			if not root then
				fhRestoreSword()
				fhBusy = false
				return false
			end
			selfPos = root.Position
		end

		local gravity = tonumber(meta.gravitationalAcceleration) or 196.2
		if gravity < 1 then gravity = 0 end
		local targetPart = ent.RootPart
		local playerGravity = targetGravity(ent)

		local maxCharge = tonumber(itemMeta.maxStrengthChargeSec) or 0
		local chargePct = (ArrowCharge and ArrowCharge.Value or 100) / 100
		local drawTime = maxCharge * chargePct
		local multiAt = tonumber(itemMeta.multiShotChargeTime)
		if multiAt and chargePct >= 1 then
			drawTime = math.max(drawTime, multiAt)
		end
		local minScalar = tonumber(itemMeta.minStrengthScalar) or 1
		local chargeRatio = maxCharge > 0 and math.clamp(drawTime / maxCharge, 0, 1) or 1
		local projSpeed = meta.launchVelocity * (minScalar + (1 - minScalar) * chargeRatio)

		local ping = getFHPing()
		local smoothVel, rawVel = smoothedVelocity(ent, targetPart)
		smoothVel = Vector3.new(smoothVel.X, rawVel.Y, smoothVel.Z)
		local hip = ent.HipHeight or 2
		local aimPart = targetPart
		local aimOffset = hip * 0.15
		do
			local itype = tostring(item.itemType)
			local head = ent.Character and ent.Character:FindFirstChild('Head')
			local speed = tonumber(meta.launchVelocity) or 0
			local grav = tonumber(meta.gravitationalAcceleration) or 196.2
			local dist = (targetPart.Position - selfPos).Magnitude

			if itype:find('headhunter') then
				local hspeed = Vector3.new(smoothVel.X, 0, smoothVel.Z).Magnitude
				if head and dist < 90 and hspeed < 28 and math.abs(smoothVel.Y) < 30 then
					aimPart = head
					aimOffset = -0.35
				else
					aimOffset = hip * 0.15
				end
			elseif itype:find('bomb') or itype:find('grenade') or itype:find('santa') or itype:find('impulse') then
				aimOffset = -hip * 0.5
			elseif itype:find('rocket') or itype:find('launcher') or itype:find('firework') then
				aimOffset = 0
			elseif meta.arrow then
				if grav <= 40 and speed >= 200 and dist < 60 and head then
					aimPart = head
					aimOffset = 0
				else
					aimOffset = hip * 0.15
				end
			elseif itype:find('snowball') or itype:find('chakram') or itype:find('spell') then
				aimOffset = hip * 0.3
			end
		end
		local leadPos = aimPart.Position + Vector3.new(0, aimOffset, 0)
		local netLead = math.clamp(ping, 0.02, 0.12)
		local vy = smoothVel.Y
		local dropY = vy * netLead
		if vy < -12 or vy > 12 then
			dropY = dropY - 0.5 * playerGravity * netLead * netLead
		end
		leadPos = leadPos + Vector3.new(smoothVel.X * netLead, dropY, smoothVel.Z * netLead)

		sharedFastHitsRayParams.FilterDescendantsInstances = {lplr.Character, gameCamera, ent.Character}

		local originPos
		do
			local handle = item.tool and item.tool:FindFirstChild('Handle')
			local bo = handle and handle:FindFirstChild('BulletOrigin')
			if bo and bo:IsA('Attachment') then
				originPos = bo.WorldPosition
			else
				local char = entitylib.character and entitylib.character.Character
				local hand = char and (char:FindFirstChild('RightHand') or char:FindFirstChild('Right Arm'))
				if hand then
					originPos = hand.Position
				else
					local pp = entitylib.character and entitylib.character.RootPart
					originPos = pp and (pp.Position + Vector3.new(0, 1.5, 0)) or gameCamera.CFrame.Position
				end
			end
		end

		local calc, flightTime = prediction.SolveTrajectory(
			originPos, projSpeed, gravity, leadPos, smoothVel,
			playerGravity, ent.HipHeight or 2,
			ent.Jumping and 42.6 or nil, sharedFastHitsRayParams
		)

		local lifetime = tonumber(meta.predictionLifetimeSec) or tonumber(meta.lifetimeSec) or (projSpeed > 0 and math.min(3, 120 / projSpeed) or 3)
		if not calc or (flightTime and flightTime > lifetime) then
			if switched then
				fhRestoreSword()
				fhBusy = false
			end
			return false
		end

		local shootPos = originPos
		if meta.arrow then
			shootPos = (CFrame.new(originPos, calc) * CFrame.new(Vector3.new(-(bedwars.BowConstantsTable.RelX or 0), -(bedwars.BowConstantsTable.RelY or 0), -(bedwars.BowConstantsTable.RelZ or 0)))).Position
		end
		do
			local myRoot = entitylib.character and entitylib.character.RootPart
			if myRoot then
				local away = (calc - shootPos)
				if away.Magnitude > 0.01 then
					shootPos = shootPos + away.Unit * 2
				end
				local flat = (shootPos - myRoot.Position) * Vector3.new(1, 0, 1)
				if flat.Magnitude < 0.5 then
					shootPos = shootPos + Vector3.new(0, 0.5, 0)
				end
			end
		end
		local dir = CFrame.lookAt(shootPos, calc).LookVector
		local id = fhGenId()
		local shotMeta = {
			shotId = fhGenId(),
			drawDurationSec = drawTime,
			drawDurationSeconds = drawTime
		}

		targetinfo.Targets[ent] = tick() + 1
		ProjectileDelay[item.itemType] = tick() + (tonumber(itemMeta.fireDelaySec) or 0.5) + drawTime

		bedwars.ProjectileController:createLocalProjectile(
			meta, ammo, projectile, shootPos, id, dir * projSpeed,
			{drawDurationSec = drawTime, drawDurationSeconds = drawTime}
		)

		task.spawn(function()
			local res = projectileRemote:InvokeServer(
				item.tool, ammo, projectile, shootPos, selfPos,
				dir * projSpeed, id, shotMeta,
				workspace:GetServerTimeNow() - ping
			)
			if res then
				pcall(function() res.Parent = replicatedStorage end)
				local sound = itemMeta.launchSound
				sound = sound and sound[math.random(1, #sound)] or nil
				if sound and bedwars.SoundManager then
					pcall(function() bedwars.SoundManager:playSound(sound) end)
				end
			else
				ProjectileDelay[item.itemType] = tick() + (itemMeta.fireDelaySec or 0.5) + 0.1
			end
		end)

		if switched then
			fhRestoreSword()
			fhBusy = false
		end

		return true
	end

	local function getGloopItem()
		for _, item in store.inventory.inventory.items do
			if item.itemType == 'glue_projectile' then
				return item
			end
		end
		return nil
	end

	local function getFireballItem()
		for _, item in store.inventory.inventory.items do
			if item.itemType == 'fireball' then
				return item
			end
		end
		return nil
	end

	local function isGlooped(ent)
		local char = ent and ent.Character
		if not char then return false end
		local val = char:GetAttribute('GlueSlow')
		return val ~= nil and val ~= 0
	end

	local function shootGloop(item, ent)
		-- Strict check: throw Gloops ONLY on real players (not NPCs)
		if not ent or not ent.RootPart or not ent.Player then return false end
		local key = tostring(ent)
		local now = tick()
		local tracked = gloopTracker[key]

		if tracked and tracked.target == ent then
			if tracked.gloopedUntil and now < tracked.gloopedUntil then return false end
			if tracked.lastShot and (now - tracked.lastShot) < (GloopCooldown and GloopCooldown.Value or 6) then return false end
		end

		if isGlooped(ent) then
			gloopTracker[key] = {target = ent, lastShot = now, gloopedUntil = now + 8}
			return false
		end

		local myRoot = entitylib.character and entitylib.character.RootPart
		if not myRoot then return false end
		if (ent.RootPart.Position - myRoot.Position).Magnitude > 45 then return false end

		local selfPos = entitylib.character.RootPart.Position
		local targetPart = ent.RootPart

		local gmeta = bedwars.ProjectileMeta.glue_trap
		local gSpeed = tonumber(gmeta and gmeta.launchVelocity) or 100
		local gGrav = tonumber(gmeta and gmeta.gravitationalAcceleration) or 85
		if gGrav < 1 then gGrav = 0 end

		local gitem = bedwars.ItemMeta[item.itemType]
		local gMax = tonumber(gitem and gitem.maxStrengthChargeSec) or 0
		local gMin = tonumber(gitem and gitem.minStrengthScalar) or 1
		local gPct = (ArrowCharge and ArrowCharge.Value or 100) / 100
		local gRatio = gMax > 0 and math.clamp(gPct, 0, 1) or 1
		gSpeed = gSpeed * (gMin + (1 - gMin) * gRatio)

		local ping = getFHPing()
		local smoothVel, rawVel = smoothedVelocity(ent, targetPart)
		smoothVel = Vector3.new(smoothVel.X, rawVel.Y, smoothVel.Z)
		local playerGravity = targetGravity(ent)

		local aimPos = targetPart.Position - Vector3.new(0, (ent.HipHeight or 2) * 0.6, 0)
		local netLead = math.clamp(ping, 0.02, 0.12)
		local dropY = smoothVel.Y * netLead
		if smoothVel.Y < -12 or smoothVel.Y > 12 then
			dropY = dropY - 0.5 * playerGravity * netLead * netLead
		end
		aimPos = aimPos + Vector3.new(smoothVel.X * netLead, dropY, smoothVel.Z * netLead)

		sharedFastHitsRayParams.FilterDescendantsInstances = {lplr.Character, gameCamera, ent.Character}

		local originPos = selfPos + Vector3.new(0, 1.5, 0)
		local calc, gFlight = prediction.SolveTrajectory(
			originPos, gSpeed, gGrav, aimPos, smoothVel,
			playerGravity, ent.HipHeight or 2,
			ent.Jumping and 42.6 or nil, sharedFastHitsRayParams
		)
		local gLife = tonumber(gmeta and gmeta.predictionLifetimeSec) or 2
		if not calc or (gFlight and gFlight > gLife) then return false end

		local dir = CFrame.lookAt(originPos, calc).LookVector

		fhBusy = true
		store._fhBusySince = workspace:GetServerTimeNow()
		if not fhEquipAwait(item.tool) then
			fhRestoreSword()
			fhBusy = false
			return false
		end

		pcall(function()
			glueRemote:InvokeServer(
				replicatedStorage.Inventories[lplr.Name].glue_projectile,
				'glue_projectile',
				'glue_trap',
				originPos,
				selfPos,
				dir * gSpeed,
				httpService:GenerateGUID(true):sub(1, 8):upper(),
				{shotId = httpService:GenerateGUID(true):sub(1, 8):upper(), drawDurationSec = 0.05},
				workspace:GetServerTimeNow()
			)
		end)

		gloopTracker[key] = {target = ent, lastShot = now}
		fhRestoreSword()
		fhBusy = false
		return true
	end

	local function shootFireball(item, ent)
		if not ent or not ent.RootPart then return false end
		local key = tostring(ent)
		local now = tick()
		local tracked = fireballTracker[key]

		if tracked and tracked.lastShot and (now - tracked.lastShot) < (FireballCooldown and FireballCooldown.Value or 8) then
			return false
		end

		local myRoot = entitylib.character and entitylib.character.RootPart
		if not myRoot then return false end
		if (ent.RootPart.Position - myRoot.Position).Magnitude > 60 then return false end

		local selfPos = entitylib.character.RootPart.Position
		local targetPart = ent.RootPart

		local fmeta = bedwars.ProjectileMeta.fireball or {launchVelocity = 80, gravitationalAcceleration = 0}
		local fSpeed = tonumber(fmeta.launchVelocity) or 80
		local fGrav = tonumber(fmeta.gravitationalAcceleration) or 0

		local ping = getFHPing()
		local smoothVel, rawVel = smoothedVelocity(ent, targetPart)
		smoothVel = Vector3.new(smoothVel.X, rawVel.Y, smoothVel.Z)

		local aimPos = targetPart.Position
		local netLead = math.clamp(ping, 0.02, 0.12)
		aimPos = aimPos + Vector3.new(smoothVel.X * netLead, smoothVel.Y * netLead, smoothVel.Z * netLead)

		sharedFastHitsRayParams.FilterDescendantsInstances = {lplr.Character, gameCamera, ent.Character}

		local originPos = selfPos + Vector3.new(0, 1.5, 0)
		local calc = prediction.SolveTrajectory(
			originPos, fSpeed, fGrav, aimPos, smoothVel,
			workspace.Gravity, ent.HipHeight or 2,
			ent.Jumping and 42.6 or nil, sharedFastHitsRayParams
		)
		if not calc then calc = aimPos end

		local dir = CFrame.lookAt(originPos, calc).LookVector

		fhBusy = true
		store._fhBusySince = workspace:GetServerTimeNow()
		if not fhEquipAwait(item.tool) then
			fhRestoreSword()
			fhBusy = false
			return false
		end

		pcall(function()
			projectileRemote:InvokeServer(
				item.tool,
				'fireball',
				'fireball',
				originPos,
				selfPos,
				dir * fSpeed,
				httpService:GenerateGUID(true):sub(1, 8):upper(),
				{shotId = httpService:GenerateGUID(true):sub(1, 8):upper(), drawDurationSec = 0.05},
				workspace:GetServerTimeNow()
			)
		end)

		fireballTracker[key] = {target = ent, lastShot = now}
		fhRestoreSword()
		fhBusy = false
		return true
	end

	local fhStage = 1
	local function doFastHitsNEW(ent)
		if not ent or not ent.RootPart or not entitylib.isAlive then return end
		local selfPos = entitylib.character.RootPart.Position

		local anyOn = (Gloops and Gloops.Enabled) or (Fireballs and Fireballs.Enabled) or (Arrows and Arrows.Enabled)
		if not anyOn then return end

		for _ = 1, 3 do
			if fhStage == 1 then
				fhStage = 2
				if Gloops and Gloops.Enabled then
					local gloopItem = getGloopItem()
					if gloopItem and shootGloop(gloopItem, ent) then return end
				end
			elseif fhStage == 2 then
				fhStage = 3
				if Fireballs and Fireballs.Enabled then
					local fireballItem = getFireballItem()
					if fireballItem and shootFireball(fireballItem, ent) then return end
				end
			else
				fhStage = 1
				if Arrows and Arrows.Enabled then
					local projectiles = getProjectiles()
					if projectiles and #projectiles > 0 then
						for _i = 1, #projectiles do
							fhUsageIndex = fhUsageIndex % #projectiles + 1
							local p = projectiles[fhUsageIndex]
							if canShoot(p) then
								local item, ammo, projectile, itemMeta = unpack(p)
								if shootProjectile(item, ammo, projectile, itemMeta, selfPos, ent, false) then return end
								break
							end
						end
					end
				end
			end
		end
	end

	local function doFastHitsLegitSwitch(ent)
		if not ent or not ent.RootPart or not entitylib.isAlive then return end

		local selfPos = entitylib.character.RootPart.Position

		if Gloops and Gloops.Enabled then
			local gloopItem = getGloopItem()
			if gloopItem and shootGloop(gloopItem, ent) then return end
		end

		if Fireballs and Fireballs.Enabled then
			local fireballItem = getFireballItem()
			if fireballItem and shootFireball(fireballItem, ent) then return end
		end

		local projectiles = getProjectiles()
		if not projectiles or #projectiles == 0 then return end

		local readyProj
		for _, proj in projectiles do
			if canShoot(proj) then
				readyProj = proj
				break
			end
		end
		if not readyProj then return end

		local item, ammo, projectile, itemMeta = unpack(readyProj)
		local bowSlot, swordSlot
		local originalSlot = store.inventory.hotbarSlot
		local hotbar = store.inventory.hotbar
		for i = 1, #hotbar do
			local hv = hotbar[i]
			if hv and hv.item and hv.item.itemType then
				if hv.item.itemType == item.itemType and not bowSlot then
					bowSlot = i - 1
				end
				if isMeleeWeapon(hv.item.itemType) and not swordSlot then
					swordSlot = i - 1
				end
			end
		end
		if not bowSlot then return end

		fhBusy = true
		store._fhBusySince = workspace:GetServerTimeNow()
		if hotbarSwitch(bowSlot) then task.wait(0.075) end
		shootProjectile(item, ammo, projectile, itemMeta, selfPos, ent, true)
		task.wait(0.075)
		hotbarSwitch(swordSlot or originalSlot)
		fhBusy = false
	end

	local function doFastHits()
		if not FastHits or not FastHits.Enabled then return end
		if not Killaura or not Killaura.Enabled then return end
		if not entitylib.isAlive then return end

		local sinceHit = workspace:GetServerTimeNow() - kaLastSrv
		if sinceHit < 0.02 then return end
		if sinceHit > (kaPeriod * 0.45) then return end

		local selfRoot = entitylib.character and entitylib.character.RootPart
		if not selfRoot then return end

		local ent = store.KillauraTarget
		if not ent or not ent.RootPart then return end
		if not fhInAngle(ent) then return end
		if (ent.RootPart.Position - selfRoot.Position).Magnitude > SwingRange.Value then return end

		if LegitSwitch and LegitSwitch.Enabled then
			doFastHitsLegitSwitch(ent)
		else
			doFastHitsNEW(ent)
		end
	end

	local function startAutoShootLoop()
		if autoShootLoop then return end
		if not ProjectileDelay then ProjectileDelay = {} end
		fhUsageIndex = 1
		fhStage = 1
		table.clear(ProjectileDelay)

		autoShootLoop = task.spawn(function()
			while Killaura and Killaura.Enabled and FastHits and FastHits.Enabled do
				pcall(doFastHits)
				task.wait(0.075)
			end
			fhBusy = false
			autoShootLoop = nil
		end)
	end

	local function stopAutoShootLoop()
		if autoShootLoop then
			pcall(task.cancel, autoShootLoop)
			autoShootLoop = nil
		end
		if ProjectileDelay then table.clear(ProjectileDelay) end
		table.clear(_fhVelHistory)
		table.clear(gloopTracker)
		table.clear(fireballTracker)
		fhUsageIndex = 1
		fhStage = 1
		fhBusy = false
	end

	local killauraFireLoop
	local _graceTarget = nil
	local _graceUntil = 0
	local _fastAcqTime = 0
	local _fastAcqRes = nil

	local function withinAngle(v)
		if not AngleSlider or AngleSlider.Value >= 360 then return true end
		if not v or not v.RootPart then return false end
		local root = entitylib.character and entitylib.character.RootPart
		if not root then return true end
		local flatLV = root.CFrame.LookVector * Vector3.new(1, 0, 1)
		local facing = flatLV.Magnitude > 0.001 and flatLV.Unit or root.CFrame.RightVector
		local flat = (v.RootPart.Position - root.Position) * Vector3.new(1, 0, 1)
		if flat.Magnitude <= 1 then return true end
		return math.acos(math.clamp(facing:Dot(flat.Unit), -1, 1)) <= math.rad(AngleSlider.Value) / 2
	end

	local function inReach(v)
		local root = entitylib.character and entitylib.character.RootPart
		if not root or not v or not v.RootPart then return false end
		return (v.RootPart.Position - root.Position).Magnitude <= (AttackRange.Value + 0)
	end

	local function aliveTarget(v)
		if not v or not v.RootPart then return false end
		local char = v.Character
		if not char or not char.Parent then return false end
		if v.Health ~= nil and v.Health <= 0 then return false end
		return true
	end

	local function resolveTarget()
		local v = store.KillauraTarget
		if aliveTarget(v) and withinAngle(v) and inReach(v) then
			_graceTarget = v
			_graceUntil = tick() + 0.4
			return v
		end
		if _graceTarget and tick() < _graceUntil then
			local g = _graceTarget
			if aliveTarget(g) and inReach(g) then
				return g
			end
		end
		local now = tick()
		if (now - _fastAcqTime) < 0.03 and _fastAcqRes then
			if not (aliveTarget(_fastAcqRes) and withinAngle(_fastAcqRes) and inReach(_fastAcqRes)) then return nil end
			return _fastAcqRes
		end
		_fastAcqTime = now
		_fastAcqRes = nil
		local list = entitylib.AllPosition({
			Range = AttackRange.Value + 0,
			Wallcheck = Targets.Walls.Enabled or nil,
			Part = 'RootPart',
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Limit = 5,
			Sort = sortmethods[Sort.Value] or sortmethods['Distance']
		})
		for _, ent in list do
			if withinAngle(ent) then
				_fastAcqRes = ent
				break
			end
		end
		return _fastAcqRes
	end

	local function attemptFire()
		if fhBusy and (workspace:GetServerTimeNow() - (store._fhBusySince or 0)) < 0.15 then return false end
		local v = resolveTarget()
		if not v then return false end

		local sword, meta = getAttackData()
		if not sword or not meta then return false end

		local weaponInst = sword.tool
		pcall(function()
			local inv = replicatedStorage:FindFirstChild('Inventories')
			local mine = inv and inv:FindFirstChild(lplr.Name)
			local w = mine and mine:FindFirstChild(sword.tool.Name)
			if w then weaponInst = w end
		end)

		local char = lplr.Character
		if not char or not char.PrimaryPart then return false end
		local tchar = v.Character
		if not tchar or not tchar.PrimaryPart then return false end
		local selfPos = entitylib.character.RootPart.Position
		local targetPos = tchar.PrimaryPart.Position
		local dist = (targetPos - selfPos).Magnitude
		if dist > AttackRange.Value + 0 then return false end

		if AirHit and AirHit.Enabled and AirHitsChance and AirHitsChance.Value < 100 then
			local hum = tchar:FindFirstChildOfClass('Humanoid')
			if hum then
				local inAir = hum.FloorMaterial == Enum.Material.Air
				if not inAir then
					local st = hum:GetState()
					inAir = st == Enum.HumanoidStateType.Jumping or st == Enum.HumanoidStateType.Freefall
				end
				if not inAir then
					local root = tchar.PrimaryPart
					local vy = root and root.AssemblyLinearVelocity.Y or 0
					inAir = math.abs(vy) > 3
				end
				if inAir then
					if math.random(1, 100) > AirHitsChance.Value then return false end
				end
			end
		end

		if sword.tool.Name:find('summoner_claw') then
			pcall(function() KaidaController:request(tchar) end)
			return false
		end

		if not FireAttackRemote(weaponInst, tchar, selfPos, targetPos) then
			return false
		end

		local srvNow = workspace:GetServerTimeNow()

		lastAttackTime = tick()
		store.attackReach = (dist * 100) // 1 / 100
		store.attackReachUpdate = tick() + 1

		kaLastSend = srvNow
		if kaLastSrv > 0 then
			kaLastSrv = kaLastSrv + kaPeriod
			if kaLastSrv < srvNow then
				kaLastSrv = srvNow
			end
		else
			kaLastSrv = srvNow
		end
		kaNextFire = 0

		if bedwars.SwordController then
			bedwars.SwordController.lastAttack = srvNow
		end
		return true
	end

	local function startKillauraFireLoop()
		if killauraFireLoop then return end

		kaPeriod = HIT_PERIOD
		kaNextFire = 0
		kaLastSrv = 0
		kaLastSend = 0

		killauraFireLoop = task.spawn(function()
			local frameDelta = 1 / 60
			local lastFrame = os.clock()
			while Killaura and Killaura.Enabled do
				runService.Heartbeat:Wait()
				local nowc = os.clock()
				local dt = nowc - lastFrame
				lastFrame = nowc
				if dt > 0 and dt < 0.25 then
					frameDelta = frameDelta + (dt - frameDelta) * 0.2
				end

				local sword, meta = getAttackData()
				if sword and meta then
					local dynamicSpd = getWeaponAttackSpeed(sword, meta)
					kaPeriod = (type(dynamicSpd) == 'number' and dynamicSpd >= 0.1) and (dynamicSpd * 0.976) or HIT_PERIOD
				else
					kaPeriod = HIT_PERIOD
				end

				local target = kaPeriod - math.min(frameDelta * 0.5, kaPeriod * 0.06)
				if (workspace:GetServerTimeNow() - kaLastSrv) >= target then
					pcall(attemptFire)
				end
			end
		end)
	end

	local function stopKillauraFireLoop()
		if killauraFireLoop then
			pcall(task.cancel, killauraFireLoop)
			killauraFireLoop = nil
		end
		_graceTarget = nil
		_graceUntil = 0
		_fastAcqTime = 0
		_fastAcqRes = nil
		kaNextFire = 0
		kaSync = 0
		kaSyncSrv = 0
	end

	Killaura = vape.Categories.Blatant:CreateModule({
		Name = 'Killaura',
		Function = function(callback)
			if callback then
				lastAttackTime = 0
				lastTargetTime = 0
				resetSwordCooldown()

				if inputService.TouchEnabled and not preserveSwordIcon then
					pcall(function()
						lplr.PlayerGui.MobileUI['2'].Visible = Limit and Limit.Enabled
					end)
				end

				if FastHits and FastHits.Enabled then
					startAutoShootLoop()
				end

				if UseKits and UseKits.Enabled then
					startUseKitsLoop()
				end

				startKillauraFireLoop()

				if Animation and Animation.Enabled and not (identifyexecutor and table.find({'Argon', 'Delta'}, ({identifyexecutor()})[1])) then
					task.spawn(function()
						local started = false
						repeat
							if Attacking and not (LegitAura and LegitAura.Enabled) then
								if not armC0 then
									armC0 = gameCamera.Viewmodel.RightHand.RightWrist.C0
								end
								local first = not started
								started = true
								if AnimationMode.Value == 'Random' then
									anims.Random = {{CFrame = CFrame.Angles(math.rad(math.random(1, 360)), math.rad(math.random(1, 360)), math.rad(math.random(1, 360))), Time = 0.12}}
								end
								for _, v in anims[AnimationMode.Value] do
									if AnimTween then AnimTween:Destroy() AnimTween = nil end
									AnimTween = tweenService:Create(gameCamera.Viewmodel.RightHand.RightWrist, TweenInfo.new(first and (AnimationTween.Enabled and 0.001 or 0.1) or v.Time / AnimationSpeed.Value, Enum.EasingStyle.Linear), {
										C0 = armC0 * v.CFrame
									})
									AnimTween:Play()
									AnimTween.Completed:Wait()
									first = false
									if (not Killaura.Enabled) or (not Attacking) then break end
								end
							elseif started then
								started = false
								if AnimTween then AnimTween:Destroy() AnimTween = nil end
								AnimTween = tweenService:Create(gameCamera.Viewmodel.RightHand.RightWrist, TweenInfo.new(AnimationTween.Enabled and 0.001 or 0.3, Enum.EasingStyle.Exponential), {
									C0 = armC0
								})
								AnimTween:Play()
							end
							if not started then
								task.wait(1 / 3.5)
							end
						until (not Killaura.Enabled) or (not Animation.Enabled)
					end)
				end

				local _gatherCache = nil
				local _gatherCacheTime = 0
				local function gatherTargets()
					if _gatherCache and (tick() - _gatherCacheTime) < 0.05 then
						return _gatherCache[1], _gatherCache[2]
					end

					local walls = Targets.Walls.Enabled or nil
					local players = Targets.Players.Enabled
					local npcs = Targets.NPCs.Enabled
					local sort = sortmethods[Sort.Value]

					local function buildList(range)
						return entitylib.AllPosition({Range = range, Wallcheck = walls, Part = 'RootPart', Players = players, NPCs = npcs, Limit = 1, Sort = sort})
					end

					local attackPlrs = buildList(AttackRange.Value)
					local swingPlrs = AttackRange.Value == SwingRange.Value and attackPlrs or buildList(SwingRange.Value)
					_gatherCache = {swingPlrs, attackPlrs}
					_gatherCacheTime = tick()
					return swingPlrs, attackPlrs
				end

				local _cachedSwordType = nil
				local _cachedIsClaw = false

				repeat
					if AttackCheck and AttackCheck.Enabled then
						local triggered = false
						local stunTime = lplr.Character and lplr.Character:GetAttribute('StunnedUntilTime')
						if stunTime and stunTime > workspace:GetServerTimeNow() then triggered = true end
						if not triggered and kitChecks then
							for _, check in pairs(kitChecks) do
								local ok, res = pcall(check)
								if ok and res then triggered = true break end
							end
						end
						if triggered then
							Attacking = false
							getgenv().Attacking = false
							store.KillauraTarget = nil
							_graceUntil = 0
							task.wait(0.3)
							continue
						end
					end

					local sword, meta = getAttackData()
					if not sword then
						if Attacking then
							Attacking = false
							getgenv().Attacking = false
							store.KillauraTarget = nil
						end
						task.wait(0.05)
						continue
					end

					if vapeTargetInfo and vapeTargetInfo.Targets then
						vapeTargetInfo.Targets.Killaura = nil
					end

					if sword then
						local swordName = sword.tool.Name
						if swordName ~= _cachedSwordType and not fhBusy then
							_cachedSwordType = swordName
							_cachedIsClaw = swordName:find('summoner_claw') ~= nil
							resetSwordCooldown()
						end
						local isClaw = _cachedIsClaw

						local selfpos = entitylib.character.RootPart.Position
						local flatLV = entitylib.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
						local localfacing = flatLV.Magnitude > 0.001 and flatLV.Unit or entitylib.character.RootPart.CFrame.RightVector
						local maxAngle = math.rad(AngleSlider.Value) / 2
						local swingPlrs, attackPlrs = gatherTargets()

						local function passesAngle(v)
							if AngleSlider.Value >= 360 then return true end
							local flat = (v.RootPart.Position - selfpos) * Vector3.new(1, 0, 1)
							if flat.Magnitude <= 1.0 then return true end
							return math.acos(math.clamp(localfacing:Dot(flat.Unit), -1, 1)) <= maxAngle
						end

						local hasValidSwingTargets = false
						local hasValidAttackTargets = false
						local chosen = nil

						for _, v in swingPlrs do
							if passesAngle(v) then
								hasValidSwingTargets = true
								break
							end
						end

						for _, v in attackPlrs do
							if passesAngle(v) then
								hasValidAttackTargets = true
								chosen = v
								break
							end
						end

						if hasValidSwingTargets or hasValidAttackTargets then
							lastTargetTime = tick()
						end

						if not hasValidSwingTargets and not hasValidAttackTargets and Attacking then
							Attacking = false
							getgenv().Attacking = false
							store.KillauraTarget = nil
						end

						local shouldSwing = hasValidSwingTargets or hasValidAttackTargets
						local isLegitAura = LegitAura and LegitAura.Enabled

						if shouldSwing or isLegitAura then
							if not fhBusy and not regentBusy and store.hand and store.hand.tool ~= sword.tool and (tick() - (store._kaSwitch or 0)) > 0.25 then
								store._kaSwitch = tick()
								switchItem(sword.tool, 0)
							end

							if chosen then
								if not Attacking then
									Attacking = true
									getgenv().Attacking = true
								end
								store.KillauraTarget = chosen
								targetinfo.Targets[chosen] = tick() + 1

								if vapeTargetInfo and vapeTargetInfo.Targets then
									vapeTargetInfo.Targets.Killaura = {
										Humanoid = {Health = chosen.Health, MaxHealth = chosen.MaxHealth},
										Player = chosen.Player
									}
								end
							end

							if not isClaw and AnimDelay <= tick() then
								local allowSwingAnim = not (Swing and Swing.Enabled)
									and not (LegitAura and LegitAura.Enabled)
									and not (Animation and Animation.Enabled)
								if allowSwingAnim then
									local swingSpeed = (SwingTime and SwingTime.Enabled)
										and math.max(SwingTimeSlider.Value, 0.11)
										or kaPeriod
									AnimDelay = tick() + swingSpeed
									if isOnTinker() then
										playTinkerSwing()
									end
									triggerFirstPersonSwing(meta)
									if vape.ThreadFix and setthreadidentity then
										pcall(setthreadidentity, 8)
									end
								end
							end
						end
					end

					task.wait()
				until not Killaura.Enabled
			else
				stopAutoShootLoop()
				stopKillauraFireLoop()
				stopUseKitsLoop()
				store.KillauraTarget = nil
				if inputService.TouchEnabled then
					pcall(function() lplr.PlayerGui.MobileUI['2'].Visible = true end)
				end
				Attacking = false
				getgenv().Attacking = false
				if vapeTargetInfo and vapeTargetInfo.Targets then
					vapeTargetInfo.Targets.Killaura = nil
				end
				if armC0 then
					if AnimTween then AnimTween:Destroy() AnimTween = nil end
					AnimTween = tweenService:Create(gameCamera.Viewmodel.RightHand.RightWrist, TweenInfo.new(AnimationTween and AnimationTween.Enabled and 0.001 or 0.3, Enum.EasingStyle.Exponential), {
						C0 = armC0
					})
					AnimTween:Play()
				end
			end
		end,
	})

	pcall(function()
		local PSI = Killaura:CreateToggle({
			Name = 'Preserve Sword Icon',
			Function = function(callback)
				preserveSwordIcon = callback
			end,
			Default = true
		})
		PSI.Object.Visible = inputService.TouchEnabled
	end)

	Targets = Killaura:CreateTargets({
		Players = true,
		NPCs = true
	})

	SwingRange = Killaura:CreateSlider({
		Name = 'Swing range',
		Min = 1,
		Max = 40,
		Default = 22,
		Suffix = function(val) return val == 1 and 'stud' or 'studs' end
	})
	AttackRange = Killaura:CreateSlider({
		Name = 'Attack range',
		Min = 1,
		Max = 22,
		Default = 22,
		Suffix = function(val) return val == 1 and 'stud' or 'studs' end
	})
	AngleSlider = Killaura:CreateSlider({
		Name = 'Max angle',
		Min = 1,
		Max = 360,
		Default = 360
	})
	Sort = Killaura:CreateDropdown({
		Name = 'Target Mode',
		List = {'Cursor', 'Angle'}
	})
	SwingTime = Killaura:CreateToggle({
		Name = 'Custom Swing Time',
		Function = function(callback)
			if SwingTimeSlider then
				SwingTimeSlider.Object.Visible = callback
			end
		end,
		Tooltip = 'change ur swing time'
	})
	SwingTimeSlider = Killaura:CreateSlider({
		Name = 'Custom Swing Speed',
		Min = 0,
		Max = 1,
		Default = 0,
		Decimal = 100,
		Visible = false
	})
	Animation = Killaura:CreateToggle({
		Name = 'Custom Animation',
		Function = function(callback)
			if AnimationMode then AnimationMode.Object.Visible = callback end
			if AnimationTween then AnimationTween.Object.Visible = callback end
			if AnimationSpeed then AnimationSpeed.Object.Visible = callback end
			if Killaura.Enabled then
				Killaura:Toggle()
				Killaura:Toggle()
			end
		end
	})
	local animnames = {}
	for i in anims do table.insert(animnames, i) end
	AnimationMode = Killaura:CreateDropdown({
		Name = 'Animation Mode',
		List = animnames,
		Darker = true,
		Visible = false
	})
	AnimationSpeed = Killaura:CreateSlider({
		Name = 'Animation Speed',
		Min = 0.1,
		Max = 2,
		Default = 1,
		Decimal = 10,
		Darker = true,
		Visible = false
	})
	AnimationTween = Killaura:CreateToggle({Name = 'No Tween', Darker = true, Visible = false})

	Limit = Killaura:CreateToggle({
		Name = 'Limit to items',
		Function = function(callback)
			if inputService.TouchEnabled and Killaura.Enabled then
				pcall(function() lplr.PlayerGui.MobileUI['2'].Visible = callback end)
			end
		end,
		Tooltip = 'checks if you got sword held out'
	})
	LegitAura = Killaura:CreateToggle({
		Name = 'Swing only',
		Tooltip = 'only swings when yu swing manually'
	})
	AirHit = Killaura:CreateToggle({
		Name = 'Air Hits',
		Default = true,
		Tooltip = 'hit people in the air',
		Function = function(callback)
			if AirHitsChance then
				AirHitsChance.Object.Visible = callback
			end
		end
	})
	AirHitsChance = Killaura:CreateSlider({
		Name = 'Air Hits Chance',
		Min = 0,
		Max = 100,
		Default = 100,
		Suffix = '%',
		Decimal = 5,
		Darker = true,
		Visible = false
	})

	local _watchersActive = true
	Killaura:Clean(function()
		_watchersActive = false
	end)

	task.spawn(function()
		local wasAvailable = false
		local availSince = 0
		while _watchersActive and vape.Loaded do
			task.wait(0.05)
			if bedwars.AbilityController then
				local ok, nowAvailable = pcall(bedwars.AbilityController.canUseAbility, bedwars.AbilityController, 'rebellion_shield')
				if ok then
					nowAvailable = nowAvailable == true
					if nowAvailable and not wasAvailable then
						availSince = tick()
					end
					if wasAvailable and not nowAvailable and availSince > 0 and (tick() - availSince) > 1 then
						store.silasAbilityTime = tick()
					end
					wasAvailable = nowAvailable
				end
			end
		end
	end)

	task.spawn(function()
		local wasStomp, wasKick = false, false
		local stompSince, kickSince = 0, 0
		while _watchersActive and vape.Loaded do
			task.wait(0.05)
			if bedwars.AbilityController then
				local ok1, nowStomp = pcall(bedwars.AbilityController.canUseAbility, bedwars.AbilityController, 'BLOCK_STOMP')
				local ok2, nowKick = pcall(bedwars.AbilityController.canUseAbility, bedwars.AbilityController, 'BLOCK_KICK')
				if ok1 then
					nowStomp = nowStomp == true
					if nowStomp and not wasStomp then stompSince = tick() end
					if wasStomp and not nowStomp and stompSince > 0 and (tick() - stompSince) > 1 then
						store.terraStompTime = tick()
					end
					wasStomp = nowStomp
				end
				if ok2 then
					nowKick = nowKick == true
					if nowKick and not wasKick then kickSince = tick() end
					if wasKick and not nowKick and kickSince > 0 and (tick() - kickSince) > 1 then
						store.terraKickTime = tick()
					end
					wasKick = nowKick
				end
			end
		end
	end)

	kitChecks = {
		['Sigrid'] = function() return entitylib.isAlive and lplr.Character and lplr.Character:FindFirstChild('elk') ~= nil end,
	}

	AttackCheck = Killaura:CreateToggle({
		Name = 'Attack Check',
		Tooltip = 'checks if attacking ina legit way',
		Default = false
	})

	UseKits = Killaura:CreateToggle({
		Name = 'Use Kits',
		Default = true,
		Tooltip = 'Automatically detects kit and uses abilities in combat',
		Function = function(callback)
			if callback then
				if Killaura.Enabled then
					startUseKitsLoop()
				end
			else
				stopUseKitsLoop()
			end
		end
	})

	FastHits = Killaura:CreateToggle({
		Name = 'Fast Hits',
		Default = false,
		Tooltip = 'use projectiles mid pvp',
		Function = function(call)
			if ArrowCharge then ArrowCharge.Object.Visible = call end
			if LegitSwitch then LegitSwitch.Object.Visible = call end
			if Arrows then Arrows.Object.Visible = call end
			if Gloops then Gloops.Object.Visible = call end
			if GloopCooldown then GloopCooldown.Object.Visible = call and (Gloops and Gloops.Enabled) end
			if Fireballs then Fireballs.Object.Visible = call end
			if FireballCooldown then FireballCooldown.Object.Visible = call and (Fireballs and Fireballs.Enabled) end
			if call then
				if Killaura and Killaura.Enabled then
					startAutoShootLoop()
				end
			else
				stopAutoShootLoop()
			end
		end
	})
	ArrowCharge = Killaura:CreateSlider({
		Name = 'FastHits Delay',
		Suffix = '%',
		Min = 0,
		Max = 100,
		Default = 0.25,
		Darker = true,
		Visible = false,
	})	
	LegitSwitch = Killaura:CreateToggle({
		Name = 'Legit Switch',
		Default = false,
		Darker = true,
		Visible = false,
		Tooltip = 'switches to projectiles to lok legit'
	})
	Arrows = Killaura:CreateToggle({
		Name = 'Arrows',
		Default = true,
		Darker = true,
		Visible = false,
		Tooltip = 'use projectile items that uses arrows'
	})
	Gloops = Killaura:CreateToggle({
		Name = 'Gloops',
		Default = false,
		Darker = true,
		Visible = false,
		Tooltip = 'auto gloops real players in combat',
		Function = function(callback)
			if GloopCooldown then
				GloopCooldown.Object.Visible = callback
			end
		end
	})
	GloopCooldown = Killaura:CreateSlider({
		Name = 'Gloop Cooldown',
		Min = 1,
		Max = 15,
		Default = 10,
		Suffix = 's',
		Darker = true,
		Visible = false
	})
	Fireballs = Killaura:CreateToggle({
		Name = 'Fireballs',
		Default = false,
		Darker = true,
		Visible = false,
		Tooltip = 'auto throws fireballs at targets in combat',
		Function = function(callback)
			if FireballCooldown then
				FireballCooldown.Object.Visible = callback
			end
		end
	})
	FireballCooldown = Killaura:CreateSlider({
		Name = 'Fireball Cooldown',
		Min = 1,
		Max = 20,
		Default = 8,
		Suffix = 's',
		Darker = true,
		Visible = false
	})

	task.defer(function()
		if AirHit and AirHit.Enabled and AirHitsChance and AirHitsChance.Object then
			AirHitsChance.Object.Visible = true
		end
		if FastHits and FastHits.Enabled then
			if ArrowCharge then ArrowCharge.Object.Visible = true end
			if LegitSwitch then LegitSwitch.Object.Visible = true end
			if Arrows then Arrows.Object.Visible = true end
			if Gloops then Gloops.Object.Visible = true end
			if GloopCooldown then GloopCooldown.Object.Visible = (Gloops and Gloops.Enabled) end
			if Fireballs then Fireballs.Object.Visible = true end
			if FireballCooldown then FireballCooldown.Object.Visible = (Fireballs and Fireballs.Enabled) end
		end
	end)
end)

run(function()
	local ProjectileAura
	local Targets
	local Range
	local List
	local HandCheck
	local FireSpeed
    local rayCheck = cloneRaycast()
	local projectileRemote = {InvokeServer = function() end}
	local FireDelays = {}
	task.spawn(function()
		projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
	end)
	
	local function getAmmo(check)
		for _, item in store.inventory.inventory.items do
			if check.ammoItemTypes and table.find(check.ammoItemTypes, item.itemType) then
				return item.itemType
			end
		end
	end
	
	local function getProjectiles()
		local items = {}
		for _, item in store.inventory.inventory.items do
			local proj = bedwars.ItemMeta[item.itemType].projectileSource
			local ammo = proj and getAmmo(proj)
			if ammo and table.find(List.ListEnabled, ammo) then
				table.insert(items, {
					item,
					ammo,
					proj.projectileType(ammo),
					proj
				})
			end
		end
		return items
	end
	
	ProjectileAura = vape.Categories.Blatant:CreateModule({
		Name = 'ProjectileAura',
		Function = function(callback)
			if callback then
				repeat
					local holdingCrossbow = store.hand and store.hand.tool and store.hand.tool.Name:find('crossbow')
					local holdingBow = store.hand and store.hand.tool and store.hand.tool.Name:find('bow')
					
					if HandCheck.Enabled and not holdingCrossbow and not holdingBow then
						task.wait(0.1)
						continue
					end
					
					if (workspace:GetServerTimeNow() - bedwars.SwordController.lastAttack) > 0.5 then
						local ent = entitylib.EntityPosition({
							Part = 'RootPart',
							Range = Range.Value,
							Players = Targets.Players.Enabled,
							NPCs = Targets.NPCs.Enabled,
							Wallcheck = Targets.Walls.Enabled
						})
	
						if ent then
							local pos = entitylib.character.RootPart.Position
							for _, data in getProjectiles() do
								local item, ammo, projectile, itemMeta = unpack(data)
								if (FireDelays[item.itemType] or 0) < tick() then
									rayCheck.FilterDescendantsInstances = {workspace.Map}
									local meta = bedwars.ProjectileMeta[projectile]
									local projSpeed, gravity = meta.launchVelocity, meta.gravitationalAcceleration or 196.2
									local lifetime = tonumber(meta.predictionLifetimeSec) or tonumber(meta.lifetimeSec) or (projSpeed > 0 and math.min(3, 120 / projSpeed) or 3)
									local entGravity = workspace.Gravity
									local balloons = ent.Character and ent.Character:GetAttribute('InflatedBalloons')
									if balloons and balloons > 0 then
										entGravity = workspace.Gravity * (1 - (balloons >= 4 and 1.2 or balloons >= 3 and 1 or 0.975))
									end
									local entVel = ent.RootPart.AssemblyLinearVelocity or ent.RootPart.Velocity or Vector3.zero
									local calc = prediction.SolveTrajectory(pos, projSpeed, gravity, ent.RootPart.Position, entVel, entGravity, ent.HipHeight, ent.Jumping and 42.6 or nil, rayCheck, nil, 1, 1, lifetime)
									if calc then
										targetinfo.Targets[ent] = tick() + 1
										local switched = switchItem(item.tool)
	
										task.spawn(function()
											local dir, id = CFrame.lookAt(pos, calc).LookVector, httpService:GenerateGUID(true)
											local shootPosition = (CFrame.new(pos, calc) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position
											
											if holdingCrossbow then
												bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_CROSSBOW_FIRE)
												bedwars.GameAnimationUtil:playAnimation(lplr, bedwars.AnimationType.CROSSBOW_FIRE)
											elseif holdingBow then
												bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_CROSSBOW_FIRE)
												bedwars.GameAnimationUtil:playAnimation(lplr, bedwars.AnimationType.BOW_FIRE)
											else
												local shootAnim = bedwars.ItemMeta[item.tool.Name].thirdPerson and bedwars.ItemMeta[item.tool.Name].thirdPerson.shootAnimation
												if shootAnim then
													bedwars.GameAnimationUtil:playAnimation(lplr, shootAnim)
												end
											end
											
											bedwars.ProjectileController:createLocalProjectile(meta, ammo, projectile, shootPosition, id, dir * projSpeed, {drawDurationSeconds = 1})
											local res = projectileRemote:InvokeServer(item.tool, ammo, projectile, shootPosition, pos, dir * projSpeed, id, {drawDurationSeconds = 1, shotId = httpService:GenerateGUID(false)}, workspace:GetServerTimeNow() - 0.045)
											if not res then
												FireDelays[item.itemType] = tick()
											else
												local shoot = itemMeta.launchSound
												shoot = shoot and shoot[math.random(1, #shoot)] or nil
												if shoot then
													bedwars.SoundManager:playSound(shoot)
												end
											end
										end)
	
										FireDelays[item.itemType] = tick() + ((tonumber(itemMeta.fireDelaySec) or 0.5) / FireSpeed.Value)
										if switched then
											task.wait(0.05)
										end
									end
								end
							end
						end
					end
					task.wait(0.1)
				until not ProjectileAura.Enabled
			end
		end,
		Tooltip = 'Shoots people around you with viewmodel animations'
	})
	Targets = ProjectileAura:CreateTargets({
		Players = true,
		Walls = true
	})
	List = ProjectileAura:CreateTextList({
		Name = 'Projectiles',
		Default = {'arrow', 'snowball'}
	})
	Range = ProjectileAura:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 200,
		Default = 150,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})
	FireSpeed = ProjectileAura:CreateSlider({
		Name = 'Fire Speed',
		Min = 0.5,
		Max = 3,
		Default = 1,
		Decimal = 10,
	})
	HandCheck = ProjectileAura:CreateToggle({
		Name = 'Hand Check',
		Default = false,
		Tooltip = 'Only shoot when holding a bow or crossbow'
	})
end)

run(function()
	local Mode
	local Value
	local WallCheck
	local AutoJump
	local AlwaysJump
	local savedImpulseTime
	local rayCheck = cloneRaycast()
	rayCheck.RespectCanCollide = true
	rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
	
	Speed = vape.Categories.Blatant:CreateModule({
		Name = 'Speed',
		Function = function(callback)
			frictionTable.Speed = callback or nil
			updateVelocity()
			pcall(function()
				debug.setconstant(bedwars.WindWalkerController.updateSpeed, 7, callback and 'constantSpeedMultiplier' or 'moveSpeedMultiplier')
			end)
	
			if callback then
				if savedImpulseTime == nil then
					savedImpulseTime = bedwars.StatefulEntityKnockbackController.lastImpulseTime
				end
				Speed:Clean(function()
					pcall(function()
						bedwars.StatefulEntityKnockbackController.lastImpulseTime = (savedImpulseTime ~= nil and savedImpulseTime ~= math.huge) and savedImpulseTime or time()
					end)
					savedImpulseTime = nil
					pcall(function()
						if entitylib.isAlive then
							local root = entitylib.character.RootPart
							root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
						end
					end)
					pcall(function()
						bedwars.SprintController:setSpeed(bedwars.SprintController:isSprinting() and 20 or 14)
					end)
				end)
				Speed:Clean(runService.PreSimulation:Connect(function(dt)
					if not Speed.Enabled then return end
					bedwars.StatefulEntityKnockbackController.lastImpulseTime = math.huge
					if entitylib.isAlive then
						if not (Fly and Fly.Enabled) and not (LongJump and LongJump.Enabled) then
							bedwars.SprintController:setSpeed(Mode.Value == 'CFrame' and 20 or Value.Value)
							if Mode.Value == 'CFrame' then
								local state = entitylib.character.Humanoid:GetState()
								if state == Enum.HumanoidStateType.Climbing then return end
			
								local root, velo = entitylib.character.RootPart, getSpeed()
								local moveDirection = AntiFallDirection or entitylib.character.Humanoid.MoveDirection
								local destination = (moveDirection * math.max(Value.Value - velo, 0) * dt)
			
								if WallCheck.Enabled then
									rayCheck.CollisionGroup = root.CollisionGroup
									local ray = workspace:Raycast(root.Position, destination, rayCheck)
									if ray then
										destination = ((ray.Position + ray.Normal) - root.Position)
									end
								end
			
								root.CFrame += destination
								root.AssemblyLinearVelocity = (moveDirection * velo) + Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
								if AutoJump.Enabled and (state == Enum.HumanoidStateType.Running or state == Enum.HumanoidStateType.Landed) and moveDirection ~= Vector3.zero and (Attacking or AlwaysJump.Enabled) then
									entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
								end
							end
						end
					end
				end))
			else
				pcall(function()
					bedwars.StatefulEntityKnockbackController.lastImpulseTime = (savedImpulseTime ~= nil and savedImpulseTime ~= math.huge) and savedImpulseTime or time()
				end)
				savedImpulseTime = nil
				pcall(function()
					if entitylib.isAlive then
						local root = entitylib.character.RootPart
						root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
					end
				end)
				pcall(function()
					bedwars.SprintController:setSpeed(bedwars.SprintController:isSprinting() and 20 or 14)
				end)
			end
		end,
		ExtraText = function()
			return 'Heatseeker'
		end,
		Tooltip = 'increases your movement with various methods.'
	})
	Mode = Speed:CreateDropdown({
		Name = 'Method',
		List = {'Bedwars', 'CFrame'},
		Default = 'CFrame'
	})
	Value = Speed:CreateSlider({
		Name = 'Speed',
		Min = 1,
		Max = 23,
		Default = 23,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})
	WallCheck = Speed:CreateToggle({
		Name = 'Wall Check',
		Default = true
	})
	AutoJump = Speed:CreateToggle({
		Name = 'AutoJump',
		Function = function(callback)
			AlwaysJump.Object.Visible = callback
		end
	})
	AlwaysJump = Speed:CreateToggle({
		Name = 'Always Jump',
		Visible = false,
		Darker = true
	})
end)

run(function()
	local Value
	local CameraDir
	local start
	local JumpTick, JumpSpeed, Direction = tick(), 0
	local projectileRemote = {InvokeServer = function() end}
	task.spawn(function()
		projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
	end)
	local handGunRemote = {InvokeServer = function() end}
	task.spawn(function()
		handGunRemote = game:GetService("ReplicatedStorage"):WaitForChild("rbxts_include"):WaitForChild("node_modules"):WaitForChild("@rbxts"):WaitForChild("net"):WaitForChild("out"):WaitForChild("_NetManaged"):WaitForChild("HandGunFireRequest")
	end)
	
	local function launchProjectile(item, pos, proj, speed, dir)
		if not pos then return end
	
		pos = pos - dir * 0.1
		local shootPosition = (CFrame.lookAlong(pos, Vector3.new(0, -speed, 0)) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ)))
		switchItem(item.tool, 0)
		task.wait(0.1)
		bedwars.ProjectileController:createLocalProjectile(bedwars.ProjectileMeta[proj], proj, proj, shootPosition.Position, '', shootPosition.LookVector * speed, {drawDurationSeconds = 1})
		if projectileRemote:InvokeServer(item.tool, proj, proj, shootPosition.Position, pos, shootPosition.LookVector * speed, httpService:GenerateGUID(true), {drawDurationSeconds = 1}, workspace:GetServerTimeNow() - 0.045) then
			local shoot = bedwars.ItemMeta[item.itemType].projectileSource.launchSound
			shoot = shoot and shoot[math.random(1, #shoot)] or nil
			if shoot then
				bedwars.SoundManager:playSound(shoot)
			end
		end
	end
	
	local LongJumpMethods = {
		cannon = function(_, pos, dir)
			pos = pos - Vector3.new(0, (entitylib.character.HipHeight + (entitylib.character.RootPart.Size.Y / 2)) - 3, 0)
			local rounded = Vector3.new(math.round(pos.X / 3) * 3, math.round(pos.Y / 3) * 3, math.round(pos.Z / 3) * 3)
			bedwars.placeBlock(rounded, 'cannon', false)
	
			task.delay(0, function()
				local block, blockpos = getPlacedBlock(rounded)
				if block and block.Name == 'cannon' and (entitylib.character.RootPart.Position - block.Position).Magnitude < 20 then
					local breaktype = bedwars.ItemMeta[block.Name].block.breakType
					local tool = store.tools[breaktype]
					if tool then
						switchItem(tool.tool)
					end
	
					bedwars.Client:Get(remotes.CannonAim):SendToServer({
						cannonBlockPos = blockpos,
						lookVector = dir
					})
	
					local broken = 0.1
					if bedwars.BlockController:calculateBlockDamage(lplr, {blockPosition = blockpos}) < block:GetAttribute('Health') then
						broken = 0.4
						bedwars.breakBlock(block, true, true)
					end
	
					task.delay(broken, function()
						for _ = 1, 4 do
							local call = bedwars.Client:Get(remotes.CannonLaunch):CallServer({cannonBlockPos = blockpos})
							if call then
								bedwars.breakBlock(block, true, true)
								JumpSpeed = 5.25 * Value.Value
								JumpTick = tick() + 2.3
								Direction = Vector3.new(dir.X, 0, dir.Z).Unit
								break
							end
							task.wait(0.1)
						end
					end)
				end
			end)
		end,
		cat = function(_, _, dir)
			LongJump:Clean(vapeEvents.CatPounce.Event:Connect(function()
				JumpSpeed = 4 * Value.Value
				JumpTick = tick() + 2.5
				Direction = Vector3.new(dir.X, 0, dir.Z).Unit
				entitylib.character.RootPart.Velocity = Vector3.zero
			end))
	
			if not bedwars.AbilityController:canUseAbility('CAT_POUNCE') then
				repeat task.wait() until bedwars.AbilityController:canUseAbility('CAT_POUNCE') or not LongJump.Enabled
			end
	
			if bedwars.AbilityController:canUseAbility('CAT_POUNCE') and LongJump.Enabled then
				bedwars.AbilityController:useAbility('CAT_POUNCE')
			end
		end,
		fireball = function(item, pos, dir)
			launchProjectile(item, pos, 'fireball', 60, dir)
		end,
		grappling_hook = function(item, pos, dir)
			launchProjectile(item, pos, 'grappling_hook_projectile', 140, dir)
		end,
		jade_hammer = function(item, _, dir)
			if not bedwars.AbilityController:canUseAbility(item.itemType..'_jump') then
				repeat task.wait() until bedwars.AbilityController:canUseAbility(item.itemType..'_jump') or not LongJump.Enabled
			end
	
			if bedwars.AbilityController:canUseAbility(item.itemType..'_jump') and LongJump.Enabled then
				bedwars.AbilityController:useAbility(item.itemType..'_jump')
				JumpSpeed = 1.4 * Value.Value
				JumpTick = tick() + 2.5
				Direction = Vector3.new(dir.X, 0, dir.Z).Unit
			end
		end,
		tnt = function(item, pos, dir)
			pos = pos - Vector3.new(0, (entitylib.character.HipHeight + (entitylib.character.RootPart.Size.Y / 2)) - 3, 0)
			local rounded = Vector3.new(math.round(pos.X / 3) * 3, math.round(pos.Y / 3) * 3, math.round(pos.Z / 3) * 3)
			start = Vector3.new(rounded.X, start.Y, rounded.Z) + (dir * (item.itemType == 'pirate_gunpowder_barrel' and 2.6 or 0.2))
			bedwars.placeBlock(rounded, item.itemType, false)
		end,
		wood_dao = function(item, pos, dir)
			if (lplr.Character:GetAttribute('CanDashNext') or 0) > workspace:GetServerTimeNow() or not bedwars.AbilityController:canUseAbility('dash') then
				repeat task.wait() until (lplr.Character:GetAttribute('CanDashNext') or 0) < workspace:GetServerTimeNow() and bedwars.AbilityController:canUseAbility('dash') or not LongJump.Enabled
			end
	
			if LongJump.Enabled then
				if not (LegitAura and LegitAura.Enabled) then
					bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()
				end
				switchItem(item.tool, 0.1)
				replicatedStorage['events-@easy-games/game-core:shared/game-core-networking@getEvents.Events'].useAbility:FireServer('dash', {
					direction = dir,
					origin = pos,
					weapon = item.itemType
				})
				JumpSpeed = 4.5 * Value.Value
				JumpTick = tick() + 2.4
				Direction = Vector3.new(dir.X, 0, dir.Z).Unit
			end
		end
	}
	for _, v in {'stone_dao', 'iron_dao', 'diamond_dao', 'emerald_dao'} do
		LongJumpMethods[v] = LongJumpMethods.wood_dao
	end
	LongJumpMethods.void_axe = LongJumpMethods.jade_hammer
	LongJumpMethods.siege_tnt = LongJumpMethods.tnt
	LongJumpMethods.pirate_gunpowder_barrel = LongJumpMethods.tnt
	
	LongJump = vape.Categories.Blatant:CreateModule({
		Name = 'LongJump',
		Function = function(callback)
			frictionTable.LongJump = callback or nil
			updateVelocity()
			if callback then
				LongJump:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
					if damageTable.entityInstance == lplr.Character and damageTable.fromEntity == lplr.Character and (not damageTable.knockbackMultiplier or not damageTable.knockbackMultiplier.disabled) then
						local knockbackBoost = bedwars.KnockbackUtil.calculateKnockbackVelocity(Vector3.one, 1, {
							vertical = 0,
							horizontal = (damageTable.knockbackMultiplier and damageTable.knockbackMultiplier.horizontal or 1)
						}).Magnitude * 1.1
	
						if knockbackBoost >= JumpSpeed then
							local pos = damageTable.fromPosition and Vector3.new(damageTable.fromPosition.X, damageTable.fromPosition.Y, damageTable.fromPosition.Z) or damageTable.fromEntity and damageTable.fromEntity.PrimaryPart.Position
							if not pos then return end
							local vec = (entitylib.character.RootPart.Position - pos)
							JumpSpeed = knockbackBoost
							JumpTick = tick() + 2.5
							Direction = Vector3.new(vec.X, 0, vec.Z).Unit
						end
					end
				end))
				LongJump:Clean(vapeEvents.GrapplingHookFunctions.Event:Connect(function(dataTable)
					if dataTable.hookFunction == 'PLAYER_IN_TRANSIT' then
						local vec = entitylib.character.RootPart.CFrame.LookVector
						JumpSpeed = 2.5 * Value.Value
						JumpTick = tick() + 2.5
						Direction = Vector3.new(vec.X, 0, vec.Z).Unit
					end
				end))
	
				start = entitylib.isAlive and entitylib.character.RootPart.Position or nil
				LongJump:Clean(runService.PreSimulation:Connect(function(dt)
					local root = entitylib.isAlive and entitylib.character.RootPart or nil
	
					if root and isnetworkowner(root) then
						if JumpTick > tick() then
							root.AssemblyLinearVelocity = Direction * (getSpeed() + ((JumpTick - tick()) > 1.1 and JumpSpeed or 0)) + Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
							if entitylib.character.Humanoid.FloorMaterial == Enum.Material.Air and not start then
								root.AssemblyLinearVelocity += Vector3.new(0, dt * (workspace.Gravity - 23), 0)
							else
								root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, 15, root.AssemblyLinearVelocity.Z)
							end
							start = nil
						else
							if start then
								root.CFrame = CFrame.lookAlong(start, root.CFrame.LookVector)
							end
							root.AssemblyLinearVelocity = Vector3.zero
							JumpSpeed = 0
						end
					else
						start = nil
					end
				end))

				if store.hand and store.hand.tool and LongJumpMethods[store.hand.tool.Name] then
					task.spawn(LongJumpMethods[store.hand.tool.Name], getItem(store.hand.tool.Name), start, (CameraDir.Enabled and gameCamera or entitylib.character.RootPart).CFrame.LookVector)
					return
				end
				
				local foundItem = false
				for i, v in LongJumpMethods do
					local item = getItem(i)
					if item or store.equippedKit == i then
						foundItem = true
						task.spawn(v, item, start, (CameraDir.Enabled and gameCamera or entitylib.character.RootPart).CFrame.LookVector)
						break
					end
				end
				if not foundItem then
					notif("LongJump", "unable to find tool to use Long Jump with gng", 3)
					LongJump:Toggle()
					return
				end
			else
				JumpTick = tick()
				Direction = nil
				JumpSpeed = 0
			end
		end,
		ExtraText = function()
			return 'Heatseeker'
		end,
		Tooltip = 'lets you jump farther'
	})
	Value = LongJump:CreateSlider({
		Name = 'Speed',
		Min = 1,
		Max = 37,
		Default = 37,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})
	CameraDir = LongJump:CreateToggle({
		Name = 'Camera Direction'
	})
end)

--[[
	Render Modules
]]

run(function()
	local BedESP
	local Reference = {}
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui
	
	local function Added(bed)
		if not BedESP.Enabled then return end
		local BedFolder = Instance.new('Folder')
		BedFolder.Parent = Folder
		Reference[bed] = BedFolder
		local parts = bed:GetChildren()
		table.sort(parts, function(a, b)
			return a.Name > b.Name
		end)
	
		for _, part in parts do
			if part:IsA('BasePart') and part.Name ~= 'Blanket' then
				local handle = Instance.new('BoxHandleAdornment')
				handle.Size = part.Size + Vector3.new(.01, .01, .01)
				handle.AlwaysOnTop = true
				handle.ZIndex = 2
				handle.Visible = true
				handle.Adornee = part
				handle.Color3 = part.Color
				if part.Name == 'Legs' then
					handle.Color3 = Color3.fromRGB(167, 112, 64)
					handle.Size = part.Size + Vector3.new(.01, -1, .01)
					handle.CFrame = CFrame.new(0, -0.4, 0)
					handle.ZIndex = 0
				end
				handle.Parent = BedFolder
			end
		end
	
		table.clear(parts)
	end
	
	BedESP = vape.Categories.Render:CreateModule({
		Name = 'BedESP',
		Function = function(callback)
			if callback then
				BedESP:Clean(collectionService:GetInstanceAddedSignal('bed'):Connect(function(bed)
					task.delay(0.2, Added, bed)
				end))
				BedESP:Clean(collectionService:GetInstanceRemovedSignal('bed'):Connect(function(bed)
					if Reference[bed] then
						Reference[bed]:Destroy()
						Reference[bed] = nil
					end
				end))
				for _, bed in collectionService:GetTagged('bed') do
					Added(bed)
				end
			else
				Folder:ClearAllChildren()
				table.clear(Reference)
			end
		end,
		Tooltip = 'Render Beds through walls'
	})
end)

run(function()
	local LootESP
	local IronToggle
	local DiamondToggle
	local EmeraldToggle
	local Reference = {}
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui
	
	local CollectionService = collectionService
	
	local lootTypes = {
		iron = {
			keywords = {'iron'},
			color = Color3.fromRGB(200, 200, 200),
			icon = 'iron',
			displayName = 'IRON'
		},
		diamond = {
			keywords = {'diamond'},
			color = Color3.fromRGB(85, 200, 255),
			icon = 'diamond',
			displayName = 'DIAMOND'
		},
		emerald = {
			keywords = {'emerald'},
			color = Color3.fromRGB(0, 255, 100),
			icon = 'emerald',
			displayName = 'EMERALD'
		}
	}
	
	local function getLootType(itemName)
		local nameLower = itemName:lower()
		for lootType, config in pairs(lootTypes) do
			for _, keyword in ipairs(config.keywords) do
				if nameLower:find(keyword, 1, true) then 
					return lootType, config
				end
			end
		end
		return nil
	end
	
	local function isLootEnabled(lootType)
		if lootType == 'iron' then
			return IronToggle.Enabled
		elseif lootType == 'diamond' then
			return DiamondToggle.Enabled
		elseif lootType == 'emerald' then
			return EmeraldToggle.Enabled
		end
		return false
	end
	
	local function getProperIcon(lootType)
		local icon = bedwars.getIcon({itemType = lootType}, true)
		
		if not icon or icon == "" then
			return nil
		end
		
		return icon
	end
	
	local function Added(lootHandle, lootType, config)
		if not isLootEnabled(lootType) then return end
		if Reference[lootHandle] then return end 
		
		local billboard = Instance.new('BillboardGui')
		billboard.Parent = Folder
		billboard.Name = lootType
		billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
		billboard.Size = UDim2.fromOffset(40, 40)
		billboard.AlwaysOnTop = true
		billboard.ClipsDescendants = false
		billboard.Adornee = lootHandle
		
		local blur = addBlur(billboard)
		blur.Visible = true 
		
		local iconImage = getProperIcon(config.icon)
		
		if iconImage then
			local image = Instance.new('ImageLabel')
			image.Size = UDim2.fromOffset(40, 40)
			image.Position = UDim2.fromScale(0.5, 0.5)
			image.AnchorPoint = Vector2.new(0.5, 0.5)
			image.BackgroundColor3 = Color3.new(0, 0, 0) 
			image.BackgroundTransparency = 0.3 
			image.BorderSizePixel = 0
			image.Image = iconImage
			image.Parent = billboard
			
			local uicorner = Instance.new('UICorner')
			uicorner.CornerRadius = UDim.new(0, 4)
			uicorner.Parent = image
		else
			local frame = Instance.new('Frame')
			frame.Size = UDim2.fromScale(1, 1)
			frame.BackgroundColor3 = Color3.new(0, 0, 0) 
			frame.BackgroundTransparency = 0.3 
			frame.BorderSizePixel = 0
			frame.Parent = billboard
			
			local uicorner = Instance.new('UICorner')
			uicorner.CornerRadius = UDim.new(0, 4)
			uicorner.Parent = frame
			
			local textLabel = Instance.new('TextLabel')
			textLabel.Size = UDim2.fromScale(1, 1)
			textLabel.Position = UDim2.fromScale(0.5, 0.5)
			textLabel.AnchorPoint = Vector2.new(0.5, 0.5)
			textLabel.BackgroundTransparency = 1
			textLabel.Text = config.displayName
			textLabel.TextColor3 = config.color
			textLabel.TextScaled = true
			textLabel.Font = Enum.Font.GothamBold
			textLabel.TextStrokeTransparency = 0.5
			textLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
			textLabel.Parent = frame
		end
		
		Reference[lootHandle] = billboard
	end
	
	local function Removed(lootHandle)
		if Reference[lootHandle] then
			Reference[lootHandle]:Destroy()
			Reference[lootHandle] = nil
		end
	end
	
	local function findExistingLoot()
		local tagged = CollectionService:GetTagged('ItemDrop')
		for _, drop in ipairs(tagged) do
			local handle = drop:FindFirstChild('Handle')
			if handle then
				local lootType, config = getLootType(drop.Name)
				if lootType and isLootEnabled(lootType) then
					if not Reference[handle] then
						Added(handle, lootType, config)
					end
				end
			end
		end
	end
	
	local function refreshLootType(lootType)
		if not LootESP.Enabled then return end
		
		local enabled = isLootEnabled(lootType)
		
		if not enabled then
			for handle, billboard in pairs(Reference) do
				if billboard.Name == lootType then
					billboard:Destroy()
					Reference[handle] = nil
				end
			end
		else
			local tagged = CollectionService:GetTagged('ItemDrop')
			for _, drop in ipairs(tagged) do
				local handle = drop:FindFirstChild('Handle')
				if handle then
					local dropLootType, config = getLootType(drop.Name)
					if dropLootType == lootType and not Reference[handle] then
						Added(handle, lootType, config)
					end
				end
			end
		end
	end
	
	LootESP = vape.Categories.Inventory:CreateModule({
		Name = 'LootESP',
		Function = function(callback)
			if callback then
				findExistingLoot()
				
				LootESP:Clean(CollectionService:GetInstanceAddedSignal('ItemDrop'):Connect(function(drop)
					if not LootESP.Enabled then return end
					
					task.defer(function()
						local handle = drop:FindFirstChild('Handle')
						if not handle then return end
						
						local lootType, config = getLootType(drop.Name)
						if lootType and isLootEnabled(lootType) then
							Added(handle, lootType, config)
						end
					end)
				end))
				
				LootESP:Clean(CollectionService:GetInstanceRemovedSignal('ItemDrop'):Connect(function(drop)
					local handle = drop:FindFirstChild('Handle')
					if handle then
						Removed(handle)
					end
				end))
				
			else
				for handle, billboard in pairs(Reference) do
					billboard:Destroy()
				end
				table.clear(Reference)
			end
		end,
		Tooltip = 'esp for loot (iron, emerald, diamonds)'
	})
	
	IronToggle = LootESP:CreateToggle({
		Name = 'Iron',
		Function = function(callback)
			refreshLootType('iron')
		end,
		Default = true
	})
	
	DiamondToggle = LootESP:CreateToggle({
		Name = 'Diamond',
		Function = function(callback)
			refreshLootType('diamond')
		end,
		Default = true
	})
	
	EmeraldToggle = LootESP:CreateToggle({
		Name = 'Emerald',
		Function = function(callback)
			refreshLootType('emerald')
		end,
		Default = true
	})
end)

run(function()
    local StorageESP
    local Background
    local Color = {}
    local Reference = {}
    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui
    
    local function refreshAdornee(v)
        local chest = v.Adornee:FindFirstChild('ChestFolderValue')
        chest = chest and chest.Value or nil
        if not chest then
            v.Enabled = false
            return
        end
    
        local chestitems = chest and chest:GetChildren() or {}
        for _, obj in v.Frame:GetChildren() do
            if obj:IsA('Frame') and obj.Name ~= 'UIListLayout' and obj.Name ~= 'UICorner' then
                obj:Destroy()
            end
        end
    
        v.Enabled = false
        local itemCounts = {}
        local order = {}
        for _, item in chestitems do
            local itemName = item.Name
            v.Enabled = true
            local count = 1
            if item:FindFirstChild("Amount") then
                count = item.Amount.Value
            elseif item:GetAttribute("Amount") then
                count = item:GetAttribute("Amount")
            elseif item:FindFirstChild("Value") then
                count = item.Value
            end
            if not itemCounts[itemName] then
                table.insert(order, itemName)
            end
            itemCounts[itemName] = (itemCounts[itemName] or 0) + count
        end
        
        for _, itemName in order do
            local totalCount = itemCounts[itemName]
            v.Enabled = true
            local container = Instance.new('Frame')
            container.Size = UDim2.fromOffset(26, 36)
            container.BackgroundTransparency = 1
            container.Parent = v.Frame
            
            local blockimage = Instance.new('ImageLabel')
            blockimage.Size = UDim2.fromOffset(24, 24)
            blockimage.Position = UDim2.new(0.5, -12, 0, 4)
            blockimage.BackgroundTransparency = 1
            blockimage.Image = bedwars.getIcon({itemType = itemName}, true)
            blockimage.Parent = container
            
            if totalCount > 1 then
                local countLabel = Instance.new('TextLabel')
                countLabel.Size = UDim2.new(1, 0, 0, 12)
                countLabel.Position = UDim2.new(0, 0, 1, -12)
                countLabel.BackgroundTransparency = 1
                countLabel.TextColor3 = Color3.new(1, 1, 1)
                countLabel.TextStrokeTransparency = 0
                countLabel.TextSize = 10
                countLabel.Font = Enum.Font.GothamBold
                countLabel.Text = tostring(totalCount)
                countLabel.Parent = container
            end
        end
        
        table.clear(chestitems)
    end
    
    local function Added(v)
        local billboard = Instance.new('BillboardGui')
        billboard.Parent = Folder
        billboard.Name = 'chest'
        billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
        billboard.Size = UDim2.fromOffset(36, 36)
        billboard.AlwaysOnTop = true
        billboard.ClipsDescendants = false
        billboard.Adornee = v
        local blur = addBlur(billboard)
        blur.Visible = Background.Enabled
        local frame = Instance.new('Frame')
        frame.Size = UDim2.fromScale(1, 1)
        frame.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
        frame.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
        frame.Parent = billboard
        
        local layout = Instance.new('UIListLayout')
        layout.FillDirection = Enum.FillDirection.Horizontal
        layout.Padding = UDim.new(0, 0)
        layout.VerticalAlignment = Enum.VerticalAlignment.Center
        layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
        layout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function()
            billboard.Size = UDim2.fromOffset(math.max(layout.AbsoluteContentSize.X + 6, 36), 36)
        end)
        layout.Parent = frame
        
        local corner = Instance.new('UICorner')
        corner.CornerRadius = UDim.new(0, 4)
        corner.Parent = frame
        Reference[v] = billboard
        
        local function setupChestListener()
            local chest = v:FindFirstChild('ChestFolderValue')
            if chest and chest.Value then
                local folderValue = chest.Value
                StorageESP:Clean(folderValue.ChildAdded:Connect(function()
                    refreshAdornee(billboard)
                end))
                StorageESP:Clean(folderValue.ChildRemoved:Connect(function()
                    refreshAdornee(billboard)
                end))
            end
        end
        
        setupChestListener()
        StorageESP:Clean(v.ChildAdded:Connect(function(child)
            if child.Name == 'ChestFolderValue' then
                task.spawn(setupChestListener)
                task.spawn(refreshAdornee, billboard)
            end
        end))
        
        task.spawn(refreshAdornee, billboard)
    end
    
    StorageESP = vape.Categories.Inventory:CreateModule({
        Name = 'TeamCrateESP',
        Function = function(callback)
            if callback then
                StorageESP:Clean(collectionService:GetInstanceAddedSignal('chest'):Connect(Added))
                for _, v in collectionService:GetTagged('chest') do
                    task.spawn(Added, v)
                end
                
                StorageESP:Clean(task.spawn(function()
                    while StorageESP.Enabled do
                        for _, billboard in Reference do
                            pcall(function()
                                refreshAdornee(billboard)
                            end)
                        end
                        task.wait(0.2)
                    end
                end))
            else
                table.clear(Reference)
                Folder:ClearAllChildren()
            end
        end,
        Tooltip = 'Displays all items tightly packed and their counts in crates in real-time'
    })
    
    Background = StorageESP:CreateToggle({
        Name = 'Background',
        Function = function(callback)
            if Color.Object then Color.Object.Visible = callback end
            for _, v in Reference do
                v.Frame.BackgroundTransparency = 1 - (callback and Color.Opacity or 0)
                v.Blur.Visible = callback
            end
        end,
        Default = true
    })
    
    Color = StorageESP:CreateColorSlider({
        Name = 'Background Color',
        DefaultValue = 0,
        DefaultOpacity = 0.5,
        Function = function(hue, sat, val, opacity)
            for _, v in Reference do
                v.Frame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
                v.Frame.BackgroundTransparency = 1 - opacity
            end
        end,
        Darker = true
    })
end)

run(function()
	local StorageESP
	local List
	local Background
	local Color = {}
	local Reference = {}
	local ChestContents = {} 
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui
	
	local function getEnabledItemsSet()
		local set = {}
		for _, v in ipairs(List.ListEnabled) do
			set[v] = true
		end
		return set
	end
	
	local function nearStorageItem(item, enabledSet)
		for itemName in pairs(enabledSet) do
			if item:find(itemName, 1, true) then return itemName end
		end
		return nil
	end
	
	local function refreshAdornee(billboard)
		local chestPart = billboard.Adornee
		local folderValue = chestPart and chestPart:FindFirstChild('ChestFolderValue')
		local chest = folderValue and folderValue.Value or nil

		for _, obj in ipairs(billboard:GetChildren()) do
			if obj:IsA('ImageLabel') and obj.Name == 'Icon' then
				obj:Destroy()
			end
		end

		if not chest then
			billboard.Enabled = false
			return
		end

		local chestitems = chest:GetChildren()
		local enabledSet = getEnabledItemsSet()
		local listIsEmpty = next(enabledSet) == nil

		local matchedItems = {}
		local amounts = {}
		for _, item in ipairs(chestitems) do
			if item:IsA('Accessory') then
				if listIsEmpty or enabledSet[item.Name] or nearStorageItem(item.Name, enabledSet) then
					if amounts[item.Name] == nil then
						amounts[item.Name] = 0
						table.insert(matchedItems, item.Name)
					end
					amounts[item.Name] = amounts[item.Name] + (item:GetAttribute('Amount') or 1)
				end
			end
		end

		local count = #matchedItems
		if count == 0 then
			billboard.Enabled = false
			return
		end

		billboard.Enabled = true
		local iconSize = 36
		local padding = 2
		local totalWidth = count * iconSize + (count - 1) * padding
		billboard.Size = UDim2.fromOffset(totalWidth, iconSize)

		for i, itemName in ipairs(matchedItems) do
			local icon = Instance.new('ImageLabel')
			icon.Name = 'Icon'
			icon.Size = UDim2.fromOffset(iconSize, iconSize)
			icon.Position = UDim2.fromOffset((i - 1) * (iconSize + padding), 0)
			icon.AnchorPoint = Vector2.new(0, 0)
			icon.BackgroundColor3 = Color3.new(0, 0, 0)
			icon.BackgroundTransparency = 0.3
			icon.BorderSizePixel = 0
			icon.Image = bedwars.getIcon({itemType = itemName}, true)
			icon.Parent = billboard

			local uicorner = Instance.new('UICorner')
			uicorner.CornerRadius = UDim.new(0, 4)
			uicorner.Parent = icon

			local amt = Instance.new('TextLabel')
			amt.Name = 'Amt'
			amt.AnchorPoint = Vector2.new(1, 1)
			amt.Position = UDim2.new(1, -1, 1, -1)
			amt.Size = UDim2.fromOffset(iconSize, 14)
			amt.BackgroundTransparency = 1
			amt.Text = tostring(amounts[itemName] or 0)
			amt.TextColor3 = Color3.fromRGB(255, 255, 255)
			amt.TextStrokeTransparency = 0.4
			amt.TextSize = 13
			amt.Font = Enum.Font.GothamBold
			amt.TextXAlignment = Enum.TextXAlignment.Right
			amt.TextYAlignment = Enum.TextYAlignment.Bottom
			amt.Parent = icon
		end
	end
	
	local function Added(v)
		if Reference[v] then return end

		local billboard = Instance.new('BillboardGui')
		billboard.Parent = Folder
		billboard.Name = 'chest'
		billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
		billboard.Size = UDim2.fromOffset(36, 36)
		billboard.AlwaysOnTop = true
		billboard.ClipsDescendants = false
		billboard.Adornee = v
		billboard.Enabled = false

		local blur = addBlur(billboard)

		Reference[v] = billboard

		refreshAdornee(billboard)

		task.defer(function()
			local folderValue = v:FindFirstChild('ChestFolderValue')
			local chest = folderValue and folderValue.Value or nil
			if chest and Reference[v] then
				local conn1 = chest.ChildAdded:Connect(function()
					if Reference[v] then refreshAdornee(Reference[v]) end
				end)
				local conn2 = chest.ChildRemoved:Connect(function()
					if Reference[v] then refreshAdornee(Reference[v]) end
				end)
				billboard.AncestryChanged:Connect(function()
					conn1:Disconnect()
					conn2:Disconnect()
				end)
			end
		end)
	end
	
	local function Removed(v)
		if Reference[v] then
			Reference[v]:Destroy()
			Reference[v] = nil
			ChestContents[v] = nil
		end
	end
	
	StorageESP = vape.Categories.Render:CreateModule({
		Name = 'StorageESP',
		Function = function(callback)
			if callback then
				local tagged = collectionService:GetTagged('chest')
				for _, v in ipairs(tagged) do
					Added(v)
				end
				
				StorageESP:Clean(collectionService:GetInstanceAddedSignal('chest'):Connect(Added))
				StorageESP:Clean(collectionService:GetInstanceRemovedSignal('chest'):Connect(Removed))
				StorageESP:Clean(task.spawn(function()
					while StorageESP.Enabled do
						task.wait(0.5)
						if not StorageESP.Enabled then break end
						for chest, billboard in pairs(Reference) do
							if not chest or not chest.Parent then
								Removed(chest)
							else
								refreshAdornee(billboard)
							end
						end
					end
				end))
			else
				for chest in pairs(Reference) do
					Removed(chest)
				end
			end
		end,
		Tooltip = 'shows what items are in a chest'
	})
	
	List = StorageESP:CreateTextList({
		Name = 'Item',
		Function = function()
			table.clear(ChestContents)
			for _, v in pairs(Reference) do
				refreshAdornee(v)
			end
		end
	})
	
	Background = StorageESP:CreateToggle({
		Name = 'Background',
		Function = function(callback)
			if Color.Object then Color.Object.Visible = callback end
			for _, v in pairs(Reference) do
				local icon = v:FindFirstChild('Icon')
				if icon then
					icon.BackgroundTransparency = callback and 0.3 or 1
				end
			end
		end,
		Default = true
	})
	
    Color = StorageESP:CreateColorSlider({
        Name = 'Background Color',
        DefaultValue = 0,
        DefaultOpacity = 0.5,
        Function = function(hue, sat, val, opacity)
            for _, v in pairs(Reference) do
                v.Frame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
                v.Frame.BackgroundTransparency = 1 - opacity
            end
        end,
        Darker = true
    })

    task.defer(function()
        if Color and Color.Object then
            Color.Object.Visible = Background.Enabled  
        end
    end)
end)

run(function()
	local TrapESP
	local Background = {}
	local Color = {}
	local Reference = {}
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui

	local function Added(v, icon)
		local billboard = Instance.new('BillboardGui')
		billboard.Parent = Folder
		billboard.Name = icon
		billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
		billboard.Size = UDim2.fromOffset(36, 36)
		billboard.AlwaysOnTop = true
		billboard.ClipsDescendants = false
		billboard.Adornee = v:IsA('Model') and (v.PrimaryPart or v:FindFirstChildWhichIsA('BasePart')) or v
		local blur = addBlur(billboard)
		blur.Visible = Background.Enabled
		local image = Instance.new('ImageLabel')
		image.Size = UDim2.fromOffset(36, 36)
		image.Position = UDim2.fromScale(0.5, 0.5)
		image.AnchorPoint = Vector2.new(0.5, 0.5)
		image.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
		image.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
		image.BorderSizePixel = 0
		local result = bedwars.getIcon({itemType = icon}, true)
		image.Image = result		
		image.Image = result
		image.Parent = billboard
		local uicorner = Instance.new('UICorner')
		uicorner.CornerRadius = UDim.new(0, 4)
		uicorner.Parent = image
		Reference[v] = billboard
	end
	


	TrapESP = vape.Categories.Render:CreateModule({
		Name = 'TrapESP',
		Function = function(callback)
			if callback then
				TrapESP:Clean(collectionService:GetInstanceAddedSignal('snap_trap'):Connect(function(v)
					if tostring(v:GetAttribute("SnapTrapTeamId")) == lplr.Team.Name then
						return
					end
					Added(v, 'snap_trap')
				end))
				TrapESP:Clean(collectionService:GetInstanceRemovedSignal('snap_trap'):Connect(function(v)
					if tostring(v:GetAttribute("SnapTrapTeamId")) == lplr.Team.Name then
						return
					end
					if Reference[v] then
						Reference[v]:Destroy()
						Reference[v] = nil
					end
				end))
				for _, v in collectionService:GetTagged('snap_trap') do
					if tostring(v:GetAttribute("SnapTrapTeamId")) == lplr.Team.Name then
						return
					end
					Added(v, 'snap_trap')
				end
			else
				Folder:ClearAllChildren()
				table.clear(Reference)
			end
		end,
		Tooltip = 'allows you to see invisible traps'
	})
	Background = TrapESP:CreateToggle({
		Name = 'Background',
		Function = function(callback)
			if Color.Object then Color.Object.Visible = callback end
			for _, v in Reference do
				v.ImageLabel.BackgroundTransparency = 1 - (callback and Color.Opacity or 0)
				v.Blur.Visible = callback
			end
		end,
		Default = true,
				Visible = true
	})
	Color = TrapESP:CreateColorSlider({
		Name = 'Background Color',
		DefaultValue = 0,
		DefaultOpacity = 0.5,
		Function = function(hue, sat, val, opacity)
			for _, v in Reference do
				v.ImageLabel.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
				v.ImageLabel.BackgroundTransparency = 1 - opacity
			end
		end,
		Darker = true
	})
end)

run(function()
	local AutoShielderUlt
	local Range
	local Targets
	local Delay
	local nextUlt = 0
	
	AutoShielderUlt = vape.Categories.Kits:CreateModule({
		Name = 'AutoInfernal',
		Function = function(callback)
			if callback then
				nextUlt = 0
	
				repeat
					if entitylib.isAlive and store.equippedKit == 'shielder' and tick() >= nextUlt then
						local origin = entitylib.character.RootPart.Position
						local found = 0
						for _, v in entitylib.List do
							if v.Targetable and (v.RootPart.Position - origin).Magnitude <= Range.Value then
								found += 1
							end
						end
	
						if found >= Targets.Value then
							nextUlt = tick() + Delay.Value
							bedwars.InfernalShieldController:useUlt()
						end
					end
					task.wait(0.1)
				until not AutoShielderUlt.Enabled
			end
		end,
		Tooltip = 'auto use the ability when ppl r around you'
	})
	Range = AutoShielderUlt:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 60,
		Default = 25,
		Suffix = function(val)
			return val <= 1 and 'stud' or 'studs'
		end
	})
	Targets = AutoShielderUlt:CreateSlider({
		Name = 'Targets',
		Min = 1,
		Max = 8,
		Default = 1,
		Tooltip = 'Enemies in range before slamming'
	})
	Delay = AutoShielderUlt:CreateSlider({
		Name = 'Delay',
		Min = 0.5,
		Max = 10,
		Default = 2,
		Decimal = 10,
		Suffix = function(val)
			return val <= 1 and 'sec' or 'secs'
		end
	})
end)

run(function()
	local OverlayEditor
	local FillColor
	local OutlineColor
	local Thickness
	local Animate
	local Speed
	local overlay, overlayBox, overlayTween
	local activePart
	
	local isOverlayPart = function(part)
		return part:IsA('BasePart') and part.Anchored and part.Transparency == 1 and part:FindFirstChildOfClass('SelectionBox') ~= nil
	end
	
	local function hideOverlay()
		if overlayTween then
			overlayTween:Cancel()
			overlayTween = nil
		end
		if overlay then
			overlay.Parent = nil
		end
	end
	
	local moveOverlay = function(part)
		if not overlay then return end
	
		if overlayTween then
			overlayTween:Cancel()
			overlayTween = nil
		end
	
		if Animate.Enabled and overlay.Parent == gameCamera then
			overlayTween = tweenService:Create(overlay, TweenInfo.new(Speed.Value, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {CFrame = part.CFrame, Size = part.Size})
			overlayTween:Play()
		else
			overlay.CFrame = part.CFrame
			overlay.Size = part.Size
			overlay.Parent = gameCamera
		end
	end
	
	local bindPart = function(part)
		if not OverlayEditor.Enabled or not isOverlayPart(part) then return end
	
		part:FindFirstChildOfClass('SelectionBox').Visible = false
		activePart = part
		moveOverlay(part)
	end
	
	OverlayEditor = vape.Categories.Render:CreateModule({
		Name = 'SelectedItemColor',
		Function = function(callback)
			if callback then
				overlay = Instance.new('Part')
				overlay.Size = Vector3.one * 3
				overlay.Anchored = true
				overlay.CanCollide = false
				overlay.CanQuery = false
				overlay.CanTouch = false
				overlay.CastShadow = false
				overlay.Transparency = 1
				overlayBox = Instance.new('SelectionBox')
				overlayBox.Adornee = overlay
				overlayBox.LineThickness = Thickness.Value
				overlayBox.Color3 = Color3.fromHSV(OutlineColor.Hue, OutlineColor.Sat, OutlineColor.Value)
				overlayBox.Transparency = 1 - OutlineColor.Opacity
				overlayBox.SurfaceColor3 = Color3.fromHSV(FillColor.Hue, FillColor.Sat, FillColor.Value)
				overlayBox.SurfaceTransparency = 1 - FillColor.Opacity
				overlayBox.Parent = overlay
				bedwars.QueryUtil:setQueryIgnored(overlay, true)
	
				for _, child in workspace:GetChildren() do
					bindPart(child)
				end
	
				OverlayEditor:Clean(workspace.ChildAdded:Connect(function(child)
					task.defer(bindPart, child)
				end))
				OverlayEditor:Clean(workspace.ChildRemoved:Connect(function(child)
					if child ~= activePart then return end
	
					activePart = nil
					task.delay(0.06, function()
						if not activePart and OverlayEditor.Enabled then
							hideOverlay()
						end
					end)
				end))
			else
				if activePart then
					local box = activePart:FindFirstChildOfClass('SelectionBox')
					if box then
						box.Visible = true
					end
					activePart = nil
				end
	
				hideOverlay()
				if overlay then
					overlay:Destroy()
					overlay, overlayBox = nil, nil
				end
			end
		end,
		Tooltip = 'Restyles the outline on the block you are aiming at'
	})
	FillColor = OverlayEditor:CreateColorSlider({
		Name = 'Fill Color',
		DefaultSat = 0,
		DefaultOpacity = 0.25,
		Darker = true,
		Function = function(hue, sat, val, opacity)
			if overlayBox then
				overlayBox.SurfaceColor3 = Color3.fromHSV(hue, sat, val)
				overlayBox.SurfaceTransparency = 1 - opacity
			end
		end
	})
	OutlineColor = OverlayEditor:CreateColorSlider({
		Name = 'Outline Color',
		DefaultSat = 0,
		Darker = true,
		Function = function(hue, sat, val, opacity)
			if overlayBox then
				overlayBox.Color3 = Color3.fromHSV(hue, sat, val)
				overlayBox.Transparency = 1 - opacity
			end
		end
	})
	Thickness = OverlayEditor:CreateSlider({
		Name = 'Thickness',
		Min = 0.01,
		Max = 0.2,
		Default = 0.04,
		Decimal = 100,
		Function = function(value)
			if overlayBox then
				overlayBox.LineThickness = value
			end
		end
	})
	Animate = OverlayEditor:CreateToggle({
		Name = 'Animate',
		Default = true,
		Tooltip = 'Glides the overlay onto the next block instead of snapping to it'
	})
	Speed = OverlayEditor:CreateSlider({
		Name = 'Animation time',
		Min = 0.01,
		Max = 0.5,
		Default = 0.08,
		Decimal = 100,
		Suffix = 's'
	})
end)

run(function()
	local NameTags
	local Targets
	local Color
	local Background
	local DisplayName
	local Health
	local Distance
	local Equipment
	local Rank
	local Enchant
	local Device
	local ShowKits
	local DrawingToggle
	local Scale
	local FontOption
	local Teammates
	local DistanceCheck
	local DistanceLimit
	local Strings, Sizes, Reference = {}, {}, {}
	local Folder
	
	pcall(function()
		Folder = Instance.new('Folder')
		Folder.Parent = vape.gui
	end)
	
	local methodused
	local refreshTag

	-- Safe Resolution of BedWars Kit Metadata from ReplicatedStorage
	local BedwarsKitMeta = (function()
		local suc, res = pcall(function()
			return require(replicatedStorage.TS.games.bedwars.kit["bedwars-kit-meta"]).BedwarsKitMeta
		end)
		if suc and res then return res end
		-- Alternative fallback path check
		local suc2, res2 = pcall(function()
			return require(replicatedStorage.TS.bedwars.kit["bedwars-kit-meta"]).BedwarsKitMeta
		end)
		return suc2 and res2 or nil
	end)()

	local RankMeta = (function()
		local suc, res = pcall(function()
			return require(replicatedStorage.TS.rank['rank-meta']).RankMeta
		end)
		return suc and res or nil
	end)()

	local rankRequested = {}

	local function getRankImage(plr)
		if not (RankMeta and plr) then return nil end
		local controller = bedwars and bedwars.RankController
		local cache = controller and controller.rankCache
		local division = cache and cache[plr.UserId]
		local meta = division and RankMeta[division]
		return meta and meta.image or nil
	end

	local ICON_SIZE = 30
	local rightIcons = {'RankIcon', 'EnchantIcon', 'KitIcon'}
	local function positionIcons(nametag, width)
		local offset = width + 10
		for _, name in rightIcons do
			local icon = nametag:FindFirstChild(name)
			if icon then
				local shown = icon.Image ~= '' and (name ~= 'KitIcon' or ShowKits.Enabled)
				icon.Visible = shown
				if shown then
					icon.Position = UDim2.fromOffset(offset, -4)
					offset += ICON_SIZE
				end
			end
		end
	end

	local function requestRank(plr, ent)
		if not plr or rankRequested[plr.UserId] then return end
		local controller = bedwars and bedwars.RankController
		if not (controller and controller.getRanks) then return end
		rankRequested[plr.UserId] = true
		task.spawn(function()
			pcall(function()
				controller:getRanks({plr.UserId}, true):andThen(function()
					if refreshTag then refreshTag(ent) end
				end)
			end)
		end)
	end

	local function getEnchantImage(plr)
		if not plr then return nil end
		if not (store.enchants and bedwars and bedwars.EnchantMeta) then return nil end
		local suc, res = pcall(function()
			return store.enchants[plr].async()
		end)
		return suc and res or nil
	end

	local function getPlayerKit(plr)
		if not plr then return nil end
		local kitAttr = plr:GetAttribute('PlayingAsKit') or plr:GetAttribute('PlayingAsKits')
		if not kitAttr and plr.Character then
			kitAttr = plr.Character:GetAttribute('PlayingAsKit') or plr.Character:GetAttribute('PlayingAsKits')
		end
		if type(kitAttr) == 'string' then
			return kitAttr:split(',')[1]
		end
		return nil
	end

	local function getKitImage(plr)
		if not (BedwarsKitMeta and plr) then return nil end
		local kitName = getPlayerKit(plr)
		if not kitName or kitName == 'none' then return nil end
		local meta = BedwarsKitMeta[kitName]
		return meta and (meta.renderImage or meta.icon) or nil
	end

	local enchantConns = {}

	local function unwatchEnchant(ent)
		local conn = enchantConns[ent]
		if conn then
			pcall(function() conn:Disconnect() end)
			enchantConns[ent] = nil
		end
	end

	local function watchEnchant(ent)
		unwatchEnchant(ent)
		local char = ent.Character
		if not char then return end
		pcall(function()
			enchantConns[ent] = char.AttributeChanged:Connect(function(attribute)
				if (attribute:find('StatusEffect_') or attribute:find('PlayingAsKit')) and refreshTag then
					refreshTag(ent)
				end
			end)
		end)
	end

	local deviceEmojis = {gamepad = '🎮', touch = '📱', keyboard = '🖥️'}

	local function getDeviceEmoji(plr)
		if not plr then return nil end
		local inputType = plr:GetAttribute('UserInputType')
		if inputType == nil and plr.Character then
			inputType = plr.Character:GetAttribute('UserInputType')
		end
		if inputType == nil then return nil end
		if type(inputType) == 'number' then
			if inputType == 7 then return deviceEmojis.touch end
			if inputType == 8 then return deviceEmojis.keyboard end
			if inputType >= 9 and inputType <= 16 then return deviceEmojis.gamepad end
			return deviceEmojis.keyboard
		end
		local name = tostring(inputType):lower()
		if name:find('gamepad') or name:find('console') or name:find('xbox') or name:find('playstation') then
			return deviceEmojis.gamepad
		end
		if name:find('touch') or name:find('mobile') or name:find('phone') or name:find('tablet') then
			return deviceEmojis.touch
		end
		return name ~= '' and deviceEmojis.keyboard or nil
	end

	local inventoryConns = {}
	local function unwatchInventory(ent)
		local conn = inventoryConns[ent]
		if conn then
			pcall(function() conn:Disconnect() end)
			inventoryConns[ent] = nil
		end
	end

	local function watchInventory(ent)
		unwatchInventory(ent)
		if not ent.Player or not store.inventories then return end
		pcall(function()
			inventoryConns[ent] = ent.Player.CharacterAdded:Connect(function()
				if refreshTag then refreshTag(ent) end
			end)
		end)
	end

	local Added = {
		Normal = function(ent)
			pcall(function()
				if not Targets.Players.Enabled and ent.Player then return end
				if not Targets.NPCs.Enabled and ent.NPC then return end
				if Teammates.Enabled and (not ent.Targetable) and (not ent.Friend) then return end
				if Reference[ent] then return end

				local nametag = Instance.new('TextLabel')
				Strings[ent] = ent.Player and whitelist:tag(ent.Player, true, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name

				if Device.Enabled and ent.Player then
					local emoji = getDeviceEmoji(ent.Player)
					if emoji then
						Strings[ent] = emoji..' '..Strings[ent]
					end
				end

				if Health.Enabled then
					local healthColor = Color3.fromHSV(math.clamp(ent.Health / ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)
					Strings[ent] = Strings[ent]..' <font color="rgb('..tostring(math.floor(healthColor.R * 255))..','..tostring(math.floor(healthColor.G * 255))..','..tostring(math.floor(healthColor.B * 255))..')">'..math.round(ent.Health)..'</font>'
				end

				if Distance.Enabled then
					Strings[ent] = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '..Strings[ent]
				end

				if Equipment.Enabled then
					for i, v in {'Hand', 'Helmet', 'Chestplate', 'Boots'} do
						local Icon = Instance.new('ImageLabel')
						Icon.Name = v
						Icon.Size = UDim2.fromOffset(30, 30)
						Icon.Position = UDim2.fromOffset(-60 + (i * 30), -30)
						Icon.BackgroundTransparency = 1
						Icon.Image = ''
						Icon.Parent = nametag

						if v == 'Hand' then
							local ValueLabel = Instance.new('TextLabel')
							ValueLabel.Name = 'AmountLabel'
							ValueLabel.Size = UDim2.fromScale(1, 1)
							ValueLabel.Position = UDim2.fromOffset(0, 0)
							ValueLabel.BackgroundTransparency = 1
							ValueLabel.Text = ''
							ValueLabel.TextColor3 = Color3.new(1, 1, 1)
							ValueLabel.TextStrokeTransparency = 0
							ValueLabel.TextSize = 12
							ValueLabel.Font = Enum.Font.SourceSansBold
							ValueLabel.TextXAlignment = Enum.TextXAlignment.Right
							ValueLabel.TextYAlignment = Enum.TextYAlignment.Bottom
							ValueLabel.Parent = Icon
						end
					end
				end

				nametag.TextSize = 14 * Scale.Value
				nametag.FontFace = FontOption.Value
				local size = getfontsize(removeTags(Strings[ent]), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
				nametag.Name = ent.Player and ent.Player.Name or ent.Character.Name
				nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)

				if Rank.Enabled and ent.Player then
					local Icon = Instance.new('ImageLabel')
					Icon.Name = 'RankIcon'
					Icon.Size = UDim2.fromOffset(ICON_SIZE, ICON_SIZE)
					Icon.BackgroundTransparency = 1
					Icon.Image = getRankImage(ent.Player) or ''
					Icon.Visible = false
					Icon.Parent = nametag
					if Icon.Image == '' then
						requestRank(ent.Player, ent)
					end
				end

				if Enchant.Enabled and ent.Player then
					local Icon = Instance.new('ImageLabel')
					Icon.Name = 'EnchantIcon'
					Icon.Size = UDim2.fromOffset(ICON_SIZE, ICON_SIZE)
					Icon.BackgroundTransparency = 1
					Icon.Image = getEnchantImage(ent.Player) or ''
					Icon.Visible = false
					Icon.Parent = nametag
					watchEnchant(ent)
				end

				if ent.Player then
					local KitIcon = Instance.new('ImageLabel')
					KitIcon.Name = 'KitIcon'
					KitIcon.Size = UDim2.fromOffset(ICON_SIZE, ICON_SIZE)
					KitIcon.BackgroundTransparency = 1
					KitIcon.Image = getKitImage(ent.Player) or ''
					KitIcon.Visible = false
					KitIcon.Parent = nametag
				end

				positionIcons(nametag, size.X)

				nametag.AnchorPoint = Vector2.new(0.5, 1)
				nametag.BackgroundColor3 = Color3.new()
				nametag.BackgroundTransparency = Background.Value
				nametag.BorderSizePixel = 0
				nametag.Visible = false
				nametag.Text = Strings[ent]
				nametag.TextColor3 = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
				nametag.RichText = true
				nametag.Parent = Folder
				Reference[ent] = nametag
				
				if Equipment.Enabled and ent.Player then
					watchInventory(ent)
				end
			end)
		end,
		Drawing = function(ent)
			pcall(function()
				if not Targets.Players.Enabled and ent.Player then return end
				if not Targets.NPCs.Enabled and ent.NPC then return end
				if Teammates.Enabled and (not ent.Targetable) and (not ent.Friend) then return end
				if Reference[ent] then return end

				local nametag = {}
				nametag.BG = Drawing.new('Square')
				nametag.BG.Filled = true
				nametag.BG.Transparency = 1 - Background.Value
				nametag.BG.Color = Color3.new()
				nametag.BG.ZIndex = 1
				nametag.Text = Drawing.new('Text')
				nametag.Text.Size = 15 * Scale.Value
				nametag.Text.Font = 0
				nametag.Text.ZIndex = 2
				Strings[ent] = ent.Player and whitelist:tag(ent.Player, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name

				if Device.Enabled and ent.Player then
					local emoji = getDeviceEmoji(ent.Player)
					if emoji then
						Strings[ent] = emoji..' '..Strings[ent]
					end
				end

				if Health.Enabled then
					Strings[ent] = Strings[ent]..' '..math.round(ent.Health)
				end

				if Distance.Enabled then
					Strings[ent] = '[%s] '..Strings[ent]
				end

				nametag.Text.Text = Strings[ent]
				nametag.Text.Color = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
				nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
				Reference[ent] = nametag
			end)
		end
	}
	
	local Removed = {
		Normal = function(ent)
			pcall(function()
				unwatchEnchant(ent)
				unwatchInventory(ent)
				local v = Reference[ent]
				if v then
					Reference[ent] = nil
					Strings[ent] = nil
					Sizes[ent] = nil
					v:Destroy()
				end
			end)
		end,
		Drawing = function(ent)
			pcall(function()
				unwatchEnchant(ent)
				unwatchInventory(ent)
				local v = Reference[ent]
				if v then
					Reference[ent] = nil
					Strings[ent] = nil
					Sizes[ent] = nil
					for _, obj in v do
						pcall(function()
							obj.Visible = false
							obj:Remove()
						end)
					end
				end
			end)
		end
	}
	
	local Updated = {
		Normal = function(ent)
			pcall(function()
				local nametag = Reference[ent]
				if not nametag or not nametag.Parent then return end
				
				if vape.ThreadFix then
					setthreadidentity(8)
				end
				Sizes[ent] = nil
				Strings[ent] = ent.Player and whitelist:tag(ent.Player, true, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name

				if Device.Enabled and ent.Player then
					local emoji = getDeviceEmoji(ent.Player)
					if emoji then
						Strings[ent] = emoji..' '..Strings[ent]
					end
				end

				if Health.Enabled then
					local healthColor = Color3.fromHSV(math.clamp(ent.Health / ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)
					Strings[ent] = Strings[ent]..' <font color="rgb('..tostring(math.floor(healthColor.R * 255))..','..tostring(math.floor(healthColor.G * 255))..','..tostring(math.floor(healthColor.B * 255))..')">'..math.round(ent.Health)..'</font>'
				end

				if Distance.Enabled then
					Strings[ent] = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '..Strings[ent]
				end

				if Equipment.Enabled and store.inventories and store.inventories[ent.Player] and nametag:FindFirstChild("Hand") then
					local inventory = store.inventories[ent.Player]
					local handItem = inventory.hand or {itemType = '', amount = 1}

					if bedwars and bedwars.getIcon then
						nametag.Hand.Image = bedwars.getIcon(handItem, true)
						nametag.Helmet.Image = bedwars.getIcon(inventory.armor and inventory.armor[4] or {itemType = ''}, true)
						nametag.Chestplate.Image = bedwars.getIcon(inventory.armor and inventory.armor[5] or {itemType = ''}, true)
						nametag.Boots.Image = bedwars.getIcon(inventory.armor and inventory.armor[6] or {itemType = ''}, true)
					end

					local amountLabel = nametag.Hand:FindFirstChild('AmountLabel')
					if amountLabel then
						local amount = handItem.amount or handItem.quantity or 1
						if amount > 1 then
							amountLabel.Text = tostring(amount)
						else
							amountLabel.Text = ''
						end
					end
				end

				if Rank.Enabled and ent.Player then
					local icon = nametag:FindFirstChild('RankIcon')
					if icon then
						icon.Image = getRankImage(ent.Player) or ''
					end
				end

				if Enchant.Enabled and ent.Player then
					local icon = nametag:FindFirstChild('EnchantIcon')
					if icon then
						icon.Image = getEnchantImage(ent.Player) or ''
					end
				end

				local kitIcon = nametag:FindFirstChild('KitIcon')
				if kitIcon and ent.Player then
					kitIcon.Image = getKitImage(ent.Player) or ''
				end

				local size = getfontsize(removeTags(Strings[ent]), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
				nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
				positionIcons(nametag, size.X)
				nametag.Text = Strings[ent]
			end)
		end,
		Drawing = function(ent)
			pcall(function()
				local nametag = Reference[ent]
				if not nametag then return end
				
				if vape.ThreadFix then
					setthreadidentity(8)
				end
				Sizes[ent] = nil
				Strings[ent] = ent.Player and whitelist:tag(ent.Player, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name

				if Device.Enabled and ent.Player then
					local emoji = getDeviceEmoji(ent.Player)
					if emoji then
						Strings[ent] = emoji..' '..Strings[ent]
					end
				end

				if Health.Enabled then
					Strings[ent] = Strings[ent]..' '..math.round(ent.Health)
				end

				if Distance.Enabled then
					Strings[ent] = '[%s] '..Strings[ent]
					nametag.Text.Text = entitylib.isAlive and string.format(Strings[ent], math.floor((entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude)) or Strings[ent]
				else
					nametag.Text.Text = Strings[ent]
				end

				nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
				nametag.Text.Color = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
			end)
		end
	}
	
	refreshTag = function(ent)
		if Reference[ent] and Updated[methodused] then
			Updated[methodused](ent)
		end
	end

	local ColorFunc = {
		Normal = function(hue, sat, val)
			pcall(function()
				local color = Color3.fromHSV(hue, sat, val)
				for i, v in Reference do
					if v and v.Parent then
						v.TextColor3 = entitylib.getEntityColor(i) or color
					end
				end
			end)
		end,
		Drawing = function(hue, sat, val)
			pcall(function()
				local color = Color3.fromHSV(hue, sat, val)
				for i, v in Reference do
					if v and v.Text then
						v.Text.Color = entitylib.getEntityColor(i) or color
					end
				end
			end)
		end
	}
	
	local Loop = {
		Normal = function()
			pcall(function()
				local selfPos = entitylib.isAlive and entitylib.character.RootPart.Position
				for ent, nametag in Reference do
					if not nametag or not nametag.Parent then
						Reference[ent] = nil
						continue
					end
					
					if DistanceCheck.Enabled then
						local distance = selfPos and (selfPos - ent.RootPart.Position).Magnitude or math.huge
						if distance < DistanceLimit.ValueMin or distance > DistanceLimit.ValueMax then
							nametag.Visible = false
							continue
						end
					end

					local headPos, headVis = gameCamera:WorldToViewportPoint(ent.RootPart.Position + Vector3.new(0, ent.HipHeight + 1, 0))
					nametag.Visible = headVis
					if not headVis then
						continue
					end

					if Distance.Enabled then
						local mag = selfPos and math.floor((selfPos - ent.RootPart.Position).Magnitude) or 0
						if Sizes[ent] ~= mag then
							nametag.Text = string.format(Strings[ent], mag)
							local ize = getfontsize(removeTags(nametag.Text), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
							nametag.Size = UDim2.fromOffset(ize.X + 8, ize.Y + 7)
							positionIcons(nametag, ize.X)
							Sizes[ent] = mag
						end
					end
					
					if Equipment.Enabled and store.inventories and store.inventories[ent.Player] then
						local inventory = store.inventories[ent.Player]
						local handItem = inventory.hand or {itemType = '', amount = 1}
						local amountLabel = nametag:FindFirstChild('Hand') and nametag.Hand:FindFirstChild('AmountLabel')
						
						if amountLabel then
							local amount = handItem.amount or handItem.quantity or 1
							local newText = amount > 1 and tostring(amount) or ''
							if amountLabel.Text ~= newText then
								amountLabel.Text = newText
							end
						end
					end
					
					nametag.Position = UDim2.fromOffset(headPos.X, headPos.Y)
				end
			end)
		end,
		Drawing = function()
			pcall(function()
				local selfPos = entitylib.isAlive and entitylib.character.RootPart.Position
				for ent, nametag in Reference do
					if not nametag or not nametag.Text or not nametag.BG then
						Reference[ent] = nil
						continue
					end

					if DistanceCheck.Enabled then
						local distance = selfPos and (selfPos - ent.RootPart.Position).Magnitude or math.huge
						if distance < DistanceLimit.ValueMin or distance > DistanceLimit.ValueMax then
							nametag.Text.Visible = false
							nametag.BG.Visible = false
							continue
						end
					end

					local headPos, headVis = gameCamera:WorldToViewportPoint(ent.RootPart.Position + Vector3.new(0, ent.HipHeight + 1, 0))
					nametag.Text.Visible = headVis
					nametag.BG.Visible = headVis
					if not headVis then
						continue
					end

					if Distance.Enabled then
						local mag = selfPos and math.floor((selfPos - ent.RootPart.Position).Magnitude) or 0
						if Sizes[ent] ~= mag then
							nametag.Text.Text = string.format(Strings[ent], mag)
							nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
							Sizes[ent] = mag
						end
					end
					nametag.BG.Position = Vector2.new(headPos.X - (nametag.BG.Size.X / 2), headPos.Y - nametag.BG.Size.Y)
					nametag.Text.Position = nametag.BG.Position + Vector2.new(4, 3)
				end
			end)
		end
	}
	
	NameTags = vape.Categories.Render:CreateModule({
		Name = 'NameTags',
		Function = function(callback)
			if callback then
				methodused = DrawingToggle.Enabled and 'Drawing' or 'Normal'
				if Removed[methodused] then
					NameTags:Clean(entitylib.Events.EntityRemoved:Connect(Removed[methodused]))
				end
				if Added[methodused] then
					for _, v in entitylib.List do
						if Reference[v] then
							Removed[methodused](v)
						end
						Added[methodused](v)
					end
					NameTags:Clean(entitylib.Events.EntityAdded:Connect(function(ent)
						if Reference[ent] then
							Removed[methodused](ent)
						end
						Added[methodused](ent)
					end))
				end
				if Updated[methodused] then
					NameTags:Clean(entitylib.Events.EntityUpdated:Connect(Updated[methodused]))
					for _, v in entitylib.List do
						Updated[methodused](v)
					end
				end
				if ColorFunc[methodused] then
					NameTags:Clean(vape.Categories.Friends.ColorUpdate.Event:Connect(function()
						ColorFunc[methodused](Color.Hue, Color.Sat, Color.Value)
					end))
				end
				if Loop[methodused] then
					NameTags:Clean(runService.RenderStepped:Connect(Loop[methodused]))
				end

				local function watchDevice(plr)
					NameTags:Clean(plr:GetAttributeChangedSignal('UserInputType'):Connect(function()
						if not Device.Enabled then return end
						local ent = entitylib.getEntity(plr)
						if ent then
							refreshTag(ent)
						end
					end))
					NameTags:Clean(plr:GetAttributeChangedSignal('PlayingAsKit'):Connect(function()
						local ent = entitylib.getEntity(plr)
						if ent then
							refreshTag(ent)
						end
					end))
				end

				for _, plr in playersService:GetPlayers() do
					watchDevice(plr)
				end
				NameTags:Clean(playersService.PlayerAdded:Connect(watchDevice))
			else
				if Removed[methodused] then
					for i in Reference do
						Removed[methodused](i)
					end
				end
				for ent in enchantConns do
					unwatchEnchant(ent)
				end
				for ent in inventoryConns do
					unwatchInventory(ent)
				end
			end
		end,
		Tooltip = 'Renders nametags on entities through walls.'
	})
	Targets = NameTags:CreateTargets({
		Players = true,
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	FontOption = NameTags:CreateFont({
		Name = 'Font',
		Blacklist = 'Arial',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	Color = NameTags:CreateColorSlider({
		Name = 'Player Color',
		Function = function(hue, sat, val)
			if NameTags.Enabled and ColorFunc[methodused] then
				ColorFunc[methodused](hue, sat, val)
			end
		end
	})
	Scale = NameTags:CreateSlider({
		Name = 'Scale',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = 1,
		Min = 0.1,
		Max = 1.5,
		Decimal = 10
	})
	Background = NameTags:CreateSlider({
		Name = 'Transparency',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = 0.5,
		Min = 0,
		Max = 1,
		Decimal = 10
	})
	Health = NameTags:CreateToggle({
		Name = 'Health',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	Distance = NameTags:CreateToggle({
		Name = 'Distance',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	Equipment = NameTags:CreateToggle({
		Name = 'Equipment',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	Rank = NameTags:CreateToggle({
		Name = 'Show Rank',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Tooltip = 'Shows the ranked division icon above the nametag'
	})
	Enchant = NameTags:CreateToggle({
		Name = 'Show Enchant',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Tooltip = 'Shows the player\'s active enchant icon above the nametag'
	})
	ShowKits = NameTags:CreateToggle({
		Name = 'Show Kits',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Tooltip = 'Shows the player\'s equipped BedWars kit icon above the nametag',
		Default = true
	})
	Device = NameTags:CreateToggle({
		Name = 'Show Device',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Tooltip = 'Shows 🎮 / 🖥️ / 📱 for the input device the player is on'
	})
	DisplayName = NameTags:CreateToggle({
		Name = 'Use Displayname',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = true
	})
	Teammates = NameTags:CreateToggle({
		Name = 'Priority Only',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = true
	})
	DrawingToggle = NameTags:CreateToggle({
		Name = 'Drawing',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
	})
	DistanceCheck = NameTags:CreateToggle({
		Name = 'Distance Check',
		Function = function(callback)
			DistanceLimit.Object.Visible = callback
		end
	})
	DistanceLimit = NameTags:CreateTwoSlider({
		Name = 'Player Distance',
		Min = 0,
		Max = 256,
		DefaultMin = 0,
		DefaultMax = 64,
		Darker = true,
		Visible = false
	})
end)

run(function()
	local GeneratorESP
	DiamondToggle = nil
	EmeraldToggle = nil
	TeamGenToggle = nil
	ShowOwnTeamGen = nil
	ShowEnemyTeamGen = nil
	local UIStyle
	local CompactDiamondToggle
	local CompactEmeraldToggle
	local CollectionService = collectionService
	local RunService = runService
	local Reference = {}
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui
	local CompactFolder = Instance.new('Folder')
	CompactFolder.Parent = vape.gui
	local teamColors = getgenv().aeroTeamColors

	local generatorTypes = {
		diamond = {
			keywords = {'diamond'},
			color = Color3.fromRGB(85, 200, 255),
			icon = 'diamond',
			displayName = 'Diamond',
			isTeamGen = false
		},
		emerald = {
			keywords = {'emerald'},
			color = Color3.fromRGB(0, 255, 100),
			icon = 'emerald',
			displayName = 'Emerald',
			isTeamGen = false
		}
	}

	local compactUI = Instance.new('ScreenGui')
	compactUI.Name = 'GeneratorCompactUI'
	compactUI.Parent = vape.gui
	compactUI.Enabled = false
	compactUI.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	compactUI.DisplayOrder = 10
	compactUI.ResetOnSpawn = false

	local mainFrame = Instance.new('Frame')
	mainFrame.Name = 'MainFrame'
	mainFrame.Parent = compactUI
	mainFrame.BackgroundColor3 = Color3.fromRGB(20, 20, 20)
	mainFrame.BackgroundTransparency = 0.3
	mainFrame.BorderSizePixel = 0
	mainFrame.Position = UDim2.new(1, -8, 1, -8)
	mainFrame.Size = UDim2.new(0, 120, 0, 100)
	mainFrame.AnchorPoint = Vector2.new(1, 1)

	local uicorner = Instance.new('UICorner')
	uicorner.CornerRadius = UDim.new(0, 8)
	uicorner.Parent = mainFrame

	local title = Instance.new('TextLabel')
	title.Name = 'Title'
	title.Parent = mainFrame
	title.BackgroundTransparency = 1
	title.Size = UDim2.new(1, 0, 0, 25)
	title.Position = UDim2.new(0, 0, 0, 5)
	title.Text = "GEN ESP"
	title.TextColor3 = Color3.fromRGB(255, 255, 255)
	title.TextSize = 14
	title.Font = Enum.Font.GothamBold
	title.TextStrokeTransparency = 0.5
	title.TextStrokeColor3 = Color3.new(0, 0, 0)

	local diamondFrame = Instance.new('Frame')
	diamondFrame.Name = 'DiamondFrame'
	diamondFrame.Parent = mainFrame
	diamondFrame.BackgroundTransparency = 1
	diamondFrame.Size = UDim2.new(1, -20, 0, 25)
	diamondFrame.Position = UDim2.new(0, 10, 0, 35)

	local diamondIcon = Instance.new('ImageLabel')
	diamondIcon.Name = 'DiamondIcon'
	diamondIcon.Parent = diamondFrame
	diamondIcon.BackgroundTransparency = 1
	diamondIcon.Size = UDim2.new(0, 18, 0, 18)
	diamondIcon.Position = UDim2.new(0, 0, 0.5, -9)
	diamondIcon.Image = bedwars.getIcon({itemType = 'diamond'}, true)

	local diamondTimer = Instance.new('TextLabel')
	diamondTimer.Name = 'DiamondTimer'
	diamondTimer.Parent = diamondFrame
	diamondTimer.BackgroundTransparency = 1
	diamondTimer.Size = UDim2.new(1, -25, 1, 0)
	diamondTimer.Position = UDim2.new(0, 25, 0, 0)
	diamondTimer.Text = "00"
	diamondTimer.TextColor3 = Color3.fromRGB(85, 200, 255)
	diamondTimer.TextSize = 18
	diamondTimer.Font = Enum.Font.GothamBold
	diamondTimer.TextXAlignment = Enum.TextXAlignment.Left

	local emeraldFrame = Instance.new('Frame')
	emeraldFrame.Name = 'EmeraldFrame'
	emeraldFrame.Parent = mainFrame
	emeraldFrame.BackgroundTransparency = 1
	emeraldFrame.Size = UDim2.new(1, -20, 0, 25)
	emeraldFrame.Position = UDim2.new(0, 10, 0, 65)

	local emeraldIcon = Instance.new('ImageLabel')
	emeraldIcon.Name = 'EmeraldIcon'
	emeraldIcon.Parent = emeraldFrame
	emeraldIcon.BackgroundTransparency = 1
	emeraldIcon.Size = UDim2.new(0, 18, 0, 18)
	emeraldIcon.Position = UDim2.new(0, 0, 0.5, -9)
	emeraldIcon.Image = bedwars.getIcon({itemType = 'emerald'}, true)

	local emeraldTimer = Instance.new('TextLabel')
	emeraldTimer.Name = 'EmeraldTimer'
	emeraldTimer.Parent = emeraldFrame
	emeraldTimer.BackgroundTransparency = 1
	emeraldTimer.Size = UDim2.new(1, -25, 1, 0)
	emeraldTimer.Position = UDim2.new(0, 25, 0, 0)
	emeraldTimer.Text = "00"
	emeraldTimer.TextColor3 = Color3.fromRGB(0, 255, 100)
	emeraldTimer.TextSize = 18
	emeraldTimer.Font = Enum.Font.GothamBold
	emeraldTimer.TextXAlignment = Enum.TextXAlignment.Left

	local diamondTimes = {}
	local emeraldTimes = {}

	local function getMyTeamId()
		local myTeam = lplr:GetAttribute('Team')
		if myTeam == nil then return nil end
		return tonumber(myTeam)
	end

	local function getGeneratorTeamId(generatorId)
		local teamNum = string.match(generatorId, "^(%d+)_generator")
		if teamNum then
			return tonumber(teamNum)
		end
		return nil
	end

	local function isTeamGenerator(generatorId)
		return string.match(generatorId, "^%d+_generator") ~= nil
	end

	local function getGeneratorType(generatorId)
		local idLower = string.lower(generatorId)

		if isTeamGenerator(generatorId) then
			return 'teamgen', {
				color = Color3.fromRGB(200, 200, 200),
				icon = 'iron',
				displayName = 'Team Gen',
				isTeamGen = true
			}
		end

		for genType, config in pairs(generatorTypes) do
			for _, keyword in ipairs(config.keywords) do
				if idLower:find(keyword) then
					return genType, config
				end
			end
		end
		return nil, nil
	end

	local function isGeneratorEnabled(genType, teamId)
		if genType == 'diamond' then
			return DiamondToggle.Enabled
		elseif genType == 'emerald' then
			return EmeraldToggle.Enabled
		elseif genType == 'teamgen' then
			if not TeamGenToggle.Enabled then return false end
			local myTeamId = getMyTeamId()
			if not myTeamId or not teamId then return TeamGenToggle.Enabled end
			if teamId == myTeamId then
				return ShowOwnTeamGen.Enabled
			else
				return ShowEnemyTeamGen.Enabled
			end
		end
		return false
	end

	local function getProperIcon(iconType)
		local icon = bedwars.getIcon({itemType = iconType}, true)
		if not icon or icon == "" then return nil end
		return icon
	end

	local function getTierText(generatorAdornee)
		if not generatorAdornee then return nil end
		if generatorAdornee.Name ~= 'GeneratorAdornee' then return nil end
		local reactTree = generatorAdornee:FindFirstChild('RoactTree')
		if not reactTree then return nil end
		local teamApp = reactTree:FindFirstChild('TeamOreGeneratorApp')
		if not teamApp then return nil end
		local globalGen = teamApp:FindFirstChild('GlobalOreGenerator')
		if globalGen then
			for _, child in pairs(globalGen:GetDescendants()) do
				if child:IsA('TextLabel') then
					local text = child.Text
					if text:find("Tier") or text:match("^[IVX]+$") or text == "0" then
						return child
					end
				end
			end
		end
		local teamGenMain = teamApp:FindFirstChild('TeamGenMain')
		if teamGenMain then
			for _, child in pairs(teamGenMain:GetDescendants()) do
				if child:IsA('TextLabel') then
					local text = child.Text
					if text:find("Tier") or text:match("^[IVX]+$") or text == "0" then
						return child
					end
				end
			end
		end
		return nil
	end

	local function extractTierLevel(tierText)
		if not tierText or tierText == "" then return "0" end
		if tierText == "0" then return "0" end
		local tierMatch = tierText:match("Tier%s+([IVX]+)")
		if tierMatch then return tierMatch end
		if tierText:match("^[IVX]+$") then return tierText end
		local numTier = tierText:match("Tier%s+(%d+)")
		if numTier then
			local num = tonumber(numTier)
			if num == 0 then return "0"
			elseif num == 1 then return "I"
			elseif num == 2 then return "II"
			elseif num == 3 then return "III"
			end
		end
		return "0"
	end

	local function getCountdownText(generatorAdornee)
		if not generatorAdornee then return nil end
		if generatorAdornee.Name ~= 'GeneratorAdornee' then return nil end
		local reactTree = generatorAdornee:FindFirstChild('RoactTree')
		if not reactTree then return nil end
		local teamApp = reactTree:FindFirstChild('TeamOreGeneratorApp')
		if not teamApp then return nil end
		local globalGen = teamApp:FindFirstChild('GlobalOreGenerator')
		if not globalGen then return nil end
		local countdown = globalGen:FindFirstChild('Countdown')
		if not countdown then return nil end
		local textLabel = countdown:FindFirstChild('Text')
		if not textLabel then
			if countdown:IsA('TextLabel') then return countdown end
			return nil
		end
		return textLabel
	end

	local function extractSecondsFromText(text)
		if not text or text == "" then return 0 end
		local seconds = text:match("%[(%d+)%]")
		if seconds then return tonumber(seconds) or 0 end
		local justNumber = text:match("(%d+)")
		if justNumber then return tonumber(justNumber) or 0 end
		return 0
	end

	local function getResourceCount(position, resourceType)
		local count = 0
		for _, drop in pairs(CollectionService:GetTagged('ItemDrop')) do
			if drop:FindFirstChild('Handle') then
				local dropName = drop.Name:lower()
				if dropName:find(resourceType) then
					local dist = (drop.Handle.Position - position).Magnitude
					if dist <= 10 then
						local amount = drop:GetAttribute('Amount') or 1
						count = count + amount
					end
				end
			end
		end
		return count
	end

	local CompactGenerators = {}

	local function rebuildCompactGenerators()
		table.clear(CompactGenerators)
		scanDescendants(workspace, function(obj)
			if obj.Name == 'GeneratorAdornee' then
				local ok, generatorId = pcall(function() return obj:GetAttribute('Id') end)
				if ok and generatorId and type(generatorId) == 'string' and generatorId ~= '' then
					local genType = getGeneratorType(generatorId)
					if genType == 'diamond' or genType == 'emerald' then
						table.insert(CompactGenerators, {obj = obj, genType = genType})
					end
				end
			end
		end)
	end

	local function updateCompactUI()
		if not GeneratorESP.Enabled or UIStyle.Value ~= 'Compact' then
			compactUI.Enabled = false
			return
		end
		compactUI.Enabled = true
		local bestDiamondTime = math.huge
		local bestEmeraldTime = math.huge
		for i = #CompactGenerators, 1, -1 do
			local entry = CompactGenerators[i]
			if not entry.obj or not entry.obj.Parent then
				table.remove(CompactGenerators, i)
				continue
			end
			local countdownText = getCountdownText(entry.obj)
			if countdownText and countdownText.Text then
				local timeLeft = extractSecondsFromText(countdownText.Text)
				if entry.genType == 'diamond' and timeLeft > 0 and timeLeft < bestDiamondTime then
					bestDiamondTime = timeLeft
				elseif entry.genType == 'emerald' and timeLeft > 0 and timeLeft < bestEmeraldTime then
					bestEmeraldTime = timeLeft
				end
			end
		end
		local showDiamond = CompactDiamondToggle and CompactDiamondToggle.Enabled
		local showEmerald = CompactEmeraldToggle and CompactEmeraldToggle.Enabled

		if not showDiamond and not showEmerald then
			compactUI.Enabled = false
			return
		end

		diamondFrame.Visible = showDiamond
		emeraldFrame.Visible = showEmerald

		if showDiamond then
			diamondFrame.Position = UDim2.new(0, 10, 0, 35)
		end
		if showEmerald then
			emeraldFrame.Position = UDim2.new(0, 10, 0, showDiamond and 65 or 35)
		end

		diamondTimes[1] = bestDiamondTime ~= math.huge and bestDiamondTime or 0
		emeraldTimes[1] = bestEmeraldTime ~= math.huge and bestEmeraldTime or 0
		if bestDiamondTime == math.huge then
			diamondTimer.Text = "00"
		else
			diamondTimer.Text = string.format("%02d", bestDiamondTime)
			if bestDiamondTime <= 5 then
				diamondTimer.TextColor3 = Color3.fromRGB(255, 50, 50)
			elseif bestDiamondTime <= 10 then
				diamondTimer.TextColor3 = Color3.fromRGB(255, 165, 0)
			else
				diamondTimer.TextColor3 = Color3.fromRGB(85, 200, 255)
			end
		end
		if bestEmeraldTime == math.huge then
			emeraldTimer.Text = "00"
		else
			emeraldTimer.Text = string.format("%02d", bestEmeraldTime)
			if bestEmeraldTime <= 5 then
				emeraldTimer.TextColor3 = Color3.fromRGB(255, 50, 50)
			elseif bestEmeraldTime <= 10 then
				emeraldTimer.TextColor3 = Color3.fromRGB(255, 165, 0)
			else
				emeraldTimer.TextColor3 = Color3.fromRGB(0, 255, 100)
			end
		end
	end

	local function clearAllESP()
		Folder:ClearAllChildren()
		table.clear(Reference)
		compactUI.Enabled = false
	end

	local function createESP(generatorAdornee, genType, config, position, teamId)
		if not isGeneratorEnabled(genType, teamId) then return end
		if Reference[generatorAdornee] then return end

		if UIStyle.Value == 'Compact' then
			Reference[generatorAdornee] = {
				genType = genType,
				position = position,
				teamId = teamId,
				isTeamGen = config.isTeamGen
			}
			return
		end
		if not generatorAdornee or not generatorAdornee.Parent then return end

		local displayColor = config.color
		local teamName = nil
		if config.isTeamGen and teamId and teamColors[teamId] then
			displayColor = teamColors[teamId].color
			teamName = teamColors[teamId].name
		end

		local billboard = Instance.new('BillboardGui')
		billboard.Parent = Folder
		billboard.Name = 'generator-esp-' .. genType
		billboard.AlwaysOnTop = true
		billboard.ClipsDescendants = false
		billboard.Adornee = generatorAdornee
		billboard.Enabled = true  

		if config.isTeamGen then
			billboard.Size = UDim2.fromOffset(180, 55)
			billboard.StudsOffsetWorldSpace = Vector3.new(0, 5, 0)
		else
			billboard.Size = UDim2.fromOffset(80, 30)
			billboard.StudsOffsetWorldSpace = Vector3.new(0, 4, 0)
		end

		local blur = pcall(function()
			return addBlur(billboard)
		end) and blur or nil
		if blur then
			blur.Visible = true
		end

		if config.isTeamGen and teamName then
			local dot = Instance.new('Frame')
			dot.Name = 'TeamDot'
			dot.Parent = billboard
			dot.Size = UDim2.fromOffset(8, 8)
			dot.Position = UDim2.new(0, 10, 0, 5)
			dot.BackgroundColor3 = displayColor
			dot.BorderSizePixel = 0
			local dotCorner = Instance.new('UICorner')
			dotCorner.CornerRadius = UDim.new(1, 0)
			dotCorner.Parent = dot

			local teamLabel = Instance.new('TextLabel')
			teamLabel.Name = 'TeamLabel'
			teamLabel.Parent = billboard
			teamLabel.BackgroundTransparency = 1
			teamLabel.Size = UDim2.new(1, 0, 0, 18)
			teamLabel.Position = UDim2.new(0, 0, 0, 0)
			teamLabel.Text = teamName
			teamLabel.TextColor3 = displayColor
			teamLabel.TextSize = 13
			teamLabel.Font = Enum.Font.GothamBold
			teamLabel.TextStrokeTransparency = 0.4
			teamLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
			teamLabel.TextXAlignment = Enum.TextXAlignment.Center
		end

		local frame = Instance.new('Frame')
		frame.Size = config.isTeamGen and UDim2.new(1, 0, 0, 35) or UDim2.fromScale(1, 1)
		frame.Position = config.isTeamGen and UDim2.new(0, 0, 0, 20) or UDim2.new(0, 0, 0, 0)
		frame.BackgroundColor3 = Color3.new(0, 0, 0)
		frame.BackgroundTransparency = 0.3
		frame.BorderSizePixel = 0
		frame.Parent = billboard

		if config.isTeamGen and teamId and teamColors[teamId] then
			local stripe = Instance.new('Frame')
			stripe.Name = 'TeamStripe'
			stripe.Parent = frame
			stripe.Size = UDim2.new(0, 3, 1, 0)
			stripe.Position = UDim2.new(0, 0, 0, 0)
			stripe.BackgroundColor3 = displayColor
			stripe.BorderSizePixel = 0
			local stripeCorner = Instance.new('UICorner')
			stripeCorner.CornerRadius = UDim.new(0, 3)
			stripeCorner.Parent = stripe
		end

		local uicorner2 = Instance.new('UICorner')
		uicorner2.CornerRadius = UDim.new(0, 6)
		uicorner2.Parent = frame

		if config.isTeamGen then
			local tierLabel = Instance.new('TextLabel')
			tierLabel.Name = 'Tier'
			tierLabel.Size = UDim2.new(0, 25, 1, 0)
			tierLabel.Position = UDim2.new(0, 8, 0, 0)
			tierLabel.BackgroundTransparency = 1
			tierLabel.Text = "0"
			tierLabel.TextColor3 = Color3.fromRGB(255, 255, 100)
			tierLabel.TextSize = 16
			tierLabel.Font = Enum.Font.GothamBold
			tierLabel.TextStrokeTransparency = 0.5
			tierLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
			tierLabel.Parent = frame

			local resources = {
				{name = 'iron',    color = Color3.fromRGB(200, 200, 200), icon = 'iron',    xOffset = 35},
				{name = 'diamond', color = Color3.fromRGB(85, 200, 255),  icon = 'diamond', xOffset = 85},
				{name = 'emerald', color = Color3.fromRGB(0, 255, 100),   icon = 'emerald', xOffset = 135}
			}

			local resourceLabels = {}
			for _, resource in ipairs(resources) do
				local iconImage = getProperIcon(resource.icon)
				if iconImage then
					local image = Instance.new('ImageLabel')
					image.Size = UDim2.fromOffset(18, 18)
					image.Position = UDim2.new(0, resource.xOffset, 0.5, 0)
					image.AnchorPoint = Vector2.new(0, 0.5)
					image.BackgroundTransparency = 1
					image.Image = iconImage
					image.Parent = frame
				end
				local countLabel = Instance.new('TextLabel')
				countLabel.Name = resource.name .. '_count'
				countLabel.Size = UDim2.new(0, 25, 1, 0)
				countLabel.Position = UDim2.new(0, resource.xOffset + 20, 0, 0)
				countLabel.BackgroundTransparency = 1
				countLabel.Text = "0"
				countLabel.TextColor3 = resource.color
				countLabel.TextSize = 16
				countLabel.Font = Enum.Font.GothamBold
				countLabel.TextStrokeTransparency = 0.5
				countLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
				countLabel.TextXAlignment = Enum.TextXAlignment.Left
				countLabel.Parent = frame
				resourceLabels[resource.name] = countLabel
			end

			Reference[generatorAdornee] = {
				billboard = billboard,
				tierLabel = tierLabel,
				ironLabel = resourceLabels.iron,
				diamondLabel = resourceLabels.diamond,
				emeraldLabel = resourceLabels.emerald,
				genType = genType,
				position = position,
				teamId = teamId,
				isTeamGen = true
			}
		else
			local iconImage = getProperIcon(config.icon)
			if iconImage then
				local image = Instance.new('ImageLabel')
				image.Size = UDim2.fromOffset(20, 20)
				image.Position = UDim2.new(0, 5, 0.5, 0)
				image.AnchorPoint = Vector2.new(0, 0.5)
				image.BackgroundTransparency = 1
				image.Image = iconImage
				image.Parent = frame
			end
			local timerLabel = Instance.new('TextLabel')
			timerLabel.Name = 'Timer'
			timerLabel.Size = UDim2.new(0, 30, 1, 0)
			timerLabel.Position = UDim2.new(0.5, 0, 0, 0)
			timerLabel.AnchorPoint = Vector2.new(0.5, 0)
			timerLabel.BackgroundTransparency = 1
			timerLabel.Text = "00"
			timerLabel.TextColor3 = displayColor
			timerLabel.TextSize = 18
			timerLabel.Font = Enum.Font.GothamBold
			timerLabel.TextStrokeTransparency = 0.5
			timerLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
			timerLabel.Parent = frame
			local amountLabel = Instance.new('TextLabel')
			amountLabel.Name = 'Amount'
			amountLabel.Size = UDim2.new(0, 20, 1, 0)
			amountLabel.Position = UDim2.new(1, -20, 0, 0)
			amountLabel.BackgroundTransparency = 1
			amountLabel.Text = "0"
			amountLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
			amountLabel.TextSize = 16
			amountLabel.Font = Enum.Font.GothamBold
			amountLabel.TextStrokeTransparency = 0.5
			amountLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
			amountLabel.Parent = frame
			Reference[generatorAdornee] = {
				billboard = billboard,
				timerLabel = timerLabel,
				amountLabel = amountLabel,
				genType = genType,
				position = position,
				teamId = teamId,
				isTeamGen = false
			}
		end
		billboard.Enabled = true
	end

	local function updateESP(generatorAdornee)
		local ref = Reference[generatorAdornee]
		if not ref then return end
		if UIStyle.Value == 'Compact' then return end

		if ref.isTeamGen then
			if ref.tierLabel then
				local tierTextLabel = getTierText(generatorAdornee)
				if tierTextLabel and tierTextLabel.Text then
					ref.tierLabel.Text = extractTierLevel(tierTextLabel.Text)
				else
					ref.tierLabel.Text = "0"
				end
			end
			if ref.ironLabel then
				ref.ironLabel.Text = tostring(getResourceCount(ref.position, 'iron'))
			end
			if ref.diamondLabel then
				ref.diamondLabel.Text = tostring(getResourceCount(ref.position, 'diamond'))
			end
			if ref.emeraldLabel then
				ref.emeraldLabel.Text = tostring(getResourceCount(ref.position, 'emerald'))
			end
		else
			local countdownText = getCountdownText(generatorAdornee)
			if countdownText and countdownText.Text then
				local timeLeft = extractSecondsFromText(countdownText.Text)
				if ref.timerLabel then
					ref.timerLabel.Text = string.format("%02d", timeLeft)
					if timeLeft <= 5 then
						ref.timerLabel.TextColor3 = Color3.fromRGB(255, 50, 50)
					elseif timeLeft <= 10 then
						ref.timerLabel.TextColor3 = Color3.fromRGB(255, 165, 0)
					else
						ref.timerLabel.TextColor3 = generatorTypes[ref.genType].color
					end
				end
			else
				if ref.timerLabel then
					ref.timerLabel.Text = "00"
					ref.timerLabel.TextColor3 = Color3.fromRGB(150, 150, 150)
				end
			end
			if ref.amountLabel then
				ref.amountLabel.Text = tostring(getResourceCount(ref.position, ref.genType))
			end
		end
	end

	local function processGeneratorAdornee(obj)
		if obj.Name ~= 'GeneratorAdornee' then return end
		local ok, generatorId = pcall(function() return obj:GetAttribute('Id') end)
		if not ok then return end
		if generatorId == nil then return end
		if type(generatorId) ~= 'string' then return end
		if generatorId == '' then return end

		local position = obj:GetPivot().Position
		local genType, config = getGeneratorType(generatorId)
		if not genType or not config then return end

		local teamId = getGeneratorTeamId(generatorId)
		if isGeneratorEnabled(genType, teamId) then
			createESP(obj, genType, config, position, teamId)
		end
	end

	local function findAllGenerators()
		scanDescendants(workspace, function(obj)
			pcall(processGeneratorAdornee, obj)
		end)
	end

	local function refreshESP()
		clearAllESP()
		if GeneratorESP.Enabled then
			findAllGenerators()
		end
	end

	local updateTimer = 0

	GeneratorESP = vape.Categories.Render:CreateModule({
		Name = 'GeneratorESP',
		Function = function(callback)
			if callback then
				findAllGenerators()
				rebuildCompactGenerators()

				GeneratorESP:Clean(workspace.DescendantAdded:Connect(function(obj)
					if not GeneratorESP.Enabled then return end
					task.wait(0.2)
					pcall(processGeneratorAdornee, obj)
					if obj.Name == 'GeneratorAdornee' then
						rebuildCompactGenerators()
					end
				end))

				GeneratorESP:Clean(runService.Heartbeat:Connect(function(dt)
					if not GeneratorESP.Enabled then return end
					updateTimer = updateTimer + dt
					if updateTimer < 0.2 then return end
					updateTimer = 0
					for generatorAdornee, ref in pairs(Reference) do
						if generatorAdornee and generatorAdornee.Parent then
							updateESP(generatorAdornee)
						else
							if ref.billboard then ref.billboard:Destroy() end
							Reference[generatorAdornee] = nil
						end
					end
					updateCompactUI()
				end))

				GeneratorESP:Clean(workspace.DescendantRemoving:Connect(function(obj)
					if not GeneratorESP.Enabled then return end
					if Reference[obj] then
						if Reference[obj].billboard then Reference[obj].billboard:Destroy() end
						Reference[obj] = nil
					end
				end))
			else
				clearAllESP()
			end
		end,
		Tooltip = 'esp for generators showing timer and items count'
	})

	UIStyle = GeneratorESP:CreateDropdown({
		Name = 'UI Style',
		List = {'Original', 'Compact'},
		Default = 'Original',
		Function = function(val)
			local isOriginal = val == 'Original'
			if DiamondToggle then DiamondToggle.Object.Visible = isOriginal end
			if EmeraldToggle then EmeraldToggle.Object.Visible = isOriginal end
			if TeamGenToggle then TeamGenToggle.Object.Visible = isOriginal end
			if ShowOwnTeamGen then ShowOwnTeamGen.Object.Visible = isOriginal and TeamGenToggle.Enabled end
			if ShowEnemyTeamGen then ShowEnemyTeamGen.Object.Visible = isOriginal and TeamGenToggle.Enabled end
			if CompactDiamondToggle then CompactDiamondToggle.Object.Visible = not isOriginal end
			if CompactEmeraldToggle then CompactEmeraldToggle.Object.Visible = not isOriginal end
			refreshESP()
		end,
		Tooltip = 'pick between the norm billboard esp on generators or a ui with timers for generators '
	})

	DiamondToggle = GeneratorESP:CreateToggle({
		Name = 'Diamond',
		Function = function() refreshESP() end,
		Default = false,
		Visible = true
	})

	EmeraldToggle = GeneratorESP:CreateToggle({
		Name = 'Emerald',
		Function = function() refreshESP() end,
		Default = false,
		Visible = true
	})

	CompactDiamondToggle = GeneratorESP:CreateToggle({
		Name = 'Compact Diamond',
		Default = false,
		Visible = false,
		Function = function()
			refreshESP()
		end
	})

	CompactEmeraldToggle = GeneratorESP:CreateToggle({
		Name = 'Compact Emerald',
		Default = false,
		Visible = false,
		Function = function()
			refreshESP()
		end
	})

	TeamGenToggle = GeneratorESP:CreateToggle({
		Name = 'Team Generators',
		Function = function(callback)
			if ShowOwnTeamGen then ShowOwnTeamGen.Object.Visible = callback end
			if ShowEnemyTeamGen then ShowEnemyTeamGen.Object.Visible = callback end
			refreshESP()
		end,
		Default = true
	})

	ShowOwnTeamGen = GeneratorESP:CreateToggle({
		Name = 'Show Own Team',
		Function = function() refreshESP() end,
		Default = false,
		Visible = true
	})

	ShowEnemyTeamGen = GeneratorESP:CreateToggle({
		Name = 'Show Enemy Teams',
		Function = function() refreshESP() end,
		Default = true,
		Visible = true
	})
end)

run(function()
	local MouseTP
	local Mode
	local MovementMode
	local Length
	local Delay
	local rayCheck = RaycastParams.new()
	rayCheck.RespectCanCollide = true
	
	local function getWaypointInMouse()
		local obj, dist, location = nil, math.huge, inputService:GetMouseLocation()
	
		for _, v in WaypointFolder:GetChildren() do
			local position, vis = gameCamera:WorldToViewportPoint(v.StudsOffsetWorldSpace)
			if not vis then continue end
	
			local mag = (location - Vector2.new(position.x, position.y)).Magnitude
			if mag < dist then
				obj, dist = v, mag
			end
		end
	
		return obj
	end
	
	MouseTP = vape.Categories.Blatant:CreateModule({
		Name = 'MouseTP',
		Function = function(callback)
			if callback then
				local position
				if Mode.Value == 'Mouse' then
					local ray = cloneref(lplr:GetMouse()).UnitRay
					rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
					ray = workspace:Raycast(ray.Origin, ray.Direction * 10000, rayCheck)
					position = ray and ray.Position + Vector3.new(0, entitylib.character.HipHeight or 2, 0)
				elseif Mode.Value == 'Waypoint' then
					local waypoint = getWaypointInMouse()
					position = waypoint and waypoint.StudsOffsetWorldSpace
				else
					local ent = entitylib.EntityMouse({
						Range = math.huge,
						Part = 'RootPart',
						Players = true
					})
					position = ent and ent.RootPart.Position
				end
	
				if not position then
					notif('MouseTP', 'No position found.', 5)
					MouseTP:Toggle()
					return
				end
	
				if MovementMode.Value ~= 'Lerp' then
					MouseTP:Toggle()
					if entitylib.isAlive then
						if MovementMode.Value == 'Motor' then
							motorMove(entitylib.character.RootPart, CFrame.lookAlong(position, entitylib.character.RootPart.CFrame.LookVector))
						else
							entitylib.character.RootPart.CFrame = CFrame.lookAlong(position, entitylib.character.RootPart.CFrame.LookVector)
						end
					end
				else
					MouseTP:Clean(runService.Heartbeat:Connect(function()
						if entitylib.isAlive then
							entitylib.character.RootPart.Velocity = Vector3.zero
						end
					end))
	
					repeat
						if entitylib.isAlive then
							local direction = CFrame.lookAt(entitylib.character.RootPart.Position, position).LookVector * math.min((entitylib.character.RootPart.Position - position).Magnitude, Length.Value)
							entitylib.character.RootPart.CFrame += direction
							if (entitylib.character.RootPart.Position - position).Magnitude < 3 and MouseTP.Enabled then
								MouseTP:Toggle()
							end
						elseif MouseTP.Enabled then
							MouseTP:Toggle()
							notif('MouseTP', 'Character missing', 5, 'warning')
						end
	
						task.wait(Delay.Value)
					until not MouseTP.Enabled
				end
			end
		end,
		Tooltip = 'Teleports to a selected position.'
	})
	Mode = MouseTP:CreateDropdown({
		Name = 'Mode',
		List = {'Mouse', 'Player', 'Waypoint'}
	})
	MovementMode = MouseTP:CreateDropdown({
		Name = 'Movement',
		List = {'CFrame', 'Motor', 'Lerp'},
		Function = function(val)
			Length.Object.Visible = val == 'Lerp'
			Delay.Object.Visible = val == 'Lerp'
		end
	})
	Length = MouseTP:CreateSlider({
		Name = 'Length',
		Min = 0,
		Max = 22,
		Darker = true,
		Visible = false,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})
	Delay = MouseTP:CreateSlider({
		Name = 'Delay',
		Min = 0,
		Max = 1,
		Decimal = 100,
		Darker = true,
		Visible = false,
		Suffix = function(val)
			return val == 1 and 'second' or 'seconds'
		end
	})
end)

run(function()
	local SkinChanger
	local ItemSkinDropdown
	local SkinTypeDropdown

	local RS = game:GetService('ReplicatedStorage')
	local LocalPlayer = lplr
	local RESKIN_NAME = 'LOCAL_ITEM_RESKIN'

	local state = {
		itemSkin = 'Victorious Lyla',
		skinType = 'Nightmare',
	}

	local ok1, ItemType = pcall(function()
		return require(RS.TS.item['item-type']).ItemType
	end)
	if not ok1 then ItemType = {} end

	local ok2, ItemSkinType = pcall(function()
		return require(RS.TS.games.bedwars['item-skin']['item-skin-types']).ItemSkinType
	end)
	if not ok2 then ItemSkinType = {} end

	local KitSkinCtrl
	pcall(function()
		local KC = require(RS.rbxts_include.node_modules['@easy-games'].knit.src).KnitClient
		KitSkinCtrl = KC.Controllers.KitSkinController
	end)

	local BOW_ROT = CFrame.Angles(0, math.rad(-90), 0)
	local CROSSBOW_ROT = CFrame.new(0, 0, 0) * CFrame.Angles(0, math.rad(-360), 0)
	local LUNAR_CROSSBOW_ROT = CFrame.new(0, 0, 0) * CFrame.Angles(0, -190, math.rad(-180))
	local VICTORIOUS_ARCHER_BOW_ROT = CFrame.new(0, 0, 0) * CFrame.Angles(0, -52, math.rad(90))
	local VICTORIOUS_ARCHER_CROSSBOW_ROT = CFrame.new(0.00, 0.00, 0.00) * CFrame.Angles(math.rad(0), math.rad(80), math.rad(0.00))
	local VICTORIOUS_ARCHER_HEADHUNTER_ROT = CFrame.new(0, 0, 0) * CFrame.Angles(0, math.rad(0), 0)
