		["Darkheart Set"] = function() return { wood_sword = "wood_sword_darkvalentine", stone_sword = "stone_sword_darkvalentine", iron_sword = "iron_sword_darkvalentine", diamond_sword = "diamond_sword_darkvalentine", emerald_sword = "emerald_sword_darkvalentine", wood_pickaxe = "wood_pickaxe_darkvalentine", stone_pickaxe = "stone_pickaxe_darkvalentine", iron_pickaxe = "iron_pickaxe_darkvalentine", diamond_pickaxe = "diamond_pickaxe_darkvalentine", wood_axe = "wood_axe_darkvalentine", stone_axe = "stone_axe_darkvalentine", iron_axe = "iron_axe_darkvalentine", diamond_axe = "diamond_axe_darkvalentine" } end,
		["Heartbeam Swords"] = function() return { wood_sword = "wood_sword_heartbeam", stone_sword = "stone_sword_heartbeam", iron_sword = "iron_sword_heartbeam", diamond_sword = "diamond_sword_heartbeam", emerald_sword = "emerald_sword_heartbeam" } end,
		["Rabbit Beam Sword"] = function() return { wood_sword = "rabbit_beam_wood_sword", stone_sword = "rabbit_beam_stone_sword", iron_sword = "rabbit_beam_iron_sword", diamond_sword = "rabbit_beam_diamond_sword", emerald_sword = "rabbit_beam_emerald_sword" } end,
		["Valentine Axes"] = function() return { wood_axe = "wood_axe_valentine", stone_axe = "stone_axe_valentine", iron_axe = "iron_axe_valentine", diamond_axe = "diamond_axe_valentine" } end,
		["Mummy Lasso"] = function() return { lasso = "lasso_mummy" } end,
		["Mummy Life Bow"] = function() return { life_bow = "life_bow_mummy", life_crossbow = "life_crossbow_mummy", life_headhunter = "life_headhunter_mummy" } end,
		["Pixel Swords"] = function() return { wood_sword = "wood_sword_pixel", stone_sword = "stone_sword_pixel", iron_sword = "iron_sword_pixel", diamond_sword = "diamond_sword_pixel", emerald_sword = "emerald_sword_pixel" } end,
		["Pixel Swords Short"] = function() return { wood_sword = "wood_sword_short_pixel", stone_sword = "stone_sword_short_pixel", iron_sword = "iron_sword_short_pixel", diamond_sword = "diamond_sword_short_pixel", emerald_sword = "emerald_sword_short_pixel" } end,
	}

	local TIERED_SKINS = {
		["Victorious Lyla"] = true,
		["Victorious Archer"] = true,
		["Victorious Zeno"] = true,
		["Victorious Triton"] = true,
		["Victorious Cannon"] = true,
	}

	local active = {}
	local hideList = {}
	local hookConns = {}
	local savedStoreSkins = {}
	local renderConn
	local oldGetKitSkin
	local oldFireCannon
	local oldLaunchSelf
	local soundsHooked = false
	local refreshVersion = 0

	local function normalizeName(s)
		return s:lower():gsub('[_%s%-]', '')
	end

	local function isCannonSkin()
		return CANNON_SKIN_NAMES[state.itemSkin] ~= nil
	end

	local function getCannonSkinName()
		local tbl = CANNON_SKIN_NAMES[state.itemSkin]
		if not tbl then return nil end
		return tbl[state.skinType] or tbl.Default
	end

	local function getCurrentMappings()
		local fn = SKIN_DATA[state.itemSkin]
		if not fn then return {} end
		local ok, res = pcall(fn, state.skinType)
		if ok and type(res) == 'table' then return res end
		return {}
	end

	local function getKitSkinValue()
		local m = KIT_SKIN_MAP[state.itemSkin]
		if not m then return nil end
		return m[state.skinType] or m.Default
	end

	local function getStoreSkins()
		local fn = STORE_SKIN_MAP[state.itemSkin]
		if not fn then return {} end
		local ok, res = pcall(fn)
		if ok and type(res) == 'table' then return res end
		return {}
	end

	local function itemsFolder()
		return RS:FindFirstChild('Items')
	end

	local function blocksFolder()
		local assets = RS:FindFirstChild('Assets')
		return assets and assets:FindFirstChild('Blocks')
	end

	local function firstBasePart(root)
		if root:IsA('BasePart') then return root end
		for _, d in root:GetDescendants() do
			if d:IsA('BasePart') then return d end
		end
		return nil
	end

	local function setNoCollide(model)
		local function strip(p)
			p.CanCollide = false
			p.CanTouch = false
			p.CanQuery = false
			p.Massless = true
			p.Anchored = false
		end
		if model:IsA('BasePart') then strip(model) end
		for _, d in model:GetDescendants() do
			if d:IsA('BasePart') then strip(d) end
		end
	end

	local function weldAllTo(anchor, container)
		for _, d in container:GetDescendants() do
			if d:IsA('BasePart') and d ~= anchor then
				local wc = Instance.new('WeldConstraint')
				wc.Part0 = anchor
				wc.Part1 = d
				wc.Parent = anchor
			end
		end
	end

	local function getRigScale(root)
		local node = root
		local hum
		for _ = 1, 6 do
			if not node or node == workspace then break end
			hum = node:FindFirstChildOfClass('Humanoid')
			if hum then break end
			node = node.Parent
		end
		if not hum then return 1 end
		local total, count = 0, 0
		for _, name in {'BodyHeightScale', 'BodyWidthScale', 'BodyDepthScale'} do
			local v = hum:FindFirstChild(name)
			if v and v:IsA('NumberValue') and v.Value > 0 then
				total = total + v.Value
				count = count + 1
			end
		end
		if count == 0 then return 1 end
		return math.clamp(total / count, 0.3, 3)
	end

	local function startRenderLoop()
		if renderConn then return end
		renderConn = runService.RenderStepped:Connect(function()
			for i = #hideList, 1, -1 do
				local p = hideList[i]
				if p and p.Parent then
					p.LocalTransparencyModifier = 1
				else
					table.remove(hideList, i)
				end
			end
		end)
	end

	local function stopRenderLoop()
		if renderConn then
			pcall(function() renderConn:Disconnect() end)
			renderConn = nil
		end
	end

	local function hideDescendant(entry, d)
		if d:IsA('BasePart') then
			entry.parts[#entry.parts + 1] = {d, d.Transparency}
			d.Transparency = 1
			d.LocalTransparencyModifier = 1
			hideList[#hideList + 1] = d
		elseif d:IsA('Decal') or d:IsA('Texture') then
			entry.decals[#entry.decals + 1] = {d, d.Transparency}
			d.Transparency = 1
		end
	end

	local function hideOriginal(entry, root)
		for _, d in root:GetDescendants() do
			if not d:IsDescendantOf(entry.clone) then
				hideDescendant(entry, d)
			end
		end
	end

	local function detach(root)
		local entry = active[root]
		if not entry then return end
		active[root] = nil
		for _, c in entry.conns do
			pcall(function() c:Disconnect() end)
		end
		if entry.clone then
			pcall(function() entry.clone:Destroy() end)
		end
		for _, rec in entry.parts do
			local p = rec[1]
			local idx = table.find(hideList, p)
			if idx then table.remove(hideList, idx) end
			pcall(function()
				if p.Parent then
					p.Transparency = rec[2]
					p.LocalTransparencyModifier = 0
				end
			end)
		end
		for _, rec in entry.decals do
			local d = rec[1]
			pcall(function()
				if d.Parent then d.Transparency = rec[2] end
			end)
		end
	end

	local function detachAll()
		for root in active do
			detach(root)
		end
		table.clear(active)
		table.clear(hideList)
	end

	local function attachReskin(root, skinName, source, opts)
		if not root or not root.Parent then return end
		if active[root] or not source then return end
		opts = opts or {}

		local origHandle = root:FindFirstChild('Handle')
		if not (origHandle and origHandle:IsA('BasePart')) then
			origHandle = firstBasePart(root)
		end
		if not origHandle then return end

		local clone = source:Clone()
		clone.Name = RESKIN_NAME
		for _, d in clone:GetDescendants() do
			if d:IsA('LuaSourceContainer') then
				pcall(function() d:Destroy() end)
			end
		end
		setNoCollide(clone)

		local anchor
		local alignByPivot = false
		if clone:IsA('BasePart') then
			anchor = clone
		else
			local handle = clone:FindFirstChild('Handle')
			if handle and handle:IsA('BasePart') then
				anchor = handle
			else
				alignByPivot = true
				anchor = clone:IsA('Model') and clone.PrimaryPart or nil
				anchor = anchor or firstBasePart(clone)
			end
		end
		if not anchor then
			pcall(function() clone:Destroy() end)
			return
		end
		if clone:IsA('Model') and not clone.PrimaryPart then
			pcall(function() clone.PrimaryPart = anchor end)
		end

		local scale = (opts.scale or 1) * getRigScale(root)
		if clone:IsA('Model') and math.abs(scale - 1) > 0.001 then
			pcall(function() clone:ScaleTo(scale) end)
		end

		local entry = {clone = clone, parts = {}, decals = {}, conns = {}}
		active[root] = entry
		clone.Parent = root

		local offset = (SKIN_OFFSETS[skinName] or CFrame.identity) * (opts.offset or CFrame.identity)
		local target = origHandle.CFrame * offset
		pcall(function()
			if not clone:IsA('Model') then
				anchor.CFrame = target
			elseif alignByPivot then
				clone:PivotTo(target)
			else
				clone:PivotTo(target * anchor.CFrame:ToObjectSpace(clone:GetPivot()))
			end
		end)

		weldAllTo(anchor, clone)

		local weld = Instance.new('WeldConstraint')
		weld.Part0 = origHandle
		weld.Part1 = anchor
		weld.Parent = anchor

		hideOriginal(entry, root)
		startRenderLoop()

		entry.conns[#entry.conns + 1] = root.DescendantAdded:Connect(function(d)
			if entry.clone and entry.clone.Parent and d:IsDescendantOf(entry.clone) then return end
			hideDescendant(entry, d)
		end)
		entry.conns[#entry.conns + 1] = root.AncestryChanged:Connect(function(_, parent)
			if not parent then detach(root) end
		end)
	end

	local function track(conn)
		hookConns[#hookConns + 1] = conn
		return conn
	end

	local function clearHooks()
		for _, c in hookConns do
			pcall(function() c:Disconnect() end)
		end
		table.clear(hookConns)
	end

	local function deferCall(fn, ...)
		local args = table.pack(...)
		task.spawn(function()
			task.wait()
			fn(table.unpack(args, 1, args.n))
		end)
	end

	local function skinNameForChild(childName)
		local mappings = getCurrentMappings()
		local skinName = mappings[childName:lower()]
		if not skinName then
			local norm = normalizeName(childName)
			for k, v in mappings do
				if normalizeName(k) == norm then
					skinName = v
					break
				end
			end
		end
		return skinName
	end

	local function applyItem(child)
		if not (SkinChanger and SkinChanger.Enabled) then return end
		if isCannonSkin() or not child or not child.Parent then return end
		local skinName = skinNameForChild(child.Name)
		if not skinName then return end
		local folder = itemsFolder()
		if not folder then return end
		attachReskin(child, skinName, folder:FindFirstChild(skinName))
	end

	local function applyCannon(child, placed)
		if not (SkinChanger and SkinChanger.Enabled) then return end
		if not isCannonSkin() or not child or not child.Parent then return end
		if child.Name ~= CANNON_TOOL_NAME then return end
		local skinName = getCannonSkinName()
		if not skinName then return end
		local folder = blocksFolder()
		if not folder then return end
		attachReskin(child, skinName, folder:FindFirstChild(skinName), {
			offset = placed and CANNON_PLACED_OFFSET or CFrame.identity,
			scale = placed and 1 or CANNON_HAND_SCALE,
		})
	end

	local function applyProjectile(inst)
		if not (SkinChanger and SkinChanger.Enabled) then return end
		if isCannonSkin() or not inst or not inst.Parent then return end
		if not inst:IsA('Model') or inst.Name ~= 'harpoon_projectile' then return end
		local shooter = inst:GetAttribute('ProjectileShooter')
		if not shooter or tostring(shooter) ~= tostring(LocalPlayer.UserId) then return end
		local skinName = getCurrentMappings().harpoon
		if not skinName then return end
		local folder = itemsFolder()
		if not folder then return end
		attachReskin(inst, skinName, folder:FindFirstChild(skinName))
	end

	local function hookItemContainer(container)
		if not container then return end
		for _, child in container:GetChildren() do
			deferCall(applyItem, child)
		end
		track(container.ChildAdded:Connect(function(child)
			deferCall(applyItem, child)
		end))
	end

	local function hookCannonContainer(container, placed)
		if not container then return end
		for _, child in container:GetChildren() do
			deferCall(applyCannon, child, placed)
		end
		track(container.ChildAdded:Connect(function(child)
			deferCall(applyCannon, child, placed)
		end))
	end

	local function hookViewmodel(vm)
		if not vm then return end
		if isCannonSkin() then
			hookCannonContainer(vm, false)
		else
			hookItemContainer(vm)
		end
	end

	local function hookCamera(cam)
		if not cam then return end
		local vm = cam:FindFirstChild('Viewmodel')
		if vm then hookViewmodel(vm) end
		track(cam.ChildAdded:Connect(function(child)
			if child.Name == 'Viewmodel' then
				deferCall(hookViewmodel, child)
			end
		end))
	end

	local function hookWorldCannons()
		local map = workspace:FindFirstChild('Map')
		if not map then return end
		local worlds = map:FindFirstChild('Worlds')
		if not worlds then return end
		local function hookWorld(world)
			local blocks = world:FindFirstChild('Blocks')
			if blocks then hookCannonContainer(blocks, true) end
		end
		for _, world in worlds:GetChildren() do
			hookWorld(world)
		end
		track(worlds.ChildAdded:Connect(function(world)
			deferCall(hookWorld, world)
		end))
	end

	local function hookProjectiles()
		track(workspace.DescendantAdded:Connect(function(inst)
			if inst.Name == 'harpoon_projectile' then
				deferCall(applyProjectile, inst)
			end
		end))
	end

	local function applyKitSkinHook()
		if not KitSkinCtrl then return end
		local val = getKitSkinValue()
		if not val then return end
		if not oldGetKitSkin then oldGetKitSkin = KitSkinCtrl.getKitSkin end
		local base = oldGetKitSkin
		KitSkinCtrl.getKitSkin = function(self, char)
			if char == LocalPlayer.Character then return val end
			return base(self, char)
		end
	end

	local function removeKitSkinHook()
		if KitSkinCtrl and oldGetKitSkin then
			KitSkinCtrl.getKitSkin = oldGetKitSkin
			oldGetKitSkin = nil
		end
	end

	local function applyStoreSkins()
		if not (bedwars and bedwars.Store) then return end
		local skins = getStoreSkins()
		if #skins == 0 then return end
		local ok, st = pcall(function() return bedwars.Store:getState() end)
		if not ok then return end
		local selected = st and st.Locker and st.Locker.selectedItemSkins
		savedStoreSkins = {}
		for _, pair in skins do
			if pair[1] and pair[2] then
				savedStoreSkins[#savedStoreSkins + 1] = {pair[1], selected and selected[pair[1]]}
				pcall(function()
					bedwars.Store:dispatch({type = 'LockerSetItemSkin', itemType = pair[1], itemSkin = pair[2]})
				end)
			end
		end
	end

	local function clearStoreSkins()
		if #savedStoreSkins == 0 then return end
		if bedwars and bedwars.Store then
			for _, saved in savedStoreSkins do
				pcall(function()
					bedwars.Store:dispatch({type = 'LockerSetItemSkin', itemType = saved[1], itemSkin = saved[2]})
				end)
			end
		end
		savedStoreSkins = {}
	end

	local function hookCannonSounds()
		if soundsHooked then return end
		if not (bedwars and bedwars.CannonHandController) then return end
		soundsHooked = true
		oldFireCannon = bedwars.CannonHandController.fireCannon
		oldLaunchSelf = bedwars.CannonHandController.launchSelf

		local function replaceSound()
			pcall(function()
				local pool = workspace:FindFirstChild('SoundPool')
				if pool then
					for _, v in pool:GetChildren() do
						if v:IsA('Sound') and v.SoundId == 'rbxassetid://7121064180' then
							v:Destroy()
						end
					end
				end
				local key = CANNON_SOUND_NAMES[state.skinType] or CANNON_SOUND_NAMES.Nightmare
				if bedwars.SoundManager and bedwars.SoundList and bedwars.SoundList[key] then
					bedwars.SoundManager:playSound(bedwars.SoundList[key])
				end
			end)
		end

		if oldFireCannon then
			bedwars.CannonHandController.fireCannon = function(...)
				replaceSound()
				return oldFireCannon(...)
			end
		end
		if oldLaunchSelf then
			bedwars.CannonHandController.launchSelf = function(...)
				replaceSound()
				return oldLaunchSelf(...)
			end
		end
	end

	local function unhookCannonSounds()
		if soundsHooked and bedwars and bedwars.CannonHandController then
			if oldFireCannon then bedwars.CannonHandController.fireCannon = oldFireCannon end
			if oldLaunchSelf then bedwars.CannonHandController.launchSelf = oldLaunchSelf end
		end
		oldFireCannon = nil
		oldLaunchSelf = nil
		soundsHooked = false
	end

	local function hookCharacter(char)
		if not char then return end
		local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')
		if isCannonSkin() then
			hookCannonContainer(char, false)
			hookCannonContainer(backpack, false)
		else
			hookItemContainer(char)
			hookItemContainer(backpack)
		end
	end

	local function setup()
		if not (SkinChanger and SkinChanger.Enabled) then return end
		applyKitSkinHook()
		hookCamera(workspace.CurrentCamera)
		track(workspace:GetPropertyChangedSignal('CurrentCamera'):Connect(function()
			if SkinChanger.Enabled then hookCamera(workspace.CurrentCamera) end
		end))
		if isCannonSkin() then
			hookCannonSounds()
			hookWorldCannons()
		else
			applyStoreSkins()
			hookProjectiles()
		end
		hookCharacter(LocalPlayer.Character)
		track(LocalPlayer.CharacterAdded:Connect(function(char)
			task.spawn(function()
				task.wait(0.25)
				if not SkinChanger.Enabled then return end
				applyKitSkinHook()
				hookCharacter(char)
			end)
		end))
	end

	local function teardown()
		clearHooks()
		detachAll()
		stopRenderLoop()
		removeKitSkinHook()
		clearStoreSkins()
		unhookCannonSounds()
	end

	local function refresh()
		if not (SkinChanger and SkinChanger.Enabled) then return end
		refreshVersion = refreshVersion + 1
		local version = refreshVersion
		teardown()
		task.defer(function()
			if version ~= refreshVersion then return end
			if SkinChanger.Enabled then setup() end
		end)
	end

	local function syncSkinTypeVisibility()
		if SkinTypeDropdown and SkinTypeDropdown.Object then
			SkinTypeDropdown.Object.Visible = TIERED_SKINS[state.itemSkin] == true
		end
	end

	local skinNames = {}
	local seenNames = {}
	for name in SKIN_DATA do
		if not seenNames[name] then
			seenNames[name] = true
			skinNames[#skinNames + 1] = name
		end
	end
	for name in CANNON_SKIN_NAMES do
		if not seenNames[name] then
			seenNames[name] = true
			skinNames[#skinNames + 1] = name
		end
	end
	table.sort(skinNames)

	SkinChanger = vape.Categories.Render:CreateModule({
		Name = 'SkinChanger',
		Function = function(enabled)
			if enabled then
				setup()
			else
				teardown()
			end
		end,
		Tooltip = 'gives ur items a diff skin, only u can see it so dont trip'
	})

	vape:Clean(function() teardown() end)

	ItemSkinDropdown = SkinChanger:CreateDropdown({
		Name = 'Item Skin',
		List = skinNames,
		Default = state.itemSkin,
		Function = function(val)
			state.itemSkin = val
			if TIERED_SKINS[val] then
				state.skinType = SkinTypeDropdown and SkinTypeDropdown.Value or state.skinType
			else
				state.skinType = 'Default'
			end
			syncSkinTypeVisibility()
			refresh()
		end,
	})

	SkinTypeDropdown = SkinChanger:CreateDropdown({
		Name = 'Skin Type',
		List = {'Gold', 'Platinum', 'Diamond', 'Emerald', 'Nightmare', 'Default'},
		Default = state.skinType,
		Visible = false,
		Function = function(val)
			if not TIERED_SKINS[state.itemSkin] then return end
			state.skinType = val
			refresh()
		end,
	})

	task.spawn(function()
		for _ = 1, 24 do
			syncSkinTypeVisibility()
			task.wait(0.25)
		end
	end)
end)

run(function()
    local InventoryESP
    local Empty
    local SideBySide
    local ScaleSlider
    local Color = {}
    local windows = {} -- Track all player windows
    local playerWindows = {} -- Map player to their window
    
    local SlotCount = 24
    local PersonalSlotCount = 24
    local BaseSlotSize = 32
    local BaseSlotPadding = 4
    local Columns = 6
    local BaseHeaderHeight = 44
    local BaseWindowWidth = 240
    local BaseWindowSpacing = 8

    -- Saved & Target Dragging Position for Ultra-Smooth Movement
    local savedPosX = 14
    local savedPosY = 75
    local targetPosX = 14
    local targetPosY = 75

    -- Safe Resolution of BedWars Kit Metadata from ReplicatedStorage
    local BedwarsKitMeta = (function()
        local suc, res = pcall(function()
            return require(replicatedStorage.TS.games.bedwars.kit["bedwars-kit-meta"]).BedwarsKitMeta
        end)
        if suc and res then return res end
        local suc2, res2 = pcall(function()
            return require(replicatedStorage.TS.bedwars.kit["bedwars-kit-meta"]).BedwarsKitMeta
        end)
        return suc2 and res2 or nil
    end)()

    local function getScale()
        return ScaleSlider and (ScaleSlider.Value / 100) or 1.15
    end

    local function getPlayerKit(plr)
        if not plr then return nil end
        local kitAttr = plr:GetAttribute('BedwarsKit') or plr:GetAttribute('PlayingAsKit') or plr:GetAttribute('PlayingAsKits')
        if not kitAttr and plr.Character then
            kitAttr = plr.Character:GetAttribute('BedwarsKit') or plr.Character:GetAttribute('PlayingAsKit') or plr.Character:GetAttribute('PlayingAsKits')
        end
        if type(kitAttr) == 'string' then
            return kitAttr:split(',')[1]
        end
        if store and store.inventories and store.inventories[plr] then
            return store.inventories[plr].kit
        end
        return nil
    end

    local function resolveKitImage(plr)
        local kit = getPlayerKit(plr)
        if not kit or kit == "" or kit == "none" then return "" end

        if BedwarsKitMeta then
            local meta = BedwarsKitMeta[kit] or BedwarsKitMeta[tostring(kit):lower()]
            if meta and (meta.renderImage or meta.icon) then
                return meta.renderImage or meta.icon
            end
        end

        if bedwars and bedwars.BedwarsKitMeta then
            local meta = bedwars.BedwarsKitMeta[kit] or bedwars.BedwarsKitMeta[tostring(kit):lower()]
            if meta and (meta.renderImage or meta.icon) then
                return meta.renderImage or meta.icon
            end
        end

        return ""
    end

    local function createSlot(parent, scale)
        local slotSize = math.round(BaseSlotSize * scale)
        local slot = Instance.new('Frame')
        slot.Size = UDim2.fromOffset(slotSize, slotSize)
        slot.BackgroundColor3 = color.Dark(uipallet.Main, 0.03)
        slot.BorderSizePixel = 0
        slot.Visible = false
        slot.Parent = parent
        
        local corner = Instance.new('UICorner')
        corner.CornerRadius = UDim.new(0, math.max(4, math.round(5 * scale)))
        corner.Parent = slot
        
        local stroke = Instance.new('UIStroke')
        stroke.Color = color.Light(uipallet.Main, 0.04)
        stroke.Thickness = 1
        stroke.Parent = slot
        
        local icon = Instance.new('ImageLabel')
        icon.Name = 'Icon'
        icon.Size = UDim2.fromOffset(slotSize - 8, slotSize - 8)
        icon.Position = UDim2.fromScale(0.5, 0.5)
        icon.AnchorPoint = Vector2.new(0.5, 0.5)
        icon.BackgroundTransparency = 1
        icon.Parent = slot
        
        local amount = Instance.new('TextLabel')
        amount.Name = 'Amount'
        amount.Size = UDim2.new(1, -4, 0, math.round(10 * scale))
        amount.Position = UDim2.new(0, 0, 1, -math.round(11 * scale))
        amount.BackgroundTransparency = 1
        amount.Text = ''
        amount.TextXAlignment = Enum.TextXAlignment.Right
        amount.TextSize = math.max(8, math.round(9.5 * scale))
        amount.TextColor3 = uipallet.Text
        amount.TextStrokeColor3 = Color3.new()
        amount.TextStrokeTransparency = 0.4
        amount.FontFace = uipallet.Font
        amount.Parent = slot
        return slot
    end

    local function createSectionHeader(text, parent, scale)
        local label = Instance.new('TextLabel')
        label.Name = text .. 'Header'
        label.Size = UDim2.new(1, -20, 0, math.round(14 * scale))
        label.BackgroundTransparency = 1
        label.Text = text:upper()
        label.TextXAlignment = Enum.TextXAlignment.Left
        label.TextSize = math.max(8, math.round(9 * scale))
        label.TextColor3 = color.Light(uipallet.Text, 0.2)
        label.FontFace = uipallet.Font
        label.Visible = false
        label.Parent = parent
        return label
    end

    -- Smooth Dragging Implementation
    local isDragging = false
    local dragOffset = Vector2.zero
    local function makeDraggable(guiObject)
        guiObject.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                isDragging = true
                local mousePos = inputService:GetMouseLocation()
                dragOffset = mousePos - Vector2.new(savedPosX, savedPosY)
            end
        end)

        guiObject.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                isDragging = false
            end
        end)
    end

    runService.RenderStepped:Connect(function(dt)
        if isDragging then
            local mousePos = inputService:GetMouseLocation()
            targetPosX = math.max(0, mousePos.X - dragOffset.X)
            targetPosY = math.max(0, mousePos.Y - dragOffset.Y)
        end
        -- High precision frame-rate independent smooth lerp
        local lerpFactor = math.clamp(dt * 22, 0, 1)
        savedPosX = savedPosX + (targetPosX - savedPosX) * lerpFactor
        savedPosY = savedPosY + (targetPosY - savedPosY) * lerpFactor
    end)

    local function buildWindow(player)
        local scale = getScale()
        local winWidth = math.round(BaseWindowWidth * scale)
        local headerHeight = math.round(BaseHeaderHeight * scale)
        local slotSize = math.round(BaseSlotSize * scale)
        local slotPadding = math.round(BaseSlotPadding * scale)

        local window = Instance.new('Frame')
        window.Name = 'ViewInventory_' .. player.Name
        window.Size = UDim2.fromOffset(winWidth, headerHeight)
        window.BackgroundColor3 = uipallet.Main
        window.BackgroundTransparency = 1 - (Color.Opacity or 0.5)
        window.Visible = false
        window.Active = true
        window.Parent = vape.gui.ScaledGui
        addBlur(window)
        makeDraggable(window)
        
        local corner = Instance.new('UICorner')
        corner.CornerRadius = UDim.new(0, math.round(8 * scale))
        corner.Parent = window
        
        local priorityStroke = Instance.new('UIStroke')
        priorityStroke.Name = 'PriorityStroke'
        priorityStroke.Color = Color3.fromRGB(255, 255, 255)
        priorityStroke.Thickness = math.max(2, math.round(2.5 * scale))
        priorityStroke.Transparency = 1
        priorityStroke.Parent = window

        -- Headshot Avatar
        local headshot = Instance.new('ImageLabel')
        headshot.Name = 'Headshot'
        headshot.Size = UDim2.fromOffset(math.round(28 * scale), math.round(28 * scale))
        headshot.Position = UDim2.fromOffset(math.round(8 * scale), math.round(8 * scale))
        headshot.BackgroundColor3 = color.Dark(uipallet.Main, 0.03)
        headshot.Image = ''
        headshot.Parent = window
        local headcorner = Instance.new('UICorner')
        headcorner.CornerRadius = UDim.new(0, math.round(5 * scale))
        headcorner.Parent = headshot

        -- Player Display Name Tag
        local nametag = Instance.new('TextLabel')
        nametag.Name = 'Name'
        nametag.Size = UDim2.new(0, math.round(110 * scale), 0, math.round(24 * scale))
        nametag.Position = UDim2.fromOffset(math.round(42 * scale), math.round(10 * scale))
        nametag.BackgroundTransparency = 1
        nametag.Text = ''
        nametag.TextXAlignment = Enum.TextXAlignment.Left
        nametag.TextSize = math.max(10, math.round(11.5 * scale))
        nametag.TextColor3 = uipallet.Text
        nametag.TextTruncate = Enum.TextTruncate.AtEnd
        nametag.FontFace = uipallet.Font
        nametag.ZIndex = 3
        nametag.Parent = window

        -- 2x Bigger Kit Icon Badge (Positioned directly beside the player nametag)
        local kitIcon = Instance.new('ImageLabel')
        kitIcon.Name = 'KitIcon'
        kitIcon.Size = UDim2.fromOffset(math.round(36 * scale), math.round(36 * scale)) -- 2x Larger (36px scaled vs 18-22px)
        kitIcon.Position = UDim2.fromOffset(math.round(154 * scale), math.round(4 * scale))
        kitIcon.BackgroundTransparency = 1
        kitIcon.ScaleType = Enum.ScaleType.Fit
        kitIcon.Image = ''
        kitIcon.Visible = false
        kitIcon.ZIndex = 3
        kitIcon.Parent = window

        local divider = Instance.new('Frame')
        divider.Name = 'Divider'
        divider.Size = UDim2.new(1, -math.round(16 * scale), 0, 1)
        divider.Position = UDim2.fromOffset(math.round(8 * scale), headerHeight - 1)
        divider.BackgroundColor3 = color.Light(uipallet.Main, 0.05)
        divider.BorderSizePixel = 0
        divider.Parent = window

        local invLabel = createSectionHeader('Inventory', window, scale)
        local invGrid = Instance.new('Frame')
        invGrid.Name = 'InventoryItems'
        invGrid.Size = UDim2.new(1, -math.round(16 * scale), 0, 0)
        invGrid.BackgroundTransparency = 1
        invGrid.Parent = window
        local layout1 = Instance.new('UIGridLayout')
        layout1.CellSize = UDim2.fromOffset(slotSize, slotSize)
        layout1.CellPadding = UDim2.fromOffset(slotPadding, slotPadding)
        layout1.SortOrder = Enum.SortOrder.LayoutOrder
        layout1.Parent = invGrid

        local playerSlots = {}
        for i = 1, SlotCount do
            local slot = createSlot(invGrid, scale)
            slot.LayoutOrder = i
            playerSlots[i] = slot
        end

        local personalLabel = createSectionHeader('Personal Chest', window, scale)
        local personalGrid = Instance.new('Frame')
        personalGrid.Name = 'PersonalItems'
        personalGrid.Size = UDim2.new(1, -math.round(16 * scale), 0, 0)
        personalGrid.BackgroundTransparency = 1
        personalGrid.Parent = window
        local layout2 = Instance.new('UIGridLayout')
        layout2.CellSize = UDim2.fromOffset(slotSize, slotSize)
        layout2.CellPadding = UDim2.fromOffset(slotPadding, slotPadding)
        layout2.SortOrder = Enum.SortOrder.LayoutOrder
        layout2.Parent = personalGrid

        local playerPersonalSlots = {}
        for i = 1, PersonalSlotCount do
            local slot = createSlot(personalGrid, scale)
            slot.LayoutOrder = i
            playerPersonalSlots[i] = slot
        end

        local armordivider = Instance.new('Frame')
        armordivider.Name = 'ArmorDivider'
        armordivider.Size = UDim2.new(1, 0, 0, 1)
        armordivider.BackgroundColor3 = color.Light(uipallet.Main, 0.04)
        armordivider.BorderSizePixel = 0
        armordivider.Parent = window

        local armorholder = Instance.new('Frame')
        armorholder.Name = 'Armor'
        armorholder.Size = UDim2.new(1, -8, 0, slotSize)
        armorholder.BackgroundTransparency = 1
        armorholder.Parent = window
        local armorlayout = Instance.new('UIListLayout')
        armorlayout.FillDirection = Enum.FillDirection.Horizontal
        armorlayout.Padding = UDim.new(0, slotPadding)
        armorlayout.Parent = armorholder

        local playerArmorSlots = {}
        for i = 1, 4 do
            local slot = createSlot(armorholder, scale)
            slot.LayoutOrder = i
            playerArmorSlots[i] = slot
        end

        return {
            window = window,
            headshot = headshot,
            kitIcon = kitIcon,
            nametag = nametag,
            invLabel = invLabel,
            invGrid = invGrid,
            personalLabel = personalLabel,
            personalGrid = personalGrid,
            armordivider = armordivider,
            armorholder = armorholder,
            slots = playerSlots,
            personalslots = playerPersonalSlots,
            armorslots = playerArmorSlots,
            priorityStroke = priorityStroke,
            scale = scale
        }
    end

    local function setSlot(slot, item, highlight)
        if not item or not item.itemType then
            slot.Visible = false
            return
        end

        slot.Visible = true
        slot.Icon.Image = bedwars.getIcon(item, true)
        slot.Amount.Text = (item.amount or 1) > 1 and tostring(item.amount) or ''
        slot.UIStroke.Color = highlight and Color3.fromHSV(Color.Hue, Color.Sat, Color.Value) or color.Light(uipallet.Main, 0.04)
    end

    local function getTarget()
        local best, highest = nil, tick()
        for ent, expiry in targetinfo.Targets do
            if expiry < tick() then
                targetinfo.Targets[ent] = nil
                continue
            end
            if expiry > highest then
                best, highest = ent, expiry
            end
        end
        return best
    end

    local function getPlayerDistance(player)
        if not player or not player.Character or not player.Character:FindFirstChild('HumanoidRootPart') then
            return math.huge
        end
        local lplrChar = lplr.Character
        if not lplrChar or not lplrChar:FindFirstChild('HumanoidRootPart') then
            return math.huge
        end
        return (player.Character.HumanoidRootPart.Position - lplrChar.HumanoidRootPart.Position).Magnitude
    end

    local function refreshWindow(playerData, isTarget)
        local player = playerData.player
        local windowData = playerData.windowData
        local scale = getScale()

        -- Rebuild window if scale changed
        if windowData.scale ~= scale then
            if windowData.window then windowData.window:Destroy() end
            windowData = buildWindow(player)
            playerWindows[player] = windowData
            playerData.windowData = windowData
        end

        local inventory = store.inventories[player] or {items = {}, armor = {}}
        local hand = inventory.hand

        local headerHeight = math.round(BaseHeaderHeight * scale)
        local slotSize = math.round(BaseSlotSize * scale)
        local slotPadding = math.round(BaseSlotPadding * scale)
        local winWidth = math.round(BaseWindowWidth * scale)
        local currentY = headerHeight + math.round(6 * scale)

        windowData.nametag.Text = player.DisplayName
        windowData.headshot.Image = 'rbxthumb://type=AvatarHeadShot&id=' .. player.UserId .. '&w=420&h=420'

        -- Dynamically calculate text bounds for precise kit icon placement directly beside the name
        local textSize = getfontsize and getfontsize(player.DisplayName, windowData.nametag.TextSize, windowData.nametag.FontFace, Vector2.new(1000, 100)) or Vector2.new(90 * scale, 24 * scale)
        local textWidth = math.min(textSize.X, 110 * scale)

        -- Kit Icon Resolution
        local kitImg = resolveKitImage(player)
        if kitImg ~= "" then
            windowData.kitIcon.Image = kitImg
            windowData.kitIcon.Visible = true
            windowData.kitIcon.Position = UDim2.fromOffset(math.round(44 * scale + textWidth + (4 * scale)), math.round(4 * scale))
        else
            windowData.kitIcon.Visible = false
        end

        ---------------------------------------------------------
        -- INVENTORY
        ---------------------------------------------------------
        local shownInventory = 0
        for i, slot in windowData.slots do
            local item = inventory.items and inventory.items[i]
            setSlot(slot, item, item and hand and item.tool == hand.tool)
            if slot.Visible then
                shownInventory = i
            end
        end

        windowData.invLabel.Visible = true
        windowData.invLabel.Position = UDim2.fromOffset(math.round(10 * scale), currentY)
        currentY += math.round(14 * scale)

        local invRows = math.max(math.ceil(shownInventory / Columns), 1)
        local invGridHeight = (invRows * slotSize) + ((invRows - 1) * slotPadding)
        windowData.invGrid.Position = UDim2.fromOffset(math.round(10 * scale), currentY)
        windowData.invGrid.Size = UDim2.new(1, -math.round(20 * scale), 0, invGridHeight)
        currentY += invGridHeight + math.round(6 * scale)

        ---------------------------------------------------------
        -- PERSONAL CHEST
        ---------------------------------------------------------
        local personalFolder = replicatedStorage:FindFirstChild('Inventories')
        personalFolder = personalFolder and personalFolder:FindFirstChild(player.Name .. '_personal') or nil

        local personalItems = {}
        if personalFolder then
            for _, item in personalFolder:GetChildren() do
                if item:IsA('Accessory') or item:IsA('Tool') or item:IsA('Folder') then
                    local amount = item:GetAttribute('Amount') or 1
                    table.insert(personalItems, {itemType = item.Name, amount = amount})
                end
            end
        end

        local shownPersonal = 0
        for i, slot in windowData.personalslots do
            local item = personalItems[i]
            setSlot(slot, item, false)
            if slot.Visible then
                shownPersonal = i
            end
        end

        if #personalItems > 0 or (Empty and Empty.Enabled) then
            windowData.personalLabel.Visible = true
            windowData.personalGrid.Visible = true
            windowData.personalLabel.Position = UDim2.fromOffset(math.round(10 * scale), currentY)
            currentY += math.round(14 * scale)

            local personalRows = math.max(math.ceil(shownPersonal / Columns), 1)
            local personalGridHeight = (personalRows * slotSize) + ((personalRows - 1) * slotPadding)
            windowData.personalGrid.Position = UDim2.fromOffset(math.round(10 * scale), currentY)
            windowData.personalGrid.Size = UDim2.new(1, -math.round(20 * scale), 0, personalGridHeight)
            currentY += personalGridHeight + math.round(6 * scale)
        else
            windowData.personalLabel.Visible = false
            windowData.personalGrid.Visible = false
        end

        windowData.armordivider.Visible = false
        windowData.armorholder.Visible = false

        windowData.window.Size = UDim2.fromOffset(winWidth, currentY)
        windowData.window.Visible = true
    end

    local function refresh()
        local targetEnt = getTarget()
        local targetPlayer = targetEnt and targetEnt.Player or nil
        local scale = getScale()
        local winWidth = math.round(BaseWindowWidth * scale)
        local winSpacing = math.round(BaseWindowSpacing * scale)
        local isSideBySide = SideBySide and SideBySide.Enabled

        -- Collect all valid enemy players
        local validPlayers = {}
        for _, player in game:GetService('Players'):GetPlayers() do
            if player ~= lplr and player:GetAttribute('Team') ~= lplr:GetAttribute('Team') then
                table.insert(validPlayers, player)
            end
        end

        -- Sort by priority (target first, then by distance)
        table.sort(validPlayers, function(a, b)
            local aIsTarget = a == targetPlayer and 1 or 0
            local bIsTarget = b == targetPlayer and 1 or 0
            if aIsTarget ~= bIsTarget then
                return aIsTarget > bIsTarget
            end
            return getPlayerDistance(a) < getPlayerDistance(b)
        end)

        -- Position grid / columns
        local colHeights = {0, 0}
        for i, player in ipairs(validPlayers) do
            if not playerWindows[player] then
                playerWindows[player] = buildWindow(player)
                table.insert(windows, playerWindows[player])
            end

            local windowData = playerWindows[player]
            local isPriority = player == targetPlayer or i == 1
            refreshWindow({player = player, windowData = windowData}, isPriority)
            
            -- Show highlight outline for priority target
            windowData.priorityStroke.Transparency = isPriority and 0 or 1

            if isSideBySide then
                local colIndex = ((i - 1) % 2) + 1
                local posX = savedPosX + (colIndex - 1) * (winWidth + winSpacing)
                local posY = savedPosY + colHeights[colIndex]
                windowData.window.Position = UDim2.fromOffset(posX, posY)
                colHeights[colIndex] = colHeights[colIndex] + windowData.window.Size.Y.Offset + winSpacing
            else
                local posX = savedPosX
                local posY = savedPosY + colHeights[1]
                windowData.window.Position = UDim2.fromOffset(posX, posY)
                colHeights[1] = colHeights[1] + windowData.window.Size.Y.Offset + winSpacing
            end

            windowData.window.Visible = true
        end

        -- Hide windows for players no longer present
        for player, windowData in pairs(playerWindows) do
            if not table.find(validPlayers, player) then
                windowData.window.Visible = false
            end
        end
    end
    
    InventoryESP = vape.Categories.Inventory:CreateModule({
        Name = 'InventoryESP',
        Function = function(callback)
            if callback then
                repeat
                    if vape.ThreadFix then
                        pcall(setthreadidentity, 8)
                    end
                    refresh()
                    task.wait(0.1)
                until not InventoryESP.Enabled
    
                for _, windowData in windows do
                    if windowData.window then windowData.window.Visible = false end
                end
            else
                for _, windowData in windows do
                    if windowData.window then windowData.window.Visible = false end
                end
            end
        end,
        Tooltip = 'Shows the inventory and personal chest of all enemy players. Draggable & resizable.'
    })

    SideBySide = InventoryESP:CreateToggle({
        Name = 'Side by Side (2 Columns)',
        Default = false,
        Tooltip = 'Arranges enemy player inventories into 2 side-by-side columns'
    })

    ScaleSlider = InventoryESP:CreateSlider({
        Name = 'GUI Scale',
        Min = 80,
        Max = 200,
        Default = 115,
        Suffix = '%',
        Tooltip = 'Adjust the size of the inventory panels'
    })

    Empty = InventoryESP:CreateToggle({
        Name = 'Show without data',
        Tooltip = 'Keeps the panel up when the server has not shared their inventory yet'
    })

    Color = InventoryESP:CreateColorSlider({
        Name = 'Background Color',
        DefaultValue = 0,
        DefaultOpacity = 0.5,
        Function = function(hue, sat, val, opacity)
            for _, windowData in windows do
                if windowData.window then
                    windowData.window.BackgroundColor3 = uipallet.Main
                    windowData.window.BackgroundTransparency = 1 - opacity
                end
            end
        end
    })
end)

run(function()
    local AutoWhimElement
    local DelaySlider
    
    AutoWhimElement = vape.Categories.Kits:CreateModule({
        Name = 'AutoWhimElement',
        Function = function(callback)
            if callback then
                local replicatedStorage = game:GetService('ReplicatedStorage')
                
                local spawnEvent
                local learnTomeRemote
                
                spawnEvent = replicatedStorage:FindFirstChild('SpawnElementTome', true)
                learnTomeRemote = replicatedStorage:FindFirstChild('LearnElementTome', true)
                
                if not learnTomeRemote then
                    vape:CreateNotification("AutoWhimElement", "LearnElementTome remote not found!", 5)
                    return
                end
                
                if not spawnEvent then
                    vape:CreateNotification("AutoWhimElement", "SpawnElementTome remote event not found!", 5)
                    return
                end
                
                -- Event-driven only: Zero workspace loops, zero lag. It only runs code when the server says a tome spawns.
                AutoWhimElement:Clean(spawnEvent.OnClientEvent:Connect(function(data)
                    if not AutoWhimElement.Enabled then return end
                    if data and data.secret then
                        task.spawn(function()
                            local success, response = pcall(function()
                                if learnTomeRemote:IsA('RemoteFunction') then
                                    return learnTomeRemote:InvokeServer({ secret = data.secret })
                                else
                                    learnTomeRemote:FireServer({ secret = data.secret })
                                    return { success = true, element = "element" }
                                end
                            end)
                            
                            if success and type(response) == "table" and response.success then
                                local elementName = response.element or "element"
                                vape:CreateNotification("AutoWhimElement", "Successfully learned element: " .. tostring(elementName), 3)
                            end
                        end)
                    end
                end))
            end
        end,
        Tooltip = 'Automatically listens to SpawnElementTome and learns elements instantly without lag.'
    })
    
    DelaySlider = AutoWhimElement:CreateSlider({
        Name = 'Delay',
        Min = 0.1,
        Max = 1,
        Default = 0.4,
        Decimal = 1,
        Suffix = function(val)
            return 'seconds'
        end,
        Tooltip = 'Delay between claiming each tome'
    })
end)

--[[
	Utility Mobule
]]

run(function()
	local CheatDetector
	local KillAuraToggle
	local SpeedToggle
	local DetectSelfToggle
	local WindowDelaySlider

	local lastFlagged = {}
	local lastPlayerPositions = {}

	local DEFAULT_SWORD_REACH = 14.4 -- 4.8 * BLOCK_SIZE (14.4 studs)
	local DEFAULT_DAGGER_REACH = 10.5
	local DEFAULT_HAMMER_REACH = 15.0
	local BASE_SPRINT_SPEED = 23.5

	local SPEED_KITS = {
		yuzi = true, jade = true, void_regent = true, barb = true, barbarian = true,
		baker = true, Santa = true, wind_walker = true, ember = true, pyro = true,
		freiya = true, hannah = true, lucia = true, zephyr = true, raven = true,
		beast = true, ninja = true
	}

	local function isNotificationAllowed(playerName, cheatType)
		local key = playerName .. "_" .. cheatType
		local now = tick()
		local lastTime = lastFlagged[key] or 0
		local delayVal = WindowDelaySlider and WindowDelaySlider.Value or 5

		if (now - lastTime) >= delayVal then
			lastFlagged[key] = now
			return true
		end
		return false
	end

	local function sendFlagNotification(titleText, bodyText)
		local sent = false
		pcall(function()
			if vape and vape.CreateNotification then
				vape:CreateNotification(titleText, bodyText, 4)
				sent = true
			end
		end)

		if not sent then
			pcall(function()
				local bedwars = vape and vape.Libraries and vape.Libraries.Bedwars
				if bedwars and bedwars.NotificationController then
					bedwars.NotificationController:sendInfoNotification({
						message = bodyText,
						title = titleText,
						duration = 4
					})
					sent = true
				end
			end)
		end

		if not sent then
			pcall(function()
				game:GetService("StarterGui"):SetCore("SendNotification", {
					Title = titleText,
					Text = bodyText,
					Duration = 4
				})
			end)
		end
	end

	-- Reach Distance Calculation Function
	local function checkHitReach(attackerInst, targetInst)
		if not CheatDetector or not CheatDetector.Enabled or not KillAuraToggle.Enabled then return end
		if not attackerInst or not targetInst then return end

		local attackerPlayer = playersService:GetPlayerFromCharacter(attackerInst) or (attackerInst == lplr.Character and lplr)
		local attackerName = attackerPlayer and attackerPlayer.DisplayName or attackerInst.Name

		-- Check self flag toggle
		if (attackerPlayer == lplr or attackerInst == lplr.Character) and not (DetectSelfToggle and DetectSelfToggle.Enabled) then
			return
		end

		local attackerPos = attackerInst.PrimaryPart and attackerInst.PrimaryPart.Position or attackerInst:GetPivot().Position
		local targetPos = targetInst.PrimaryPart and targetInst.PrimaryPart.Position or targetInst:GetPivot().Position

		if attackerPos and targetPos then
			local dist = math.floor(((attackerPos - targetPos).Magnitude) * 10) / 10
			local maxAllowedReach = DEFAULT_SWORD_REACH

			local tool = attackerInst:FindFirstChildWhichIsA("Tool")
			if tool then
				local itemName = tool.Name:lower()
				if itemName:find("dagger") then
					maxAllowedReach = DEFAULT_DAGGER_REACH
				elseif itemName:find("hammer") then
					maxAllowedReach = DEFAULT_HAMMER_REACH
				end
			end

			-- Flag if attack distance exceeds max allowed weapon reach
			if dist > (maxAllowedReach + 0.5) then
				if isNotificationAllowed(attackerName, "killaura") then
					sendFlagNotification(
						"CheatDetector",
						"CheatDetector killaura : flagged " .. attackerName .. " reach : " .. tostring(dist)
					)
				end
			end
		end
	end

	-- Hook 1: ClientSyncEvents.SwordSwing (Triggers on local or client attacks)
	task.spawn(function()
		pcall(function()
			local bedwars = vape and vape.Libraries and vape.Libraries.Bedwars
			if bedwars and bedwars.ClientSyncEvents then
				bedwars.ClientSyncEvents.SwordSwing:connect(function(event)
					if not CheatDetector or not CheatDetector.Enabled or not KillAuraToggle.Enabled then return end
					if not (DetectSelfToggle and DetectSelfToggle.Enabled) then return end

					-- Detect nearest target when swinging sword
					local myRoot = lplr.Character and lplr.Character.PrimaryPart
					if myRoot then
						for _, otherPlr in ipairs(playersService:GetPlayers()) do
							if otherPlr ~= lplr and otherPlr.Character and otherPlr.Character.PrimaryPart then
								checkHitReach(lplr.Character, otherPlr.Character)
							end
						end
					end
				end)

				bedwars.ClientSyncEvents.EntityDamageEvent:connect(function(event)
					if event and event.entityInstance and event.fromEntity then
						checkHitReach(event.fromEntity, event.entityInstance)
					end
				end)
			end
		end)
	end)

	-- Hook 2: Network Remotes (`EntityDamageEventZap` & `DamageBlock` fallback)
	task.spawn(function()
		pcall(function()
			local RuntimeLib = require(game:GetService("ReplicatedStorage"):WaitForChild("rbxts_include"):WaitForChild("RuntimeLib"))
			local EntityDamageEventZap = RuntimeLib.import(script, game:GetService("ReplicatedStorage"), "Players", "erickmikaell", "PlayerScripts", "TS", "lib", "network").EntityDamageEventZap

			if EntityDamageEventZap then
				EntityDamageEventZap.On(function(targetInst, _, _, _, attackerInst, _, _, _, _, _, _, _, _, _)
					checkHitReach(attackerInst, targetInst)
				end)
			end
		end)
	end)

	-- Smart Speed Detector Loop
	local function checkSpeed()
		if not CheatDetector or not CheatDetector.Enabled or not SpeedToggle.Enabled then return end

		local now = tick()
		for _, player in ipairs(playersService:GetPlayers()) do
			if player == lplr and not (DetectSelfToggle and DetectSelfToggle.Enabled) then
				continue
			end

			local char = player.Character
			if char and char.PrimaryPart then
				local root = char.PrimaryPart
				local humanoid = char:FindFirstChildWhichIsA("Humanoid")
				local userId = player.UserId

				local kit = char:GetAttribute("Kit") or player:GetAttribute("Kit")
				if not (kit and SPEED_KITS[tostring(kit):lower()]) then
					local hasSpeedBuff = char:GetAttribute("SpeedBoost") or char:GetAttribute("HasSpeedPotion") or char:GetAttribute("SpeedPotion")
					local isGliding = char:GetAttribute("IsGliding") or char:GetAttribute("InAirLaunch") or char:GetAttribute("TelepearlLaunch")

					if not hasSpeedBuff and not isGliding then
						local baseSpeed = (humanoid and humanoid.WalkSpeed > 0) and humanoid.WalkSpeed or BASE_SPRINT_SPEED
						local speedMultiplier = char:GetAttribute("moveSpeedMultiplier") or char:GetAttribute("WalkSpeedModifier") or 1
						local maxLegitSpeed = (math.max(baseSpeed, BASE_SPRINT_SPEED) * speedMultiplier) + 2.5

						-- Direct Humanoid WalkSpeed Check
						if humanoid and humanoid.WalkSpeed > (BASE_SPRINT_SPEED * speedMultiplier + 3) then
							if isNotificationAllowed(player.DisplayName, "speed") then
								sendFlagNotification(
									"CheatDetector",
									"CheatDetector speed : flagged " .. player.DisplayName .. " speed : " .. tostring(math.floor(humanoid.WalkSpeed * 10) / 10) .. " studs/s"
								)
							end
						end

						-- Displacement Check over time
						local prevData = lastPlayerPositions[userId]
						if prevData then
							local dt = now - prevData.time
							if dt >= 0.3 and dt <= 1.5 then
								local currentPos = Vector3.new(root.Position.X, 0, root.Position.Z)
								local lastPos = Vector3.new(prevData.pos.X, 0, prevData.pos.Z)
								local displacementSpeed = math.floor(((currentPos - lastPos).Magnitude / dt) * 10) / 10

								if displacementSpeed > maxLegitSpeed then
									if isNotificationAllowed(player.DisplayName, "speed") then
										sendFlagNotification(
											"CheatDetector",
											"CheatDetector speed : flagged " .. player.DisplayName .. " speed : " .. tostring(displacementSpeed) .. " studs/s"
										)
									end
								end
							end
						end
						lastPlayerPositions[userId] = { pos = root.Position, time = now }
					end
				end
			end
		end
	end

	CheatDetector = vape.Categories.Utility:CreateModule({
		Name = 'CheatDetector',
		Function = function(callback)
			if callback then
				table.clear(lastFlagged)
				table.clear(lastPlayerPositions)
				task.spawn(function()
					while CheatDetector.Enabled do
						task.wait(0.3)
						checkSpeed()
					end
				end)
			else
				table.clear(lastFlagged)
				table.clear(lastPlayerPositions)
			end
		end,
		Tooltip = 'detects reach and speed cheaters in your server'
	})

	KillAuraToggle = CheatDetector:CreateToggle({
		Name = 'KillAura',
		Default = true,
		Tooltip = 'flags players using reach/killaura over legit sword range'
	})

	SpeedToggle = CheatDetector:CreateToggle({
		Name = 'Speed',
		Default = true,
		Tooltip = 'flags players moving faster than normal game speed (ignores speed kits/items)'
	})

	DetectSelfToggle = CheatDetector:CreateToggle({
		Name = 'Detect Self',
		Default = false,
		Tooltip = 'also checks and flags your own reach and speed so you can test if it works'
	})

	WindowDelaySlider = CheatDetector:CreateSlider({
		Name = 'Window delay',
		Min = 0,
		Max = 15,
		Default = 5,
		Tooltip = 'delay in seconds between repeat flag notifications for the same person'
	})
end)

run(function()
	local NetworkTP
	NetworkTP = vape.Categories.Utility:CreateModule({
		Name = 'NetworkTP',
		Function = function(callback)
			if callback then
				local items = collection('ItemDrop', NetworkTP)
				repeat
					if entitylib.isAlive then
						local localPosition = entitylib.character.RootPart.Position
						local humanoidHealth = entitylib.character.Humanoid.Health
						local currentTime = tick()

						for _, v in pairs(items) do
							local dropTime = v:GetAttribute('ClientDropTime')
							if not dropTime then continue end
							if (currentTime - dropTime) < 2 then continue end
							if isnetworkowner(v) and humanoidHealth > 0 then
								v.CFrame = CFrame.new(localPosition - Vector3.new(0, 3, 0))
							end
						end
					end
					task.wait(0.1)
				until not NetworkTP.Enabled
			end
		end,
		Tooltip = 'gets items back'
	})
end)
				
run(function()
    local ChatMover
    local ChatPosition
    local guiService = game:GetService("GuiService")
    local textChatService = game:GetService("TextChatService")

    -- Positions map based on ChatWindowConfiguration or legacy Chat Gui
    local function updateChatPosition(posName)
        -- Support for modern TextChatService (New Chat System)
        if textChatService.ChatVersion == Enum.ChatVersion.TextChatService then
            local chatWindow = textChatService:FindFirstChildOfClass("ChatWindowConfiguration")
            if chatWindow then
                if posName == "Top Left" then
                    chatWindow.HorizontalAlignment = Enum.HorizontalAlignment.Left
                    chatWindow.VerticalAlignment = Enum.VerticalAlignment.Top
                elseif posName == "Top Right" then
                    chatWindow.HorizontalAlignment = Enum.HorizontalAlignment.Right
                    chatWindow.VerticalAlignment = Enum.VerticalAlignment.Top
                elseif posName == "Bottom Left" then
                    chatWindow.HorizontalAlignment = Enum.HorizontalAlignment.Left
                    chatWindow.VerticalAlignment = Enum.VerticalAlignment.Bottom
                elseif posName == "Bottom Right" then
                    chatWindow.HorizontalAlignment = Enum.HorizontalAlignment.Right
                    chatWindow.VerticalAlignment = Enum.VerticalAlignment.Bottom
                end
            end
        else
            -- Support for Legacy Chat System
            local playerGui = game:GetService("Players").LocalPlayer:FindFirstChildOfClass("PlayerGui")
            local chatGui = playerGui and playerGui:FindFirstChild("Chat")
            if chatGui and chatGui:FindFirstChild("Frame") then
                local frame = chatGui.Frame
                if posName == "Top Left" then
                    frame.Position = UDim2.new(0, 0, 0, 0)
                elseif posName == "Top Right" then
                    frame.Position = UDim2.new(1, -frame.AbsoluteSize.X, 0, 0)
                elseif posName == "Bottom Left" then
                    frame.Position = UDim2.new(0, 0, 1, -frame.AbsoluteSize.Y)
                elseif posName == "Bottom Right" then
                    frame.Position = UDim2.new(1, -frame.AbsoluteSize.X, 1, -frame.AbsoluteSize.Y)
                end
            end
        end
    end

    ChatMover = vape.Categories.Utility:CreateModule({
        Name = 'ChatMover',
        Function = function(callback)
            if callback then
                updateChatPosition(ChatPosition.Value)
            else
                -- Revert back to default Top Left position on disable
                updateChatPosition("Top Left")
            end
        end,
    })

    ChatPosition = ChatMover:CreateDropdown({
        Name = 'Position',
        List = {'Top Left', 'Top Right', 'Bottom Left', 'Bottom Right'},
        Default = 'Bottom Left',
        Function = function(val)
            if ChatMover.Enabled then
                updateChatPosition(val)
            end
        end
    })
end)

run(function()
    local moduleData = {
        Connection = nil,
        CurrentDuration = 1,
        CachedPrompts = {}
    }
    
    local function updatePrompt(prompt, duration)
        if prompt and prompt:IsA("ProximityPrompt") then
            prompt.HoldDuration = duration
        end
    end
    
    local function updateAllPrompts(duration)
        for prompt in pairs(moduleData.CachedPrompts) do
            if prompt and prompt.Parent then
                prompt.HoldDuration = duration
            else
                moduleData.CachedPrompts[prompt] = nil
            end
        end
    end
    
    local function cacheExistingPrompts()
        moduleData.CachedPrompts = {}
        
        scanDescendants(workspace, function(descendant)
            if descendant:IsA("ProximityPrompt") then
                moduleData.CachedPrompts[descendant] = true
                descendant.HoldDuration = moduleData.CurrentDuration
            end
        end)
    end
    
	ProximityPromptDuration = vape.Categories.Utility:CreateModule({
		Name = 'ProximityPromptDuration',
		Function = function(callback)
			if callback then
				cacheExistingPrompts()
				ProximityPromptDuration:Clean(workspace.DescendantAdded:Connect(function(descendant)
					if descendant:IsA("ProximityPrompt") then
						moduleData.CachedPrompts[descendant] = true
						descendant.HoldDuration = moduleData.CurrentDuration
					end
				end))
			else
				moduleData.CachedPrompts = {}
			end
		end,
		Tooltip = 'customize proximity prompts'
	})
    
    local ProximityDurationSlider = ProximityPromptDuration:CreateSlider({
        Name = 'Duration',
        Min = 0,
        Max = 10,
        Default = 1,
        Decimal = 100,
        Suffix = 's',
        Function = function(value)
            moduleData.CurrentDuration = value
            if ProximityPromptDuration.Enabled then
                updateAllPrompts(value)
            end
        end
    })
end)

run(function()
	local AutoMarina

	AutoMarina = vape.Categories.Kits:CreateModule({
		Name = 'AutoMarina',
		Function = function(callback)
			if callback then
				local Players = game:GetService("Players")
				local ReplicatedStorage = game:GetService("ReplicatedStorage")
				local lplr = Players.LocalPlayer

				-- Fetch exact RemoteEvent
				local useAbilityRemote
				pcall(function()
					useAbilityRemote = ReplicatedStorage:WaitForChild("events-@easy-games/game-core:shared/game-core-networking@getEvents.Events"):WaitForChild("useAbility")
				end)

				if not useAbilityRemote then
					if vape.CreateNotification then
						vape:CreateNotification("AutoMarina", "useAbility remote not found!", 5)
					end
					AutoMarina:ToggleButton(false)
					return
				end

				-- Check for nearby Players or Dummies/NPCs
				local function checkTargets()
					if not lplr or not lplr.Character then return false end
					local myRoot = lplr.Character:FindFirstChild("HumanoidRootPart")
					if not myRoot then return false end

					local myTeam = lplr:GetAttribute("Team") or lplr:GetAttribute("TeamId") or -1
					local range = AutoMarina.Options["Detection Range"].Value or 22

					-- 1. Check Players
					if AutoMarina.Targets.Players then
						for _, player in ipairs(Players:GetPlayers()) do
							if player ~= lplr and player.Character then
								local pTeam = player:GetAttribute("Team") or player:GetAttribute("TeamId") or -1
								if pTeam ~= myTeam or myTeam == -1 then
									local root = player.Character:FindFirstChild("HumanoidRootPart")
									local hum = player.Character:FindFirstChildOfClass("Humanoid")

									if root and hum and hum.Health > 0 then
										if (root.Position - myRoot.Position).Magnitude <= range then
											return true
										end
									end
								end
							end
						end
					end

					-- 2. Check NPCs / Dummies
					if AutoMarina.Targets.NPCs then
						for _, ent in entitylib.List do
							if ent.RootPart and ent.Character and ent.Character ~= lplr.Character and not Players:GetPlayerFromCharacter(ent.Character) then
								local hum = ent.Character:FindFirstChildOfClass("Humanoid")
								if hum and hum.Health > 0 then
									if (ent.RootPart.Position - myRoot.Position).Magnitude <= range then
										return true
									end
								end
							end
						end
						for _, entity in collectionService:GetTagged('entity') do
							if entity:IsA("Model") and entity ~= lplr.Character and not Players:GetPlayerFromCharacter(entity) then
								local root = entity:FindFirstChild("HumanoidRootPart") or entity.PrimaryPart or entity:FindFirstChildWhichIsA("BasePart")
								local hum = entity:FindFirstChildOfClass("Humanoid")
								if root and hum and hum.Health > 0 then
									if (root.Position - myRoot.Position).Magnitude <= range then
										return true
									end
								end
							end
						end
					end

					return false
				end

				-- Main execution loop
				local lastUsed = 0
				local loopThread = task.spawn(function()
					while AutoMarina.Enabled do
						task.wait(0.1)

						if checkTargets() then
							if tick() - lastUsed >= 0.5 then
								lastUsed = tick()
								pcall(function()
									useAbilityRemote:FireServer("electrify_jellyfish")
								end)
							end
						end
					end
				end)

				AutoMarina:Clean(function()
					if loopThread then
						task.cancel(loopThread)
					end
				end)
			end
		end,
		Tooltip = 'Triggers Marina\'s electrify_jellyfish ability when enemies or dummies enter range.'
	})

	-- Target Configuration Component
	AutoMarina.Targets = AutoMarina:CreateTargets({
		Players = true,
		NPCs = true,
		Walls = true
	})

	-- Detection Range Slider (0 to 22 studs)
	AutoMarina:CreateSlider({
		Name = "Detection Range",
		Min = 0,
		Max = 50,
		Default = 50,
		Suffix = "studs"
	})
end)

run(function()
	local KnitInit, Knit
	repeat
		KnitInit, Knit = pcall(function()
			return debug.getupvalue(require(lplr.PlayerScripts.TS.knit).setup, 9)
		end)
		if KnitInit then break end
		task.wait()
	until KnitInit

	if not debug.getupvalue(Knit.Start, 1) then
		repeat task.wait() until debug.getupvalue(Knit.Start, 1)
	end

	local Players = game:GetService("Players")

	shared.PERMISSION_CONTROLLER_HASANYPERMISSIONS_REVERT = shared.PERMISSION_CONTROLLER_HASANYPERMISSIONS_REVERT or Knit.Controllers.PermissionController.hasAnyPermissions
	shared.MATCH_CONTROLLER_GETPLAYERPARTY_REVERT = shared.MATCH_CONTROLLER_GETPLAYERPARTY_REVERT or Knit.Controllers.MatchController.getPlayerParty

	local AC_MOD_View = {
		playerConnections = {},
		Enabled = false,
		Friends = {}, 
		parties = {}, 
		teamMap = {}, 
		display = {},
		isRefreshing = false,
		cacheDirty = true,
		disable_disguises = false,
		disguises = {},
		teamData = {}
	}

	AC_MOD_View.controller = Knit.Controllers.PermissionController
	AC_MOD_View.match_controller = Knit.Controllers.MatchController

	function AC_MOD_View:getPartyById(displayId)
		if not displayId then return end
		displayId = tostring(displayId)
		if self.display[displayId] then return self.display[displayId] end
		for _, party in pairs(self.parties) do
			if party.displayId == tostring(displayId) then
				self.display[displayId] = party
				return party
			end
		end
	end

	function AC_MOD_View:refreshDisplayCache()
		for _, plr in pairs(Players:GetPlayers()) do
			local playerId = tostring(plr.UserId)

			local playerPartyId = self.teamMap[playerId]
			if playerPartyId ~= nil then
				self:getPartyById(playerPartyId)
			end
			task.wait()
		end
	end

	function AC_MOD_View:refreshDisplayCacheAsync()
		task.spawn(self.refreshDisplayCache, self)
	end

	function AC_MOD_View:getPlayerTeamData(plr)
		if self.teamData[plr] then return self.teamData[plr] end

		self.teamData[plr] = {}

		local teamMembers = {}
		local playerTeam = plr.Team 
		if not playerTeam then
			return teamMembers 
		end

		local playerId = tostring(plr.UserId)
		self.Friends[playerId] = self.Friends[playerId] or {}

		for _, otherPlayer in pairs(Players:GetPlayers()) do
			if otherPlayer == plr then continue end 

			local otherPlayerId = tostring(otherPlayer.UserId)
			local areFriends = self.Friends[playerId][otherPlayerId]

			if areFriends == nil then
				local suc, res = pcall(function()
					return plr:IsFriendsWith(otherPlayer.UserId)
				end)
				areFriends = suc and res or false

				if suc then
					self.Friends = self.Friends or {}
					self.Friends[playerId] = self.Friends[playerId] or {}
					self.Friends[playerId][otherPlayerId] = areFriends
					self.Friends[otherPlayerId] = self.Friends[otherPlayerId] or {}
					self.Friends[otherPlayerId][playerId] = areFriends
				end
			end

			if areFriends and otherPlayer.Team == playerTeam then
				table.insert(teamMembers, otherPlayerId)
			end
		end

		self.teamData[plr] = teamMembers

		return teamMembers
	end

	function AC_MOD_View:refreshPlayerTeamData()
		for i,v in pairs(Players:GetPlayers()) do
			self:getPlayerTeamData(v)
			task.wait()
		end
	end

	function AC_MOD_View:refreshPlayerTeamDataAsync()
		task.spawn(self.refreshPlayerTeamData, self)
	end

	function AC_MOD_View:refreshTeamMap()
		local allTeams = {}
		for _, p in pairs(Players:GetPlayers()) do
			local teamMembers = self:getPlayerTeamData(p)
			if teamMembers and #teamMembers > 0 then 
				allTeams[p] = teamMembers
			end
		end

		local validTeams = {}
		for playerInTeams, members in pairs(allTeams) do
			local playerIdInTeams = tostring(playerInTeams.UserId)
			local cleanedMembers = {}

			for _, memberId in pairs(members) do
				local memberIdStr = tostring(memberId)
				if memberIdStr == playerIdInTeams then
					--print("Warning: Player " .. playerIdInTeams .. " has themselves in their team list.")
				else
					table.insert(cleanedMembers, memberIdStr)
				end
			end

			if #cleanedMembers > 0 then
				validTeams[playerInTeams] = cleanedMembers
			end
		end

		self.parties = {}
		self.teamMap = {}
		local teamId = 0
		for playerInTeams, members in pairs(validTeams) do
			local playerIdInTeams = tostring(playerInTeams.UserId)
			if not self.teamMap[playerIdInTeams] then
				self.teamMap[playerIdInTeams] = teamId
				table.insert(self.parties, {
					displayId = tostring(teamId),
					members = members
				})
				teamId = teamId + 1

				for _, memberId in pairs(members) do
					self.teamMap[memberId] = teamId - 1
				end
			end
		end

		self.cacheDirty = false
		self.isRefreshing = false
	end

	function AC_MOD_View:refreshTeamMapAsync()
		if self.isRefreshing then return end 
		self.isRefreshing = true
		task.spawn(function()
			self:refreshTeamMap()
		end)
	end

	function AC_MOD_View:getPlayerParty(plr)
		if not plr or not plr:IsA("Player") then
			return nil
		end

		local playerId = tostring(plr.UserId)

		if self.cacheDirty or not next(self.teamMap) then
			self:refreshTeamMapAsync()
		end

		local playerPartyId = self.teamMap[playerId]
		if playerPartyId ~= nil then
			return self:getPartyById(playerPartyId)
		end

		return nil 
	end

	AC_MOD_View.mockGetPlayerParty = function(self, plr)
		local parties = self.parties 
		if parties ~= nil and #parties > 0 then
			return shared.MATCH_CONTROLLER_GETPLAYERPARTY_REVERT(self, plr)
		end
		return AC_MOD_View:getPlayerParty(plr)
	end

	function AC_MOD_View:toggleDisableDisguises()
		if not self.Enabled then return end
		if self.disable_disguises then
			for _,v in pairs(Players:GetPlayers()) do
				if v == Players.LocalPlayer then continue end
				local disguiseName = v:GetAttribute("DisguiseDisplayName")
				if disguiseName and disguiseName ~= "" then
					self.disguises[v] = disguiseName
					v:SetAttribute("DisguiseDisplayName", "")
					notif("Remove Disguises", "Disabled streamer mode for "..tostring(v.Name).."!", 3)
				end
			end
			pcall(function() Knit.Controllers.StreamerModeController:updateNametags(true) end)
		else
			for v, originalName in pairs(self.disguises) do
				if v and v.Parent then
					v:SetAttribute("DisguiseDisplayName", originalName)
					notif("Remove Disguises", "Re-enabled Streamer mode for "..tostring(v.Name).."!", 2)
				end
			end
			table.clear(self.disguises)
			pcall(function() Knit.Controllers.StreamerModeController:updateNametags(true) end)
		end
	end

	function AC_MOD_View:refreshCore()
		self:refreshTeamMapAsync()
		self:refreshDisplayCacheAsync()
		self:refreshPlayerTeamDataAsync()

		self:toggleDisableDisguises()
	end

	function AC_MOD_View:refreshCoreAsync()
		task.spawn(self.refreshCore, self)
	end

	function AC_MOD_View:init()
		self.Enabled = true
		self.controller.hasAnyPermissions = function(self)
			return true
		end
		self.match_controller.getPlayerParty = self.mockGetPlayerParty

		self.playerConnections = {
			added = Players.PlayerAdded:Connect(function(player)
				self.cacheDirty = true
				self:refreshCoreAsync()
				player:GetPropertyChangedSignal("Team"):Connect(function()
					self.cacheDirty = true
					self:refreshCoreAsync()
				end)
			end),
			removed = Players.PlayerRemoving:Connect(function(player)
				local playerId = tostring(player.UserId)
				self.Friends[playerId] = nil 
				for _, cache in pairs(self.Friends) do
					cache[playerId] = nil
				end
				self.cacheDirty = true
				self:refreshCoreAsync()
			end)
		}

		self:refreshCore()
	end

	function AC_MOD_View:disable()
		self.Enabled = false

		self.controller.hasAnyPermissions = shared.PERMISSION_CONTROLLER_HASANYPERMISSIONS_REVERT
		self.match_controller.getPlayerParty = shared.MATCH_CONTROLLER_GETPLAYERPARTY_REVERT

		if self.playerConnections then
			for _, v in pairs(self.playerConnections) do
				pcall(function() v:Disconnect() end)
			end
			table.clear(self.playerConnections)
		end

		self.parties = {}
		self.teamMap = {}
		self.Friends = {}
		self.display = {}
		self.teamData = {}
		self.cacheDirty = true

		self:toggleDisableDisguises()
	end

	shared.ACMODVIEWENABLED = false
	AC_MOD_View.moduleInstance = vape.Categories.World:CreateModule({
		Name = "AC MOD",
		Function = function(call)
			shared.ACMODVIEWENABLED = call
			if call then
				AC_MOD_View:init()
			else
				AC_MOD_View:disable()
			end
		end
	})

	AC_MOD_View.disableDisguisesToggle = AC_MOD_View.moduleInstance:CreateToggle({
		Name = "Remove Disguises",
		Function = function(call)
			AC_MOD_View.disable_disguises = call
			AC_MOD_View:toggleDisableDisguises()
		end
	})
end)

run(function()
	local AutoArmorTrim
	local TrimDropdown
	local ColorDropdown
	local RankDropdown
	local ForceWeldToggle

	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local Players = game:GetService("Players")
	local LocalPlayer = Players.LocalPlayer

	-- Helper function to safely fetch TS modules
	local function getTSModule(modulePath, itemName)
		local success, result = pcall(function()
			local rbxts = ReplicatedStorage:WaitForChild("rbxts_include", 2)
			if not rbxts then return nil end
			local RuntimeLib = require(rbxts:WaitForChild("RuntimeLib"))
			local module = RuntimeLib.import(script, ReplicatedStorage, unpack(modulePath))
			return itemName and module[itemName] or module
		end)
		return success and result or nil
	end

	-- Readable Names -> Internal ArmorTrimType keys
	local TrimNameMap = {
		["Test (Trim 1)"] = "trim_1",
		["Retro (Trim 2)"] = "trim_2",
		["Overgrown (Trim 3)"] = "trim_3",
		["Butterfly (Trim 4)"] = "trim_4",
		["Fire (Trim 5)"] = "trim_5",
		["Frosty (Trim 6)"] = "trim_6",
		["Void (Trim 7)"] = "trim_7",
		["Trim 8"] = "trim_8",
		["Trim 9"] = "trim_9",
		["Trim 10"] = "trim_10",
		["Trim 11"] = "trim_11",
		["Trim 12"] = "trim_12"
	}

	-- Direct body part anchor map
	local TrimAnchorMap = {
		["boots_left_trim"] = "LeftFoot",
		["boots_right_trim"] = "RightFoot",
		["chestplate_left_shoulder_trim"] = "LeftUpperArm",
		["chestplate_right_shoulder_trim"] = "RightUpperArm",
		["chestplate_trim"] = "UpperTorso",
		["helmet_trim"] = "Head"
	}

	-- Attach and weld trim parts directly to avatar body parts
	local function attachAndWeldArmorTrims(character, trimId, colorValue, rankValue)
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid then return end

		-- Destroy old custom trim accessories
		for _, child in ipairs(character:GetChildren()) do
			if child:IsA("Accessory") and child:GetAttribute("AutoArmorTrimAccessory") then
				child:Destroy()
			end
		end

		local ArmorTrimColorMeta = getTSModule({"TS", "armor-trim", "armor-trim-color-meta"}, "ArmorTrimColorMeta")
		local ArmorTrimEffectRankMeta = getTSModule({"TS", "armor-trim", "armor-trim-rank"}, "ArmorTrimEffectRankMeta")

		local colorRGB = (ArmorTrimColorMeta and ArmorTrimColorMeta[colorValue] and ArmorTrimColorMeta[colorValue].color) or Color3.fromRGB(255, 99, 99)
		local rankMeta = ArmorTrimEffectRankMeta and ArmorTrimEffectRankMeta[rankValue]

		-- Fetch trim accessory templates from ReplicatedStorage Assets
		local folder = ReplicatedStorage:FindFirstChild("Assets") and ReplicatedStorage.Assets:FindFirstChild("ArmorTrims") and ReplicatedStorage.Assets.ArmorTrims:FindFirstChild(trimId)
		if not folder then return end

		for _, desc in ipairs(folder:GetDescendants()) do
			if desc:IsA("Accessory") then
				local acc = desc:Clone()
				acc:SetAttribute("AutoArmorTrimAccessory", true)

				-- Recolor & apply rank material to parts
				for _, part in ipairs(acc:GetDescendants()) do
					if part:IsA("BasePart") then
						part.Color = colorRGB
						part.Transparency = 0
						if rankMeta and rankMeta.material then
							part.Material = rankMeta.material
						end
					end
				end

				local accName = acc.Name:lower()
				local targetPartName = nil
				for keyName, partName in pairs(TrimAnchorMap) do
					if accName:find(keyName) then
						targetPartName = partName
						break
					end
				end

				local targetPart = targetPartName and character:FindFirstChild(targetPartName)

				if targetPart then
					acc.Parent = character
					local handle = acc:FindFirstChild("Handle")
					if handle then
						handle.CFrame = targetPart.CFrame
						handle.CanCollide = false
						handle.CanTouch = false
						handle.CanQuery = false

						local weld = Instance.new("WeldConstraint")
						weld.Part0 = handle
						weld.Part1 = targetPart
						weld.Parent = handle
					end
				else
					humanoid:AddAccessory(acc)
				end
			end
		end
	end

	-- Main update function
	local function updateArmorTrim()
		if not AutoArmorTrim or not AutoArmorTrim.Enabled then return end
		local character = LocalPlayer.Character or (entitylib and entitylib.character)
		if not character or not character:FindFirstChildOfClass("Humanoid") then return end

		pcall(function()
			local rawTrimName = TrimDropdown.Value or "Test (Trim 1)"
			local trimId = TrimNameMap[rawTrimName] or "trim_1"
			local colorName = ColorDropdown.Value or "RED"
			local rankName = RankDropdown.Value or "T7"

			local ArmorTrimColor = getTSModule({"TS", "armor-trim", "armor-trim-colors"}, "ArmorTrimColor")
			local ArmorTrimEffectRank = getTSModule({"TS", "armor-trim", "armor-trim-rank"}, "ArmorTrimEffectRank")

			local colorValue = (ArmorTrimColor and ArmorTrimColor[colorName]) or 0
			local rankValue = (ArmorTrimEffectRank and ArmorTrimEffectRank[rankName]) or 6

			-- Update character attributes so game knows armor trim is applied
			character:SetAttribute("ArmorTrimType", trimId)
			character:SetAttribute("ArmorTrimColor", colorValue)
			character:SetAttribute("ArmorTrimEffectRank", rankValue)

			-- 1. Attach Particle & Beam Effects via Knit Controller
			-- Correct Order: (p1 = Controller, p2 = Character, p3 = TrimId, p4 = ColorValue, p5 = RankValue, p6 = EffectType)
			local KnitClient = (shared.bedwars and shared.bedwars.KnitClient) or (bedwars and bedwars.KnitClient)
			if KnitClient and KnitClient.Controllers and KnitClient.Controllers.ArmorTrimController then
				KnitClient.Controllers.ArmorTrimController:attachArmorTrimEffects(character, trimId, colorValue, rankValue, nil)
			end

			-- 2. Attach and weld accessories to body parts
			if not ForceWeldToggle or ForceWeldToggle.Enabled then
				attachAndWeldArmorTrims(character, trimId, colorValue, rankValue)
			else
				for _, child in ipairs(character:GetChildren()) do
					if child:IsA("Accessory") and child:GetAttribute("AutoArmorTrimAccessory") then
						child:Destroy()
					end
				end
			end
		end)
	end

	-- Register Module under Render Category
	AutoArmorTrim = vape.Categories.Render:CreateModule({
		Name = 'AutoArmorTrim',
		Function = function(callback)
			if callback then
				updateArmorTrim()

				local connection
				connection = LocalPlayer.CharacterAdded:Connect(function(newChar)
					if not AutoArmorTrim.Enabled then
						connection:Disconnect()
						return
					end
					newChar:WaitForChild("Humanoid")
					task.wait(0.3)
					updateArmorTrim()
				end)
			else
				local char = LocalPlayer.Character
				if char then
					for _, item in ipairs(char:GetChildren()) do
						if item:IsA("Accessory") and item:GetAttribute("AutoArmorTrimAccessory") then
							item:Destroy()
						end
					end
				end
			end
		end,
		Tooltip = 'Loads Bedwars TS Armor Trim modules, applies particle effects and attaches trim accessories'
	})

	TrimDropdown = AutoArmorTrim:CreateDropdown({
		Name = 'Trim Style',
		List = {
			"Test (Trim 1)",
			"Retro (Trim 2)",
			"Overgrown (Trim 3)",
			"Butterfly (Trim 4)",
			"Fire (Trim 5)",
			"Frosty (Trim 6)",
			"Void (Trim 7)",
		},
		Default = "Test (Trim 1)",
		OnChange = function() updateArmorTrim() end,
		Tooltip = 'Select the Armor Trim style'
	})

	ColorDropdown = AutoArmorTrim:CreateDropdown({
		Name = 'Trim Color',
		List = { "RED", "ORANGE", "YELLOW", "GREEN", "BLUE", "INDIGO", "PURPLE", "WHITE", "BLACK", "BROWN", "PINK" },
		Default = "RED",
		OnChange = function() updateArmorTrim() end,
		Tooltip = 'Select the Armor Trim color'
	})

	RankDropdown = AutoArmorTrim:CreateDropdown({
		Name = 'Rank Tier',
		List = { "T1", "T2", "T3", "T4", "T5", "T6", "T7" },
		Default = "T7",
		OnChange = function() updateArmorTrim() end,
		Tooltip = 'Select rank tier for material & particle intensity'
	})

	ForceWeldToggle = AutoArmorTrim:CreateToggle({
		Name = 'Weld Accessories',
		Default = true,
		OnChange = function() updateArmorTrim() end,
		Tooltip = 'Clones, colors, and attaches trim accessories to designated body parts'
	})
end)

run(function()
	local GhostBlockFixer
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local Players = game:GetService("Players")
	local LocalPlayer = Players.LocalPlayer

	-- Helper function to fetch TS modules safely
	local function getTSModule(modulePath, itemName)
		local success, result = pcall(function()
			local rbxts = ReplicatedStorage:WaitForChild("rbxts_include", 2)
			if not rbxts then return nil end
			local RuntimeLib = require(rbxts:WaitForChild("RuntimeLib"))
			local module = RuntimeLib.import(script, ReplicatedStorage, unpack(modulePath))
			return itemName and module[itemName] or module
		end)
		return success and result or nil
	end

	-- Intercept and fix ghost block prediction desync
	local originalDestroyBlock = nil
	local originalHitBlock = nil
	local isHooked = false
	local predictionDepth = 0

	local function hookGhostBlockFix()
		if isHooked then return end

		local BlockEngine = getTSModule({
			"rbxts_include", "node_modules", "@easy-games", "block-engine", "out"
		}, "BlockEngine")

		local BlockBreaker = getTSModule({
			"rbxts_include", "node_modules", "@easy-games", "block-engine", "out", "client", "break", "block-breaker"
		}, "BlockBreaker")

		if not BlockEngine or not BlockBreaker then return end
		isHooked = true

		-- 1. Hook BlockEngine.destroyBlock to suppress client predicted ghost destroys
		originalDestroyBlock = BlockEngine.destroyBlock
		BlockEngine.destroyBlock = function(self, blockRef, options)
			if GhostBlockFixer and GhostBlockFixer.Enabled then
				if predictionDepth > 0 and options and options.destroyingPlayer == LocalPlayer then
					return { spawnedGreedyBlocks = {} }
				end
			end
			return originalDestroyBlock(self, blockRef, options)
		end

		-- 2. Hook BlockBreaker.hitBlock to manage prediction depth and clear stale predicted breaks
		originalHitBlock = BlockBreaker.hitBlock
		BlockBreaker.hitBlock = function(self, ...)
			if GhostBlockFixer and GhostBlockFixer.Enabled then
				predictionDepth += 1
				local success, ret1, ret2, ret3, ret4 = pcall(originalHitBlock, self, ...)
				predictionDepth -= 1

				if self.clientPredictedBlockBreaks then
					table.clear(self.clientPredictedBlockBreaks)
				end

				if not success then
					error(ret1, 2)
				end
				return ret1, ret2, ret3, ret4
			else
				return originalHitBlock(self, ...)
			end
		end
	end

	local function unhookGhostBlockFix()
		local BlockEngine = getTSModule({
			"rbxts_include", "node_modules", "@easy-games", "block-engine", "out"
		}, "BlockEngine")

		local BlockBreaker = getTSModule({
			"rbxts_include", "node_modules", "@easy-games", "block-engine", "out", "client", "break", "block-breaker"
		}, "BlockBreaker")

		if BlockEngine and originalDestroyBlock then
			BlockEngine.destroyBlock = originalDestroyBlock
		end
		if BlockBreaker and originalHitBlock then
			BlockBreaker.hitBlock = originalHitBlock
		end
	end

	-- Register Module under Utility Category
	GhostBlockFixer = vape.Categories.Utility:CreateModule({
		Name = 'GhostBlockFixer',
		Function = function(callback)
			if callback then
				pcall(hookGhostBlockFix)
			else
				pcall(unhookGhostBlockFix)
			end
		end,
		Tooltip = 'Prevents client-side ghost block desync when breaking bed defense blocks'
	})
end)

run(function()
    local AutoRaven
    local TargetModeOption
    local TargetsOption
    local RangeSlider
    local Players = playersService
    local player = Players.LocalPlayer
    local camera = workspace.CurrentCamera
    local steeringThread = nil
    local activeRaven = nil
    local attachedTarget = nil

    local function getTargetScore(hrp, mode, myPos)
        local dist = (hrp.Position - myPos).Magnitude
        if mode == "Distance" then
            return dist
        elseif mode == "Angle" then
            local lookDir = camera.CFrame.LookVector
            local targetDir = (hrp.Position - camera.CFrame.Position).Unit
            local angle = math.acos(math.clamp(lookDir:Dot(targetDir), -1, 1))
            return math.deg(angle)
        elseif mode == "Cursor" then
            local screenPos, onScreen = camera:WorldToViewportPoint(hrp.Position)
            if not onScreen then return math.huge end
            local mousePos = player:GetMouse()
            local cursorDist = (Vector2.new(screenPos.X, screenPos.Y) - Vector2.new(mousePos.X, mousePos.Y)).Magnitude
            return cursorDist
        end
        return dist
    end

    local function getBestTarget(maxRange)
        local myChar = player.Character
        local myPos = myChar and myChar.PrimaryPart and myChar.PrimaryPart.Position
        if not myPos then return nil end

        local bestTarget = nil
        local bestScore = math.huge
        local mode = TargetModeOption and TargetModeOption.Value or "Distance"

        local checkPlayers = TargetsOption and TargetsOption.Players.Enabled
        local checkNPCs = TargetsOption and TargetsOption.NPCs.Enabled

        -- 1. Scan Players
        if checkPlayers then
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr ~= player and plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then
                    local myTeam = player:GetAttribute("Team")
                    local enemyTeam = plr:GetAttribute("Team")
                    if not myTeam or not enemyTeam or myTeam ~= enemyTeam then
                        local hum = plr.Character:FindFirstChildOfClass("Humanoid")
                        if hum and hum.Health > 0 then
                            local dist = (plr.Character.HumanoidRootPart.Position - myPos).Magnitude
                            if dist <= maxRange then
                                local score = getTargetScore(plr.Character.HumanoidRootPart, mode, myPos)
                                if score < bestScore then
                                    bestScore = score
                                    bestTarget = plr.Character.HumanoidRootPart
                                end
                            end
                        end
                    end
                end
            end
        end

        -- 2. Scan NPCs
        if checkNPCs then
            local ws = game:GetService("Workspace")
            for _, obj in ipairs(ws:GetDescendants()) do
                if obj:IsA("Humanoid") and obj.Health > 0 and obj.Parent then
                    local hrp = obj.Parent:FindFirstChild("HumanoidRootPart") or obj.Parent:FindFirstChild("PrimaryPart")
                    if hrp and not Players:GetPlayerFromCharacter(obj.Parent) then
                        local dist = (hrp.Position - myPos).Magnitude
                        if dist <= maxRange then
                            local score = getTargetScore(hrp, mode, myPos)
                            if score < bestScore then
                                bestScore = score
                                bestTarget = hrp
                            end
                        end
                    end
                end
            end
        end

        return bestTarget
    end

    local function attachAndDetonateRaven(ravenModel, targetHRP)
        if not ravenModel or not ravenModel.PrimaryPart or not targetHRP or not targetHRP.Parent then 
            activeRaven = nil
            attachedTarget = nil
            return 
        end

        activeRaven = ravenModel
        attachedTarget = targetHRP

        -- Create attachment thread that keeps raven locked to target while following and detonates
        task.spawn(function()
            local clientRemotes = require(game:GetService("ReplicatedStorage").TS.remotes).default.Client
            local detonateRemote = clientRemotes:Get("DetonateRaven")
            
            while activeRaven and activeRaven.Parent and attachedTarget and attachedTarget.Parent and AutoRaven.Enabled do
                pcall(function()
                    if activeRaven.PrimaryPart and attachedTarget then
                        -- Keep raven at target position
                        activeRaven:PivotTo(CFrame.new(attachedTarget.Position))
                    end
                end)
                task.wait(0.01)
            end
            
            -- Detonate at attached position when raven dies or target dies
            if detonateRemote and activeRaven then
                pcall(function()
                    detonateRemote:CallServerAsync(activeRaven)
                end)
            end
            
            activeRaven = nil
            attachedTarget = nil
        end)
    end

    local function triggerAutoRaven()
        if not AutoRaven.Enabled then return end
        if activeRaven then return end -- Don't spawn new raven if one is active

        local range = RangeSlider and RangeSlider.Value or 150
        local targetHRP = getBestTarget(range)
        if not targetHRP then return end

        task.spawn(function()
            local clientRemotes = require(game:GetService("ReplicatedStorage").TS.remotes).default.Client
            local spawnRemote = clientRemotes:Get("SpawnRaven")
            
            if spawnRemote then
                spawnRemote:CallServerAsync():andThen(function(ravenModel)
                    if ravenModel and ravenModel.PrimaryPart and targetHRP and targetHRP.Parent then
                        -- Teleport to initial target position
                        ravenModel:PivotTo(CFrame.new(targetHRP.Position))
                        
                        -- Attach raven to target and setup detonation on detach
                        attachAndDetonateRaven(ravenModel, targetHRP)
                    end
                end)
            end
        end)
    end

    AutoRaven = vape.Categories.Kits:CreateModule({
        Name = "RavenTP",
        Tooltip = "teleports raven directly to target and locks on until detonation",
        Function = function(callback)
            if callback then
                steeringThread = task.spawn(function()
                    while AutoRaven.Enabled do
                        triggerAutoRaven()
                        task.wait(1)
                    end
                end)
            else
                if steeringThread then
                    task.cancel(steeringThread)
                    steeringThread = nil
                end
                activeRaven = nil
                attachedTarget = nil
            end
        end
    })

    TargetModeOption = AutoRaven:CreateDropdown({
        Name = "Target Mode",
        List = { "Distance", "Angle", "Cursor" },
        Default = "Distance",
        Tooltip = "choose how targets are prioritized",
        Function = function() end
    })

    TargetsOption = AutoRaven:CreateTargets({
        Players = true,
        NPCs = true,
        Tooltip = "select target types (Players / NPCs)"
    })

    RangeSlider = AutoRaven:CreateSlider({
        Name = "Target Range",
        Min = 20,
        Max = 300,
        Default = 150,
        Decimal = 1,
        Tooltip = "max detection distance for auto raven targeting",
        Function = function() end
    })
end)

run(function()
	local AutoSkoll
	local Targets
	local RangeSlider
	local AutoFacing
	local AutoDetonate
	local DetonateRange

	local isMarked = false
	local markedTarget = nil
	local markedTime = 0

	task.spawn(function()
		local ClientSyncEvents = bedwars.ClientSyncEvents or (bedwars.Client and bedwars.Client:GetNamespace('Default'))
		if ClientSyncEvents then
			ClientSyncEvents:Get('VoidHunter_TargetMarked'):Connect(function(data)
				isMarked = true
				markedTime = tick()
				if data and data.target then
					markedTarget = data.target
				end
			end)
			ClientSyncEvents:Get('VoidHunter_TargetMarkedRemoved'):Connect(function()
				isMarked = false
				markedTarget = nil
			end)
		end
	end)

	local function isTargetValid(ent)
		if not ent or not ent.Targetable then return false end
		if ent.Player and Targets and Targets.Players and Targets.Players.Enabled then return true end
		if not ent.Player and Targets and Targets.NPCs and Targets.NPCs.Enabled then return true end
		return false
	end

	local function getTarget()
		if not entitylib.isAlive or not entitylib.character or not entitylib.character.RootPart then return nil end
		local rootPos = entitylib.character.RootPart.Position
		local maxDist = RangeSlider and RangeSlider.Value or 22
		local bestTarget, bestDist = nil, maxDist

		for _, ent in pairs(entitylib.List) do
			if isTargetValid(ent) and ent.RootPart then
				local dist = (ent.RootPart.Position - rootPos).Magnitude
				if dist <= bestDist then
					bestDist = dist
					bestTarget = ent
				end
			end
		end
		return bestTarget
	end

	AutoSkoll = vape.Categories.Kits:CreateModule({
		Name = 'AutoSkoll',
		Function = function(callback)
			if callback then
				repeat
					if entitylib.isAlive and entitylib.character and entitylib.character.RootPart then
						local myPos = entitylib.character.RootPart.Position
						local target = getTarget()

						if not isMarked then
							if target and target.RootPart then
								local targetPos = target.RootPart.Position
								local dir = (targetPos - myPos).Unit

								if AutoFacing and AutoFacing.Enabled then
									pcall(function()
										entitylib.character.RootPart.CFrame = CFrame.lookAt(myPos, Vector3.new(targetPos.X, myPos.Y, targetPos.Z))
									end)
								end

								pcall(function()
									if bedwars.AbilityController then
										bedwars.AbilityController:useAbility('void_hunter_mark')
									elseif bedwars.KnitClient and bedwars.KnitClient.Controllers.VoidHunterKitController then
										bedwars.KnitClient.Controllers.VoidHunterKitController:useMarkAbility(dir)
									end
								end)
								task.wait(0.3)
							end
						else
							if AutoDetonate and AutoDetonate.Enabled then
								local detonateDist = DetonateRange and DetonateRange.Value or 50
								local shouldDetonate = false

								if markedTarget and markedTarget.Parent and markedTarget:FindFirstChild('HumanoidRootPart') then
									local tPos = markedTarget.HumanoidRootPart.Position
									if (tPos - myPos).Magnitude >= detonateDist then
										shouldDetonate = true
									end
								elseif tick() - markedTime > 5 then
									shouldDetonate = true
								end

								if shouldDetonate then
									pcall(function()
										if bedwars.AbilityController then
											bedwars.AbilityController:useAbility('void_hunter_detonate')
										end
									end)
									task.wait(0.3)
								end
							end
						end
					end
					task.wait(0.1)
				until not AutoSkoll.Enabled
			else
				isMarked = false
				markedTarget = nil
			end
		end,
		Tooltip = 'Auto launches & auto detonates Skoll Fenrir wolf mark ability'
	})

	Targets = AutoSkoll:CreateTargets({
		Players = true,
		NPCs = true
	})

	RangeSlider = AutoSkoll:CreateSlider({
		Name = 'Range',
		Min = 0,
		Max = 22,
		Default = 22,
		Suffix = function(val) return val <= 1 and 'stud' or 'studs' end
	})

	AutoFacing = AutoSkoll:CreateToggle({
		Name = 'Auto Facing',
		Default = true,
		Tooltip = 'Faces target when sending wolf'
	})

	AutoDetonate = AutoSkoll:CreateToggle({
		Name = 'Auto Detonate',
		Default = true,
		Tooltip = 'Detonates mark when enemy moves out of detonate range'
	})

	DetonateRange = AutoSkoll:CreateSlider({
		Name = 'Detonate Range',
		Min = 0,
		Max = 50,
		Default = 35,
		Suffix = function(val) return val <= 1 and 'stud' or 'studs' end
	})
end)

run(function()
	local AutoAlchemist
	local PotionSelect
	local BrewDelay

	local RECIPES = {
		['Heal Potion']   = { ingredients = { wild_flower = 3 } },
		['Sleep Potion']  = { ingredients = { mushrooms = 3 } },
		['Poison Potion'] = { ingredients = { thorns = 1, mushrooms = 2 } },
		['Big Shield']    = { ingredients = { thorns = 2, wild_flower = 1 } },
	}

	local INGREDIENT_NAMES = {
		wild_flower = 'Wild Flower',
		mushrooms   = 'Mushrooms',
		thorns      = 'Thorns',
	}

	local ABILITY_MAP = {
		wild_flower = 'alchemist_add_flower',
		mushrooms   = 'alchemist_add_mushrooms',
		thorns      = 'alchemist_add_thorns',
	}

	-- Find the useAbility RemoteEvent from ReplicatedStorage
	local useAbilityRemote
	task.spawn(function()
		for _, desc in replicatedStorage:GetDescendants() do
			if desc.Name == 'useAbility' and desc:IsA('RemoteEvent') then
				useAbilityRemote = desc
				break
			end
		end
		if not useAbilityRemote then
			replicatedStorage.DescendantAdded:Connect(function(desc)
				if desc.Name == 'useAbility' and desc:IsA('RemoteEvent') then
					useAbilityRemote = desc
				end
			end)
		end
	end)

	local lplr = game:GetService('Players').LocalPlayer

	local function getItemCount(itemType)
		if not store or not store.inventory or not store.inventory.inventory then return 0 end
		local count = 0
		for _, item in store.inventory.inventory.items do
			if item.itemType == itemType then
				count += (item.quantity or 1)
			end
		end
		return count
	end

	local function isHoldingFlask()
		if not store or not store.inventory then return false end
		local inv = store.inventory.inventory or store.inventory.observedInventory and store.inventory.observedInventory.inventory
		if not inv then return false end
		local hand = inv.hand
		return hand and hand.itemType == 'alchemist_flask'
	end

	local function getStagedCount(ingredient)
		local attr = lplr:GetAttribute('AlchemistFlaskBrewStage')
		if type(attr) ~= 'string' or attr == '' then return 0 end
		local count = 0
		for t in attr:gmatch('[^,]+') do
			if t:lower() == ingredient then count += 1 end
		end
		return count
	end

	local function fireAbility(abilityId)
		local ok = pcall(function()
			bedwars.AbilityController:useAbility(abilityId)
		end)
		if not ok and useAbilityRemote then
			pcall(function()
				useAbilityRemote:FireServer(abilityId, {})
			end)
		end
	end

	AutoAlchemist = vape.Categories.Kits:CreateModule({
		Name = 'AutoAlchemist',
		Function = function(callback)
			if callback then
				repeat
					task.wait(BrewDelay and BrewDelay.Value or 0.5)
					if not entitylib.isAlive then continue end
					if not isHoldingFlask() then continue end

					local selectedPotion = PotionSelect and PotionSelect.Value or 'Heal Potion'
					local recipe = RECIPES[selectedPotion]
					if not recipe then continue end

					-- Check for missing ingredients
					local missing = {}
					for ingredient, needed in pairs(recipe.ingredients) do
						local staged = getStagedCount(ingredient)
						local have = getItemCount(ingredient)
						local stillNeeded = math.max(0, needed - staged)
						if have < stillNeeded then
							table.insert(missing, (stillNeeded - have) .. 'x ' .. INGREDIENT_NAMES[ingredient])
						end
					end

					if #missing > 0 then
						vape.Notify({
							Title = 'AutoAlchemist',
							Description = 'Missing: ' .. table.concat(missing, ', '),
							Duration = 3
						})
						continue
					end

					-- Stage each ingredient that still needs to be added
					for ingredient, needed in pairs(recipe.ingredients) do
						local toAdd = math.max(0, needed - getStagedCount(ingredient))
						for _ = 1, toAdd do
							fireAbility(ABILITY_MAP[ingredient])
							task.wait(0.2)
						end
					end

				until not AutoAlchemist.Enabled
			end
		end,
		Tooltip = 'Auto brews selected potions with the Alchemist flask. Notifies on missing ingredients.'
	})

	PotionSelect = AutoAlchemist:CreateDropdown({
		Name = 'Potion',
		List = {'Heal Potion', 'Sleep Potion', 'Poison Potion', 'Big Shield'},
		Default = 'Heal Potion',
		Tooltip = 'Potion to auto brew'
	})

	BrewDelay = AutoAlchemist:CreateSlider({
		Name = 'Brew Delay',
		Min = 0.1,
		Max = 2,
		Default = 0.5,
		Decimal = 10,
		Tooltip = 'Delay between brew cycles'
	})
end)

run(function()
	local AutoShoot
	local Targets
	local Check
	local Projectiles
	local UseSophia
	local UseWhim
	local ArrowCharge
	local SwitchDelay
	
	local FireDelays = {}
	
	local function getEntity()
		local selfpos = entitylib.character.RootPart.Position
		local plrs = entitylib.AllPosition({
			Origin = selfpos,
			Part = 'RootPart',
			Range = 22,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Wallcheck = Targets.Walls.Enabled,
			Limit = 10
		})
		if #plrs > 0 then
			for _, ent in plrs do
				local localfacing = entitylib.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
				local delta = (ent.RootPart.Position - selfpos) * Vector3.new(1, 0, 1)
				local angle = localfacing.Magnitude > 0 and delta.Magnitude > 0 and math.acos(math.clamp(localfacing.Unit:Dot(delta.Unit), -1, 1)) or 0
				if angle > (math.rad(120) / 2) then continue end
				return ent
			end
		end
		return nil
	end
	
	AutoShoot = vape.Categories.Utility:CreateModule({
		Name = 'AutoShoot',
		Function = function(callback)
			if callback then
				repeat
					if entitylib.isAlive and store.hand.toolType == 'sword' and (tick() - bedwars.SwordController.lastSwing) < 0.2 then
						local hotbar = store.hand.tool and getHotbar(store.hand.tool) or nil
						for _, data in getProjectiles(Projectiles.ListEnabled, UseSophia.Enabled, UseWhim.Enabled) do
							local item, ammo, projectile, itemMeta = unpack(data)
							if (FireDelays[item.itemType] or 0) < tick() then
								local ent = getEntity()
								if (not Check.Enabled or ent) and hotbarSwitch(getHotbar(item.tool)) then
									task.wait(store.ping.total or 0)
									local meta = bedwars.ProjectileMeta[projectile]
									local projSpeed, gravity = meta.launchVelocity, meta.gravitationalAcceleration or 196.2
									local calc = ent and prediction.SolveTrajectory(entitylib.character.RootPart.Position, projSpeed, gravity, ent.RootPart.Position, ent.RootPart.Velocity, workspace.Gravity, ent.HipHeight, ent.Jumping and 42.6 or nil, rayCheck, ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(ent.RootPart.Velocity.Y) > 0.01, ent.RootPart.Position, ent.RootPart, nil, true) or nil
									if calc then
										local shootPosition = (CFrame.new(entitylib.character.RootPart.Position, calc) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position
										local aim = prediction.SolveTrajectory(shootPosition, projSpeed, gravity, ent.RootPart.Position, ent.RootPart.Velocity, workspace.Gravity, ent.HipHeight, ent.Jumping and 42.6 or nil, rayCheck, ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(ent.RootPart.Velocity.Y) > 0.01, ent.RootPart.Position, ent.RootPart, nil, true) or calc
										local dir, id = CFrame.lookAt(shootPosition, aim).LookVector, httpService:GenerateGUID(true)
										bedwars.Handler:Get('ProjectileFire'):Fire('CallServerAsync',
											item.tool,
											ammo,
											projectile,
											shootPosition,
											entitylib.character.RootPart.Position,
											dir * projSpeed,
											id,
											{
												drawDurationSeconds = 1,
												shotId = httpService:GenerateGUID(false),
											},
											workspace:GetServerTimeNow() - 0.045
										):andThen(function(res)
											if res then
												res.Parent = replicatedStorage
											end
										end)
										prediction.trackShot(ent.RootPart)
										FireDelays[item.itemType] = tick() + (itemMeta.fireDelaySec + FireRate:GetRandomValue())
										task.wait(SwitchDelay.Value)
									end
								end
							end
						end
						hotbarSwitch(hotbar)
					end
					task.wait(0.1)
				until not AutoShoot.Enabled
			end
		end,
		Tooltip = 'Automatically crossbow macro\'s'
	})
	Targets = AutoShoot:CreateTargets({Players = true})
	Check = AutoShoot:CreateToggle({
		Name = 'Target check',
		Default = true,
		Function = function(callback)
			if Targets.Object then
				Targets.Object.Visible = callback
			end
		end
	})
	Projectiles = AutoShoot:CreateTextList({
		Name = 'Projectile Type',
		Default = {'arrow', 'fireball'}
	})
	UseSophia = AutoShoot:CreateToggle({
		Name = 'Sophia',
	})
	UseWhim = AutoShoot:CreateToggle({
		Name = 'Whim',
	})
	FireRate = AutoShoot:CreateTwoSlider({
		Name = 'Fire Rate',
		Min = 0,
		Max = 1,
		DefaultMin = 0.05,
		DefaultMax = 0.12,
		Decimal = 100
	})
	SwitchDelay = AutoShoot:CreateSlider({
		Name = 'Switch Delay',
		Min = 0,
		Max = 1,
		Decimal = 100,
		Suffix = 's',
		Default = 0.02
	})
end)

run(function()
	local BedAlarm
	local Types
	local Distance
	local UpdateTick
	local HighlightEnemies
	local SoundVolume
	local ShowAlarm

	local function getBed()
		if not (entitylib.isAlive and lplr.Character) then return nil end
		local id = lplr.Character:GetAttribute('Team') or lplr.Character:GetAttribute('TeamId')
		for _, v in collectionService:GetTagged('bed') do
			if tonumber(id) == tonumber(v:GetAttribute('TeamID') or v:GetAttribute('Team') or v:GetAttribute('TeamId')) then
				return v
			end
		end
		return nil
	end

	local function createAlarm(bedpos)
		if not ShowAlarm.Enabled then return end
		if not bedpos then return end
		if store.BedAlarm[lplr] then return end

		if bedwars.BedAlarmController then
			local suc, res = pcall(function()
				local oldthread = 0
				if vape.ThreadFix then 
					oldthread = getthreadidentity()
					setthreadidentity(8) 
				end

				local myTeam = lplr.Character:GetAttribute('Team') or lplr.Character:GetAttribute('TeamId') or -1
				bedwars.BedAlarmController:getOrCreateBedAlarmModel(myTeam, bedpos)

				if vape.ThreadFix then 
					setthreadidentity(oldthread) 
				end
			end)

			if suc then
				store.BedAlarm[lplr] = true
			else
				vape:CreateNotification("BedAlarm", `Creating Alarm issue: {res}`, 16, 'alert')
			end
		end
	end

	local function AlarmAffects(bedpos)
		if not ShowAlarm.Enabled or not bedpos then return end
		if not store.BedAlarm[lplr] then return end

		local myTeam = lplr.Character:GetAttribute('Team') or lplr.Character:GetAttribute('TeamId') or -1
		pcall(function()
			bedwars.BedAlarmController:triggerBedAlarmModel({bedPosition = bedpos, teamId = myTeam})
		end)
	end

	local function removeAlarm()
		if not store.BedAlarm[lplr] then return end
		
		local myTeam = lplr.Character:GetAttribute('Team') or lplr.Character:GetAttribute('TeamId') or -1
		local alarm = bedwars.BedAlarmController.bedAlarmModelMap[myTeam]
		if alarm then
			alarm:Destroy()
			bedwars.BedAlarmController.bedAlarmModelMap[myTeam] = nil
		end
		store.BedAlarm[lplr] = nil
	end

	local function createHighlight(ent)
		if store.BedAlarmHighlightedEnimes[ent] then return end
		
		local character = ent.character or ent.Character
		if not character then return end

		local highlight = Instance.new("Highlight")
		highlight.Name = "BedAlarmHighlight"
		highlight.Adornee = character
		highlight.FillColor = Color3.fromRGB(255, 80, 80)
		highlight.OutlineColor = Color3.fromRGB(255, 100, 100)
		highlight.FillTransparency = 0.6
		highlight.OutlineTransparency = 0
		highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
		highlight.Parent = character
		
		store.BedAlarmHighlightedEnimes[ent] = highlight
	end

	local function clearAllHighlights()
		for _, highlight in pairs(store.BedAlarmHighlightedEnimes) do
			if highlight and highlight.Parent then highlight:Destroy() end
		end
		table.clear(store.BedAlarmHighlightedEnimes)
	end

	local function removeHighlight(ent)
		local hl = store.BedAlarmHighlightedEnimes[ent]
		if hl then
			hl:Destroy()
			store.BedAlarmHighlightedEnimes[ent] = nil
		end
	end

	BedAlarm = vape.Categories.Utility:CreateModule({
		Name = "BedAlarm",
		Function = function(callback)
			if callback then
				store.BedAlarmNotifyTick = 0
				store.BedAlarmSoundTick = 0
				store.BedAlarmIsTrigged = false

				local bed = getBed()
				local bedpos = bed and bed:GetPivot().Position or Vector3.zero

				if ShowAlarm.Enabled then
					createAlarm(bedpos)
				end

				local _bedAlarmSearch = {Origin = bedpos, Range = Distance.Value, Part = 'RootPart', Players = true, IgnoreLocal = true}
				repeat
					if bedpos then
						_bedAlarmSearch.Origin = bedpos
						_bedAlarmSearch.Range = Distance.Value
						local entity = entitylib.EntityPosition(_bedAlarmSearch)

						if entity then
							store.BedAlarmIsTrigged = true

							if ShowAlarm.Enabled then
								createAlarm(bedpos)
							end

							if os.time() >= store.BedAlarmNotifyTick then
								store.BedAlarmNotifyTick = os.time() + UpdateTick.Value

								AlarmAffects(bedpos)

								local msg = '[Bed Alarm]: An intruder is near your bed!'
								if Types.Value == 'Vape' then
									vape:CreateNotification("BedAlarm", msg, UpdateTick.Value + 1)
								else
									pcall(function()
										bedwars.NotificationController:sendInfoNotification({ message = msg })
									end)
								end
							end

							if os.time() >= store.BedAlarmSoundTick then
								store.BedAlarmSoundTick = os.time() + 1.2

								local distance = (bedpos - entity.RootPart.Position).Magnitude
								local soundId = distance >= 30 and bedwars.SoundList.BED_ALARM_TRIGGERED_FAR or bedwars.SoundList.BED_ALARM

								pcall(function()
									bedwars.SoundManager:playSound(soundId, {
										volumeMultiplier = SoundVolume.Value
									})
								end)
							end

							if HighlightEnemies.Enabled then
								createHighlight(entity)
							end
						else
							store.BedAlarmIsTrigged = false
						end
					end

					for ent, _ in pairs(store.BedAlarmHighlightedEnimes) do
						if not entity or ent ~= entity then
							removeHighlight(ent)
						end
					end

					task.wait(1/60)
				until not BedAlarm.Enabled

			else
				store.BedAlarmIsTrigged = false
				clearAllHighlights()
				removeAlarm()
			end
		end
	})

	Distance = BedAlarm:CreateSlider({Name = 'Distance', Min = 10, Max = 100, Default = 64, Suffix = " studs"})
	
	Types = BedAlarm:CreateDropdown({
		Name = 'Notification Type',
		List = {'Vape','Bedwars'},
		Default = 'Bedwars'
	})
	
	UpdateTick = BedAlarm:CreateSlider({
		Name = "Update Tick",
		Min = 0.5,
		Max = 8,
		Decimal = 5,
		Default = 3,
		Suffix = 's'
	})
	
	SoundVolume = BedAlarm:CreateSlider({
		Name = "Volume Multiplier",
		Min = 0.1,
		Max = 3,
		Default = 1.5,
		Decimal = 5,
	})
	
	HighlightEnemies = BedAlarm:CreateToggle({
		Name = 'Highlight Enemies',
		Default = true,
		Function = function(v)
			if not v then clearAllHighlights() end
		end
	})
	
	ShowAlarm = BedAlarm:CreateToggle({
		Name = "Show Alarm Model",
		Default = false,
		Function = function(v)
			local bed = getBed()
			local pos = bed and bed:GetPivot().Position or Vector3.zero
			if v then
				createAlarm(pos)
			else
				removeAlarm()
			end
		end
	})
end)

run(function()
	local AutoPlay
	local Random
	
	local function isEveryoneDead()
		return #bedwars.Store:getState().Party.members <= 0
	end
	
	local function joinQueue()
		if not bedwars.Store:getState().Game.customMatch and bedwars.Store:getState().Party.leader.userId == lplr.UserId and bedwars.Store:getState().Party.queueState == 0 then
			if Random.Enabled then
				local listofmodes = {}
				for i, v in bedwars.QueueMeta do
					if not v.disabled and not v.voiceChatOnly and not v.rankCategory then 
						table.insert(listofmodes, i) 
					end
				end
				bedwars.QueueController:joinQueue(listofmodes[math.random(1, #listofmodes)])
			else
				bedwars.QueueController:joinQueue(store.queueType)
			end
		end
	end
	
	AutoPlay = vape.Categories.Utility:CreateModule({
		Name = 'AutoPlay',
		Function = function(callback)
			if callback then
				AutoPlay:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable)
					if deathTable.finalKill and deathTable.entityInstance == lplr.Character and isEveryoneDead() and store.matchState ~= 2 then
						joinQueue()
					end
				end))
				AutoPlay:Clean(vapeEvents.MatchEndEvent.Event:Connect(function()
					task.wait(1)
					joinQueue()
				end))
			end
		end,
		Tooltip = 'auto queues after the match ends.'
	})
	Random = AutoPlay:CreateToggle({
		Name = 'Random',
	})
end)

run(function()
	local AutoVoidDrop
	local OwlCheck
	local PearlCheck
	local AutoReset
	local pearlLastInHandTickVoid = 0
	local DropToggles = {
		iron = nil,
		diamond = nil,
		emerald = nil,
		gold = nil
	}
	local cachedLowestPoint
	
	AutoVoidDrop = vape.Categories.Utility:CreateModule({
		Name = 'AutoVoidDrop',
		Function = function(callback)
			if callback then
				repeat task.wait() until store.matchState ~= 0 or (not AutoVoidDrop.Enabled)
				if not AutoVoidDrop.Enabled then return end

				cachedLowestPoint = math.huge
				for _, v in pairs(store.blocks) do
					local point = (v.Position.Y - (v.Size.Y / 2)) - 75
					if point < cachedLowestPoint then
						cachedLowestPoint = point
					end
				end

				repeat
					if entitylib.isAlive then
						local root = entitylib.character.RootPart

						local handItem = store.inventory and store.inventory.inventory and store.inventory.inventory.hand
						if handItem and handItem.itemType == 'telepearl' then
							pearlLastInHandTickVoid = tick()
						end

						if root.Position.Y < cachedLowestPoint and (lplr.Character:GetAttribute('InflatedBalloons') or 0) <= 0 and not getItem('balloon') then
							local pearlBlock = PearlCheck.Enabled and (tick() - pearlLastInHandTickVoid) < 4
							if (not OwlCheck.Enabled or not root:FindFirstChild('OwlLiftForce')) and not pearlBlock then
								for _, item in pairs(store.inventory.inventory.items) do
									if item and item.tool then
										local dropped = bedwars.Client:Get(remotes.DropItem):CallServer({
											item = item.tool,
											amount = item.amount
										})
										if dropped then
											dropped:SetAttribute('ClientDropTime', tick() + 100)
										end
									end
								end
								if AutoReset.Enabled then
									local hum = root.Parent:FindFirstChildOfClass('Humanoid')
									if hum then
										hum.Health = 0
									end
								end
								break
							end
						end
					end

					task.wait(0.1)
				until not AutoVoidDrop.Enabled
			end
		end,
		Tooltip = 'drops resources when you fall into the void'
	})
	
	OwlCheck = AutoVoidDrop:CreateToggle({
		Name = 'Owl check',
		Default = true,
		Tooltip = 'doesnt drop items if being picked up by an owl'
	})
	PearlCheck = AutoVoidDrop:CreateToggle({
		Name = 'Pearl check',
		Default = false,
		Tooltip = 'does not drop if holding a pearl or recently threw one (4 sec cooldown)'
	})
	AutoReset = AutoVoidDrop:CreateToggle({
		Name = 'Auto Reset',
		Default = false,
		Tooltip = 'resets ur character right after dropping all the loot gng'
	})
	DropToggles.iron = AutoVoidDrop:CreateToggle({
		Name = 'Drop Iron',
		Default = true
	})
	DropToggles.diamond = AutoVoidDrop:CreateToggle({
		Name = 'Drop Diamond',
		Default = true
	})
	DropToggles.emerald = AutoVoidDrop:CreateToggle({
		Name = 'Drop Emerald',
		Default = true
	})
	DropToggles.gold = AutoVoidDrop:CreateToggle({
		Name = 'Drop Gold',
		Default = true
	})
end)
	
run(function()
	local PickupRange
	local Range
	local Network
	local Lower
	local Picked = {}
	
	PickupRange = vape.Categories.Utility:CreateModule({
		Name = 'PickupRange',
		Function = function(callback)
			if callback then
				local items = collection('ItemDrop', PickupRange)
				repeat
					if entitylib.isAlive then
						local localPosition = entitylib.character.RootPart.Position
						for _, v in items do
							if tick() - (v:GetAttribute('ClientDropTime') or 0) < 2 or table.find(Picked, v) then continue end
							if isnetworkowner(v) and Network.Enabled and entitylib.character.Humanoid.Health > 0 then
								v.CFrame = CFrame.new(localPosition - Vector3.new(0, 3, 0))
							end
	
							if (localPosition - v.Position).Magnitude <= Range.Value then
								if Lower.Enabled and (localPosition.Y - v.Position.Y) < (entitylib.character.HipHeight - 1) then continue end
								local InsertPosition = #Picked + 1
								table.insert(Picked, InsertPosition, v)
								task.spawn(function()
									bedwars.Handler:Get('PickupItemDrop'):Fire('CallServerAsync', {
										itemDrop = v
									}):andThen(function(suc)
										table.remove(Picked, InsertPosition)
										if suc and bedwars.SoundList then
											bedwars.AudioManager:playAudio(bedwars.SoundList.PICKUP_ITEM_DROP)
											local sound = bedwars.ItemMeta[v.Name].pickUpOverlaySound
											if sound then
												bedwars.AudioManager:playAudio(sound, {
													position = v.Position,
													volumeMultiplier = 0.9
												})
											end
										end
									end)
								end)
							end
						end
					end
					task.wait(0.1)
				until not PickupRange.Enabled
			end
		end,
		Tooltip = 'Picks up items from a farther distance'
	})
	
	Range = PickupRange:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 10,
		Default = 10,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})
	Network = PickupRange:CreateToggle({
		Name = 'Network TP',
		Default = true
	})
	Lower = PickupRange:CreateToggle({Name = 'Feet Check'})
end)

run(function()
	local InfiniteMana
	local manaLoop

	InfiniteMana = vape.Categories.Kits:CreateModule({
		Name = 'InfWhim',
		Tooltip = 'Locks your client-side mana bar to max',
		Function = function(callback)
			if callback then
				manaLoop = task.spawn(function()
					while InfiniteMana.Enabled do
						if lplr then
							pcall(function()
								lplr:SetAttribute("Mana", 100)
							end)
						end
						task.wait(0.05)
					end
				end)
			else
				if manaLoop then
					pcall(task.cancel, manaLoop)
					manaLoop = nil
				end
			end
		end
	})
end)

run(function()
	local Scaffold
	local Expand
	local Tower
	local Downwards
	local Diagonal
	local LimitItem
	local Mouse
	local PlaceDelay
	local adjacent, lastpos = {}, Vector3.zero
	local lastPlaceTime = 0
	
	for x = -3, 3, 3 do
		for y = -3, 3, 3 do
			for z = -3, 3, 3 do
				local vec = Vector3.new(x, y, z)
				if vec ~= Vector3.zero then
					table.insert(adjacent, vec)
				end
			end
		end
	end
	
	local function checkAdjacent(pos)
		for _, v in adjacent do
			if getPlacedBlock(pos + v) then
				return true
			end
		end
		return false
	end
	
	local function getScaffoldBlock()
		if store.hand.toolType == 'block' then
			return store.hand.tool.Name, store.hand.amount
		elseif (not LimitItem.Enabled) then
			local isHoldingSwordOrTool = store.hand.toolType == 'sword' or (store.hand.tool and bedwars.ItemMeta[store.hand.tool.Name].sword)
			if not isHoldingSwordOrTool then
				local wool, amount = getWool()
				if wool then
					return wool, amount
				else
					for _, item in store.inventory.inventory.items do
						if bedwars.ItemMeta[item.itemType].block then
							return item.itemType, item.amount
						end
					end
				end
			end
		end
	
		return nil, 0
	end
	
	Scaffold = vape.Categories.Utility:CreateModule({
		Name = 'Scaffold',
		Function = function(callback)
			if callback then
				lastPlaceTime = 0
				repeat
					if entitylib.isAlive then
						local wool, amount = getScaffoldBlock()

						if Mouse.Enabled then
							if not inputService:IsMouseButtonPressed(0) then
								wool = nil
							end
						end

						if wool then
							local root = entitylib.character.RootPart
							if Tower.Enabled and inputService:IsKeyDown(Enum.KeyCode.Space) and (not inputService:GetFocusedTextBox()) then
								root.Velocity = Vector3.new(root.Velocity.X, 38, root.Velocity.Z)
							end

							for i = Expand.Value, 1, -1 do
								local currentpos = roundPos(root.Position - Vector3.new(0, entitylib.character.HipHeight + (Downwards.Enabled and inputService:IsKeyDown(Enum.KeyCode.LeftShift) and 4.5 or 1.5), 0) + entitylib.character.Humanoid.MoveDirection * (i * 3))
								if Diagonal.Enabled then
									if math.abs(math.round(math.deg(math.atan2(-entitylib.character.Humanoid.MoveDirection.X, -entitylib.character.Humanoid.MoveDirection.Z)) / 45) * 45) % 90 == 45 then
										local dt = (lastpos - currentpos)
										if ((dt.X == 0 and dt.Z ~= 0) or (dt.X ~= 0 and dt.Z == 0)) and ((lastpos - root.Position) * Vector3.new(1, 0, 1)).Magnitude < 2.5 then
											currentpos = lastpos
										end
									end
								end

								local block, blockpos = getPlacedBlock(currentpos)
								if not block then
									if tick() - lastPlaceTime >= (PlaceDelay.Value / 1000) then
										blockpos = checkAdjacent(blockpos * 3) and blockpos * 3 or blockProximity(currentpos)
										if blockpos then
											task.spawn(bedwars.placeBlock, blockpos, wool, false)
											lastPlaceTime = tick()
										end
									end
								end
								lastpos = currentpos
							end
						end
					end

					task.wait(0.03)
				until not Scaffold.Enabled
			else
				lastPlaceTime = 0
			end
		end,
		Tooltip = 'Helps you make bridges/scaffold walk.'
	})
	Expand = Scaffold:CreateSlider({
		Name = 'Expand',
		Min = 1,
		Max = 6
	})
	Tower = Scaffold:CreateToggle({
		Name = 'Tower',
		Default = true
	})
	Downwards = Scaffold:CreateToggle({
		Name = 'Downwards',
		Default = true
	})
	Diagonal = Scaffold:CreateToggle({
		Name = 'Diagonal',
		Default = true
	})
	LimitItem = Scaffold:CreateToggle({Name = 'Limit to items'})
	Mouse = Scaffold:CreateToggle({Name = 'Require mouse down'})
	PlaceDelay = Scaffold:CreateSlider({
		Name = 'Place Delay',
		Min = 0,
		Max = 200,
		Default = 0,
		Suffix = "ms"
	})
end)

run(function()
	local AutoBuy
	local ItemShop
	local TeamUpgrade
	local WrenShop
	local GUICheck
	local BuyArmorToggle
	local BuyAxeToggle
	local BuyPickaxeToggle
	local BuyProjectileToggle
	local BuySerpentToggle
	local BuyJumpToggle
	local BuyShieldToggle
	local BreakSpeedToggle
	local ArmorUpgradeToggle
	local DamageToggle
	local DiamondGenToggle
	local TeamGenToggle
	local BedBarrierToggle

	local purchaseRemote
	local function getPurchaseRemote()
		if not purchaseRemote then
			purchaseRemote = game:GetService("ReplicatedStorage").rbxts_include.node_modules["@rbxts"].net.out._NetManaged.BedwarsPurchaseItem
		end
		return purchaseRemote
	end

	local function getResourceCount(currency)
		local item = getItem(currency)
		return item and item.amount or 0
	end

	local function playerOwns(itemType)
		for _, item in store.inventory.inventory.items do
			if item.itemType == itemType then return true end
		end
		if store.inventory.inventory.armor then
			for _, v in pairs(store.inventory.inventory.armor) do
				if type(v) == 'table' and v.itemType == itemType then return true end
			end
		end
		return false
	end

	local function isNearShop(checkType)
		if not GUICheck.Enabled then return true end
		local _, items, upgrades = getShopNPC()
		if checkType == 'item' then return items end
		if checkType == 'upgrade' then return upgrades end
		return false
	end

	local function buyItem(shopItem, shopId)
		pcall(function()
			getPurchaseRemote():InvokeServer({shopItem = shopItem, shopId = shopId})
		end)
	end

	local function getShopData(itemType)
		if not bedwars.Shop then return nil end
		local ok, res = pcall(function()
			return bedwars.Shop.getShopItem(itemType, lplr)
		end)
		return ok and res or nil
	end

	local armorTiers = {
		'emerald_chestplate','emerald_leggings','emerald_boots',
		'diamond_chestplate','diamond_leggings','diamond_boots',
		'iron_chestplate','iron_leggings','iron_boots',
		'leather_chestplate',
	}
	local axeTiers = {'emerald_axe','diamond_axe','iron_axe','stone_axe','wood_axe'}
	local pickaxeTiers = {'emerald_pickaxe','diamond_pickaxe','iron_pickaxe','stone_pickaxe','wood_pickaxe'}

	local function buyBestTier(tierList, shopId)
		for _, itemType in ipairs(tierList) do
			if playerOwns(itemType) then break end
			local data = getShopData(itemType)
			if data then
				if getResourceCount(data.currency or 'iron') >= (data.price or math.huge) then
					buyItem(data, shopId)
					break
				end
			end
		end
	end

	local function buyProjectile(shopId)
		local em = getResourceCount('emerald')
		local ir = getResourceCount('iron')
		local ownsAny = playerOwns('headhunter') or playerOwns('wood_crossbow') or playerOwns('wood_bow')
		if ownsAny then return end

		if em >= 24 then
			buyItem({
				lockAfterPurchase = true, itemType = "headhunter", price = 24,
				currency = "emerald", amount = 1,
				disabledInQueue = {"tnt_wars","bedwars_og_to4"}, category = "Combat",
				spawnWithItems = {"headhunter"},
				ignoredByKit = {"archer","flower_bee","falconer","nazar"}
			}, shopId)
		elseif em >= 7 then
			buyItem({
				disabledInQueue = {"tnt_wars","bedwars_og_to4"},
				itemType = "wood_crossbow", price = 7,
				superiorItems = {"headhunter"}, currency = "emerald",
				category = "Combat", lockAfterPurchase = true,
				ignoredByKit = {"archer","flower_bee","falconer","nazar"},
				spawnWithItems = {"wood_crossbow"}, amount = 1
			}, shopId)
		elseif ir >= 24 then
			buyItem({
				ignoredByKit = {"flower_bee","falconer","nazar"},
				itemType = "wood_bow", price = 24,
				superiorItems = {"wood_crossbow","tactical_crossbow"},
				currency = "iron", category = "Combat", lockAfterPurchase = true,
				spawnWithItems = {"wood_bow"}, amount = 1
			}, shopId)
		end
	end

	local function getNearestShopId()
		if not entitylib.isAlive then return nil end
		local localPosition = entitylib.character.RootPart.Position
		local id
		for _, v in store.shop do
			if v.Shop and v.RootPart and (v.RootPart.Position - localPosition).Magnitude <= 20 then
				id = v.Id
			end
		end
		return id
	end

	local function buyPotion(itemType)
		local shopId = getNearestShopId()
		if not shopId then return end
		local ok, item = pcall(function()
			return bedwars.Shop.getShopItem(itemType, lplr, {shopId = shopId})
		end)
		if not ok or not item then return end
		if getResourceCount(item.currency or 'iron') < (item.price or math.huge) then return end
		buyItem(item, shopId)
	end

	local upgradeIds = {
		BreakSpeed = 'BREAK_SPEED',
		Armor      = 'ARMOR',
		Damage     = 'DAMAGE',
		DiamondGen = 'DIAMOND_GENERATOR',
		TeamGen    = 'TEAM_GENERATOR',
	}

	local upgradeRemote = replicatedStorage:WaitForChild("rbxts_include"):WaitForChild("node_modules"):WaitForChild("@rbxts"):WaitForChild("net"):WaitForChild("out"):WaitForChild("_NetManaged"):WaitForChild("RequestPurchaseTeamUpgrade")

	local function buyTeamUpgrade(upgradeType)
		if not upgradeType then return end
		pcall(function()
			upgradeRemote:InvokeServer(upgradeType)
		end)
	end

	local lastBedBarrierBuy = 0
	local BED_BARRIER_DURATION = 180

	local bedUpgradeRemote = replicatedStorage:WaitForChild("rbxts_include"):WaitForChild("node_modules"):WaitForChild("@rbxts"):WaitForChild("net"):WaitForChild("out"):WaitForChild("_NetManaged"):WaitForChild("RequestPurchaseBedTeamUpgrade")

	local function buyBedBarrier()
		local now = tick()
		if now - lastBedBarrierBuy < BED_BARRIER_DURATION then return end
		local ok = pcall(function()
			bedUpgradeRemote:InvokeServer("bed_shield")
			bedUpgradeRemote:InvokeServer("bed_alarm")
		end)
		if ok then
			lastBedBarrierBuy = now
		end
	end

	AutoBuy = vape.Categories.Utility:CreateModule({
		Name = 'AutoBuy',
		Function = function(callback)
			if callback then
				task.spawn(function()
					repeat task.wait() until store.shopLoaded or not AutoBuy.Enabled
					if not AutoBuy.Enabled then return end
					repeat
						task.wait(0.5)
						if not entitylib.isAlive then continue end
						if WrenShop.Enabled then
							if BuySerpentToggle.Enabled then buyPotion('serpents_touch_potion') end
							if BuyJumpToggle.Enabled then buyPotion('jump_potion') end
							if BuyShieldToggle.Enabled then buyPotion('mini_shield') end
						end
						if ItemShop.Enabled and isNearShop('item') then
							local sid = "1_item_shop"
							if BuyArmorToggle.Enabled then buyBestTier(armorTiers, sid) end
							if BuyAxeToggle.Enabled then buyBestTier(axeTiers, sid) end
							if BuyPickaxeToggle.Enabled then buyBestTier(pickaxeTiers, sid) end
							if BuyProjectileToggle.Enabled then buyProjectile(sid) end
						end
						if TeamUpgrade.Enabled and isNearShop('upgrade') then
							if BreakSpeedToggle.Enabled   then buyTeamUpgrade(upgradeIds.BreakSpeed) end
							if ArmorUpgradeToggle.Enabled then buyTeamUpgrade(upgradeIds.Armor) end
							if DamageToggle.Enabled        then buyTeamUpgrade(upgradeIds.Damage) end
							if DiamondGenToggle.Enabled    then buyTeamUpgrade(upgradeIds.DiamondGen) end
							if TeamGenToggle.Enabled       then buyTeamUpgrade(upgradeIds.TeamGen) end
							if BedBarrierToggle.Enabled then buyBedBarrier() end
						end
					until not AutoBuy.Enabled
				end)
			end
		end,
		Tooltip = 'auto buys from the shops u turn on when ur near them'
	})

	ItemShop = AutoBuy:CreateToggle({
		Name = 'Item Shop',
		Default = true,
		Tooltip = 'buys gear from the item shop when ur near it',
		Function = function(v)
			if BuyArmorToggle     then BuyArmorToggle.Object.Visible     = v end
			if BuyAxeToggle       then BuyAxeToggle.Object.Visible       = v end
			if BuyPickaxeToggle   then BuyPickaxeToggle.Object.Visible   = v end
			if BuyProjectileToggle then BuyProjectileToggle.Object.Visible = v end
		end
	})

	TeamUpgrade = AutoBuy:CreateToggle({
		Name = 'Team Upgrade',
		Default = false,
		Tooltip = 'buys team upgrades when ur near the upgrade shop',
		Function = function(v)
			if BreakSpeedToggle   then BreakSpeedToggle.Object.Visible   = v end
			if ArmorUpgradeToggle then ArmorUpgradeToggle.Object.Visible = v end
			if DamageToggle       then DamageToggle.Object.Visible       = v end
			if DiamondGenToggle   then DiamondGenToggle.Object.Visible   = v end
			if TeamGenToggle      then TeamGenToggle.Object.Visible      = v end
			if BedBarrierToggle   then BedBarrierToggle.Object.Visible   = v end
		end
	})

	WrenShop = AutoBuy:CreateToggle({
		Name = 'Wren Shop',
		Default = false,
		Tooltip = 'buys potions from the wren shop gng',
		Function = function(v)
			if BuySerpentToggle then BuySerpentToggle.Object.Visible = v end
			if BuyJumpToggle    then BuyJumpToggle.Object.Visible    = v end
			if BuyShieldToggle  then BuyShieldToggle.Object.Visible  = v end
		end
	})

	GUICheck = AutoBuy:CreateToggle({
		Name = 'GUI Check',
		Default = true,
		Tooltip = 'only buys when ur near the shop'
	})

	BuyArmorToggle     = AutoBuy:CreateToggle({Name = 'Buy Armor',      Default = true, Darker = true})
	BuyAxeToggle       = AutoBuy:CreateToggle({Name = 'Buy Axe',        Default = false, Darker = true})
	BuyPickaxeToggle   = AutoBuy:CreateToggle({Name = 'Buy Pickaxe',    Default = false, Darker = true})
	BuyProjectileToggle = AutoBuy:CreateToggle({Name = 'Buy Projectile', Default = false, Darker = true})
	BuySerpentToggle   = AutoBuy:CreateToggle({Name = 'Buy Serpent Potion',     Default = false, Darker = true})
	BuyJumpToggle      = AutoBuy:CreateToggle({Name = 'Buy Jump Potion',        Default = false, Darker = true})
	BuyShieldToggle    = AutoBuy:CreateToggle({Name = 'Buy Shield Potion',      Default = false, Darker = true})
	BreakSpeedToggle   = AutoBuy:CreateToggle({Name = 'Break Speed',  Default = false, Darker = true})
	ArmorUpgradeToggle = AutoBuy:CreateToggle({Name = 'Armor',        Default = false, Darker = true})
	DamageToggle       = AutoBuy:CreateToggle({Name = 'Damage',       Default = false, Darker = true})
	DiamondGenToggle   = AutoBuy:CreateToggle({Name = 'Diamond Gen',  Default = false, Darker = true})
	TeamGenToggle      = AutoBuy:CreateToggle({Name = 'Team Gen',     Default = false, Darker = true})
	BedBarrierToggle   = AutoBuy:CreateToggle({Name = 'Bed Barrier',  Default = false, Darker = true})

	task.defer(function()
		if BuySerpentToggle   and BuySerpentToggle.Object   then BuySerpentToggle.Object.Visible   = WrenShop.Enabled end
		if BuyJumpToggle      and BuyJumpToggle.Object      then BuyJumpToggle.Object.Visible      = WrenShop.Enabled end
		if BuyShieldToggle    and BuyShieldToggle.Object    then BuyShieldToggle.Object.Visible    = WrenShop.Enabled end
		if BreakSpeedToggle   and BreakSpeedToggle.Object   then BreakSpeedToggle.Object.Visible   = TeamUpgrade.Enabled end
		if ArmorUpgradeToggle and ArmorUpgradeToggle.Object then ArmorUpgradeToggle.Object.Visible = TeamUpgrade.Enabled end
		if DamageToggle       and DamageToggle.Object       then DamageToggle.Object.Visible       = TeamUpgrade.Enabled end
		if DiamondGenToggle   and DiamondGenToggle.Object   then DiamondGenToggle.Object.Visible   = TeamUpgrade.Enabled end
		if TeamGenToggle      and TeamGenToggle.Object      then TeamGenToggle.Object.Visible      = TeamUpgrade.Enabled end
		if BedBarrierToggle   and BedBarrierToggle.Object   then BedBarrierToggle.Object.Visible   = TeamUpgrade.Enabled end
	end)
end)

run(function()
    local ViewMatchHistory

    ViewMatchHistory = vape.Categories.Utility:CreateModule({
        Name = "ViewMatchHistory",
