	task.defer(function()
		if CustomHealth and CustomHealth.Object and Effect then
			CustomHealth.Object.Visible = Effect.Enabled
		end
		if BedCheck and BedCheck.Object and Bed then
			BedCheck.Object.Visible = Bed.Enabled
