run(function()
    local Fisherman
    local AutoMinigameToggle
    local CompleteDelaySlider
    local PullAnimationToggle
    local MinigameAnimationToggle
    local BlacklistOption
    local Blacklist
    local ESPToggle
	local AutoCastDelay
	local AutoCast
    local ESPNotifyToggle
    local Players = playersService
	local RunService = runService
	local lplr = Players.LocalPlayer
	local RandomizeToggle
    local RandomRange
	local waitTime
    local fishNames = {
		fish_iron = "Iron Fish",
		fish_diamond = "Diamond Fish",
		fish_gold = "Gold Fish",
		fish_special = "Special Fish",
		fish_emerald = "Emerald Fish",
	}

    local function buildMessage(fishModel, drops)
        local fishName = fishNames[fishModel] or fishModel

        if fishModel == "fish_special" then
            if drops and drops[1] then
                return "You caught a " .. fishName .. "! You will receive a " .. tostring(drops[1].itemType)
            else
                return "You caught a " .. fishName .. "! (special item incoming)"
            end
        end

        if drops and drops[1] then
            local drop = drops[1]
            return "You caught a " .. fishName .. "! Receiving " ..
                   tostring(drop.amount) .. "x " .. tostring(drop.itemType)
        end

        return "You caught a " .. fishName .. "!"
    end

    local notifQueue = {}
	local function safeNotif(title, msg, dur)
		table.insert(notifQueue, {title=title, message=msg, duration=dur or 5})
	end
	local heartbeatConn = nil

    local autoMinigameActive    = false
    local pullAnimationTrack    = nil
    local successAnimationTrack = nil
    local espOld                = nil

	local function getBait()
		for _, v in workspace:GetChildren() do
			if v.Name == "fisherman_bobber" and v:GetAttribute("ProjectileShooter") == lplr.UserId then
				return v
			end
		end

		return
	end

    local function stopAllAnimations()
        if pullAnimationTrack then
            pcall(function() pullAnimationTrack:Stop() end)
            pullAnimationTrack = nil
        end
        if successAnimationTrack then
            pcall(function() successAnimationTrack:Stop() end)
            successAnimationTrack = nil
        end
    end

    local function setupESP()
        if not bedwars or not bedwars.FishingMinigameController then
            warn("[AutoFisher] FishingMinigameController not found")
            return
        end
        if espOld then return end 
        espOld = bedwars.FishingMinigameController.startMinigame

        bedwars.FishingMinigameController.startMinigame = function(self, dropData, result)
            if ESPToggle.Enabled and ESPNotifyToggle.Enabled and dropData and dropData.fishModel then
                safeNotif("Fisherman ESP", buildMessage(dropData.fishModel, dropData.drops), 8)
            end
            return espOld(self, dropData, result)
        end

        Fisherman:Clean(function()
            if espOld then
                bedwars.FishingMinigameController.startMinigame = espOld
                espold = nil
                nsHooked = false
            end
        end)
    end

    local function cleanupESP()
        if espOld then
            bedwars.FishingMinigameController.startMinigame = espOld
            espOld = nil
        end
    end

    local function setupAutoMinigame()
        if not bedwars or not bedwars.FishingMinigameController then
            warn("[AutoFisher] FishingMinigameController not found")
            return
        end

        local old = bedwars.FishingMinigameController.startMinigame

        bedwars.FishingMinigameController.startMinigame = function(self, dropData, result)
            if not AutoMinigameToggle.Enabled then
                return old(self, dropData, result)
            end

            if BlacklistOption.Enabled and dropData and dropData.fishModel then
                if table.find(Blacklist.ListEnabled, dropData.fishModel) then
                    local hum = lplr.Character and lplr.Character:FindFirstChildOfClass("Humanoid")
                    if hum and hum:GetState() ~= Enum.HumanoidStateType.Jumping then
                        hum:ChangeState(Enum.HumanoidStateType.Jumping)
                    end
                    return old(self, dropData, result)
                end
            end

            autoMinigameActive = true
            stopAllAnimations()

            local waitTime = 0
            if RandomizeToggle and RandomizeToggle.Enabled then
                local min = RandomRange.ValueMin
                local max = RandomRange.ValueMax
                waitTime = min + (max - min) * math.random()
            else
                waitTime = CompleteDelaySlider.Value
            end

            task.spawn(function()
                if PullAnimationToggle.Enabled and waitTime > 0 then
                    local ok, track = pcall(function()
                        return bedwars.GameAnimationUtil:playAnimation(
                            lplr, bedwars.AnimationType.FISHING_ROD_PULLING
                        )
                    end)
                    if ok and track then pullAnimationTrack = track end
                end

                if waitTime > 0 then
                    task.wait(waitTime)
                end

                if pullAnimationTrack then
                    pcall(function() pullAnimationTrack:Stop() end)
                    pullAnimationTrack = nil
                end

                if MinigameAnimationToggle.Enabled then
                    local ok, track = pcall(function()
                        return bedwars.GameAnimationUtil:playAnimation(
                            lplr, bedwars.AnimationType.FISHING_ROD_CATCH_SUCCESS
                        )
                    end)
                    if ok and track then successAnimationTrack = track end
                end

                if result then
                    pcall(function() result({ win = true }) end)
                end

                task.wait(0.5)

                if successAnimationTrack then
                    pcall(function() successAnimationTrack:Stop() end)
                    successAnimationTrack = nil
                end

                autoMinigameActive = false
            end)
        end

        Fisherman:Clean(function()
            bedwars.FishingMinigameController.startMinigame = old
            stopAllAnimations()
        end)
    end

	local function setupAutoCast()
		task.spawn(function()
			repeat
				if entitylib.isAlive and AutoCast.Enabled and (store.hand.tool and store.hand.tool.Name == 'fishing_rod') then
					local position = workspace.CurrentCamera.ViewportSize / 2
					local ray = cloneref(lplr:GetMouse()).UnitRay

					if not getBait() and not workspace:Raycast(entitylib.character.Head.Position + (ray.Direction * 6), Vector3.new(0, -20, 0)) then
						task.wait(AutoCastDelay:GetRandomValue())

						for _, v in {true, false} do
							VirtualInputManager:SendMouseButtonEvent(position.X, position.Y, 0, v, game, 1)
							task.wait()
						end
						task.wait(0.5)
					end
				end
				task.wait(0.1)
			until not Fisherman.Enabled
		end)
	end

    Fisherman = vape.Categories.Kits:CreateModule({
		Name = "AutoFisher",
		Function = function(callback)
            if callback then
                if ESPToggle.Enabled then setupESP() end
                if AutoMinigameToggle.Enabled then setupAutoMinigame() end
                setupAutoCast()

                heartbeatConn = RunService.Heartbeat:Connect(function()
                    if #notifQueue == 0 then return end
                    local entry = table.remove(notifQueue, 1)
                    pcall(notif, entry.title, entry.message, entry.duration)
                end)
                Fisherman:Clean(heartbeatConn)

            else
                autoMinigameActive = false
                stopAllAnimations()
                cleanupESP()
                notifQueue = {} 
            end
        end
    })

    AutoMinigameToggle = Fisherman:CreateToggle({
		Name = "Auto Minigame",
		Default = false,
		Function = function(cv)
			if CompleteDelaySlider and CompleteDelaySlider.Object then
				CompleteDelaySlider.Object.Visible = cv and not (RandomizeToggle and RandomizeToggle.Enabled)
			end
			if PullAnimationToggle and PullAnimationToggle.Object then PullAnimationToggle.Object.Visible = cv end
			if MinigameAnimationToggle and MinigameAnimationToggle.Object then MinigameAnimationToggle.Object.Visible = cv end
			if RandomizeToggle and RandomizeToggle.Object then RandomizeToggle.Object.Visible = cv end
			if RandomRange and RandomRange.Object then RandomRange.Object.Visible = cv and RandomizeToggle.Enabled end
			if Fisherman.Enabled and cv then setupAutoMinigame() end
		end
	})

	CompleteDelaySlider = Fisherman:CreateSlider({
		Name = "Complete Delay",
		Min = 0,
		Max = 5,
		Default = 1,
		Decimal = 10,
		Suffix = "s",
		Visible = false,
	})

	RandomizeToggle = Fisherman:CreateToggle({
		Name = "Randomize Timing",
		Default = false,
		Function = function(cv)
			if RandomRange and RandomRange.Object then RandomRange.Object.Visible = cv end
			if CompleteDelaySlider and CompleteDelaySlider.Object then CompleteDelaySlider.Object.Visible = not cv end
		end
	})

	RandomRange = Fisherman:CreateTwoSlider({
		Name = "Random Delay Range",
		Min = 0.1,
		Max = 5,
		DefaultMin = 0.5,
		DefaultMax = 2,
		Decimal = 10,
		Visible = false,
	})

	PullAnimationToggle = Fisherman:CreateToggle({
		Name = "Pull Animation",
		Default = true,
		Visible = false,
	})

	MinigameAnimationToggle = Fisherman:CreateToggle({
		Name = "Success Animation",
		Default = true,
		Visible = false,
	})

	BlacklistOption = Fisherman:CreateToggle({
		Name = "Blacklist",
		Default = false,
		Function = function(cv)
			if Blacklist and Blacklist.Object then Blacklist.Object.Visible = cv end
		end
	})

	Blacklist = Fisherman:CreateTextList({
		Name = "Blacklist Fish",
		Default = {"fish_iron"}
	})

	AutoCast = Fisherman:CreateToggle({
		Name 	= "AutoCast",
		Default = false,
		Function = function(callback)
			if callback then
				if AutoCastDelay and AutoCastDelay.Object then AutoCastDelay.Object.Visible = callback end
				if AutoCast.Enabled and callback then setupAutoCast() end
			end
		end
	})

	AutoCastDelay = Fisherman:CreateTwoSlider({
		Name 	= "Cast Delay",
		Min 	= 0,
		Max 	= 5,
		Decimal = 5,
		DefaultMin = 0.3,
		DefaultMax = 1.2,
		Darker 	= true,
		Visible = AutoCast.Enabled
	})	

    ESPToggle = Fisherman:CreateToggle({
		Name = "Fisherman ESP",
		Default = false,
		Function = function(cv)
			if ESPNotifyToggle and ESPNotifyToggle.Object then ESPNotifyToggle.Object.Visible = cv end
			if Fisherman.Enabled then
				if cv then setupESP() else cleanupESP() end
			end
		end
	})

	ESPNotifyToggle = Fisherman:CreateToggle({
		Name = "Notify Loot",
		Default = true,
		Visible = false,
	})
end)

run(function()
	local CannonHandController = bedwars.CannonHandController
	local CannonController = bedwars.CannonController
	local oldLaunchSelf = CannonHandController.launchSelf
	local oldStopAiming = CannonController.stopAiming
	local oldStartAiming = CannonController.startAiming
	local AutoDavey
	local AutoDaveyAutojump
	local AutoDaveyAutoLaunch
	local AutoDaveyAutoBreak
	local AutoDaveyPickaxeCheck
	local AutoDaveyAutoSwitch
	local LaunchDelay
	local BreakDelay
	local isLaunching = false
	local didAutoLaunch = false

	local function getCannonSlot()
		for i, v in pairs(store.inventory.hotbar) do
			if v.item then
				local t = tostring(v.item.itemType):lower()
				if t:find("cannon") then
					return i - 1
				end
			end
		end
		return nil
	end

	local function hasWoodPickaxeOnly()
		local bestTier = 0
		for _, slot in pairs(store.inventory.hotbar) do
			if slot.item then
				local t = tostring(slot.item.itemType):lower()
				if t == "wood_pickaxe" and bestTier < 1 then
					bestTier = 1
				elseif (t:find("pickaxe") or t:find("drill")) and t ~= "wood_pickaxe" then
					bestTier = 2
				end
			end
		end
		return bestTier == 1
	end

	local function getNearestCannon()
		if not entitylib.isAlive then return nil end
		local nearest
		local nearestDist = math.huge
		for i, v in pairs(CannonController.getCannons()) do
			pcall(function()
				local dist = (v.Position - entitylib.character.RootPart.Position).Magnitude
				if dist < nearestDist and dist < 30 then
					nearestDist = dist
					nearest = v
				end
			end)
		end
		return nearest
	end

	local function findCannonModel(pos)
		local closest = nil
		local closestDist = 8
		for _, obj in store.blocks do
			if obj and obj:IsA("BasePart") and obj.Name == "cannon" then
				local dist = (obj.Position - pos).Magnitude
				if dist < closestDist then
					closestDist = dist
					closest = obj
				end
			end
		end
		return closest
	end

	local function doBreakCannon(cannon)
		if not entitylib.isAlive then return end
		if not cannon or not cannon.Parent then return end
		local block, blockpos = getPlacedBlock(cannon.Position)
		if block and block.Name == 'cannon' and
		   (entitylib.character.RootPart.Position - block.Position).Magnitude < 30 then
			pcall(bedwars.breakBlock, block, false, nil, true)
		else
			local directBlock = findCannonModel(cannon.Position)
			if directBlock and directBlock.Parent then
				pcall(bedwars.breakBlock, directBlock, false, nil, true)
			end
		end
	end

	local function firstHitCannon(cannon)
		if not entitylib.isAlive then return end
		if not cannon or not cannon.Parent then return end
		if hasWoodPickaxeOnly() then
			doBreakCannon(cannon)
		end
	end

	local function breakCannon(cannon, shootfunc)
		if not entitylib.isAlive then
			isLaunching = false
			return shootfunc()
		end

		local cannonSlot = nil

		if AutoDaveyAutoSwitch.Enabled and not isHoldingPickaxe() then
			local pickaxeSlot = getPickaxeSlot()
			if not pickaxeSlot then
				notif("AutoDavey", "No pickaxe found in hotbar!", 3)
				if AutoDaveyAutojump.Enabled and entitylib.isAlive and entitylib.character.Humanoid then
					entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
				end
				isLaunching = false
				return shootfunc()
			end
			cannonSlot = getCannonSlot()
			if hotbarSwitch(pickaxeSlot) then
				task.wait(0.05)
			end
		end

		if AutoDaveyPickaxeCheck.Enabled and not isHoldingPickaxe() then
			notif("AutoDavey", "You need to HOLD a pickaxe to break cannons!", 3)
			if AutoDaveyAutojump.Enabled and entitylib.isAlive and entitylib.character.Humanoid then
				entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
			end
			isLaunching = false
			return shootfunc()
		end

		if BreakDelay.Value > 0 then
			task.wait(BreakDelay.Value)
		end

		local cannonRef = cannon
		if AutoDaveyAutojump.Enabled and entitylib.isAlive and entitylib.character.Humanoid then
			entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
		end
		shootfunc()
		isLaunching = false

		task.spawn(function()
			task.wait(0.05)
			doBreakCannon(cannonRef)
			task.wait(0.35)
			if cannonRef and cannonRef.Parent then
				doBreakCannon(cannonRef)
			end
			if AutoDaveyAutoSwitch.Enabled and cannonSlot then
				task.wait(0.05)
				hotbarSwitch(cannonSlot)
			end
		end)
	end

	AutoDavey = vape.Categories.Kits:CreateModule({
		Name = 'AutoDavey',
		Function = function(callback)
			if callback then
				CannonHandController.launchSelf = function(...)
					if isLaunching then
						isLaunching = false
						return oldLaunchSelf(...)
					end
					isLaunching = true
					if LaunchDelay.Value > 0 then
						task.wait(LaunchDelay.Value)
					end
					if AutoDaveyAutoBreak.Enabled then
						local cannon = getNearestCannon()
						if cannon then
							local args = {...}
							breakCannon(cannon, function()
								oldLaunchSelf(unpack(args))
							end)
							return
						else
							if AutoDaveyAutojump.Enabled and entitylib.isAlive and entitylib.character.Humanoid then
								entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
							end
							local res = oldLaunchSelf(...)
							isLaunching = false
							return res
						end
					else
						if AutoDaveyAutojump.Enabled and entitylib.isAlive and entitylib.character.Humanoid then
							entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
						end
						local res = oldLaunchSelf(...)
						isLaunching = false
						return res
					end
				end

				local aimedCannon = nil
				CannonController.startAiming = function(...)
					didAutoLaunch = false
					isLaunching = false
					local result = oldStartAiming(...)
					aimedCannon = getNearestCannon()
					return result
				end

				CannonController.stopAiming = function(...)
					local cannon = aimedCannon or getNearestCannon()
					local result = oldStopAiming(...)
					aimedCannon = nil
					isLaunching = false
					if AutoDaveyAutoLaunch.Enabled and not didAutoLaunch then
						didAutoLaunch = true
						if AutoDaveyAutoBreak.Enabled and AutoDaveyPickaxeCheck.Enabled and not isHoldingPickaxe() and not AutoDaveyAutoSwitch.Enabled then
							notif("AutoDavey", "Hold a pickaxe to auto-break!", 3)
							return result
						end
						if cannon then
							task.spawn(function()
								pcall(CannonHandController.launchSelf, CannonHandController, cannon)
							end)
						end
					end
					return result
				end

				local firstHitDebounce = {}
				AutoDavey:Clean(workspace.DescendantAdded:Connect(function(obj)
					if not (obj:IsA("BasePart") and obj.Name == "cannon") then return end
					if firstHitDebounce[obj] then return end
					firstHitDebounce[obj] = true
					task.spawn(function()
						task.wait(0.5)
						if AutoDaveyAutoBreak.Enabled and hasWoodPickaxeOnly() then
							local dist = entitylib.isAlive
								and (entitylib.character.RootPart.Position - obj.Position).Magnitude
								or math.huge
							if dist < 20 and obj.Parent then
								firstHitCannon(obj)
							end
						end
						firstHitDebounce[obj] = nil
					end)
				end))
			else
				CannonHandController.launchSelf = oldLaunchSelf
				CannonController.stopAiming = oldStopAiming
				CannonController.startAiming = oldStartAiming
				isLaunching = false
				didAutoLaunch = false
			end
		end,
	})

	LaunchDelay = AutoDavey:CreateSlider({
		Name = 'Launch Delay',
		Min = 0,
		Max = 2,
		Default = 0,
		Decimal = 10,
		Suffix = 's',
	})
	BreakDelay = AutoDavey:CreateSlider({
		Name = 'Break Delay',
		Min = 0,
		Max = 2,
		Default = 0,
		Decimal = 10,
		Suffix = 's',
	})

	AutoDaveyAutojump = AutoDavey:CreateToggle({
		Name = 'Auto Jump',
		Default = true,
	})
	AutoDaveyAutoLaunch = AutoDavey:CreateToggle({
		Name = 'Auto Launch',
		Default = true,
		Tooltip = 'automatically lauches u after your done aiming'
	})
	AutoDaveyAutoBreak = AutoDavey:CreateToggle({
		Name = 'Auto Break',
		Default = true,
		Tooltip = 'auto breaks cannon when you lauch'
	})
	AutoDaveyPickaxeCheck = AutoDavey:CreateToggle({
		Name = 'Pickaxe Check',
		Default = true,
	})
	AutoDaveyAutoSwitch = AutoDavey:CreateToggle({
		Name = 'AutoSwitch Pickaxe',
		Default = false,
		Tooltip = 'switches to pickaxe when breaking thens switches back to cannon'
	})
end)

run(function()
	local AutoGompy
	local AutoCollect
	local CollectRange
	local CollectDelay
	local CollectLimit
	local GhostESP
	local ESPBackground
	local ESPColor
	local ESPLimitVacuum
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui
	local Reference = {}
	local ghostIcon
	local collectionActive = false

	local collectRemote = replicatedStorage:WaitForChild("rbxts_include"):WaitForChild("node_modules"):WaitForChild("@rbxts"):WaitForChild("net"):WaitForChild("out"):WaitForChild("_NetManaged"):WaitForChild("CollectCollectableEntity")

	local function isHoldingVacuum()
		return isHoldingItem({'vacuum'})
	end

	local function getGhostIcon()
		if not ghostIcon then
			ghostIcon = bedwars.getIcon({itemType = 'ghost_orb'}, true)
		end
		return ghostIcon
	end

	local function Added(obj)
		if Reference[obj] then return end
		local part = not obj:IsA('Model') and obj or obj.PrimaryPart
		if not part then return end
		local billboard = Instance.new('BillboardGui')
		billboard.Parent = Folder
		billboard.Name = 'ghost'
		billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
		billboard.Size = UDim2.fromOffset(36, 36)
		billboard.AlwaysOnTop = true
		billboard.ClipsDescendants = false
		billboard.Adornee = part
		local blur = addBlur(billboard)
		blur.Visible = ESPBackground.Enabled
		local image = Instance.new('ImageLabel')
		image.Size = UDim2.fromOffset(36, 36)
		image.Position = UDim2.fromScale(0.5, 0.5)
		image.AnchorPoint = Vector2.new(0.5, 0.5)
		image.BackgroundColor3 = Color3.fromHSV(ESPColor.Hue, ESPColor.Sat, ESPColor.Value)
		image.BackgroundTransparency = 1 - (ESPBackground.Enabled and ESPColor.Opacity or 0)
		image.BorderSizePixel = 0
		image.Image = getGhostIcon()
		image.Parent = billboard
		local uicorner = Instance.new('UICorner')
		uicorner.CornerRadius = UDim.new(0, 4)
		uicorner.Parent = image
		Reference[obj] = billboard
	end

	local function Removed(obj)
		if Reference[obj] then
			Reference[obj]:Destroy()
			Reference[obj] = nil
		end
	end

	local function setupESP()
		for _, v in collectionService:GetTagged('ghost') do
			Added(v)
		end
		AutoGompy:Clean(collectionService:GetInstanceAddedSignal('ghost'):Connect(function(v)
			if GhostESP.Enabled then Added(v) end
		end))
		AutoGompy:Clean(collectionService:GetInstanceRemovedSignal('ghost'):Connect(function(v)
			Removed(v)
		end))
		local lastUpdate = 0
		AutoGompy:Clean(runService.RenderStepped:Connect(function()
			if not GhostESP.Enabled then return end
			local now = tick()
			if now - lastUpdate < 0.1 then return end
			lastUpdate = now
			for obj, billboard in pairs(Reference) do
				if not obj or not obj.Parent then
					Removed(obj)
					continue
				end
				local shouldShow = true
				if ESPLimitVacuum.Enabled and not isHoldingVacuum() then
					shouldShow = false
				end
				billboard.Enabled = shouldShow
			end
		end))
	end

	local function startAutoCollect()
		if collectionActive then return end
		collectionActive = true
		task.spawn(function()
			while AutoGompy.Enabled and AutoCollect.Enabled and collectionActive do
				if not entitylib.isAlive then
					task.wait(0.5)
					continue
				end
				if CollectLimit.Enabled and not isHoldingVacuum() then
					task.wait(0.5)
					continue
				end
				local localPosition = entitylib.character.RootPart.Position
				local range = CollectRange.Value
				for _, obj in collectionService:GetTagged('ghost') do
					if not AutoGompy.Enabled or not AutoCollect.Enabled or not collectionActive then break end
					local part = not obj:IsA('Model') and obj or obj.PrimaryPart
					if part and (localPosition - part.Position).Magnitude <= range then
						local id = obj:GetAttribute('Id') or obj:GetAttribute('id')
							or obj:GetAttribute('CollectableId') or tonumber(obj.Name:match('%d+'))
						if id then
							pcall(function() collectRemote:FireServer({ id = id }) end)
							if CollectDelay.Value > 0 then
								task.wait(CollectDelay.Value)
							end
						end
					end
				end
				task.wait(0.1)
			end
			collectionActive = false
		end)
	end

	local function stopAutoCollect()
		collectionActive = false
	end

	AutoGompy = vape.Categories.Kits:CreateModule({
		Name = 'AutoGompy',
		Function = function(callback)
			if callback then
				if GhostESP.Enabled then setupESP() end
				if AutoCollect.Enabled then startAutoCollect() end
			else
				stopAutoCollect()
				Folder:ClearAllChildren()
				table.clear(Reference)
			end
		end,
		Tooltip = 'ghost stuff for gompy fr'
	})

	AutoCollect = AutoGompy:CreateToggle({
		Name = 'Auto Collect',
		Tooltip = 'grabs the ghosts for u no cap',
		Function = function(callback)
			if CollectRange and CollectRange.Object then CollectRange.Object.Visible = callback end
			if CollectDelay and CollectDelay.Object then CollectDelay.Object.Visible = callback end
			if CollectLimit and CollectLimit.Object then CollectLimit.Object.Visible = callback end
			if AutoGompy.Enabled then
				if callback then startAutoCollect() else stopAutoCollect() end
			end
		end
	})
	CollectRange = AutoGompy:CreateSlider({
		Name = 'Range',
		Tooltip = 'how far it grabs ghosts gng',
		Min = 10,
		Max = 200,
		Default = 50,
		Visible = false
	})
	CollectDelay = AutoGompy:CreateSlider({
		Name = 'Delay',
		Tooltip = 'wait time between grabs',
		Min = 0,
		Max = 1,
		Default = 0.1,
		Decimal = 100,
		Suffix = 's',
		Visible = false
	})
	CollectLimit = AutoGompy:CreateToggle({
		Name = 'Limit to Vacuum',
		Tooltip = 'only grabs ghosts when ur holding the vacuum'
	})

	GhostESP = AutoGompy:CreateToggle({
		Name = 'Ghost ESP',
		Tooltip = 'shows u where the ghosts at',
		Function = function(callback)
			if ESPBackground and ESPBackground.Object then ESPBackground.Object.Visible = callback end
			if ESPColor and ESPColor.Object then ESPColor.Object.Visible = (callback and ESPBackground and ESPBackground.Enabled) end
			if ESPLimitVacuum and ESPLimitVacuum.Object then ESPLimitVacuum.Object.Visible = callback end
			if AutoGompy.Enabled then
				if callback then
					setupESP()
				else
					Folder:ClearAllChildren()
					table.clear(Reference)
				end
			end
		end
	})
	ESPBackground = AutoGompy:CreateToggle({
		Name = 'Background',
		Tooltip = 'adds a lil box behind the icon',
		Default = true,
		Function = function(callback)
			if ESPColor and ESPColor.Object then ESPColor.Object.Visible = (callback and GhostESP and GhostESP.Enabled) end
			for _, v in Reference do
				if v and v:FindFirstChild('ImageLabel') then
					local blur = v:FindFirstChild('Blur')
					if blur then blur.Visible = callback end
					v.ImageLabel.BackgroundTransparency = 1 - (callback and ESPColor.Opacity or 0)
				end
			end
		end
	})
	ESPColor = AutoGompy:CreateColorSlider({
		Name = 'Background Color',
		DefaultValue = 0,
		DefaultOpacity = 0.5,
		Darker = true,
		Function = function(hue, sat, val, opacity)
			for _, v in Reference do
				if v and v:FindFirstChild('ImageLabel') then
					v.ImageLabel.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
					v.ImageLabel.BackgroundTransparency = 1 - opacity
				end
			end
		end
	})
	ESPLimitVacuum = AutoGompy:CreateToggle({
		Name = 'ESP Limit to Vacuum',
		Tooltip = 'only shows ghosts when ur holding the vacuum'
	})

	task.defer(function()
		local collectOn = AutoCollect and AutoCollect.Enabled
		if CollectRange and CollectRange.Object then CollectRange.Object.Visible = collectOn end
		if CollectDelay and CollectDelay.Object then CollectDelay.Object.Visible = collectOn end
		if CollectLimit and CollectLimit.Object then CollectLimit.Object.Visible = collectOn end
		local espOn = GhostESP and GhostESP.Enabled
		if ESPBackground and ESPBackground.Object then ESPBackground.Object.Visible = espOn end
		if ESPColor and ESPColor.Object then ESPColor.Object.Visible = (espOn and ESPBackground.Enabled) end
		if ESPLimitVacuum and ESPLimitVacuum.Object then ESPLimitVacuum.Object.Visible = espOn end
	end)
end)

run(function()
	local AutoSilas
	local Damage
	local Targets
	local DamageRange
	local Heal
	local HealThreshold

	local useAbilityRemote = replicatedStorage:WaitForChild("events-@easy-games/game-core:shared/game-core-networking@getEvents.Events"):WaitForChild("useAbility")

	local function getCurrentAura()
		return lplr:GetAttribute("LeaderAuraType")
	end

	local function startLoop()
		task.spawn(function()
			repeat task.wait() until Damage and Heal and DamageRange and HealThreshold and Targets
			repeat
				if not entitylib.isAlive then task.wait(0.1); continue end
				local hum = entitylib.character.Humanoid
				if Heal.Enabled and hum and hum.MaxHealth > 0 then
					local pct = (hum.Health / hum.MaxHealth) * 100
					if pct <= HealThreshold.Value then
						useAbilityRemote:FireServer("rebellion_shield")
						if getCurrentAura() ~= "healing" then
							useAbilityRemote:FireServer("rebellion_aura_swap")
						end
						task.wait(0.1)
						continue
					end
				end
				if Damage.Enabled then
					local plr = entitylib.EntityPosition({
						Range = DamageRange.Value,
						Part = "RootPart",
						Players = Targets.Players.Enabled,
						NPCs = Targets.NPCs.Enabled,
						Wallcheck = Targets.Walls.Enabled,
						Sort = sortmethods.Distance
					})
					if plr and getCurrentAura() ~= "damage" then
						useAbilityRemote:FireServer("rebellion_aura_swap")
						task.wait(0.1)
					end
				end
				task.wait(0.1)
			until not AutoSilas.Enabled
		end)
	end

	AutoSilas = vape.Categories.Kits:CreateModule({
		Name = 'AutoSilas',
		Function = function(callback)
			if callback then
				startLoop()
			end
		end,
		Tooltip = 'auto uses silas auras for u'
	})

	Damage = AutoSilas:CreateToggle({
		Name = 'Damage',
		Tooltip = 'swaps to damage aura when a enemy is close',
		Function = function(callback)
			if DamageRange and DamageRange.Object then DamageRange.Object.Visible = callback end
			if Targets and Targets.Object then Targets.Object.Visible = callback end
		end
	})
	Targets = AutoSilas:CreateTargets({
		Players = true,
		NPCs = true,
		Walls = true
	})
	DamageRange = AutoSilas:CreateSlider({
		Name = 'Range',
		Tooltip = 'how close a enemy gotta be gng',
		Min = 1,
		Max = 50,
		Default = 14,
		Visible = false
	})

	Heal = AutoSilas:CreateToggle({
		Name = 'Heal',
		Tooltip = 'shields + heal aura when ur hp gets low',
		Function = function(callback)
			if HealThreshold and HealThreshold.Object then HealThreshold.Object.Visible = callback end
		end
	})
	HealThreshold = AutoSilas:CreateSlider({
		Name = 'HP Threshold',
		Tooltip = 'heals when ur hp drops under this',
		Min = 1,
		Max = 100,
		Default = 40,
		Suffix = '%',
		Visible = false
	})

	task.defer(function()
		if Targets and Targets.Object then Targets.Object.Visible = Damage and Damage.Enabled end
		if DamageRange and DamageRange.Object then DamageRange.Object.Visible = Damage and Damage.Enabled end
		if HealThreshold and HealThreshold.Object then HealThreshold.Object.Visible = Heal and Heal.Enabled end
	end)
end)

run(function()
	local MemoryFixer
	local Sync
	local Interval
	local Notify
	local signals = {'Heartbeat', 'PostSimulation', 'PreAnimation', 'PreRender', 'PreSimulation', 'RenderStepped', 'Stepped'}
	
	local function clean()
		if not getconnections or not getfunctionhash or not isexecutorclosure then
			return 0
		end
	
		local removed, seen = 0, {}
		for _, v in signals do
			for _, connection in getconnections(runService[v]) do
				if connection.Function and not connection.ForeignState and isexecutorclosure(connection.Function) then
					local hash = v..getfunctionhash(connection.Function)
					if seen[hash] then
						connection:Disconnect()
						removed += 1
					else
						seen[hash] = true
					end
				end
			end
		end
	
		if Sync.Enabled then
			for _, event in bedwars.SyncEvents do
				if typeof(event) == 'table' and typeof(event.entries) == 'table' then
					table.clear(seen)
					for i, entry in event.entries do
						local callback = entry.callbackInfo and entry.callbackInfo.callback
						if callback and isexecutorclosure(callback) then
							local hash = getfunctionhash(callback)
							if seen[hash] then
								event.entries[i] = nil
								event.isSorted = false
								removed += 1
							else
								seen[hash] = true
							end
						end
					end
				end
			end
		end
	
		return removed
	end
	
	MemoryFixer = vape.Categories.Utility:CreateModule({
		Name = 'MemoryFixer',
		Function = function(callback)
			if callback then
				task.spawn(function()
					repeat
						local removed = clean()
						if Notify.Enabled and removed > 0 then
							notif('MemoryFixer', `Dropped {removed} leftover connection{removed == 1 and '' or 's'}`, 5)
						end
						task.wait(Interval.Value)
					until not MemoryFixer.Enabled
				end)
			end
		end,
		Tooltip = 'Drops the duplicate loops and listeners an older injection left connected'
	})
	Sync = MemoryFixer:CreateToggle({
		Name = 'Sync events',
		Default = true,
		Tooltip = 'Also prunes duplicate bedwars sync event listeners, the ones that survive a reinject'
	})
	Interval = MemoryFixer:CreateSlider({
		Name = 'Interval',
		Min = 5,
		Max = 300,
		Default = 30,
		Suffix = 'seconds'
	})
	Notify = MemoryFixer:CreateToggle({
		Name = 'Notify',
		Default = true,
		Tooltip = 'Tells you how many it dropped'
	})
	MemoryFixer:CreateButton({
		Name = 'Clean now',
		Function = function()
			local removed = clean()
			notif('MemoryFixer', `Dropped {removed} leftover connection{removed == 1 and '' or 's'}`, 5)
		end
	})
end)

run(function()
	local JadeAura
	local Targets
	local SlamRange
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local Players = game:GetService("Players")
	local LocalPlayer = Players.LocalPlayer

	-- Safely locate the Jade Hammer remote
	local function getJadeRemote()
		local success, remote = pcall(function()
			return ReplicatedStorage:FindFirstChild("events-@easy-games/game-core:shared/game-core-networking@getEvents.Events"):FindFirstChild("useAbility")
		end)
		return success and remote or nil
	end

	-- Check if target is valid based on selected Targets options
	local function isValidTarget(ent)
		if not ent or ent == entitylib.character then return false end
		if ent.Player and not Targets.Players.Enabled then return false end
		if ent.NPC and not Targets.NPCs.Enabled then return false end
		if ent.Targetable == false then return false end
		return true
	end

	-- Find the closest valid target within Slam Range
	local function getTargetInRange()
		if not entitylib.isAlive then return nil end

		local myPos = entitylib.character.RootPart.Position
		local closestEnt = nil
		local shortestDist = SlamRange.Value

		for _, ent in ipairs(entitylib.List) do
			if isValidTarget(ent) and ent.RootPart then
				local dist = (myPos - ent.RootPart.Position).Magnitude
				if dist <= shortestDist then
					shortestDist = dist
					closestEnt = ent
				end
			end
		end

		return closestEnt
	end

	-- Create module in Blatant category
	local Category = vape.Categories.Blatant

	JadeAura = Category:CreateModule({
		Name = 'JadeAura',
		Function = function(callback)
			if callback then
				local lastJump = 0
				JadeAura:Clean(runService.Heartbeat:Connect(function()
					if tick() - lastJump < 0.25 then return end
					local target = getTargetInRange()
					if target then
						local remote = getJadeRemote()
						if remote then
							lastJump = tick()
							pcall(function()
								remote:FireServer("jade_hammer_jump")
							end)
						end
					end
				end))
			end
		end,
		Tooltip = 'Automatically uses Jade Hammer ability when targets enter range.'
	})

	-- Configurable Targets & Range Sliders
	Targets = JadeAura:CreateTargets({
		Players = true,
		NPCs = false,
		Function = function() end
	})

	SlamRange = JadeAura:CreateSlider({
		Name = 'Slam Range',
		Function = function() end,
		Default = 18,
		Min = 0,
		Max = 22,
		Decimal = 10
	})
end)

run(function()
    local ElektraExtender
    local ExtensionSlider
    local InstantToggle

    local netManaged = game:GetService("ReplicatedStorage"):WaitForChild("rbxts_include"):WaitForChild("node_modules"):WaitForChild("@rbxts"):WaitForChild("net"):WaitForChild("out"):WaitForChild("_NetManaged")
    local electricDashRemote = netManaged:FindFirstChild("ElectricDash")
    local tweenTeleportRemote = netManaged:FindFirstChild("TweenTeleport")

    local oldInvoke
    local oldFireSignal

    ElektraExtender = vape.Categories.Kits:CreateModule({
        Name = 'ElektraExtender',
        Function = function(callback)
            if callback then
                -- Hook ElectricDash InvokeServer for range extension
                if electricDashRemote then
                    oldInvoke = hookmetamethod(game, "__namecall", function(self, ...)
                        local args = {...}
                        local method = getnamecallmethod()

                        if self == electricDashRemote and (method == "InvokeServer" or method == "invokeServer") and args[1] then
                            local data = args[1]
                            if data.startCFrame and data.destCFrame then
                                local direction = (data.destCFrame.Position - data.startCFrame.Position).Unit
                                local distance = (data.destCFrame.Position - data.startCFrame.Position).Magnitude + ExtensionSlider.Value
                                
                                local newDestPos = data.startCFrame.Position + (direction * distance)
                                data.destCFrame = CFrame.new(newDestPos) * (data.destCFrame - data.destCFrame.Position)
                            end
                        end

                        return oldInvoke(self, ...)
                    end)
                end

                -- Hook firesignal / client event handling to override tween time BEFORE client receives it
                if firesignal then
                    oldFireSignal = hookfunction(firesignal, function(signal, ...)
                        local args = {...}
                        if InstantToggle.Enabled and signal == tweenTeleportRemote.OnClientEvent and typeof(args[1]) == "table" then
                            args[1].time = 0.1 -- Forces instant execution
                        end
                        return oldFireSignal(signal, unpack(args))
                    end)
                end
            else
                if oldInvoke then
                    hookmetamethod(game, "__namecall", oldInvoke)
                    oldInvoke = nil
                end
                if oldFireSignal then
                    hookfunction(firesignal, oldFireSignal)
                    oldFireSignal = nil
                end
            end
        end,
        Tooltip = 'Extends Elektra dash distance and removes teleport delay'
    })

    ExtensionSlider = ElektraExtender:CreateSlider({
        Name = 'Extra Studs',
        Min = 0,
        Max = 13,
        Default = 5,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end,
        Tooltip = 'Additional distance added to your ElectricDash (Max 13)'
    })

    InstantToggle = ElektraExtender:CreateToggle({
        Name = 'Instant Teleport',
        Default = true,
        Tooltip = 'Forces TweenTeleport duration from 0.3s to 0.01s'
    })
end)

run(function()
	local AutoMiner
	local AutoCollect
	local CollectRange
	local CollectDelay
	local PetrifiedESP
	local ESPBackground
	local ESPColor
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui
	local Reference = {}
	local rockIcon
	local collectionActive = false

	local function getRockIcon()
		if not rockIcon then
			rockIcon = bedwars.getIcon({itemType = 'large_rock'}, true)
		end
		return rockIcon
	end

	local function Added(obj)
		if Reference[obj] then return end
		local part = not obj:IsA('Model') and obj or obj.PrimaryPart
		if not part then return end
		local billboard = Instance.new('BillboardGui')
		billboard.Parent = Folder
		billboard.Name = 'petrified-player'
		billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
		billboard.Size = UDim2.fromOffset(36, 36)
		billboard.AlwaysOnTop = true
		billboard.ClipsDescendants = false
		billboard.Adornee = part
		local blur = addBlur(billboard)
		blur.Visible = ESPBackground.Enabled
		local image = Instance.new('ImageLabel')
		image.Size = UDim2.fromOffset(36, 36)
		image.Position = UDim2.fromScale(0.5, 0.5)
		image.AnchorPoint = Vector2.new(0.5, 0.5)
		image.BackgroundColor3 = Color3.fromHSV(ESPColor.Hue, ESPColor.Sat, ESPColor.Value)
		image.BackgroundTransparency = 1 - (ESPBackground.Enabled and ESPColor.Opacity or 0)
		image.BorderSizePixel = 0
		image.Image = getRockIcon()
		image.Parent = billboard
		local uicorner = Instance.new('UICorner')
		uicorner.CornerRadius = UDim.new(0, 4)
		uicorner.Parent = image
		Reference[obj] = billboard
	end

	local function Removed(obj)
		if Reference[obj] then
			Reference[obj]:Destroy()
			Reference[obj] = nil
		end
	end

	local function setupESP()
		for _, v in collectionService:GetTagged('petrified-player') do
			Added(v)
		end
		AutoMiner:Clean(collectionService:GetInstanceAddedSignal('petrified-player'):Connect(function(v)
			if PetrifiedESP.Enabled then Added(v) end
		end))
		AutoMiner:Clean(collectionService:GetInstanceRemovedSignal('petrified-player'):Connect(function(v)
			Removed(v)
		end))
		local lastUpdate = 0
		AutoMiner:Clean(runService.RenderStepped:Connect(function()
			if not PetrifiedESP.Enabled then return end
			local now = tick()
			if now - lastUpdate < 0.2 then return end
			lastUpdate = now
			for obj in pairs(Reference) do
				if not obj or not obj.Parent then
					Removed(obj)
				end
			end
		end))
	end

	local function startAutoCollect()
		if collectionActive then return end
		collectionActive = true
		task.spawn(function()
			while AutoMiner.Enabled and AutoCollect.Enabled and collectionActive do
				if not entitylib.isAlive then
					task.wait(0.5)
					continue
				end
				local localPosition = entitylib.character.RootPart.Position
				local range = CollectRange.Value
				for _, obj in collectionService:GetTagged('petrified-player') do
					if not AutoMiner.Enabled or not AutoCollect.Enabled or not collectionActive then break end
					local part = not obj:IsA('Model') and obj or obj.PrimaryPart
					if part and (localPosition - part.Position).Magnitude <= range then
						local petrifyId = obj:GetAttribute('petrifyId') or obj:GetAttribute('PetrifyId')
						if petrifyId then
							pcall(function()
								bedwars.Client:Get(remotes.DestroyPetrifiedPlayer):SendToServer({ petrifyId = petrifyId })
							end)
							if CollectDelay.Value > 0 then
								task.wait(CollectDelay.Value)
							end
						end
					end
				end
				task.wait(0.1)
			end
			collectionActive = false
		end)
	end

	local function stopAutoCollect()
		collectionActive = false
	end

	AutoMiner = vape.Categories.Kits:CreateModule({
		Name = 'AutoMiner',
		Function = function(callback)
			if callback then
				if PetrifiedESP.Enabled then setupESP() end
				if AutoCollect.Enabled then startAutoCollect() end
			else
				stopAutoCollect()
				Folder:ClearAllChildren()
				table.clear(Reference)
			end
		end,
		Tooltip = 'frees petrified players + esp for miner'
	})

	AutoCollect = AutoMiner:CreateToggle({
		Name = 'Auto Collect',
		Tooltip = 'auto frees the petrified players',
		Function = function(callback)
			if CollectRange and CollectRange.Object then CollectRange.Object.Visible = callback end
			if CollectDelay and CollectDelay.Object then CollectDelay.Object.Visible = callback end
			if AutoMiner.Enabled then
				if callback then startAutoCollect() else stopAutoCollect() end
			end
		end
	})
	CollectRange = AutoMiner:CreateSlider({
